        var all = localReadAll();
        var coll = (all[collPath] = all[collPath] || {});
        var touched = [];
        list.forEach(function(e){ coll[e.id] = Object.assign({}, e.data); touched.push([collPath, e.id]); });
        localWriteAll(all, touched);
