function wireEmailServiceSettings(ov){
  var save = ov.querySelector('#emSave'); if(!save) return;
  var msg = ov.querySelector('#emMsg');
  function say(t, ok){ msg.innerHTML = '<div class="banner">'+(ok?ICONS.check:ICONS.warn)+'<span>'+esc(t)+'</span></div>'; }
  function persist(){
    var cfg = { service:ov.querySelector('#emSvc').value.trim(), template:ov.querySelector('#emTpl').value.trim(), key:ov.querySelector('#emKey').value.trim() };
    try{ localStorage.setItem(EMAIL_CFG_KEY, JSON.stringify(cfg)); }catch(e){}
    return cfg;
  }
  save.addEventListener('click', function(){ var c = persist(); say(c.service && c.template && c.key ? tr('Email settings saved.') : tr('Saved, but all three values are needed before emails can be sent.'), !!(c.service && c.template && c.key)); });
  ov.querySelector('#emTest').addEventListener('click', async function(){
    persist();
    var me = State.users.find(function(x){ return x.id === (State.session||{}).userId; }) || {};
    var to = ov.querySelector('#emTo').value.trim() || (isEmail(me.email) ? me.email : '');
    if(!isEmail(to)) return say(tr('Enter a valid email address'), false);
    say(tr('Sending…'), true);
    var res = await sendEmailJs({ to_email:to, to_name:me.name || 'there', code:'123456', shop_name:State.settings.shopName || 'Pesa', expires_minutes:String(RESET_MINUTES), app_name:'Pesa' });
    say(res.ok ? tr('Test email sent to')+' '+to+'.' : (res.reason === 'not_configured' ? tr('Fill in all three values first.') : tr('The email could not be sent. Check the three values and your internet connection.') + (res.detail ? ' ('+String(res.detail).slice(0,120)+')' : '')), res.ok);
  });
}

