    var rec = { id: bioB64u(cred.rawId), at: new Date().toISOString(), alg: -7 };
    try{ if(cred.response.getPublicKey){ var pk = cred.response.getPublicKey(); if(pk){ rec.pk = bioB64u(pk); rec.alg = cred.response.getPublicKeyAlgorithm ? cred.response.getPublicKeyAlgorithm() : -7; } } }catch(e){}
