function btHelpIndex(){
  var out = [], mgr = isManagerOrOwner();
  BT_HELP_TOPICS.forEach(function(t){ if(t[3] && !mgr) return; out.push({ kind:'topic', title:t[0], hay:(t[0]+' '+t[1]).toLowerCase(), titleLow:t[0].toLowerCase(), run:t[2] }); });
  try{
    lessonsForRole().forEach(function(l){
      var hay = [l.title].concat((l.slides||[]).map(function(s){ return [s.title, s.text, s.where, s.tip, (s.steps||[]).join(' ')].join(' '); })).join(' ').toLowerCase();
      out.push({ kind:'lesson', title:l.title, hay:hay, titleLow:l.title.toLowerCase(), id:l.id });
    });
  }catch(e){}
  return out;
}
function btHelpSearch(q){
  var toks = String(q||'').toLowerCase().split(/[^a-z0-9]+/).filter(function(x){ return x.length > 1; });
  if(!toks.length) return [];
  return btHelpIndex().map(function(it){
    var sc = 0; toks.forEach(function(t){ if(it.titleLow.indexOf(t) > -1) sc += 4; if(it.hay.indexOf(t) > -1) sc += 1; });
    if(toks.every(function(t){ return it.hay.indexOf(t) > -1; })) sc += 3;
    return { it:it, sc:sc };
  }).filter(function(x){ return x.sc > 0; }).sort(function(a,b){ return b.sc - a.sc; }).slice(0, 12).map(function(x){ return x.it; });
}
