/* ---- backup folder (copies saved to a folder you choose, for example one that syncs to Google Drive) ---- */
var BackupFolder = (function(){
  var DB = 'pesa_bkfolder_v1', ST = 'h', KEEP = 30;
  function supported(){ return typeof window.showDirectoryPicker === 'function' && !!window.indexedDB; }
  function open(){ return new Promise(function(res, rej){ var r = indexedDB.open(DB, 1); r.onupgradeneeded = function(){ r.result.createObjectStore(ST); }; r.onsuccess = function(){ res(r.result); }; r.onerror = function(){ rej(r.error); }; }); }
  function getH(){ return open().then(function(db){ return new Promise(function(res){ var q = db.transaction(ST,'readonly').objectStore(ST).get(WS.id); q.onsuccess = function(){ res(q.result || null); db.close(); }; q.onerror = function(){ res(null); db.close(); }; }); }).catch(function(){ return null; }); }
  function setH(h){ return open().then(function(db){ return new Promise(function(res){ var s = db.transaction(ST,'readwrite').objectStore(ST); var q = h ? s.put(h, WS.id) : s.delete(WS.id); q.onsuccess = function(){ res(true); db.close(); }; q.onerror = function(){ res(false); db.close(); }; }); }).catch(function(){ return false; }); }
  async function perm(h, ask){
    try{
      var o = { mode:'readwrite' };
      if((await h.queryPermission(o)) === 'granted') return true;
      if(ask && (await h.requestPermission(o)) === 'granted') return true;
    }catch(e){}
    return false;
  }
  function lastKey(){ return 'pesa_bkfolder_last_'+WS.id; }
  function lastAt(){ try{ return parseInt(localStorage.getItem(lastKey()) || '0', 10) || 0; }catch(e){ return 0; } }
  function safe(s){ return String(s||'shop').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,24) || 'shop'; }
  async function writeJson(json, at){
    var h = await getH(); if(!h) return { ok:false, why:'nofolder' };
    if(!(await perm(h, false))) return { ok:false, why:'permission' };
    try{
      var d = new Date(at || Date.now()), name = 'pesa-backup-'+safe(btShop())+'-'+todayKey(d)+'-'+String(d.getHours()).padStart(2,'0')+String(d.getMinutes()).padStart(2,'0')+'.json';
      var fh = await h.getFileHandle(name, { create:true }), w = await fh.createWritable(); await w.write(json); await w.close();
      try{ localStorage.setItem(lastKey(), String(Date.now())); }catch(e){}
      try{
        var names = [], it = h.values(), nx; while(!(nx = await it.next()).done){ var e = nx.value; if(e.kind === 'file' && e.name.indexOf('pesa-backup-'+safe(btShop())+'-') === 0) names.push(e.name); }
        names.sort(); while(names.length > KEEP){ await h.removeEntry(names.shift()); }
      }catch(e2){}
      return { ok:true, name:name };
    }catch(e){ return { ok:false, why:'error' }; }
  }
  async function choose(){
    try{ var h = await window.showDirectoryPicker({ mode:'readwrite' }); await setH(h); return h; }catch(e){ return null; }
  }
  async function status(){
    if(!supported()) return { state:'unsupported' };
    var h = await getH(); if(!h) return { state:'none' };
    var ok = await perm(h, false);
    return { state: ok ? 'ready' : 'permission', name:h.name, last:lastAt() };
  }
  async function renew(){ var h = await getH(); if(!h) return false; return perm(h, true); }
  async function forget(){ await setH(null); }
  return { supported:supported, choose:choose, status:status, renew:renew, forget:forget, writeJson:writeJson, lastAt:lastAt };
})();
function btShareBackup(){
  (async function(){
    try{
      var data = backupPayload(); data.ledgers = await gatherLedgers();
      var json = JSON.stringify(data), name = 'pesa-backup-'+todayKey()+'.json';
      var file = new File([json], name, { type:'application/json' });
      if(navigator.canShare && navigator.canShare({ files:[file] })){ await navigator.share({ files:[file], title:'Pesa backup' }); bkMarkOutside(); }
      else { downloadTextFile(name, json); bkMarkOutside(); }
    }catch(e){ if(e && e.name !== 'AbortError') toast(tr('Could not share the backup')); }
  })();
}
/* ---- is there a copy that survives losing this phone or computer? ---- */
var _bkSafety = { folder:'', at:0 };
function bkSafetyRefresh(){ try{ BackupFolder.status().then(function(st){ _bkSafety.folder = st.state; _bkSafety.at = Date.now(); }, function(){}); }catch(e){} }
(function(){ try{ setTimeout(bkSafetyRefresh, 4000); setInterval(bkSafetyRefresh, 10 * 60000); document.addEventListener('visibilitychange', function(){ if(!document.hidden) bkSafetyRefresh(); }); }catch(e){} })();
function bkMarkOutside(){ try{ localStorage.setItem('pesa_ext_copy_' + WS.id, String(Date.now())); }catch(e){} }
function bkIsComputer(){ try{ return !/Android|iPhone|iPad|iPod|Mobile/i.test(navigator.userAgent || ''); }catch(e){ return false; } }
// { safe, why }: cloud sync running, a backup folder that is ready and was written to in the last 7 days, or a copy downloaded or sent in the last 14 days
function bkOutsideSafe(){
  var now = Date.now(), DAY = 86400000;
  try{ if(Store.isCloud && Store.isCloud()) return { safe:true, why:'cloud' }; }catch(e){}
  try{ var ss = Sync.status(); if(ss && (ss.state === 'ok' || ss.state === 'pending' || ss.state === 'syncing')) return { safe:true, why:'sync' }; }catch(e){}
  try{ if(_bkSafety.folder === 'ready' && BackupFolder.lastAt() && now - BackupFolder.lastAt() < 7 * DAY) return { safe:true, why:'folder' }; }catch(e){}
  try{ var x = parseInt(localStorage.getItem('pesa_ext_copy_' + WS.id) || '0', 10) || 0; if(x && now - x < 14 * DAY) return { safe:true, why:'copy' }; }catch(e){}
  return { safe:false, why:'none' };
}
// Safe copy prompts live only in Settings (Automatic backups and Backup and recovery); nothing is shown on the dashboard
function bkBannerHtml(){ return ''; }
(function(){ try{
  var _dw = dashWrap; dashWrap = function(inner){ return _dw(bkBannerHtml() + inner); };
  document.addEventListener('click', function(e){
    var b = e.target && e.target.closest ? e.target.closest('[data-bksafe]') : null; if(!b) return;
    var act = b.getAttribute('data-bksafe');
    if(act === 'allow'){ BackupFolder.renew().then(function(ok){ toast(ok ? tr('Allowed') : tr('Not allowed')); bkSafetyRefresh(); setTimeout(function(){ try{ render(); }catch(x){} }, 400); }); }
    else if(act === 'open'){ welcomeDone('bk'); openBackupsSheet(); }
    else { welcomeDone('bk'); try{ localStorage.setItem('pesa_bk_later_' + WS.id, String(Date.now())); }catch(x){} var c = document.getElementById('bkSafeBanner'); if(c) c.remove(); }
  });
}catch(e){} })();
function btBackupFolderPaint(box){
  if(!box) return;
  BackupFolder.status().then(function(s){
    var h = '<div class="section-title" style="margin-top:12px;">'+tr('Copies outside Pesa')+'</div>';
    if(s.state === 'unsupported'){
      h += '<div class="banner" style="display:block;">'+tr('This browser cannot save to a folder by itself. Use Download on a backup below, or the share button, to put a copy somewhere safe such as Google Drive, email or a flash disk.')+'</div>';
    } else {
      h += '<div class="banner" style="display:block;">'+tr('Choose a folder and Pesa saves a copy there every time it makes a backup. Pick a folder that your Google Drive, OneDrive or Dropbox app syncs, and the copy goes to the cloud as well. Pesa keeps the latest 30.')+'</div>';
      if(s.state === 'none') h += '<div class="actions"><button class="btn btn-ghost btn-block" id="bfChoose" type="button">'+tr('Choose a backup folder')+'</button></div>';
      else h += '<div class="row" style="margin-top:6px;"><div class="main"><div class="title">'+esc(s.name)+'</div><div class="sub">'+(s.state === 'ready' ? '<span style="color:var(--success);">'+tr('Ready')+'</span>' : '<span style="color:var(--warn, #d98e2b);">'+tr('Pesa needs your permission again')+'</span>')+(s.last ? ' · '+tr('last copy')+' '+fmtDateTime(new Date(s.last).toISOString()) : '')+'</div></div><div class="trail" style="display:flex;gap:6px;">'+(s.state === 'ready' ? '' : '<button class="btn btn-primary" id="bfRenew" type="button" style="padding:6px 12px;min-height:0;">'+tr('Allow')+'</button>')+'<button class="btn btn-ghost" id="bfForget" type="button" style="padding:6px 12px;min-height:0;">'+tr('Stop')+'</button></div></div>';
    }
    h += '<div class="actions"><button class="btn btn-ghost btn-block" id="bfShare" type="button">'+tr('Share a backup now (email, Drive, WhatsApp)')+'</button></div>';
    box.innerHTML = h;
    var c = box.querySelector('#bfChoose'); if(c) c.addEventListener('click', function(){ BackupFolder.choose().then(function(hh){ if(hh){ toast(tr('Folder chosen')); Backups.make('folder').then(function(){ btBackupFolderPaint(box); }); } }); });
    var r = box.querySelector('#bfRenew'); if(r) r.addEventListener('click', function(){ BackupFolder.renew().then(function(ok){ toast(ok ? tr('Allowed') : tr('Not allowed')); btBackupFolderPaint(box); }); });
    var fg = box.querySelector('#bfForget'); if(fg) fg.addEventListener('click', function(){ BackupFolder.forget().then(function(){ btBackupFolderPaint(box); }); });
    var sh = box.querySelector('#bfShare'); if(sh) sh.addEventListener('click', btShareBackup);
  });
}

function roleTabs(role){
  if(role === 'cashier') return ['me','sell','till','records'];
  if(role === 'stockclerk') return ['me','stock','records'];
  return ['dashboard','sell','stock','credit','invoices','reports','expenses','till','reconcile','team'];
}
function isManagerOrOwner(){ var r = secRoleNow(); return r === 'owner' || r === 'manager'; }
function isOwner(){ return secRoleNow() === 'owner'; }
function isRestricted(){ return !!State.session && !isManagerOrOwner(); }
function isCashier(){ return secRoleNow() === 'cashier'; }
function saveSessionLocal(userId){ try{ var n = Date.now(); localStorage.setItem(SESSION_KEY, JSON.stringify({userId:userId, at:n, last:n})); localStorage.setItem('pesa_last_user_' + WS.id, userId); }catch(e){} }
function clearSessionLocal(){ try{ localStorage.removeItem(SESSION_KEY); }catch(e){} }

var signedOutPending = false;
function logout(){
  confirmSheet(tr('Log out?'), tr('You can log back in anytime with your password or PIN.'), tr('Log out'), function(){
    signedOutPending = true; _bioLockPending = false;
    State.session = null;
    State.till.current = null;
    State.tab = 'dashboard';
    clearSessionLocal();
    closeModal();
    checkAuthAndRoute();
  });
}

function checkAuthAndRoute(){
  if(suppressAuthRoute) return;
  if(typeof POS !== 'undefined' && POS.open) return; // the point of sale handles its own sign in
  if(!State.ready.company || !State.ready.users) return;
  var appEl = document.getElementById('app');
  var authEl = document.getElementById('authScreen');
  if(!appEl || !authEl) return;

  if(!State.company){ showAuthScreen('register'); return; }
  if(!State.session && empSignupActive) return;

  if(!State.session){
    var saved = null;
    try{ saved = JSON.parse(localStorage.getItem(SESSION_KEY) || 'null'); }catch(e){}
    if(saved && saved.userId && !sessionFresh(saved)){ clearSessionLocal(); logAudit('other','staff',saved.userId,'Saved sign in expired, sign in required'); saved = null; }
    if(saved && !saved.at){ saveSessionLocal(saved.userId); }
    if(saved && saved.userId && !(State.ready && State.ready.users)) return;   // staff list still loading after a reload: wait, do not flash the sign in page
    if(saved && saved.userId){
      var u = State.users.find(function(x){ return x.id===saved.userId && x.active!==false && !x.pending; });
      if(u){ State.session = { userId:u.id, name:u.name, role:u.role }; if(bioEnrolled(u.id) && bioLockOn(u.id) && bioSupported() && !pesaAfterUpdateFresh()) _bioLockPending = true; }
    }
  }
  if(!State.session){
    try{
      var pa = JSON.parse(sessionStorage.getItem('pesa_pwreset_apply') || 'null');
      if(pa && pa.ws === WS.id){
        sessionStorage.removeItem('pesa_pwreset_apply');
        refs.users.doc(pa.userId).update({ passHash:pa.hash });
        toast(tr('Password changed, sign in with your new password.'));
      }
    }catch(e){}
    // one-step sign-in from another business's register page (see wireRegisterCompany)
    var al = null;
    try{ al = JSON.parse(sessionStorage.getItem('pesa_autologin') || 'null'); sessionStorage.removeItem('pesa_autologin'); }catch(e){}
    if(al && al.ws === WS.id){
      var au = State.users.find(function(x){ return x.id === al.userId && x.active !== false; });
      if(au && al.secret != null){
        pwCheck(al.secret, au.passHash).then(function(ok){
          if(!ok || State.session) return;
          pwUpgrade(au, al.secret);
          State.session = { userId:au.id, name:au.name, role:au.role };
          saveSessionLocal(au.id);
          toast(tr('Welcome back, ')+au.name+'!');
          checkAuthAndRoute();
        });
      }
    }
  }
  if(!State.session){ showAuthScreen(signedOutPending ? 'signedout' : 'login'); return; }
  signedOutPending = false;
  if(!getConsent(State.session.userId)){ showConsentScreen(); return; }
  if(_bioLockPending && bioEnrolled(State.session.userId) && bioLockOn(State.session.userId) && bioSupported()){ showBioLock(); return; }
  _bioLockPending = false;

  authEl.style.display = 'none';
  appEl.style.display = '';
  var mine = State.tillSessions.find(function(t){ return t.cashierId===State.session.userId && t.status==='open'; });
  State.till.current = mine || null;
  var allowed = roleTabs(State.session.role);
  if(allowed.indexOf(State.tab) === -1) State.tab = allowed[0];
  render();
  try{ licCheck(); }catch(e){}
  startIdleWatch(); touchUserActive(); setTimeout(btMaybeSetupPrompt, 2200); try{ onMessagesChanged(); if(isRestricted()) setTimeout(empStockAlertTick, 1500); }catch(e){}
  if(!_whatsNewChecked){ _whatsNewChecked = true; maybeShowWhatsNew(); }
  try{ if(_welcomeFor !== State.session.userId){ _welcomeFor = State.session.userId; welcomeAtSignIn(); } }catch(e){}
  (function(uid0){ setTimeout(function(){ try{ if(State.session && State.session.userId === uid0) pfRemindStart(0); }catch(e){} }, 5000); })(State.session ? State.session.userId : null);
  (function(uid0){ setTimeout(function(){ try{ bkShowOnOpen(uid0, 0); }catch(e){} }, 1800); })(State.session ? State.session.userId : null);
}
/* Optional (Settings, Backups): show the saved backup files each time the owner or a manager opens Pesa.
   It waits politely if another sheet is open, and gives up after about a minute. */
function bkShowOnOpen(uid0, tries){
  if(!State.session || State.session.userId !== uid0 || !State.settings || !State.settings.bkShowOnOpen || !isManagerOrOwner()) return;
  if(pfBusy()){ if(tries < 12) setTimeout(function(){ try{ bkShowOnOpen(uid0, tries + 1); }catch(e){} }, 5000); return; }
  openBackupsSheet();
}
var _whatsNewChecked = false;

function showAuthScreen(view){
  var _lg = document.getElementById('licGate'); if(_lg) _lg.remove();
  empSignupActive = (view === 'employee');
  var authEl = document.getElementById('authScreen');
  document.getElementById('app').style.display = 'none';
  authEl.style.display = 'flex';
  if(view === 'signedout'){
    authEl.innerHTML = renderSignedOutHtml();
    wireSignedOut(authEl);
    return;
  }
  if(view === 'employee'){
    authEl.innerHTML = renderEmployeeSignupHtml();
    wireEmployeeSignup(authEl);
    return;
  }
  if(view === 'forgot'){
    authEl.innerHTML = renderForgotHtml();
    wireForgot(authEl);
    return;
  }
  authEl.innerHTML = view === 'register' ? renderRegisterCompanyHtml() : renderLoginHtml();
  if(view === 'register') wireRegisterCompany(authEl); else wireLoginView(authEl);
}

/* ---- signed-out screen: log in again, or register as a new user/business ---- */
