    '<div class="authbox">' +
      '<div class="actions"><button class="btn btn-primary btn-block" id="soLoginBtn">'+tr('Log in again')+'</button></div>' +
      otherBusinessesHtml(tr('Other businesses on this device')) +
    '</div>' + newHereHtml() +
  '</div>';
