/* ---- register page: "I already have an account on this device" dropdown ---- */
function accountPickerHtml(){
  var accts = WS.accounts();
  if(!accts.length) return '';
  var opts = accts.map(function(a, i){
    return '<option value="'+i+'">'+esc(a.name)+', '+esc(a.wsName)+' ('+esc(tr(ROLE_LABELS[a.role]||a.role||''))+')</option>';
  }).join('');
  return '<div class="section-title" style="margin-top:22px;">'+tr('Already have an account on this device?')+'</div>' +
    '<div class="field"><label>'+tr('Choose your account')+'</label>' +
      '<select id="rcAcctSelect"><option value="">'+tr('Choose…')+'</option>'+opts+'</select></div>' +
    '<div id="rcAcctBox"></div>';
}
function wireAccountPicker(root){
  var sel = root.querySelector('#rcAcctSelect');
  if(!sel) return;
  var accts = WS.accounts();
  sel.addEventListener('change', function(){
    var box = root.querySelector('#rcAcctBox');
    if(sel.value === ''){ box.innerHTML = ''; return; }
    var a = accts[parseInt(sel.value, 10)];
    var isCash = a.role === 'cashier';
    box.innerHTML =
      '<div class="field"><label>'+(isCash ? tr('4-digit PIN') : tr('Password'))+'</label>' +
        '<input id="rcAcctPass" type="password" inputmode="'+(isCash?'numeric':'text')+'" '+(isCash?'maxlength="4"':'')+' placeholder="'+(isCash?'••••':tr('Enter your password'))+'"></div>' +
      '<div id="rcAcctError"></div>' +
      '<div class="actions"><button class="btn btn-primary btn-block" id="rcAcctLogin" type="button">'+tr('Log in')+'</button></div>';
    var pass = box.querySelector('#rcAcctPass');
    pass.focus();
    function attempt(){
      var val = pass.value; if(!val) return;
      var btn = box.querySelector('#rcAcctLogin'), err = box.querySelector('#rcAcctError');
      var lt = authLockText('xlogin:'+a.id); if(lt){ err.innerHTML = '<div class="banner">'+ICONS.warn+'<span>'+esc(lt)+'</span></div>'; pass.value = ''; return; }
      btn.disabled = true;
      (a.passHash ? pwCheck(val, a.passHash) : Promise.resolve(true)).then(function(ok){
        // when this device holds that business's data we can check the password right here
        if(!ok){
          var f = authFailed('xlogin:'+a.id, a.name);
          btn.disabled = false;
          err.innerHTML = '<div class="banner">'+ICONS.warn+'<span>'+esc(f.locked ? authLockText('xlogin:'+a.id) : (isCash?tr('Incorrect PIN.'):tr('Incorrect password.')))+'</span></div>';
          pass.value = ''; pass.focus();
          return;
        }
        authOk('xlogin:'+a.id);
        try{ sessionStorage.setItem('pesa_autologin', JSON.stringify({ ws:a.ws, userId:a.id, secret:val })); }catch(e){}
        switchBusiness(a.ws);
      });
    }
    box.querySelector('#rcAcctLogin').addEventListener('click', attempt);
    pass.addEventListener('keydown', function(e){ if(e.key==='Enter') attempt(); });
  });
}

function wireRegisterCompany(root){
  wireBusinessSwitcher(root);
  wireAccountPicker(root);
  var js = root.querySelector('[data-joinsync]'); if(js) js.addEventListener('click', openJoinSyncSheet);
  var jn = root.querySelector('[data-joinnearby]'); if(jn) jn.addEventListener('click', openNearbySheet);
  bipaWire(root, '#rcRegNumber', '#rcBipaHint', null);
  (function(){
    var page = root.querySelector('.regpage'); if(!page) return;
    var steps = page.querySelectorAll('.reg-step');
    function setStep(n){ steps.forEach(function(el, i){ el.classList.toggle('on', i === n-1); el.classList.toggle('done', i < n-1); }); }
    page.addEventListener('focusin', function(e){
      var t = e.target; if(!t || !t.closest) return;
      if(t.closest('#regOwnerSec')) setStep(2); else if(t.closest('#regBizSec')) setStep(1);
    });
  })();
  root.querySelector('#rcSubmit').addEventListener('click', function(){
    var v = function(id){ var el = root.querySelector(id); return el && el.value ? el.value.trim() : ''; };
    var companyName = v('#rcCompanyName'), regNumber = v('#rcRegNumber'), address = v('#rcAddress'),
        town = v('#rcTown'), region = v('#rcRegion'), phone = v('#rcPhone'),
        ownerName = tr('Owner'), ownerContact = '',
        pw = v('#rcOwnerPassword'), pw2 = v('#rcOwnerPassword2');
    var errEl = root.querySelector('#rcError');
    errEl.innerHTML = '';
    function fail(msg){ errEl.innerHTML = '<div class="banner">'+ICONS.warn+'<span>'+esc(msg)+'</span></div>'; }
    // Only the essentials are required, everything else can be filled in later,
    // once the business has it, from Settings → Company details.
    if(!companyName) return fail(tr('Enter your business name.'));
    if(pwProblem(pw)) return fail(pwProblem(pw));
    if(pw !== pw2) return fail(tr('Passwords don’t match.'));
    var btn = root.querySelector('#rcSubmit');
    btn.disabled = true; btn.textContent = tr('Setting up…');
    suppressAuthRoute = true;
    (async function(){
      try{
        var passHash = await pwHash(pw);
        var tradingName = v('#rcTradingName');
        await refs.company.set({
          companyName: companyName, tradingName: tradingName,
          regNumber: bipaFields(regNumber, v('#rcLegal')).regNumber, legalName: v('#rcLegal'),
          bipaStatus: bipaFields(regNumber, v('#rcLegal')).bipaStatus, bipaVerifiedAt: null, verificationTier: 'UNVERIFIED',
          vatNumber: v('#rcVatNumber'), address: address, town: town, region: region,
          phone: phone, email: v('#rcEmail'), ownerName: ownerName, businessType: 'retail',
          createdAt: new Date().toISOString()
        });
        var newUserRef = refs.users.doc();
        await newUserRef.set({ name: ownerName, email: ownerContact.toLowerCase(), role:'owner', passHash: passHash, active:true, createdAt: new Date().toISOString() });
        var displayName = tradingName || companyName;
        State.settings.shopName = displayName;
        try{ await refs.settings.set(State.settings); }catch(e2){}
        State.session = { userId: newUserRef.id, name: ownerName, role:'owner' };
        welcomeMark(newUserRef.id);   // the first session gets the one time pilot and backup prompts
        saveSessionLocal(newUserRef.id);
        showWelcomeSplash(displayName, function(){
          suppressAuthRoute = false;
          checkAuthAndRoute();
        });
      }catch(e){
        suppressAuthRoute = false;
        btn.disabled = false; btn.textContent = tr('Register & continue');
        fail(tr('Something went wrong saving your details, please try again.'));
      }
    })();
  });
}

/* ============================== EMPLOYEE ACCOUNTS: invite, sign up, personal dashboard ============================== */
function newInviteCode(){ var c; do{ c = String(Math.floor(100000 + Math.random()*900000)); }while(State.users.some(function(u){ return u.inviteCode === c; })); return c; }
function nextEmployeeNo(){ return 'E' + String(State.users.filter(function(u){ return u.employeeNo; }).length + 1).padStart(3,'0'); }
function appUrl(){ return location.href.split('#')[0].split('?')[0]; }
function inviteMessage(u){
  var co = State.company || {};
  return 'Hi '+u.name+', you have been added to '+(co.tradingName||co.companyName||'our shop')+' on Pesa as '+(u.jobTitle||ROLE_LABELS[u.role]||u.role)+'. To create your own account: open '+appUrl()+' , tap "New employee sign up" and enter this code: '+u.inviteCode+' (valid for 7 days).';
}
function openInviteSheet(u){
  var cur = State.users.find(function(x){ return x.id === u.id; }) || u;
  var expired = cur.inviteExpires && new Date(cur.inviteExpires) < new Date();
  var msg = inviteMessage(cur);
  var html = '<div class="sheet-head"><h2>'+tr('Invite')+' '+esc(cur.name)+'</h2></div>' +
    '<div style="font-size:13px;color:var(--text-muted);margin-bottom:8px;">'+esc(tr(ROLE_LABELS[cur.role]||cur.role))+(cur.jobTitle?' · '+esc(cur.jobTitle):'')+' · '+tr('Employee')+' '+esc(cur.employeeNo||'')+'</div>' +
    (cur.pending ? '<div class="field"><label>'+tr('Invite code')+'</label><div class="num" style="font-size:32px;font-weight:700;letter-spacing:.14em;text-align:center;padding:12px;background:var(--surface-2);border-radius:12px;">'+esc(posFmtCode(cur.inviteCode))+'</div>' +
      '<div style="font-size:12px;color:'+(expired?'var(--danger)':'var(--text-muted)')+';margin-top:6px;">'+(expired?tr('This code has expired. Make a new one.'):tr('Valid until')+' '+fmtDateTime(cur.inviteExpires))+'</div></div>' +
      '<div class="banner">'+ICONS.info+'<span>'+tr('The employee signs up on their own computer or device. It must be connected to this business first (Advanced Pesa Connection or the same Wi-Fi). On this same device it works straight away.')+'</span></div>' +
      '<div class="actions"><button class="btn btn-accent btn-block" id="invWa" type="button">'+tr('Send on WhatsApp')+'</button><button class="btn btn-ghost btn-block" id="invCopy" type="button">'+tr('Copy message')+'</button></div>' +
      '<div class="actions" style="margin-top:8px;"><button class="btn btn-ghost btn-block" id="invNew" type="button">'+tr('New code')+'</button><button class="btn btn-ghost btn-block" id="invEdit" type="button">'+tr('Edit details')+'</button></div>' +
      '<div class="actions" style="margin-top:8px;"><button class="btn btn-danger btn-block" id="invCancel" type="button">'+tr('Cancel invite')+'</button></div>'
     : '<div class="banner">'+ICONS.check+'<span>'+tr('This employee has created their account.')+'</span></div>') +
    '<div class="actions" style="margin-top:8px;"><button class="btn btn-ghost btn-block" id="invBack" type="button">'+tr('Back to team')+'</button></div>';
  var ov = openSheet(html, {center:true});
  ov.querySelector('#invBack').addEventListener('click', openTeamSheet);
  if(!cur.pending) return;
  ov.querySelector('#invWa').addEventListener('click', function(){ window.open('https://wa.me/?text='+encodeURIComponent(msg), '_blank'); });
  ov.querySelector('#invCopy').addEventListener('click', function(){ try{ navigator.clipboard.writeText(msg).then(function(){ toast(tr('Message copied')); }); }catch(e){ toast(msg); } });
  ov.querySelector('#invNew').addEventListener('click', function(){
    var patch = { inviteCode:newInviteCode(), inviteExpires:new Date(Date.now()+7*86400000).toISOString() };
    refs.users.doc(cur.id).update(patch); openInviteSheet(Object.assign({}, cur, patch));
  });
  ov.querySelector('#invEdit').addEventListener('click', function(){ openStaffSheet(cur); });
  ov.querySelector('#invCancel').addEventListener('click', function(){ confirmSheet(tr('Cancel invite?'), tr('The code stops working and this employee is removed.'), tr('Cancel invite'), function(){
    refs.users.doc(cur.id).delete(); logAudit('delete','staff',cur.id,'Cancelled invite for '+cur.name); openTeamSheet(); }, true); });
}

/* ---- employee sign up page ---- */
var _empFails = 0, _empUntil = 0, empSignupActive = false;
function renderEmployeeSignupHtml(){
  var company = State.company || {};
  return '<div class="authcard"><div class="authbrand"><div class="brandmark"></div><h1>'+esc(company.tradingName||company.companyName||'Pesa')+'</h1><div class="slogan">Your Mula, Your Pride<span class="slogan-sub">(Retail Automated System)</span></div><p>'+tr('New employee sign up')+'</p></div>' +
    '<div class="authbox"><div id="empBox"></div><div style="text-align:center;margin-top:12px;"><button class="btn btn-ghost" id="empBack" type="button">'+tr('Back to sign in')+'</button></div></div></div>';
}
function wireEmployeeSignup(root){
  var box = root.querySelector('#empBox');
  root.querySelector('#empBack').addEventListener('click', function(){ showAuthScreen(State.company ? 'login' : 'register'); });
  function step1(){
    box.innerHTML = '<div class="banner">'+ICONS.info+'<span>'+tr('Your employer gave you a 6 digit invite code. Enter it to create your own account.')+'</span></div>' +
      '<div class="field"><label>'+tr('Invite code')+'</label><input id="empCode" inputmode="numeric" maxlength="7" placeholder="123 456" autocomplete="off"></div><div id="empErr"></div>' +
      '<div class="actions"><button class="btn btn-primary btn-block" id="empNext" type="button">'+tr('Continue')+'</button></div>';
    var inp = box.querySelector('#empCode'); inp.focus();
    function go(){
      var err = box.querySelector('#empErr');
      function fail(m){ err.innerHTML = '<div class="banner">'+ICONS.warn+'<span>'+esc(m)+'</span></div>'; }
      var _il = authLockText('invite'); if(_il){ fail(_il); return; }
      var code = inp.value.replace(/\D/g,'');
      var u = State.users.find(function(x){ return x.pending && x.inviteCode && x.inviteCode === code; });
      if(!u){ authFailed('invite', 'employee invite code'); fail(tr('That code was not found. Check it, or ask your employer for a new one. This computer or device must be connected to the business.')); return; }
      if(u.inviteExpires && new Date(u.inviteExpires) < new Date()){ fail(tr('This code has expired. Ask your employer for a new one.')); return; }
      authOk('invite'); step2(u);
    }
    box.querySelector('#empNext').addEventListener('click', go);
    inp.addEventListener('keydown', function(e){ if(e.key === 'Enter') go(); });
  }
  function step2(u){
    var isCash = u.role === 'cashier', co = State.company || {};
    box.innerHTML = '<div class="section-title" style="margin-top:0;">'+tr('Welcome')+', '+esc(u.name)+'</div>' +
      '<div style="font-size:13px;color:var(--text-muted);margin-bottom:10px;">'+tr('You are joining')+' '+esc(co.tradingName||co.companyName||'')+' '+tr('as')+' <b>'+esc(u.jobTitle||tr(ROLE_LABELS[u.role]||u.role))+'</b>.</div>' +
      (ROLE_INFO[u.role] ? '<div class="banner" style="display:block;font-size:12.5px;"><b>'+tr('What this job can do')+'</b><br>'+ROLE_INFO[u.role].can.map(function(x){ return '✓ '+esc(tr(x)); }).join('<br>')+'</div>' : '') +
      '<div class="field"><label>'+tr('Phone (optional)')+'</label><input id="empPhone" value="'+esc(u.phone||'')+'" placeholder="081 234 5678"></div>' +
      '<div class="field"><label>'+tr('Email (optional)')+'</label><input id="empEmail" type="email" value="'+esc(u.email||'')+'" placeholder="name@example.com"></div>' +
      '<div class="field"><label>'+(isCash?tr('Choose a 4-digit PIN'):tr('Choose a password'))+'</label><input id="empPw" type="password" '+(isCash?'inputmode="numeric" maxlength="4"':'')+' autocomplete="new-password"></div>' +
      '<div class="field"><label>'+(isCash?tr('Confirm PIN'):tr('Confirm password'))+'</label><input id="empPw2" type="password" '+(isCash?'inputmode="numeric" maxlength="4"':'')+' autocomplete="new-password"></div><div id="empErr"></div>' +
      '<div class="actions"><button class="btn btn-primary btn-block" id="empCreate" type="button">'+tr('Create my account')+'</button></div>';
    box.querySelector('#empCreate').addEventListener('click', async function(){
      var err = box.querySelector('#empErr');
      function fail(m){ err.innerHTML = '<div class="banner">'+ICONS.warn+'<span>'+esc(m)+'</span></div>'; }
      var pw = box.querySelector('#empPw').value, pw2 = box.querySelector('#empPw2').value;
      if(isCash && !/^\d{4}$/.test(pw)) return fail(tr('PIN must be exactly 4 digits.'));
      if(!isCash && pwProblem(pw)) return fail(pwProblem(pw));
      if(pw !== pw2) return fail(tr('The two entries do not match.'));
      var fresh = State.users.find(function(x){ return x.id === u.id; });
      if(!fresh || !fresh.pending){ return fail(tr('This invite has already been used.')); }
      var hash = await pwHash(pw);
      var patch = { passHash:hash, pending:false, inviteCode:'', inviteExpires:'', joinedAt:new Date().toISOString(), phone:box.querySelector('#empPhone').value.trim(), email:box.querySelector('#empEmail').value.trim().toLowerCase(), active:true, lastActiveAt:new Date().toISOString() };
      refs.users.doc(u.id).update(patch);
      State.session = { userId:u.id, name:u.name, role:u.role };
      welcomeMark(u.id);   // the first session gets the one time pilot and backup prompts
      saveSessionLocal(u.id);
      logAudit('create','staff',u.id,u.name+' created their account');
      toast(tr('Welcome')+', '+u.name+'!');
      checkAuthAndRoute();
    });
  }
  step1();
}

/* ---- personal dashboard ---- */
function renderMe(){
  var me = State.users.find(function(x){ return x.id === (State.session||{}).userId; }) || {};
  var role = State.session.role, tk = todayKey(), co = State.company || {};
  var h = new Date().getHours(), hi = h < 12 ? tr('Good morning') : (h < 18 ? tr('Good afternoon') : tr('Good evening'));
  var out = '<div class="me-hero"><div class="me-av">'+userAvatarInner(me.photo ? me : { name:State.session.name })+'</div><div class="me-hi"><div class="hi">'+hi+' 👋</div><div class="nm">'+esc(State.session.name)+'</div><div class="meta">'+esc(me.jobTitle || tr(ROLE_LABELS[role]||role))+(me.employeeNo?' · '+esc(me.employeeNo):'')+' · '+esc(co.tradingName||co.companyName||'')+'</div></div></div>';
  out += meTopHtml();
  var low = State.products.filter(function(p){ return p.stockQty != null && p.stockQty <= (p.lowStock != null ? p.lowStock : State.settings.lowStockDefault); }).sort(function(a,b){ return a.stockQty - b.stockQty; });
  var lowHtml = '<div class="section-title" data-lowlist="1">'+tr('Running low')+' ('+low.length+')</div>' + (low.length ? '<div class="rowlist">'+low.slice(0,6).map(function(p){
    return '<div class="row"><div class="main"><div class="title">'+esc(p.name)+'</div></div><div class="trail"><div class="amt num" style="color:'+(p.stockQty<=0?'var(--danger)':'inherit')+'">'+(p.stockQty<=0?tr('Out'):p.stockQty+' '+esc(p.unit||tr('left')))+'</div></div></div>'; }).join('')+'</div>' : '<div style="font-size:13px;color:var(--text-muted);">'+tr('Nothing is running low.')+'</div>');
  if(role === 'stockclerk'){
    var outN = State.products.filter(function(p){ return p.stockQty != null && p.stockQty <= 0; }).length;
    out += '<div class="me-actions"><button class="me-act" data-me="stock">'+ICONS.box+tr('Open stock')+'</button><button class="me-act" data-me="waste">'+ICONS.trash+tr('Record wastage')+'</button>' +
      '<button class="me-act" data-me="addprod">'+ICONS.plus+tr('Add a product')+'</button><button class="me-act" data-me="profile">'+ICONS.people+tr('My profile')+'</button></div>' +
      '<div class="me-grid"><div class="me-stat"><div class="l">'+tr('Products')+'</div><div class="v num">'+State.products.length+'</div></div><div class="me-stat"><div class="l">'+tr('Running low')+'</div><div class="v num">'+low.length+'</div></div><div class="me-stat"><div class="l">'+tr('Out of stock')+'</div><div class="v num" style="color:var(--danger)">'+outN+'</div></div><div class="me-stat"><div class="l">'+tr('Wastage logged')+'</div><div class="v num">'+State.wastage.filter(function(w){ return w.userName === State.session.name || w.recordedBy === State.session.name; }).length+'</div></div></div>' + lowHtml;
    return out + syncStripHtml();
  }
  // cashier
  var all = State.sales.filter(function(s){ return s.cashierName === State.session.name; });
  var mine = all.filter(function(s){ return todayKey(new Date(s.createdAt)) === tk; });
  var by = { cash:0, card:0, wallet:0, credit:0 }; mine.forEach(function(s){ salePayParts(s).forEach(function(q){ by[q.method] = (by[q.method]||0) + q.amount; }); });
  var till = State.till.current, tt = till ? tillTotals(till.id) : null;
  out += '<div class="me-actions">'+(me.posAccess === false ? '' : '<button class="me-act" data-me="pos">'+ICONS.till+tr('Point of sale')+'</button>')+'<button class="me-act" data-me="sell">'+ICONS.cart+tr('New sale')+'</button>' +
    '<button class="me-act" data-me="'+(till?'till-close':'till-open')+'">'+ICONS.clock+(till?tr('Close till'):tr('Open till'))+'</button><button class="me-act" data-me="profile">'+ICONS.people+tr('My profile')+'</button></div>';
  out += '<div class="section-title" style="margin-top:0;">'+tr('Your sales today')+'</div><div class="me-grid">' +
    '<div class="me-stat"><div class="l">'+tr('Sales')+'</div><div class="v num">'+mine.length+'</div></div><div class="me-stat"><div class="l">'+tr('Total')+'</div><div class="v num">'+fmtMoney(posSum(mine))+'</div></div>' +
    '<div class="me-stat"><div class="l">'+tr('Cash')+'</div><div class="v num">'+fmtMoney(by.cash)+'</div></div><div class="me-stat"><div class="l">'+tr('Card')+'</div><div class="v num">'+fmtMoney(by.card)+'</div></div>' +
    '<div class="me-stat"><div class="l">'+tr('Mobile wallet')+'</div><div class="v num">'+fmtMoney(by.wallet)+'</div></div><div class="me-stat"><div class="l">'+tr('Credit')+'</div><div class="v num">'+fmtMoney(by.credit)+'</div></div></div>';
  var _todayT = posSum(mine), _best = 0; for(var bi=1; bi<=7; bi++){ var bd = new Date(); bd.setDate(bd.getDate()-bi); var bk = todayKey(bd); _best = Math.max(_best, posSum(all.filter(function(s){ return todayKey(new Date(s.createdAt)) === bk; }))); }
  if((_best > 0 || _todayT > 0) && me.showGoal !== false){
    var pct = _best > 0 ? Math.min(100, Math.round(_todayT/_best*100)) : 100;
    out += '<div class="me-goal"><div class="gt"><span>'+(_todayT >= _best && _todayT > 0 ? '🏆 '+tr('New best day!') : '🎯 '+tr('Beat your best day'))+'</span><b class="num">'+pct+'%</b></div><div class="gbar"><i style="width:'+pct+'%"></i></div><div class="gs">'+(_todayT >= _best && _todayT > 0 ? tr('Well done, keep going!') : fmtMoney(Math.max(0,_best-_todayT))+' '+tr('to go'))+'</div></div>';
  }
  out += '<div class="tillcard"><div class="section-title" style="margin-top:0;">'+tr('My till')+'</div>' + (till
    ? '<div class="tillrow"><span class="l">'+tr('Open since')+'</span><span class="v">'+fmtDateTime(till.openedAt)+'</span></div><div class="tillrow"><span class="l">'+tr('Opening float')+'</span><span class="v num">'+fmtMoney(till.openingFloat||0)+'</span></div><div class="tillrow grand"><span class="l">'+tr('Cash expected in drawer')+'</span><span class="v num">'+fmtMoney((till.openingFloat||0)+tt.totals.cash-(tt.cashBack||0))+'</span></div>'
    : '<div style="font-size:13px;color:var(--text-muted);">'+tr('Your till is closed. Open it before you start selling.')+'</div>') + '</div>';
  // last 7 days
  var days = [], mx = 1;
  for(var i=6;i>=0;i--){ var d = new Date(); d.setDate(d.getDate()-i); var k = todayKey(d); var t = posSum(all.filter(function(s){ return todayKey(new Date(s.createdAt)) === k; })); days.push({ l:d.toLocaleDateString(uiLocale(),{weekday:'short'}).slice(0,2), t:t }); mx = Math.max(mx, t); }
  out += '<div class="section-title">'+tr('My last 7 days')+'</div><div class="me-week">'+days.map(function(d){ return '<i style="height:'+Math.round(d.t/mx*100)+'%" title="'+fmtMoney(d.t)+'"></i>'; }).join('')+'</div><div class="me-weekl">'+days.map(function(d){ return '<span>'+esc(d.l)+'</span>'; }).join('')+'</div>';
  out += '<div class="section-title">'+tr('My recent sales')+'</div>' + (all.length ? '<div class="rowlist">'+all.slice(0,5).map(function(s){ return '<div class="row" data-me-sale="'+s.id+'"><div class="main"><div class="title">'+esc(posSaleWho(s))+'</div><div class="sub">'+esc(fmtDateTime(s.createdAt))+' · '+tr(s.paymentMethod==='wallet'?'Mobile wallet':(s.paymentMethod||'cash').charAt(0).toUpperCase()+(s.paymentMethod||'cash').slice(1))+'</div></div><div class="trail"><div class="amt num">'+fmtMoney(s.total)+'</div></div></div>'; }).join('')+'</div>' : '<div style="font-size:13px;color:var(--text-muted);">'+tr('No sales yet.')+'</div>');
  return out + lowHtml + syncStripHtml();
}
function meTopHtml(){
  var um = unreadMessages(), out = '';
  if(um.length){ var m0 = um[0]; out += '<div class="me-msg'+(um.some(function(m){ return m.urgent; })?' urgent':'')+'" data-me="inbox"><div class="t">'+ICONS.bolt+'<span>'+um.length+' '+tr(um.length===1?'new message':'new messages')+'</span></div><div class="s">'+esc(m0.fromName)+': '+esc((m0.title||msgPreview(m0)).slice(0,90))+'</div></div>'; }
  var low = State.products.filter(function(p){ return p.stockQty != null && p.stockQty <= (p.lowStock != null ? p.lowStock : State.settings.lowStockDefault); }), outN = low.filter(function(p){ return p.stockQty <= 0; }).length;
  if(low.length) out += '<div class="me-msg stock" data-me="'+(State.session.role==='stockclerk'?'stock':'lowlist')+'"><div class="t">'+ICONS.warn+'<span>'+tr('Stock alert')+': '+low.length+' '+tr('products need stock')+(outN?' ('+outN+' '+tr('out of stock')+')':'')+'</span></div><div class="s">'+esc(low.slice(0,3).map(function(p){ return p.name; }).join(', '))+(low.length>3?'…':'')+'</div></div>';
  if(!isInstalledApp() && !(function(){ var m = State.users.find(function(x){ return x.id === (State.session||{}).userId; }); return m && m.showHints === false; })()) out += '<div class="me-msg" data-me="install"><div class="t">'+ICONS.info+'<span>'+tr('Install Pesa on this device')+'</span></div><div class="s">'+tr('Opens in its own window and works offline.')+'</div></div>';
  out += '<div class="me-actions" style="grid-template-columns:repeat(3,1fr);"><button class="me-act" data-me="inbox">'+ICONS.bolt+tr('Messages')+(um.length?' ('+um.length+')':'')+'</button><button class="me-act" data-me="report">'+ICONS.chartbar+tr('Work report')+'</button><button class="me-act" data-me="records">'+ICONS.clipboard+tr('My records')+'</button></div>';
  out += tmCardHtml();
  out += pilotCardHtml();
  return out;
}
function wireMe(root){
  root.querySelectorAll('[data-me]').forEach(function(b){ b.addEventListener('click', function(){
    var k = b.getAttribute('data-me');
    if(k === 'pos') posOpen(); else if(k === 'sell') setTab('sell'); else if(k === 'stock') setTab('stock');
    else if(k === 'waste') openWastageSheet(); else if(k === 'addprod'){ setTab('stock'); openProductSheet(null); }
    else if(k === 'till-open') openStartTillSheet(); else if(k === 'till-close'){ if(State.till.current) openCloseTillSheet(State.till.current); }
    else if(k === 'profile') openMyProfileSheet();
    else if(k === 'pilotform') pilotOpen();
    else if(k === 'inbox') openInboxSheet(); else if(k === 'report') openWorkReportSheet(); else if(k === 'records') setTab('records'); else if(k === 'install') installPesa();
    else if(k === 'lowlist'){ var el = root.querySelector('[data-lowlist]'); if(el) el.scrollIntoView({behavior:'smooth'}); }
  }); });
  empStockAlertTick();
  root.querySelectorAll('[data-me-sale]').forEach(function(b){ b.addEventListener('click', function(){ openPosSaleDetail(b.getAttribute('data-me-sale')); }); });
}
// centre-cropped square profile photo, small enough to store and sync
function squarePhoto(file, size, quality){
  return new Promise(function(resolve, reject){
    var r = new FileReader();
    r.onload = function(){
      var img = new Image();
      img.onload = function(){
        var w = img.naturalWidth, h = img.naturalHeight, m = Math.min(w, h);
        var c = document.createElement('canvas'); c.width = c.height = size;
        var x = c.getContext('2d'); x.fillStyle = '#fff'; x.fillRect(0, 0, size, size);
        x.drawImage(img, (w-m)/2, (h-m)/2, m, m, 0, 0, size, size);
        resolve(c.toDataURL('image/jpeg', quality || 0.82));
      };
      img.onerror = function(){ reject(new Error('bad image')); };
      img.src = String(r.result || '');
    };
    r.onerror = function(){ reject(new Error('read failed')); };
    r.readAsDataURL(file);
  });
}
function userAvatarInner(u){
  if(u && u.photo) return '<img alt="" src="'+esc(u.photo)+'">';
  return esc(initials((u && u.name) || ''));
}
function openMyProfileSheet(){
  var me = State.users.find(function(x){ return x.id === (State.session||{}).userId; }); if(!me) return;
  var ri = ROLE_INFO[me.role] || { can:[], cannot:[] };
  function line(a,b){ return b ? '<div class="sumline"><span>'+a+'</span><span style="text-align:right;">'+esc(b)+'</span></div>' : ''; }
  var html = '<div class="sheet-head"><h2>'+tr('My profile')+'</h2></div>' +
    '<div class="pf-photo"><div class="pf-ph" id="mpPhoto">'+userAvatarInner(me)+'</div><div class="pf-phb">' +
      '<button class="btn btn-ghost" id="mpPhotoBtn" type="button">'+ICONS.plus+' '+(me.photo ? tr('Change photo') : tr('Upload photo'))+'</button>' +
      (me.photo ? '<button class="btn btn-ghost" id="mpPhotoDel" type="button">'+ICONS.trash+' '+tr('Remove photo')+'</button>' : '') +
      '<input type="file" id="mpPhotoFile" accept="image/*" style="display:none">' +
    '</div></div><div id="mpPhotoMsg"></div>' +
    line(tr('Name'), me.name) + line(tr('Job'), me.jobTitle || tr(ROLE_LABELS[me.role]||me.role)) + line(tr('Employee number'), me.employeeNo) + line(tr('Joined'), me.joinedAt ? fmtDateTime(me.joinedAt) : '') +
    '<div class="field" style="margin-top:10px;"><label>'+tr('Phone')+'</label><input id="mpPhone" value="'+esc(me.phone||'')+'"></div>' +
    '<div class="field"><label>'+tr('Email')+'</label><input id="mpEmail" type="email" value="'+esc(me.email||'')+'"></div>' +
    '<div class="section-title">'+tr('My work settings')+'</div>' +
    '<div class="field"><label>'+tr('Preferred shift')+'</label><select id="mpShift">'+['','Morning','Afternoon','Evening','Flexible'].map(function(x){ return '<option value="'+x+'"'+((me.shift||'')===x?' selected':'')+'>'+(x?tr(x):tr('Not set'))+'</option>'; }).join('')+'</select></div>' +
    '<div class="field-row"><div class="field"><label>'+tr('Emergency contact name')+'</label><input id="mpEmName" value="'+esc(me.emName||'')+'" placeholder="'+esc(tr('Who we call'))+'"></div>' +
    '<div class="field"><label>'+tr('Emergency contact phone')+'</label><input id="mpEmPhone" inputmode="tel" value="'+esc(me.emPhone||'')+'" placeholder="081 234 5678"></div></div>' +
    '<label class="pf-tg"><input type="checkbox" id="mpStockAl"'+(me.stockAlerts===false?'':' checked')+'><span><b>'+tr('Low stock alerts')+'</b><i>'+tr('Tell me on this device when products run low')+'</i></span></label>' +
    '<label class="pf-tg"><input type="checkbox" id="mpGoal"'+(me.showGoal===false?'':' checked')+'><span><b>'+tr('Best day goal')+'</b><i>'+tr('Show the beat your best day bar on my home screen')+'</i></span></label>' +
    '<label class="pf-tg"><input type="checkbox" id="mpHints"'+(me.showHints===false?'':' checked')+'><span><b>'+tr('Install and sync tips')+'</b><i>'+tr('Show tips about installing Pesa and syncing on my home screen')+'</i></span></label>' +
    '<div class="section-title">'+tr('What I can do')+'</div><div style="font-size:13px;line-height:1.7;">'+ri.can.map(function(x){ return '✓ '+esc(tr(x)); }).join('<br>')+'</div>' +
    '<div class="section-title">'+tr('Not allowed')+'</div><div style="font-size:13px;line-height:1.7;color:var(--text-muted);">'+ri.cannot.map(function(x){ return '✗ '+esc(tr(x)); }).join('<br>')+'</div>' +
    '<div class="actions" style="margin-top:12px;"><button class="btn btn-primary btn-block" id="mpSave" type="button">'+tr('Save details')+'</button></div>' +
    '<div class="actions" style="margin-top:8px;"><button class="btn btn-ghost btn-block" id="mpPw" type="button">'+(me.role==='cashier'?tr('Change PIN'):tr('Change password'))+'</button><button class="btn btn-ghost btn-block" id="mpOut" type="button">'+tr('Log out')+'</button></div>';
  var ov = openSheet(html);
  var pfMsg = ov.querySelector('#mpPhotoMsg'), pfFile = ov.querySelector('#mpPhotoFile');
  ov.querySelector('#mpPhotoBtn').addEventListener('click', function(){ pfFile.click(); });
  var pfDel = ov.querySelector('#mpPhotoDel');
  if(pfDel) pfDel.addEventListener('click', function(){ refs.users.doc(me.id).update({ photo:'' }); toast(tr('Photo removed')); closeModal(); setTimeout(function(){ render(); openMyProfileSheet(); }, 150); });
  pfFile.addEventListener('change', function(){
    var f = pfFile.files && pfFile.files[0]; if(!f) return;
    pfMsg.innerHTML = '<div class="banner">'+ICONS.info+'<span>'+tr('Preparing your photo…')+'</span></div>';
    squarePhoto(f, 320, 0.82).then(function(url){
      refs.users.doc(me.id).update({ photo:url }); toast(tr('Photo saved')); closeModal();
      setTimeout(function(){ render(); openMyProfileSheet(); }, 150);
    }, function(){ pfMsg.innerHTML = '<div class="banner">'+ICONS.warn+'<span>'+tr('That file is not a picture Pesa can read. Choose a JPG or PNG photo.')+'</span></div>'; });
  });
  ov.querySelector('#mpSave').addEventListener('click', function(){ refs.users.doc(me.id).update({ phone:ov.querySelector('#mpPhone').value.trim(), email:ov.querySelector('#mpEmail').value.trim().toLowerCase(),
    shift:ov.querySelector('#mpShift').value, emName:ov.querySelector('#mpEmName').value.trim(), emPhone:ov.querySelector('#mpEmPhone').value.trim(),
    stockAlerts:ov.querySelector('#mpStockAl').checked, showGoal:ov.querySelector('#mpGoal').checked, showHints:ov.querySelector('#mpHints').checked }); toast(tr('Saved')); closeModal(); });
  ov.querySelector('#mpPw').addEventListener('click', openChangePasswordSheet);
  ov.querySelector('#mpOut').addEventListener('click', logout);
}

/* ============================== EMPLOYEE TRACKING, MESSAGES, WORK REPORTS, RECORDS ============================== */
function staffList(){ return State.users.filter(function(u){ return u.role !== 'owner' && !u.pending; }); }
function trkRange(key){
  var now = new Date(), from = null;
  if(key === 'today'){ from = new Date(now.getFullYear(), now.getMonth(), now.getDate()); }
  else if(key === '7'){ from = new Date(now.getTime() - 6*86400000); from.setHours(0,0,0,0); }
  else if(key === '30'){ from = new Date(now.getTime() - 29*86400000); from.setHours(0,0,0,0); }
  else if(key === 'month'){ from = new Date(now.getFullYear(), now.getMonth(), 1); }
  return from;
}
function inRange(iso, from, to){ var t = new Date(iso).getTime(); return (!from || t >= from.getTime()) && (!to || t < to.getTime()); }
// Everything one employee did between two dates.
function staffStats(u, from, to){
  var sales = State.sales.filter(function(s){ return (s.cashierName === u.name) && inRange(s.createdAt, from, to); });
  var by = { cash:{n:0,t:0}, card:{n:0,t:0}, wallet:{n:0,t:0}, credit:{n:0,t:0} }, items = 0, cashBack = 0, pos = 0;
  sales.forEach(function(s){ salePayParts(s).forEach(function(q, qi){ var m = by[q.method] || (by[q.method] = {n:0,t:0}); if(!qi) m.n++; m.t += q.amount; }); cashBack += s.cashBack||0; if(s.viaPos) pos++; (s.items||[]).forEach(function(i){ items += i.qty||0; }); });
  var total = sales.reduce(function(a,s){ return a + s.total; }, 0);
  var tills = State.tillSessions.filter(function(t){ return t.cashierId === u.id && inRange(t.openedAt, from, to); });
  var closed = tills.filter(function(t){ return t.status === 'closed'; });
  var variance = closed.reduce(function(a,t){ return a + (t.variance||0); }, 0);
  var openTill = State.tillSessions.find(function(t){ return t.cashierId === u.id && t.status === 'open'; });
  var expected = 0; if(openTill){ var tt = tillTotals(openTill.id); expected = (openTill.openingFloat||0) + tt.totals.cash - (tt.cashBack||0); }
  var waste = State.wastage.filter(function(w){ return w.recordedBy === u.name && inRange(w.createdAt, from, to); });
  var acts = State.auditLog.filter(function(a){ return a.userId === u.id; });
  return { sales:sales, count:sales.length, total:total, avg: sales.length ? total/sales.length : 0, by:by, items:items, cashBack:cashBack, pos:pos,
    tills:tills, closed:closed, variance:variance, openTill:openTill, expected:expected, waste:waste, acts:acts };
}
function lastSeenText(u){
  var t = u.lastActiveAt ? new Date(u.lastActiveAt).getTime() : 0;
  if(!t) return tr('Not seen yet');
  var m = Math.round((Date.now() - t)/60000);
  if(m < 10) return tr('Active now');
  if(m < 60) return tr('Seen')+' '+m+' '+tr('min ago');
  return tr('Seen')+' '+fmtDateTime(u.lastActiveAt);
}
var _touchAt = 0;
function touchUserActive(force){
  try{
    if(!State.session || (!force && Date.now() - _touchAt < 5*60000)) return;
    _touchAt = Date.now();
    refs.users.doc(State.session.userId).update({ lastActiveAt:new Date().toISOString() });
  }catch(e){}
}
function syncNowSafe(){ try{ if(Sync && Sync.usable && Sync.usable()) Sync.syncNow(); }catch(e){} }
function syncStripHtml(){
  var st = { state:'off', label:'' }; try{ st = Sync.status(); }catch(e){}
  var txt = st.state === 'off' ? tr('Devices are not connected. Turn on Advanced Pesa Connection in Settings so every computer and device shares the same data.') : (st.state === 'cloud' ? tr('Live cloud storage: all devices share the same data.') : st.label);
  return '<div class="banner" style="justify-content:space-between;gap:8px;">'+ICONS.globe+'<span style="flex:1;">'+esc(txt)+'</span>'+(st.state !== 'off' && st.state !== 'cloud' ? '<button class="btn btn-ghost" data-syncnow="1" type="button" style="padding:6px 10px;font-size:12px;">'+tr('Sync now')+'</button>' : '')+'</div>';
}
function wireSyncStrip(root){ root.querySelectorAll('[data-syncnow]').forEach(function(b){ b.addEventListener('click', function(){ syncNowSafe(); toast(tr('Syncing…')); }); }); }

/* ---- owner / manager: Employee tracking tab ---- */
var TRK = { range:'today' };
function teamCardHtml(){
  if(!isManagerOrOwner()) return '';
  var staff = staffList().filter(function(u){ return u.active !== false; });
  var from = trkRange('today'), tot = 0, open = 0, drawer = 0, active = 0;
  staff.forEach(function(u){ var st = staffStats(u, from, null); tot += st.total; if(st.openTill){ open++; drawer += st.expected; } if(u.lastActiveAt && Date.now()-new Date(u.lastActiveAt).getTime() < 600000) active++; });
  var _ur = unreadMessages().length;
  return (_ur ? '<div class="me-msg" data-goinbox="1"><div class="t">'+ICONS.bolt+'<span>'+_ur+' '+tr(_ur===1?'new message':'new messages')+'</span></div><div class="s">'+esc(unreadMessages()[0].fromName+': '+msgPreview(unreadMessages()[0]).slice(0,90))+'</div></div>' : '') + '<div class="me-msg" data-goteam="1" style="border-left-color:var(--accent);"><div class="t">'+ICONS.people+'<span>'+tr('Employee tracking')+'</span></div><div class="s">' +
    (staff.length ? staff.length+' '+tr('employees')+' · '+active+' '+tr('Active now').toLowerCase()+' · '+tr('Staff sales')+' '+fmtMoney(tot)+' · '+open+' '+tr('Tills open now').toLowerCase()+' · '+fmtMoney(drawer)
      : tr('No employees yet')+'. '+tr('Add employees under Settings → Team.')) + '</div></div>';
}
var TK_CSS = '<style>' +
  '.tk{--tk-g:#0B6B50;--tk-g2:#1FA97F;--tk-y:#C97A0A;--tk-card:linear-gradient(160deg,#FFFFFF 0%,#F1F8F4 100%);}' +
  ':root[data-theme="dark"] .tk{--tk-g:#4BE3A2;--tk-y:#F2B53A;--tk-card:linear-gradient(160deg,rgba(255,255,255,.09),rgba(255,255,255,.03));}' +
  '@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .tk{--tk-g:#4BE3A2;--tk-y:#F2B53A;--tk-card:linear-gradient(160deg,rgba(255,255,255,.09),rgba(255,255,255,.03));}}' +
  '.tk-banner{position:relative;overflow:hidden;border-radius:24px;border:1px solid var(--border);background:var(--tk-card);padding:14px 14px 14px 16px;margin:2px 0 12px;box-shadow:0 12px 26px -18px rgba(8,70,50,.5);}' +
  '.tk-banner:before{content:"";position:absolute;right:-40px;bottom:-46px;width:260px;height:120px;border-radius:50%;background:radial-gradient(closest-side,rgba(43,212,160,.28),rgba(43,212,160,0));transform:rotate(-12deg);}' +
  '.tk-banner:after{content:"";position:absolute;right:-20px;bottom:-14px;width:200px;height:60px;border-radius:50%;background:linear-gradient(90deg,rgba(242,181,58,0),rgba(242,181,58,.45));transform:rotate(-10deg);}' +
  '.tk-bt{position:relative;z-index:1;display:flex;align-items:center;gap:10px;}.tk-bt h2{margin:0;font-size:22px;letter-spacing:.02em;text-transform:uppercase;font-weight:800;font-family:Inter,system-ui,sans-serif;}' +
  '.tk-bs{position:relative;z-index:1;display:flex;gap:12px;align-items:flex-start;margin-top:8px;padding-right:46px;font-size:14px;line-height:1.45;color:var(--text);}.tk-bs svg{flex:none;margin-top:2px;color:var(--tk-g);}' +
  '.tk-go{position:absolute;z-index:2;right:12px;top:50%;transform:translateY(-50%);width:44px;height:44px;border-radius:50%;border:1px solid var(--border);background:linear-gradient(160deg,#BDEBD7,#7FD0B0);color:#06513C;display:grid;place-items:center;cursor:pointer;}' +
  '.tk-pills{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin:0 0 14px;}@media (max-width:420px){.tk-pills{grid-template-columns:repeat(2,minmax(0,1fr));}}' +
  '.tk-pill{display:flex;align-items:center;justify-content:center;gap:7px;border:1px solid var(--border);border-radius:18px;background:var(--tk-card);color:var(--text);font:inherit;font-size:14px;font-weight:700;padding:12px 8px;cursor:pointer;}.tk-pill svg{flex:none;color:var(--tk-g);}' +
  '.tk-pill.active{background:linear-gradient(180deg,#0E8466,#065543);color:#fff;border-color:transparent;box-shadow:0 10px 18px -10px rgba(4,70,50,.9);}.tk-pill.active svg{color:#fff;}' +
  '.tk-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-bottom:14px;}' +
  '.tk-stat{position:relative;display:flex;align-items:center;gap:10px;min-height:88px;padding:12px 10px 12px 16px;border-radius:22px;border:1px solid var(--border);background:var(--tk-card);box-shadow:0 12px 24px -18px rgba(8,70,50,.5);overflow:hidden;}' +
  '.tk-stat:before{content:"";position:absolute;left:0;top:14%;bottom:14%;width:5px;border-radius:0 5px 5px 0;background:linear-gradient(180deg,#2BD4A0,#0B7A5C);}.tk-stat.y:before{background:linear-gradient(180deg,#F7C65A,#D18A12);}' +
  '.tk-ic{flex:none;width:46px;height:46px;border-radius:50%;display:grid;place-items:center;color:#fff;background:radial-gradient(circle at 32% 28%,#2FC79A,#07533F);box-shadow:0 8px 14px -6px rgba(4,70,50,.7),inset 0 2px 3px rgba(255,255,255,.45);}.tk-stat.y .tk-ic{background:radial-gradient(circle at 32% 28%,#FFD36E,#C97A0A);box-shadow:0 8px 14px -6px rgba(150,90,0,.7),inset 0 2px 3px rgba(255,255,255,.5);}' +
  '.tk-tx{min-width:0;flex:1;}.tk-l{font-size:10.5px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--text);opacity:.85;line-height:1.25;}.tk-v{font-size:19px;font-weight:800;line-height:1.2;margin-top:3px;color:var(--tk-g);white-space:nowrap;letter-spacing:-.03em;}@media (min-width:600px){.tk-v{font-size:25px;letter-spacing:0;}}.tk-stat.y .tk-v{color:var(--tk-y);}.tk-v.sm{font-size:13.5px;line-height:1.25;}.tk-v .tk-sub{display:block;}' +
  '.tk-corner{flex:none;align-self:flex-start;color:var(--tk-g);opacity:.9;}@media (max-width:480px){.tk-corner{display:none;}}.tk-stat.y .tk-corner{color:var(--tk-y);}' +
  '.tk-acts{display:grid;grid-template-columns:1.1fr 1fr;gap:12px;margin:0 0 14px;}@media (max-width:360px){.tk-acts{grid-template-columns:1fr;}}' +
  '.tk-act{display:flex;align-items:center;gap:10px;border-radius:20px;font:inherit;font-size:15px;font-weight:800;padding:14px 12px;cursor:pointer;border:1px solid var(--border);white-space:nowrap;}.tk-act .t{flex:1;text-align:left;overflow:hidden;text-overflow:ellipsis;}' +
  '.tk-act.main{background:linear-gradient(100deg,#0B7A5C 0%,#2AA37C 45%,#E5A12B 100%);color:#fff;border-color:transparent;box-shadow:0 12px 22px -12px rgba(150,90,0,.8);}.tk-act.alt{background:var(--tk-card);color:var(--text);}.tk-act.alt svg{color:var(--tk-g);}' +
  '.tk-empty{text-align:center;padding:14px 10px 6px;}.tk-empty .t{font-size:19px;font-weight:800;margin-top:6px;}.tk-empty .s{font-size:14.5px;color:var(--text-muted);margin-top:3px;}' +
  '.tk .rowlist .row{border-radius:20px;background:var(--tk-card);box-shadow:0 10px 20px -16px rgba(8,70,50,.5);}' +
  '</style>';
function tkIcon(k, sz){
  var a = 'viewBox="0 0 24 24" width="' + (sz || 26) + '" height="' + (sz || 26) + '" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"';
  return ({
    people:'<svg ' + a + '><circle cx="9" cy="8" r="3.2"/><path d="M3 20c0-3.3 2.7-6 6-6s6 2.7 6 6"/><circle cx="17.5" cy="9" r="2.4"/><path d="M16.5 14.3c2.6.1 4.5 2.2 4.5 5"/></svg>',
    cart:'<svg ' + a + '><path d="M3 4h2l2.4 11h10.2L20 7H6.2"/><circle cx="9" cy="19.5" r="1.4"/><circle cx="17" cy="19.5" r="1.4"/></svg>',
    clock:'<svg ' + a + '><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3.2 2"/></svg>',
    cash:'<svg ' + a + '><rect x="3" y="6" width="18" height="12" rx="2.5"/><circle cx="12" cy="12" r="2.6"/><path d="M6.5 9.5h.01M17.5 14.5h.01"/></svg>',
    pulse:'<svg ' + a + '><path d="M3 12h4l2-6 4 12 2-6h6"/></svg>',
    card:'<svg ' + a + '><rect x="3" y="5" width="18" height="14" rx="2.5"/><path d="M3 10h18M7 15h4"/></svg>',
    trend:'<svg ' + a + '><path d="M3 17l6-6 4 4 8-8M15 7h6v6"/></svg>',
    shop:'<svg ' + a + '><path d="M4 9l1.5-5h13L20 9M4 9v11h16V9M4 9c0 1.7 1.3 3 3 3s3-1.3 3-3c0 1.7 1.3 3 3 3s3-1.3 3-3c0 1.7 1.3 3 3 3M10 20v-5h4v5"/></svg>',
    user:'<svg ' + a + '><circle cx="12" cy="8" r="3.4"/><path d="M5 20c0-3.6 3-6.2 7-6.2s7 2.6 7 6.2"/></svg>',
    wallet:'<svg ' + a + '><rect x="3" y="6" width="18" height="13" rx="2.5"/><path d="M3 10h18M16 14.5h2"/></svg>',
    cal:'<svg ' + a + '><rect x="3.5" y="5" width="17" height="15" rx="2.5"/><path d="M3.5 10h17M8 3v4M16 3v4M8 14h.01M12 14h.01M16 14h.01"/></svg>',
    grid:'<svg ' + a + '><rect x="4" y="4" width="6.5" height="6.5" rx="1.5"/><rect x="13.5" y="4" width="6.5" height="6.5" rx="1.5"/><rect x="4" y="13.5" width="6.5" height="6.5" rx="1.5"/><rect x="13.5" y="13.5" width="6.5" height="6.5" rx="1.5"/></svg>',
    send:'<svg ' + a + '><path d="M21 3L3 11l7 3 3 7z"/><path d="M10 14l11-11"/></svg>',
    chat:'<svg ' + a + '><path d="M4 5h16v11H9l-5 4z"/><path d="M8.5 10.5h.01M12 10.5h.01M15.5 10.5h.01"/></svg>',
    arrow:'<svg ' + a + '><path d="M9 5l7 7-7 7"/></svg>',
    globe:'<svg ' + a + '><circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c3 3.3 3 14.7 0 18M12 3c-3 3.3-3 14.7 0 18"/></svg>'
  })[k] || '';
}
function tkStat(ic, label, value, y, corner, small){
  return '<div class="tk-stat' + (y ? ' y' : '') + '"><span class="tk-ic">' + tkIcon(ic, 28) + '</span><div class="tk-tx"><div class="tk-l">' + label + '</div><div class="tk-v num' + (small ? ' sm' : '') + '">' + value + '</div></div><span class="tk-corner">' + tkIcon(corner, 22) + '</span></div>';
}
function tkBannerHtml(){
  var st = { state:'off', label:'' }; try{ st = Sync.status(); }catch(e){}
  var txt = st.state === 'off' ? tr('Devices are not connected. Turn on Advanced Pesa Connection in Settings so every computer and device shares the same data.') : (st.state === 'cloud' ? tr('Live cloud storage: all devices share the same data.') : st.label);
  var act = st.state === 'off' ? tr('Open Settings') : (st.state !== 'cloud' ? tr('Sync now') : '');
  return '<div class="tk-banner"><div class="tk-bt"><span style="color:var(--tk-g);">' + tkIcon('people', 34) + '</span><h2>' + tr('Employee tracking') + '</h2></div>' +
    '<div class="tk-bs">' + tkIcon('globe', 24) + '<span>' + esc(txt) + '</span></div>' +
    (act ? '<button class="tk-go" data-trkgo="' + (st.state === 'off' ? 'settings' : 'sync') + '" type="button" aria-label="' + esc(act) + '">' + tkIcon('arrow', 22) + '</button>' : '') + '</div>';
}
function renderTeamTracking(){
  if(!isManagerOrOwner()) return '<div class="empty"><div class="t">'+tr('Only the owner and managers can see this.')+'</div></div>';
  var from = trkRange(TRK.range), staff = staffList();
  var h = TK_CSS + '<div class="tk">' + tkBannerHtml();
  h += '<div class="tk-pills">' + [['today','Today','cal'],['7','Last 7 days','cal'],['month','This month','cal'],['all','All','grid']].map(function(r){ return '<button class="tk-pill'+(TRK.range===r[0]?' active':'')+'" data-trk="'+r[0]+'" type="button">'+tkIcon(r[2], 20)+'<span>'+tr(r[1])+'</span></button>'; }).join('') + '</div>';
  var stats = staff.map(function(u){ return { u:u, s:staffStats(u, from, null) }; }).sort(function(a,b){ return b.s.total - a.s.total; });
  var team = stats.reduce(function(a,x){ a.total += x.s.total; a.count += x.s.count; a.cash += x.s.by.cash.t; a.card += x.s.by.card.t; a.drawer += x.s.openTill ? x.s.expected : 0; a.open += x.s.openTill ? 1 : 0; a.active += (x.u.lastActiveAt && Date.now()-new Date(x.u.lastActiveAt).getTime() < 600000) ? 1 : 0; return a; }, { total:0, count:0, cash:0, card:0, drawer:0, open:0, active:0 });
  h += '<div class="tk-grid">' +
    tkStat('people', tr('Staff sales'), fmtMoney(team.total), false, 'trend') +
    tkStat('cart', tr('Sales'), team.count, true, 'trend') +
    tkStat('clock', tr('Tills open now'), team.open, false, 'shop') +
    tkStat('cash', tr('Cash in open tills'), fmtMoney(team.drawer), true, 'wallet') +
    tkStat('pulse', tr('Active now'), team.active + ' / ' + staff.length, false, 'user') +
    tkStat('card', tr('Cash') + ' / ' + tr('Card'), fmtMoney(team.cash) + '<span class="tk-sub">/ ' + fmtMoney(team.card) + '</span>', true, 'card', true) + '</div>';
  h += '<div class="tk-acts"><button class="tk-act main" data-trkmsg="all" type="button">'+tkIcon('send', 22)+'<span class="t">'+tr('Send a message')+'</span>'+tkIcon('arrow', 16)+'</button><button class="tk-act alt" data-trklog="1" type="button">'+tkIcon('chat', 22)+'<span class="t">'+tr('Messages')+(unreadMessages().length?' ('+unreadMessages().length+')':'')+'</span>'+tkIcon('arrow', 16)+'</button></div>';
  if(!staff.length) return h + '<div class="tk-empty"><span style="color:var(--tk-g);">'+tkIcon('people', 46)+'</span><div class="t">'+tr('No employees yet')+'</div><div class="s">'+tr('Add employees under Settings → Team.')+'</div></div></div>';
  var best = stats[0] && stats[0].s.total > 0 ? stats[0].u.id : null;
  h += '<div class="rowlist">' + stats.map(function(x){
    var u = x.u, s = x.s;
    var tillTxt = s.openTill ? tr('Till open')+' · '+fmtMoney(s.expected)+' '+tr('expected') : tr('Till closed');
    var varTxt = s.closed.length ? (Math.abs(s.variance) < 0.01 ? tr('Cash ups balanced') : (s.variance < 0 ? tr('Short')+' '+fmtMoney(Math.abs(s.variance)) : tr('Over')+' '+fmtMoney(s.variance))) : '';
    var main = u.role === 'stockclerk' ? s.waste.length+' '+tr('wastage records') : s.count+' '+tr('sales')+' · '+tr('avg')+' '+fmtMoney(s.avg);
    return '<div class="row" data-trku="'+u.id+'"><div class="avatar">'+userAvatarInner(u)+'</div><div class="main"><div class="title">'+esc(u.name)+(u.id===best?' ★':'')+(u.active===false?' ('+tr('deactivated')+')':'')+'</div>' +
      '<div class="sub">'+esc(u.jobTitle||tr(ROLE_LABELS[u.role]||u.role))+' · '+esc(lastSeenText(u))+'</div>' +
      '<div class="sub">'+esc(main)+(u.role!=='stockclerk'?' · '+esc(tillTxt):'')+(varTxt?' · '+esc(varTxt):'')+'</div></div>' +
      '<div class="trail"><div class="amt num">'+(u.role==='stockclerk'?'':fmtMoney(s.total))+'</div></div></div>';
  }).join('') + '</div></div>';
  return h;
}
function wireTeamTracking(root){
  wireSyncStrip(root);
  root.querySelectorAll('[data-trkgo]').forEach(function(b){ b.addEventListener('click', function(){ if(b.getAttribute('data-trkgo') === 'settings') openSettingsSheet(); else { syncNowSafe(); toast(tr('Syncing…')); } }); });
  root.querySelectorAll('[data-trk]').forEach(function(b){ b.addEventListener('click', function(){ TRK.range = b.getAttribute('data-trk'); render(); }); });
  root.querySelectorAll('[data-trku]').forEach(function(b){ b.addEventListener('click', function(){ openStaffDetailSheet(b.getAttribute('data-trku')); }); });
  root.querySelectorAll('[data-trkmsg]').forEach(function(b){ b.addEventListener('click', function(){ openComposeMessageSheet(b.getAttribute('data-trkmsg')); }); });
  root.querySelectorAll('[data-trklog]').forEach(function(b){ b.addEventListener('click', openInboxSheet); });
}
function openStaffDetailSheet(uid){
  var u = State.users.find(function(x){ return x.id === uid; }); if(!u) return;
  var from = trkRange(TRK.range), s = staffStats(u, from, null), all = staffStats(u, null, null);
  function line(a,b){ return '<div class="sumline"><span>'+a+'</span><span class="num" style="text-align:right;">'+b+'</span></div>'; }
  var rangeLbl = { today:'Today', '7':'Last 7 days', month:'This month', all:'All' }[TRK.range];
  var h = '<div class="sheet-head"><h2>'+esc(u.name)+'</h2></div>' +
    '<div style="font-size:13px;color:var(--text-muted);margin-bottom:8px;">'+esc(u.jobTitle||tr(ROLE_LABELS[u.role]||u.role))+(u.employeeNo?' · '+esc(u.employeeNo):'')+' · '+esc(lastSeenText(u))+'</div>' +
    '<div style="font-size:12.5px;color:var(--text-muted);margin-bottom:8px;">'+(u.joinedAt?tr('Joined')+' '+fmtDateTime(u.joinedAt):'')+(u.approvedBy?' · '+tr('Approved by')+' '+esc(u.approvedBy):'')+(u.phone?' · '+esc(u.phone):'')+(u.email?' · '+esc(u.email):'')+' · '+tr('Point of sale')+': '+(u.posAccess===false||u.role==='stockclerk'?tr('No'):tr('Yes'))+'</div>' +
    '<div class="section-title">'+tr(rangeLbl)+'</div>';
  if(u.role === 'stockclerk'){
    h += line(tr('Wastage records'), s.waste.length) + s.waste.slice(0,15).map(function(w){ return line(esc(fmtDateTime(w.createdAt))+' · '+esc(w.productName||''), w.qty+' · '+esc(w.reason||'')); }).join('');
  } else {
    h += line(tr('Sales'), s.count) + line(tr('Total'), fmtMoney(s.total)) + line(tr('Average sale'), fmtMoney(s.avg)) + line(tr('Items sold'), s.items) + line(tr('On the point of sale'), s.pos) +
      line(tr('Cash'), fmtMoney(s.by.cash.t)+' · '+s.by.cash.n) + line(tr('Card'), fmtMoney(s.by.card.t)+' · '+s.by.card.n) + line(tr('Mobile wallet'), fmtMoney(s.by.wallet.t)+' · '+s.by.wallet.n) + line(tr('Credit'), fmtMoney(s.by.credit.t)+' · '+s.by.credit.n) +
      (s.cashBack ? line(tr('Cash back paid out'), fmtMoney(s.cashBack)) : '') +
      '<div class="section-title">'+tr('Till and cash')+'</div>' +
      (s.openTill ? line(tr('Till open since'), fmtDateTime(s.openTill.openedAt)) + line(tr('Cash expected in drawer'), fmtMoney(s.expected)) : line(tr('Till'), tr('Closed'))) +
      line(tr('Cash ups'), s.closed.length) + (s.closed.length ? line(tr('Total variance'), (Math.abs(s.variance)<0.01?tr('Balanced'):fmtMoney(s.variance))) : '') +
      s.closed.slice(0,6).map(function(t){ return line(esc(fmtDay(t.closedAt)), fmtMoney(t.countedCash!=null?t.countedCash:0)+' · '+(Math.abs(t.variance||0)<0.01?tr('Balanced'):fmtMoney(t.variance||0))); }).join('') +
      '<div class="section-title">'+tr('Recent sales')+'</div>' + (s.sales.length ? '<div class="rowlist">'+s.sales.slice(0,10).map(function(x){ return '<div class="row" data-sdsale="'+x.id+'"><div class="main"><div class="title">'+esc(posSaleWho(x))+'</div><div class="sub">'+esc(fmtDateTime(x.createdAt))+' · '+esc(x.paymentMethod||'cash')+'</div></div><div class="trail"><div class="amt num">'+fmtMoney(x.total)+'</div></div></div>'; }).join('')+'</div>' : '<div style="font-size:13px;color:var(--text-muted);">'+tr('No sales yet.')+'</div>') +
      '<div class="section-title">'+tr('All time')+'</div>' + line(tr('Sales'), all.count) + line(tr('Total'), fmtMoney(all.total));
  }
  h += '<div class="section-title">'+tr('Activity')+'</div>' + (all.acts.length ? all.acts.slice(0,10).map(function(a){ return '<div style="font-size:12.5px;padding:4px 0;border-bottom:1px dashed var(--border);">'+esc(a.summary||a.action)+' <span style="color:var(--text-muted);">· '+esc(fmtDateTime(a.createdAt))+'</span></div>'; }).join('') : '<div style="font-size:13px;color:var(--text-muted);">'+tr('No activity yet.')+'</div>');
  h += '<div class="actions" style="margin-top:12px;"><button class="btn btn-accent btn-block" id="sdMsg" type="button">'+tr('Send a message')+'</button><button class="btn btn-ghost btn-block" id="sdRep" type="button">'+tr('Work report')+'</button></div>' +
    '<div class="actions" style="margin-top:8px;"><button class="btn btn-ghost btn-block" id="sdEdit" type="button">'+tr('Edit access')+'</button><button class="btn btn-ghost btn-block" id="sdClose" type="button">'+tr('Close')+'</button></div>';
  var ov = openSheet(h);
  ov.querySelector('#sdClose').addEventListener('click', closeModal);
  ov.querySelector('#sdMsg').addEventListener('click', function(){ openComposeMessageSheet(u.id); });
  ov.querySelector('#sdRep').addEventListener('click', function(){ openWorkReportSheet(u.id); });
  ov.querySelector('#sdEdit').addEventListener('click', function(){ openStaffSheet(u); });
  ov.querySelectorAll('[data-sdsale]').forEach(function(b){ b.addEventListener('click', function(){ openPosSaleDetail(b.getAttribute('data-sdsale')); }); });
}

