var MV_EMOJI = ['😀','😂','😊','😍','😎','😅','🤔','😢','😡','👍','👌','🙏','👏','🙌','💪','🤝','👋','🔥','💯','✅','❌','⚠️','⭐','🎉','❤️','💰','🛒','📦','🧾','🕒','🚚','📞','📷','🍞','🥩','🥤','🍺','🏪'];
function msgDur(s){ s = Math.max(0, Math.round(+s || 0)); return Math.floor(s/60)+':'+('0'+(s%60)).slice(-2); }
function msgPreview(m){
  var b = String(m.body||'').trim();
  if(m.mediaGone && !b && !m.img && !m.audio) return (/img/.test(m.mediaGone) ? '📷 ' : '🎤 ')+tr('Removed to save space');
  if(m.img && !b) return '📷 '+tr('Photo');
  if(m.audio && !b) return '🎤 '+tr('Voice message')+' '+msgDur(m.dur);
  return (m.img ? '📷 ' : m.audio ? '🎤 ' : '') + b;
}
// ---- keeping chat storage small: photos and voice notes are removed after a while, the words stay ----
function msgMediaBytes(){ var n = 0; State.messages.forEach(function(m){ if(m.img) n += m.img.length; if(m.audio) n += m.audio.length; }); return Math.round(n * 0.75); }
function msgMediaDays(){ var d = State.settings && State.settings.msgMediaDays; return d === 0 ? 0 : (d > 0 ? d : 60); }
function msgMb(b){ return b < 100*1024 ? Math.max(0, Math.round(b/1024))+' KB' : (b/1048576).toFixed(1)+' MB'; }
var _msgSwept = false;
function msgSweepMedia(force){
  if(!isManagerOrOwner()) return 0;
  var days = msgMediaDays(); if(!days) return 0;
  var cutoff = Date.now() - days * 86400000, n = 0;
  State.messages.forEach(function(m){
    if(!(m.img || m.audio) || new Date(m.createdAt).getTime() > cutoff) return;
    n++;
    refs.messages.doc(m.id).update({ img:'', audio:'', mediaGone:(m.img ? 'img' : '') + (m.audio ? 'audio' : '') });
  });
  if(n){ syncNowSafe(); try{ logAudit('other','message',null,'Removed photos and voice notes older than '+days+' days from '+n+' messages'); }catch(e){} }
  return n;
}
function msgDayLabel(iso){
  var d = new Date(iso), now = new Date(), y = new Date(now.getTime() - 86400000);
  if(d.toDateString() === now.toDateString()) return tr('Today');
  if(d.toDateString() === y.toDateString()) return tr('Yesterday');
  return d.toLocaleDateString(uiLocale(), { weekday:'short', day:'numeric', month:'long', year: d.getFullYear() === now.getFullYear() ? undefined : 'numeric' });
}
function msgBlobToDataUrl(blob){
  return new Promise(function(res, rej){ var fr = new FileReader(); fr.onload = function(){ res(String(fr.result)); }; fr.onerror = function(){ rej(fr.error); }; fr.readAsDataURL(blob); });
}
// Photos are shrunk until they fit the size a synced record can hold.
function msgCompressImage(file){
  var tries = [[1100,0.8],[900,0.7],[720,0.6],[560,0.5],[420,0.45]], i = 0;
  return new Promise(function(res, rej){
    (function next(){
      if(i >= tries.length){ rej(new Error('too big')); return; }
      var t = tries[i++];
      resizeImageFile(file, t[0], t[1]).then(function(r){ if(r.dataUrl.length <= MSG_IMG_MAX) res(r); else next(); }, rej);
    })();
  });
}
// One recorder shared by the chat and the compose sheet.
var MsgRec = {
  mr:null, stream:null, chunks:[], t0:0, timer:0, mime:'',
  supported:function(){ return !!(navigator.mediaDevices && navigator.mediaDevices.getUserMedia && window.MediaRecorder); },
  _mime:function(){ var c = ['audio/webm;codecs=opus','audio/webm','audio/mp4','audio/ogg;codecs=opus']; for(var i = 0; i < c.length; i++){ try{ if(MediaRecorder.isTypeSupported(c[i])) return c[i]; }catch(e){} } return ''; },
  _release:function(){ if(this.timer){ clearInterval(this.timer); this.timer = 0; } if(this.stream){ try{ this.stream.getTracks().forEach(function(t){ t.stop(); }); }catch(e){} this.stream = null; } },
  active:function(){ return !!(this.mr && this.mr.state === 'recording'); },
  start:function(onTick, onLimit){
    var self = this;
    self.cancel();
    return navigator.mediaDevices.getUserMedia({ audio:{ echoCancellation:true, noiseSuppression:true, autoGainControl:true } }).then(function(stream){
      self.stream = stream; self.chunks = []; self.mime = self._mime();
      var mr;
      try{ mr = self.mime ? new MediaRecorder(stream, { mimeType:self.mime, audioBitsPerSecond:24000 }) : new MediaRecorder(stream); }
      catch(e){ mr = new MediaRecorder(stream); }
      self.mr = mr;
      mr.ondataavailable = function(e){ if(e.data && e.data.size) self.chunks.push(e.data); };
      mr.start(250); self.t0 = Date.now();
      self.timer = setInterval(function(){
        var s = (Date.now() - self.t0) / 1000;
        if(onTick) onTick(s);
        if(s >= MSG_VOICE_LIMIT){ clearInterval(self.timer); self.timer = 0; if(onLimit) onLimit(); }
      }, 250);
    });
  },
  stop:function(){
    var self = this, mr = self.mr;
    return new Promise(function(res){
      if(!mr || mr.state !== 'recording'){ self._release(); res(null); return; }
      mr.onstop = function(){
        var dur = (Date.now() - self.t0) / 1000, type = mr.mimeType || self.mime || 'audio/webm';
        self._release(); self.mr = null;
        res({ blob:new Blob(self.chunks, { type:type }), dur:dur });
      };
      try{ mr.stop(); }catch(e){ self._release(); self.mr = null; res(null); }
    });
  },
  cancel:function(){
    var mr = this.mr; this.mr = null;
    if(mr){ mr.onstop = null; mr.ondataavailable = null; try{ if(mr.state === 'recording') mr.stop(); }catch(e){} }
    this._release();
  }
};
var _msgAudio = null;   // { id, el } while a voice note plays
function msgNetSig(){ var p = 0; try{ p = Sync.pendingCount(); }catch(e){} return p+'|'+(navigator.onLine?1:0)+'|'+(Sync.usable()?1:0); }
function msgSyncChanged(){
  if(!_openThread || !_openThread.paint || !document.getElementById('mvThread')) return;
  var sg = msgNetSig(); if(sg === _openThread.sig) return;
  _openThread.sig = sg; _openThread.paint();
}
// A thin strip under the chat header that says where messages are going.
function msgNetStrip(){
  var on = false; try{ on = Sync.usable(); }catch(e){}
  if(on && !navigator.onLine) return '<div class="mv-net off">'+tr('You are offline. Messages are saved on this device and will send when you are back online.')+'</div>';
  if(!on && staffList().length) return '<div class="mv-net">'+tr('Advanced Pesa Connection is off, so messages stay on this device. Turn it on in Settings so other devices receive them.')+'</div>';
  return '';
}
function msgCleanup(){
  try{ MsgRec.cancel(); }catch(e){}
  try{ if(_msgAudio){ _msgAudio.el.pause(); } }catch(e){}
  _msgAudio = null;
}
function msgVoiceHtml(x){
  var h = 0, bars = ''; String(x.id).split('').forEach(function(c){ h = (h*33 + c.charCodeAt(0)) % 9973; });
  for(var i = 0; i < 26; i++){ h = (h*131 + 17) % 9973; bars += '<i style="height:'+(18 + (h % 70))+'%"></i>'; }
  return '<div class="mv-voice"><button type="button" class="mv-vp" data-play="'+x.id+'" aria-label="'+tr('Play voice message')+'">'+MV_IC.play+'</button><div class="mv-wave" data-wave="'+x.id+'">'+bars+'</div><span class="mv-vd" data-vd="'+x.id+'">'+msgDur(x.dur)+'</span></div>';
}
function msgPlayUi(box){
  box.querySelectorAll('[data-play]').forEach(function(b){
    var id = b.getAttribute('data-play'), on = _msgAudio && _msgAudio.id === id && !_msgAudio.el.paused;
    b.innerHTML = on ? MV_IC.pause : MV_IC.play;
    var w = box.querySelector('[data-wave="'+id+'"]'); if(!w) return;
    var m = State.messages.find(function(x){ return x.id === id; }), dur = (m && m.dur) || 1, el = _msgAudio && _msgAudio.id === id ? _msgAudio.el : null;
    var frac = el ? Math.min(1, el.currentTime / dur) : 0, n = w.children.length, k = Math.round(frac * n);
    for(var i = 0; i < n; i++) w.children[i].classList.toggle('on', i < k);
    var d = box.querySelector('[data-vd="'+id+'"]'); if(d) d.textContent = el && on ? msgDur(el.currentTime) : msgDur(dur);
  });
}
function msgWirePlayers(box){
  box.querySelectorAll('[data-play]').forEach(function(b){
    b.addEventListener('click', function(){
      var id = b.getAttribute('data-play'), m = State.messages.find(function(x){ return x.id === id; }); if(!m || !m.audio) return;
      if(_msgAudio && _msgAudio.id === id){ if(_msgAudio.el.paused) _msgAudio.el.play().catch(function(){}); else _msgAudio.el.pause(); msgPlayUi(box); return; }
      if(_msgAudio){ try{ _msgAudio.el.pause(); }catch(e){} }
      var el = new Audio(m.audio); _msgAudio = { id:id, el:el };
      var host = box;
      el.addEventListener('timeupdate', function(){ if(_msgAudio && _msgAudio.el === el) msgPlayUi(host.isConnected ? host : document); });
      el.addEventListener('ended', function(){ el.currentTime = 0; msgPlayUi(host.isConnected ? host : document); });
      el.addEventListener('pause', function(){ msgPlayUi(host.isConnected ? host : document); });
      el.play().then(function(){ msgPlayUi(box); }).catch(function(){ toast(tr('Could not play this voice note.')); });
    });
  });
  msgPlayUi(box);
}
function msgLightbox(ov, src){
  var lb = document.createElement('div'); lb.className = 'mv-lb';
  src = safeImg(src); lb.innerHTML = '<img src="'+esc(src)+'" alt="">' + '<div class="mv-lbbar"><a class="btn btn-accent" download="pesa-photo.jpg" href="'+esc(src)+'">'+tr('Save photo')+'</a><button type="button" class="btn btn-ghost" data-lbx>'+tr('Close')+'</button></div>';
  lb.addEventListener('click', function(e){ if(e.target === lb || e.target.hasAttribute('data-lbx')) lb.remove(); });
  ov.appendChild(lb);
}
