/* ---- team management (owner adds managers & cashiers; manager adds cashiers) ---- */
function openTeamSheet(){
  if(!secAllow('manager', 'opening the team list')) return;
  var html = '<div class="sheet-head"><h2>'+tr('Team')+'</h2></div>' +
    '<div class="banner">'+tr('Managers and Supervisors can see everything except your company’s legal details. Cashiers can only sell and run their own till.')+'</div>' +
    '<div id="teamList"></div>' +
    '<div class="actions"><button class="btn btn-primary btn-block" id="teamAddBtn">'+tr('Add staff member')+'</button></div>';
  var ov = openSheet(html);
  function renderList(){
    var list = ov.querySelector('#teamList');
    if(State.users.length === 0){ list.innerHTML = '<div class="empty" style="padding:16px 0;">'+tr('No staff yet')+'</div>'; return; }
    list.innerHTML = State.users.map(function(u){
      var isMe = State.session && State.session.userId === u.id;
      return '<div class="staffrow'+(u.active===false?' inactive':'')+'" data-staffrow="'+u.id+'">' +
        '<div class="avatar" style="width:34px;height:34px;border-radius:9px;background:var(--surface-3);display:flex;align-items:center;justify-content:center;color:var(--primary-dim);font-weight:700;font-size:12px;flex-shrink:0;">'+esc(initials(u.name))+'</div>' +
        '<div class="main"><div class="n">'+esc(u.name)+(isMe?' ('+tr('you')+')':'')+'</div><div class="e">'+esc(u.email||'')+'</div></div>' +
        (u.pending ? '<span class="rolebadge pending">'+tr('Invited')+'</span>' : '<span class="rolebadge '+u.role+'">'+esc(tr(ROLE_LABELS[u.role]||u.role))+'</span>') +
      '</div>';
    }).join('');
    list.querySelectorAll('[data-staffrow]').forEach(function(row){
      row.addEventListener('click', function(){
        var u = State.users.find(function(x){ return x.id===row.getAttribute('data-staffrow'); });
        if(u && u.pending) openInviteSheet(u); else if(u) openStaffSheet(u);
      });
    });
  }
  renderList();
  ov.querySelector('#teamAddBtn').addEventListener('click', function(){ openStaffSheet(null); });
}

/** A person who has sold something or run a till is kept (deactivate them instead) so reports and the books stay correct. */
function staffHasRecords(u){
  return State.sales.some(function(x){ return x.cashierName === u.name; }) || State.tillSessions.some(function(t){ return t.cashierId === u.id; }) ||
    State.wastage.some(function(w){ return w.recordedBy === u.name; });
}
function openStaffSheet(user){
  if(!secAllow('manager', 'editing staff')) return;
  if(user && user.role === 'owner' && !isOwner()){ secBlocked('opening the owner account'); return; }
  if(user && user.role === 'manager' && !isOwner() && !(State.session && State.session.userId === user.id)){ secBlocked('editing another manager'); return; }
  var isEdit = !!user;
  var isMe = isEdit && State.session && State.session.userId === user.id;
  var canPickManager = isOwner(); // only the Owner can create/change Managers
  var roleOpts =
    (canPickManager ? '<option value="manager" '+(user&&user.role==='manager'?'selected':'')+'>'+tr('Manager / Supervisor')+'</option>' : '') +
    '<option value="cashier" '+(!user||user.role==='cashier'?'selected':'')+'>'+tr('Cashier')+'</option>' +
    '<option value="stockclerk" '+(user&&user.role==='stockclerk'?'selected':'')+'>'+tr('Stock clerk')+'</option>';
  var sfMode = 'invite';
  var html = '<div class="sheet-head"><h2>'+(isEdit?tr('Edit staff member'):tr('Add staff member'))+'</h2></div>' +
    '<div class="field"><label>'+tr('Full name')+'</label><input id="sfName" value="'+esc(user?user.name:'')+'"></div>' +
    '<div class="field"><label>'+tr('Role')+'</label><select id="sfRole" '+(isMe?'disabled':'')+'>'+roleOpts+'</select></div>' +
    '<div class="field"><label>'+tr('Job title (optional)')+'</label><input id="sfJob" placeholder="'+tr('e.g. Front till cashier')+'" value="'+esc(user&&user.jobTitle||'')+'"></div>' +
    '<div id="sfRoleInfo"></div>' +
    '<div class="field" id="sfPosBox"><label><input type="checkbox" id="sfPos" style="width:auto;margin-right:8px;" '+(!user || user.posAccess !== false ? 'checked' : '')+'>'+tr('Can use the Point of sale')+'</label><div style="font-size:12px;color:var(--text-muted);margin-top:4px;">'+tr('Cashiers sign in on the point of sale with the same private PIN they choose when they create their account.')+'</div></div>' +
    (!isEdit ? '<div class="field"><label>'+tr('How do they get access?')+'</label><div class="segbtns"><button type="button" class="segbtn active" data-sfmode="invite">'+tr('They create their own account')+'</button><button type="button" class="segbtn" data-sfmode="direct">'+tr('I set their PIN or password')+'</button></div></div>' +
      '<div class="field" id="sfContactBox"><label>'+tr('Phone or email (optional)')+'</label><input id="sfContact" placeholder="081 234 5678 or name@example.com"></div>' : '') +
    '<div id="sfCredFields"></div>' +
    (isEdit ? '<div class="field"><label>'+tr('Reset password / PIN (leave blank to keep current)')+'</label><input id="sfNewPass" type="password" placeholder="New password or PIN"></div>' : '') +
    '<div id="sfError"></div>' +
    '<div class="actions">' +
      (isEdit && !isMe ? '<button class="btn '+(user.active===false?'btn-primary':'btn-danger')+'" id="sfToggleActive">'+(user.active===false?tr('Reactivate'):tr('Deactivate'))+'</button>' : '') +
      (isEdit && !isMe && isOwner() && user.role !== 'owner' ? '<button class="btn btn-danger" id="sfDelete" type="button">'+tr('Remove')+'</button>' : '') +
      '<button class="btn btn-primary btn-block" id="sfSave">'+(isEdit?tr('Save changes'):tr('Add staff member'))+'</button>' +
    '</div>';
  var ov = openSheet(html, {center:true});
  function renderCredFields(){
    var role = ov.querySelector('#sfRole').value;
    var f = ov.querySelector('#sfCredFields');
    var ri = ROLE_INFO[role];
    ov.querySelector('#sfPosBox').style.display = role === 'stockclerk' ? 'none' : '';
    ov.querySelector('#sfRoleInfo').innerHTML = ri ? '<div class="banner" style="display:block;font-size:12.5px;"><b>'+tr('What this job can do')+'</b><br>'+ri.can.map(function(x){ return '✓ '+esc(tr(x)); }).join('<br>')+'<br><b>'+tr('Not allowed')+'</b><br>'+ri.cannot.map(function(x){ return '✗ '+esc(tr(x)); }).join('<br>')+'</div>' : '';
    if(isEdit){ f.innerHTML=''; return; }
    var cb = ov.querySelector('#sfContactBox'); if(cb) cb.style.display = sfMode === 'invite' ? '' : 'none';
    if(sfMode === 'invite'){ f.innerHTML = '<div class="banner">'+ICONS.info+'<span>'+tr('You get an invite code to give them. They open Pesa, tap New employee sign up, enter the code and choose their own PIN or password.')+'</span></div>'; return; }
    if(role === 'cashier'){
      f.innerHTML = '<div class="field"><label>'+tr('4-digit PIN (used to log in)')+'</label><input id="sfEmail" style="display:none;"><input id="sfPass" type="password" inputmode="numeric" maxlength="4" placeholder="e.g. 4821"></div>';
    } else {
      f.innerHTML = '<div class="field"><label>'+tr('Phone or email (optional, used to log in)')+'</label><input id="sfEmail" placeholder="081 234 5678 or name@example.com"></div>' +
        '<div class="field"><label>'+tr('Password')+'</label><input id="sfPass" type="password" placeholder="At least 4 characters"></div>';
    }
  }
  renderCredFields();
  ov.querySelector('#sfRole').addEventListener('change', renderCredFields);
  ov.querySelectorAll('[data-sfmode]').forEach(function(b){ b.addEventListener('click', function(){ sfMode = b.getAttribute('data-sfmode'); ov.querySelectorAll('[data-sfmode]').forEach(function(x){ x.classList.toggle('active', x===b); }); renderCredFields(); }); });
  var sfDel = ov.querySelector('#sfDelete');
  if(sfDel) sfDel.addEventListener('click', function(){
    var hist = staffHasRecords(user);
    confirmSheet(tr('Remove')+' '+user.name+'?', hist ? tr('Their login and Point of sale access are removed. Their past sales and till records stay under their name, so no history is lost. A copy of the staff record is kept in the archive.') : tr('Their login and Point of sale access are removed. A copy of the staff record is kept in the archive.'), tr('Remove'), function(){
      if(!secAllow('owner', 'removing a staff member')) return;
      secAskEveryTime(tr('Enter your password to remove this staff member'), function(){
        secWithReason('Staff member removed', function(){ archiveRemoved('users', user.id, Object.assign({}, user, { passHash:'', inviteCode:'' })); guardRun(function(){ refs.users.doc(user.id).delete(); }); });
        logAudit('delete','staff',user.id,'Removed staff member '+user.name); toast(tr('Staff member removed')); openTeamSheet();
      });
    }, true, true);
  });
  if(isEdit && !isMe){
    ov.querySelector('#sfToggleActive').addEventListener('click', function(){
      var nowActive = user.active === false;
      refs.users.doc(user.id).update({ active: nowActive });
      logAudit('update','staff',user.id,(nowActive?'Reactivated ':'Deactivated ')+user.name);
      toast(nowActive ? tr('Staff member reactivated') : tr('Staff member deactivated'));
      openTeamSheet();
    });
  }
  ov.querySelector('#sfSave').addEventListener('click', function(){
    var name = ov.querySelector('#sfName').value.trim();
    var role = ov.querySelector('#sfRole').value;
    var errEl = ov.querySelector('#sfError');
    errEl.innerHTML = '';
    function fail(msg){ errEl.innerHTML = '<div class="banner">'+ICONS.warn+'<span>'+esc(msg)+'</span></div>'; }
    if(!name) return fail(tr('Enter a name.'));
    (async function(){
      if(isEdit){
        var patch = { name:name, jobTitle: ov.querySelector('#sfJob').value.trim(), posAccess: (isMe ? user.posAccess !== false : (role !== 'stockclerk' && ov.querySelector('#sfPos').checked)) };
        if(!isMe) patch.role = role;
        var newPass = ov.querySelector('#sfNewPass') ? ov.querySelector('#sfNewPass').value : '';
        if(newPass){
          if(role === 'cashier' ? !/^\d{4}$/.test(newPass) : !!pwProblem(newPass)) return fail(role === 'cashier' ? tr('PIN must be exactly 4 digits.') : pwProblem(newPass));
          patch.passHash = await pwHash(newPass);
        }
        var doSave = function(){
        refs.users.doc(user.id).update(patch);
        logAudit('update','staff',user.id,'Edited '+name+(patch.passHash ? ' (password or PIN reset)' : ''));
        if(patch.passHash) logAudit('other','security',user.id,'Password or PIN reset for '+name+' by '+(State.session ? State.session.name : ''));
        toast(tr('Staff member updated'));
        if(isMe) State.session.name = name;
        openTeamSheet();
        };
        if(patch.passHash && !isMe) secReauth(tr('Confirm with your own password or PIN to reset theirs'), doSave); else doSave();
      } else {
        if(!licAllow('users')) return;
        if(sfMode === 'invite'){
          var ct = (ov.querySelector('#sfContact').value||'').trim();
          var invRef = refs.users.doc();
          var rec = { name:name, role:role, jobTitle:ov.querySelector('#sfJob').value.trim(), email: ct.indexOf('@')>-1 ? ct.toLowerCase() : '', phone: ct.indexOf('@')>-1 ? '' : ct,
            pending:true, active:true, passHash:'', inviteCode:newInviteCode(), inviteExpires:new Date(Date.now()+7*86400000).toISOString(),
            employeeNo:nextEmployeeNo(), createdAt:new Date().toISOString(), approvedBy:State.session.name, approvedAt:new Date().toISOString(), posAccess: role !== 'stockclerk' && ov.querySelector('#sfPos').checked };
          invRef.set(rec);
          logAudit('create','staff',invRef.id,'Invited '+name+' as '+role);
          openInviteSheet(Object.assign({id:invRef.id}, rec));
          return;
        }
        var email = (ov.querySelector('#sfEmail').value||'').trim().toLowerCase();
        var pass = ov.querySelector('#sfPass').value;
        // Contact details are optional for small teams, only the credential used
        // to unlock the till/account (PIN for cashiers, password for everyone else) is required.
        if(role === 'cashier' && !/^\d{4}$/.test(pass)) return fail(tr('PIN must be exactly 4 digits.'));
        if(role !== 'cashier' && pwProblem(pass)) return fail(pwProblem(pass));
        var passHash = await pwHash(pass);
        refs.users.doc().set({ name:name, email:email, role:role, jobTitle:ov.querySelector('#sfJob').value.trim(), employeeNo:nextEmployeeNo(), passHash:passHash, active:true, createdAt:new Date().toISOString(), approvedBy:State.session.name, approvedAt:new Date().toISOString(), posAccess: role !== 'stockclerk' && ov.querySelector('#sfPos').checked });
        logAudit('create','staff',null,'Added '+name+' as '+role);
        toast(name+' '+tr('added as')+' '+tr(ROLE_LABELS[role]||role));
        openTeamSheet();
      }
    })();
  });
}

/* ============================== till / cash-up (cash register reconciliation) ============================== */
function tillTotals(tillId){
  var sales = State.sales.filter(function(s){ return s.tillId === tillId; });
  var totals = {cash:0, card:0, wallet:0, credit:0, voucher:0};
  var cashBack = 0;
  var items = {cash:0, card:0, wallet:0, credit:0};
  sales.forEach(function(s){
    var m = s.paymentMethod || 'cash';
    salePayParts(s).forEach(function(q){ totals[q.method] = mRound2((totals[q.method]||0) + q.amount); });
    var vA = saleVoucherAmt(s); if(vA && m !== 'voucher') totals.voucher = mRound2((totals.voucher||0) + vA);
    cashBack = mRound2(cashBack + (s.cashBack || 0));
    var qty = (s.items||[]).reduce(function(a,it){ return a+it.qty; }, 0);
    items[m] = (items[m]||0) + qty;
  });
  var itemTotal = items.cash+items.card+items.wallet+items.credit;
  return { totals:totals, items:items, saleCount:sales.length, itemTotal:itemTotal, cashBack:cashBack };
}

function renderTill(){
  if(isCashier()) return renderTillCashierView();
  return renderTillOverviewView();
}

function renderTillCashierView(){
  var open = State.till.current;
  if(!open){
    return '<div class="empty">'+ICONS.receipt+'<div class="t">'+tr('Your till is closed')+'</div><div class="s">'+tr('Count the cash in the drawer and open your register to start selling.')+'</div>' +
      '<div style="margin-top:14px;"><button class="btn btn-primary" id="startTillBtn">'+tr('Open till')+'</button></div></div>';
  }
  var t = tillTotals(open.id);
  var html = '<div class="banner" style="color:var(--success);">'+ICONS.check.replace(/width="24" height="24"/,'width="15" height="15"')+'<span>'+tr('Till open since')+' '+fmtDateTime(open.openedAt)+'</span></div>';
  html += tillSummaryCardHtml(open, t);
  html += '<button class="btn btn-danger btn-block" id="closeTillBtn" style="margin-top:14px;">'+tr('Close till &amp; count cash')+'</button>';
  return html;
}

function tillSummaryCardHtml(session, t){
  return '<div class="tillcard">' +
    '<div class="section-title" style="margin-top:0;">'+tr('Sales this shift')+'</div>' +
    '<div class="tillrow"><span class="l">'+tr('Opening float')+'</span><span class="v num">'+fmtMoney(session.openingFloat||0)+'</span></div>' +
    '<div class="tillrow"><span class="l">'+tr('Cash sales')+'</span><span class="v num">'+fmtMoney(t.totals.cash)+' ('+t.items.cash+' '+(t.items.cash===1?tr('item'):tr('items'))+')</span></div>' +
    (t.cashBack > 0 ? '<div class="tillrow"><span class="l">'+tr('Cash back paid out')+'</span><span class="v num">−'+fmtMoney(t.cashBack)+'</span></div>' : '') +
    '<div class="tillrow"><span class="l">'+tr('Card sales')+'</span><span class="v num">'+fmtMoney(t.totals.card)+' ('+t.items.card+' '+(t.items.card===1?tr('item'):tr('items'))+')</span></div>' +
    '<div class="tillrow"><span class="l">'+tr('Mobile wallet sales')+'</span><span class="v num">'+fmtMoney(t.totals.wallet)+' ('+t.items.wallet+' '+(t.items.wallet===1?tr('item'):tr('items'))+')</span></div>' +
    (t.totals.voucher ? '<div class="tillrow"><span class="l">'+tr('Voucher sales (owed by the platform)')+'</span><span class="v num">'+fmtMoney(t.totals.voucher)+'</span></div>' : '') +
    '<div class="tillrow"><span class="l">'+tr('Credit sales')+'</span><span class="v num">'+fmtMoney(t.totals.credit)+' ('+t.items.credit+' '+(t.items.credit===1?tr('item'):tr('items'))+')</span></div>' +
    '<div class="tillrow grand"><span class="l">'+tr('Total items sold')+'</span><span class="v">'+t.itemTotal+'</span></div>' +
  '</div>';
}

function renderTillOverviewView(){
  var openOnes = State.tillSessions.filter(function(t){ return t.status==='open'; });
  var closedOnes = State.tillSessions.filter(function(t){ return t.status==='closed'; });
  var html = '';
  if(openOnes.length > 0){
    html += '<div class="section-title" style="margin-top:0;">'+tr('Currently open')+' ('+openOnes.length+')</div>';
    html += '<div class="rowlist">' + openOnes.map(function(t){
      var tt = tillTotals(t.id);
      var cashExpected = (t.openingFloat||0) + tt.totals.cash - (tt.cashBack||0);
      return '<div class="row" data-till="'+t.id+'">' +
        '<div class="avatar">'+esc(initials(t.cashierName))+'</div>' +
        '<div class="main"><div class="title">'+esc(t.cashierName)+'</div><div class="sub">'+tr('Open since')+' '+fmtDateTime(t.openedAt)+'</div></div>' +
        '<div class="trail"><div class="amt num">'+fmtMoney(cashExpected)+'</div><div class="note">'+tr('cash expected')+'</div></div>' +
      '</div>';
    }).join('') + '</div>';
  }
  html += '<div class="section-title">'+tr('Cash-up history')+'</div>';
  if(closedOnes.length === 0){
    html += '<div class="empty">'+ICONS.receipt+'<div class="t">'+tr('No cash-ups yet')+'</div><div class="s">'+tr('Closed till sessions from your cashiers will appear here.')+'</div></div>';
  } else {
    html += '<div class="rowlist">' + closedOnes.slice(0,40).map(function(t){
      var varClass = Math.abs(t.variance||0) < 0.01 ? 'variance-ok' : (t.variance<0 ? 'variance-bad' : 'variance-over');
      var varLabel = Math.abs(t.variance||0) < 0.01 ? tr('Balanced') : (t.variance<0 ? tr('Short')+' '+fmtMoney(Math.abs(t.variance)) : tr('Over')+' '+fmtMoney(t.variance));
      return '<div class="row" data-till="'+t.id+'">' +
        '<div class="avatar">'+esc(initials(t.cashierName))+'</div>' +
        '<div class="main"><div class="title">'+esc(t.cashierName)+'</div><div class="sub">'+fmtDay(t.closedAt)+'</div></div>' +
        '<div class="trail"><div class="amt num '+varClass+'">'+varLabel+'</div><div class="note">'+fmtMoney(t.expectedCash)+' '+tr('expected')+'</div></div>' +
      '</div>';
    }).join('') + '</div>';
  }
  return html;
}

function openStartTillSheet(){
  var html = '<div class="sheet-head"><h2>'+tr('Open till')+'</h2></div>' +
    '<div class="banner">'+tr('Count the cash currently in the drawer before you start selling.')+'</div>' +
    '<div class="field"><label>'+tr('Opening float (cash counted now)')+'</label><input id="tsFloat" type="number" inputmode="decimal" step="0.01" placeholder="0.00"></div>' +
    '<div class="actions"><button class="btn btn-primary btn-block" id="tsOpenBtn">'+tr('Open till')+'</button></div>';
  var ov = openSheet(html, {center:true});
  ov.querySelector('#tsOpenBtn').addEventListener('click', function(){
    var floatAmt = parseFloat(ov.querySelector('#tsFloat').value);
    if(isNaN(floatAmt) || floatAmt<0){ toast(tr('Enter the opening cash amount')); return; }
    var ref = refs.tills.doc();
    ref.set({
      cashierId: State.session.userId, cashierName: State.session.name,
      openingFloat: floatAmt, openedAt: new Date().toISOString(), status:'open'
    }).then(function(){
      State.till.current = { id: ref.id, cashierId:State.session.userId, cashierName:State.session.name, openingFloat:floatAmt, openedAt:new Date().toISOString(), status:'open' };
      logAudit('create','till',ref.id,'Till opened with '+fmtMoney(floatAmt));
      closeModal();
      toast(tr('Till opened with')+' '+fmtMoney(floatAmt));
      render();
    });
  });
}

function openCloseTillSheet(session){
  var t = tillTotals(session.id);
  var expectedFloat = mRound2((session.openingFloat||0) + t.totals.cash - (t.cashBack||0));
  var html = '<div class="sheet-head"><h2>'+tr('Close till')+'</h2></div>' +
    tillSummaryCardHtml(session, t) +
    '<div class="field"><label>'+tr('Cash paid out during shift (expenses paid from the drawer, if any)')+'</label><input id="tcPayout" type="number" inputmode="decimal" step="0.01" placeholder="0.00"></div>' +
    '<div class="field"><label>'+tr('Cash counted in drawer now')+'</label><input id="tcCounted" type="number" inputmode="decimal" step="0.01" placeholder="0.00"></div>' +
    '<div id="tcResult"></div>' +
    '<div class="field" id="tcWhyBox" style="display:none;"><label>'+tr('Why is the cash different? (required for a difference of')+' '+fmtMoney(tillVarianceLimit())+' '+tr('or more)')+'</label><input id="tcWhy" maxlength="200" placeholder="'+esc(tr('For example: change given wrongly, paid a supplier'))+'"></div>' +
    '<div style="font-size:11.5px;color:var(--text-muted);margin:2px 0 8px;">'+tr('A difference is recorded for review. It is a warning to look into, not a finding about anyone.')+'</div>' +
    '<div class="actions"><button class="btn btn-danger btn-block" id="tcCloseBtn">'+tr('Confirm cash-up')+'</button></div>';
  var ov = openSheet(html, {center:true});
  function recalc(){
    var payout = parseFloat(ov.querySelector('#tcPayout').value) || 0;
    var counted = parseFloat(ov.querySelector('#tcCounted').value);
    var expected = mRound2(expectedFloat - payout);
    var box = ov.querySelector('#tcResult');
    if(isNaN(counted)){ box.innerHTML=''; return; }
    var variance = mRound2(counted - expected);
    ov.querySelector('#tcWhyBox').style.display = Math.abs(variance) >= tillVarianceLimit() ? '' : 'none';
    var cls = Math.abs(variance)<0.01 ? 'variance-ok' : (variance<0?'variance-bad':'variance-over');
    var label = Math.abs(variance)<0.01 ? tr('Balanced, well done!') : (variance<0 ? tr('Cash is short by')+' '+fmtMoney(Math.abs(variance)) : tr('Cash is over by')+' '+fmtMoney(variance));
    box.innerHTML = '<div class="tillcard">' +
      '<div class="tillrow"><span class="l">'+tr('Expected in drawer')+'</span><span class="v num">'+fmtMoney(expected)+'</span></div>' +
      '<div class="tillrow"><span class="l">'+tr('Counted in drawer')+'</span><span class="v num">'+fmtMoney(counted)+'</span></div>' +
      '<div class="tillrow grand"><span class="l">'+tr('Variance')+'</span><span class="v num '+cls+'">'+label+'</span></div>' +
    '</div>';
  }
  ov.querySelector('#tcPayout').addEventListener('input', recalc);
  ov.querySelector('#tcCounted').addEventListener('input', recalc);
  ov.querySelector('#tcCloseBtn').addEventListener('click', function(){
    var payout = parseFloat(ov.querySelector('#tcPayout').value) || 0;
    var counted = parseFloat(ov.querySelector('#tcCounted').value);
    if(isNaN(counted)){ toast(tr('Enter the cash counted in the drawer')); return; }
    var expected = mRound2(expectedFloat - payout);
    var variance = mRound2(counted - expected);
    var why = (ov.querySelector('#tcWhy').value || '').trim();
    if(Math.abs(variance) >= tillVarianceLimit() && !why){ toast(tr('Write why the cash is different')); ov.querySelector('#tcWhy').focus(); return; }
    if(!uiOnce('closeTill:'+session.id, 3000)) return;
    refs.tills.doc(session.id).update({
      status:'closed', closedAt:new Date().toISOString(), cashPayout:payout,
      closingCash:counted, expectedCash:expected, variance:variance,
      varianceNote:why, reviewStatus:Math.abs(variance) >= tillVarianceLimit() ? 'needs review' : 'none', closedById:State.session ? State.session.userId : '', deviceId:Dev.id(),
      totals:t.totals, items:t.items
    }).then(function(){
      if(Math.abs(variance) >= tillVarianceLimit()) logAudit('other','till',session.id,'Cash up needs review: difference of '+fmtMoney(variance)+' (reason given: '+why+')');
      if(State.till.current && State.till.current.id === session.id) State.till.current = null;
      logAudit('update','till',session.id,'Till closed, variance '+fmtMoney(variance));
      if(notifyActive() || emailAlertsOn()){
        var tillTotal = Object.keys(t.totals||{}).reduce(function(a,k){ return a + (Number(t.totals[k])||0); }, 0);
        var today = todayKey();
        var todays = State.sales.filter(function(s){ return s.createdAt && todayKey(new Date(s.createdAt)) === today; });
        var dayTotal = todays.reduce(function(a,s){ return a + (s.total||0); }, 0);
        showDeviceNotification('Till closed: ' + (State.settings.shopName || 'Pesa'),
          'This till took ' + fmtMoney(tillTotal) + '. All sales today: ' + fmtMoney(dayTotal) + ' from ' + todays.length + ' sale(s). Cash ' +
          (Math.abs(variance)<0.01 ? 'balanced.' : (variance<0 ? 'short by ' + fmtMoney(Math.abs(variance)) + '.' : 'over by ' + fmtMoney(variance) + '.')),
          'pesa-till-' + session.id);
      }
      closeModal();
      toast(tr('Till closed')+', '+(Math.abs(variance)<0.01?tr('balanced'):(variance<0?tr('short')+' '+fmtMoney(Math.abs(variance)):tr('over')+' '+fmtMoney(variance))));
      render();
    });
  });
}

function openTillDetailSheet(session){
  var t = session.status==='open' ? tillTotals(session.id) : { totals:session.totals||{cash:0,card:0,wallet:0,credit:0}, items:session.items||{cash:0,card:0,wallet:0,credit:0}, itemTotal:Object.values(session.items||{}).reduce(function(a,b){return a+b;},0) };
  var html = '<div class="sheet-head"><h2>'+esc(session.cashierName)+'</h2></div>' +
    '<div class="banner">'+(session.status==='open'?tr('Opened')+' '+fmtDateTime(session.openedAt):tr('Closed')+' '+fmtDateTime(session.closedAt))+'</div>' +
    tillSummaryCardHtml(session, t);
  if(session.status==='closed'){
    var cls = Math.abs(session.variance||0)<0.01 ? 'variance-ok' : (session.variance<0?'variance-bad':'variance-over');
    var label = Math.abs(session.variance||0)<0.01 ? tr('Balanced') : (session.variance<0?tr('Short')+' '+fmtMoney(Math.abs(session.variance)):tr('Over')+' '+fmtMoney(session.variance));
    html += '<div class="tillcard">' +
      '<div class="tillrow"><span class="l">'+tr('Cash paid out')+'</span><span class="v num">'+fmtMoney(session.cashPayout||0)+'</span></div>' +
      '<div class="tillrow"><span class="l">'+tr('Expected in drawer')+'</span><span class="v num">'+fmtMoney(session.expectedCash||0)+'</span></div>' +
      '<div class="tillrow"><span class="l">'+tr('Counted in drawer')+'</span><span class="v num">'+fmtMoney(session.closingCash||0)+'</span></div>' +
      '<div class="tillrow grand"><span class="l">'+tr('Variance')+'</span><span class="v num '+cls+'">'+label+'</span></div>' +
    '</div>';
  } else if(isManagerOrOwner()){
    html += '<div class="actions"><button class="btn btn-danger btn-block" id="managerCloseTillBtn">'+tr('Close this till')+'</button></div>';
  }
  var ov = openSheet(html);
  var mgrBtn = ov.querySelector('#managerCloseTillBtn');
  if(mgrBtn) mgrBtn.addEventListener('click', function(){ closeModal(); openCloseTillSheet(session); });
}

/* ============================== toast ============================== */
function toast(msg){
  var root = document.getElementById('toastRoot');
  var el = document.createElement('div');
  el.className = 'toast';
  el.textContent = msg;
  root.innerHTML = '';
  root.appendChild(el);
  setTimeout(function(){ if(el.parentNode) el.parentNode.removeChild(el); }, 2200);
}

/* ============================== modal helpers ============================== */
/* ============================== BACK NAVIGATION ============================== */
/* The Back button of the phone or browser, and the Back buttons in Pesa, step back through the sheets and pages
   you opened instead of leaving Pesa. History entries are kept in line with what is on screen:
   one base entry, one per page you moved away from, and one while a sheet is open. */
var NavBack = (function(){
  var tabStack = [], sheetPushed = false, ignore = 0, ready = false;
  function sheetOpen(){ var r = document.getElementById('modalRoot'), a = document.getElementById('authModalRoot'); return !!((r && r.firstChild) || (a && a.firstChild)); }
  function homeTab(){ try{ return State.session ? roleTabs(State.session.role)[0] : 'dashboard'; }catch(e){ return 'dashboard'; } }
  function init(){
    if(ready) return; ready = true;
    try{ history.replaceState({ pesa:'base' }, ''); }catch(e){}
    window.addEventListener('popstate', function(){
      if(ignore > 0){ ignore--; return; }
      if(sheetOpen()){ sheetPushed = false; closeModal(); return; }
      if(tabStack.length){ State.tab = tabStack.pop(); render(); }
    });
  }
  function onOwnEntry(kind){ try{ return !!(history.state && history.state.pesa === kind); }catch(e){ return false; } }
  function sheetOpened(){ init(); if(!sheetPushed){ try{ history.pushState({ pesa:'sheet' }, ''); sheetPushed = true; }catch(e){} } }
  function sheetClosed(){
    setTimeout(function(){
      if(sheetPushed && !sheetOpen()){
        sheetPushed = false;
        // only step back over an entry Pesa pushed itself. Going back from the base entry would leave the app (a blank page)
        if(onOwnEntry('sheet')){ ignore++; try{ history.back(); }catch(e){ ignore--; } }
      }
    }, 0);
  }
  function tabChanged(from, to){
    init(); if(from === to) return;
    tabStack.push(from);
    try{
      if(sheetPushed && !sheetOpen()){ sheetPushed = false; history.replaceState({ pesa:'tab' }, ''); }   // the closed sheet's entry becomes this page's entry
      else history.pushState({ pesa:'tab' }, '');
    }catch(e){}
  }
  function canGoBack(){ return sheetOpen() || tabStack.length > 0 || State.tab !== homeTab(); }
  function back(){
    // never call history.back() from the base entry: it would leave Pesa. Close the sheet or go to the earlier page directly instead
    if(sheetOpen() && !onOwnEntry('sheet')){ sheetPushed = false; closeModal(); return; }
    if(!sheetOpen() && tabStack.length && !onOwnEntry('tab')){ State.tab = tabStack.pop(); render(); return; }
    if(sheetOpen() || tabStack.length){ try{ history.back(); }catch(e){} return; }
    if(State.tab !== homeTab()){ State.tab = homeTab(); render(); }
  }
  function reset(){ tabStack = []; }
  return { sheetOpened:sheetOpened, sheetClosed:sheetClosed, tabChanged:tabChanged, back:back, reset:reset, canGoBack:canGoBack, homeTab:homeTab };
})();

function closeModal(){
  try{ msgCleanup(); }catch(e){}
  try{ if(typeof stopNarration === 'function' && _trainState && (_trainState.playing || _trainState.autoTimer)) stopNarration(); }catch(e){}
  document.getElementById('modalRoot').innerHTML = '';
  var ar = document.getElementById('authModalRoot'); if(ar) ar.innerHTML = '';
  try{ NavBack.sheetClosed(); }catch(e){}
}
// Sign-in / register screens hide the app shell (which holds #modalRoot), so
// sheets opened from them are mounted straight on <body> instead.
function sheetRoot(){
  var app = document.getElementById('app');
  if((app && app.style.display === 'none') || document.getElementById('licGate')){   // the licence lock sits above the app, so sheets open in the top level holder
    var ar = document.getElementById('authModalRoot');
    if(!ar){ ar = document.createElement('div'); ar.id = 'authModalRoot'; document.body.appendChild(ar); }
    return ar;
  }
  return document.getElementById('modalRoot');
}
function openSheet(innerHtml, opts){
  opts = opts || {};
  try{ msgCleanup(); }catch(e){}
  var root = sheetRoot();
  var overlay = document.createElement('div');
  overlay.className = 'overlay' + (opts.center ? ' center' : '');
  overlay.innerHTML = '<div class="sheet">' + (opts.center ? '' : '<div class="sheet-handle"></div>') + innerHtml + '</div>';
  overlay.addEventListener('mousedown', function(e){ if(e.target === overlay) closeModal(); });
  root.innerHTML = '';
  root.appendChild(overlay);
  try{
    NavBack.sheetOpened();
    var sh = overlay.firstChild;
    if(!opts.center && !opts.noBack && !overlay.querySelector('.drawer-close, #vsBack, #vlBack, .mv-full, #cnAgree, #licGate, [data-noback]')){
      var bb = document.createElement('button'); bb.type = 'button'; bb.className = 'sheet-backrow'; bb.innerHTML = ICONS.back + '<span>' + esc(tr('Back')) + '</span>';
      bb.addEventListener('click', function(){ NavBack.back(); });
      sh.insertBefore(bb, sh.firstChild && sh.firstChild.classList && sh.firstChild.classList.contains('sheet-handle') ? sh.firstChild.nextSibling : sh.firstChild);
    }
    if(!opts.center){
      decorateSheetIcon(sh);
      if(window.MutationObserver){ var mo = new MutationObserver(function(){ if(!document.body.contains(sh)){ mo.disconnect(); return; } decorateSheetIcon(sh); }); mo.observe(sh, { childList:true, subtree:true }); }
    }
  }catch(e){}
  return overlay;
}
/* Each page shows its own icon at the top left, beside its title (the Pesa logo sits at the top right). */
var PAGE_ICON_RULES = [
  [/^pesa ad$/i,'about'],
  [/pay for pesa|practice payment/i,'pay'],[/wastage|shrinkage/i,'wastage'],[/supplier/i,'suppliers'],[/purchase order/i,'purchase'],
  [/stock take|opening balances|review & post/i,'stocktake'],[/stock|reorder|expiry|barcode|scan|product|bulk/i,'stock'],
  [/vat|tax records|namra|past month/i,'vat'],[/branch/i,'branches'],[/activity log/i,'audit'],
  [/cart|charge|sale recorded|point of sale/i,'sell'],[/till|cash up|card batch|card terminal|end of day|mobile money/i,'till'],
  [/invoice|quote|recurring/i,'invoices'],[/who owes|credit|customer|reminder|loyalty|payment/i,'credit'],[/expense/i,'expenses'],
  [/insight|profit|targets/i,'insights'],[/report|risk|staff performance|work report/i,'reports'],
  [/team|staff member|invite|my profile|change (pin|password)/i,'team'],[/message|alert centre/i,'messages'],
  [/smart/i,'smart'],[/business tools|import|currency|calculator|labels/i,'bizhub'],
  [/^settings$/i,'gear'],[/setup|licence|security|data health|backup|link this device|connect to|wi-fi|company details|speed check/i,'setup'],
  [/feedback/i,'feedback'],[/text size/i,'display'],[/check this computer/i,'compat'],[/search help/i,'helpsearch'],
  [/terms|privacy|confidential/i,'legal'],[/about pesa|what.s new/i,'about'],[/training|lesson/i,'training'],[/install/i,'install'],[/accountant/i,'accountant']
];
function pageIconFor(title){
  for(var i = 0; i < PAGE_ICON_RULES.length; i++) if(PAGE_ICON_RULES[i][0].test(title)) return PAGE_ICON_RULES[i][1];
  return '';
}
function decorateSheetIcon(sh){
  var head = sh.querySelector('.sheet-head'); if(!head || head.querySelector('.pg-ico, img')) return;
  var h = head.querySelector('h2'); if(!h) return;
  var name = pageIconFor((h.textContent || '').trim()); if(!name) return;
  var html = name === 'gear' ? GEAR_ICON_SMALL : ico3(name); if(!html) return;
  var sp = document.createElement('span'); sp.className = 'pg-ico'; sp.setAttribute('aria-hidden', 'true'); sp.innerHTML = html;
  head.insertBefore(sp, head.firstChild);
}
function confirmSheet(title, body, confirmLabel, onConfirm, danger, sensitive){
  var html =
    '<div class="sheet-head"><h2>'+esc(title)+'</h2></div>' +
    '<div style="font-size:14px;color:var(--text-muted);margin-bottom:16px;line-height:1.5;">'+esc(body)+'</div>' +
    '<div class="actions">' +
      '<button class="btn btn-ghost btn-block" id="cfCancel">Cancel</button>' +
      '<button class="btn '+(danger?'btn-danger':'btn-primary')+' btn-block" id="cfOk">'+esc(confirmLabel)+'</button>' +
    '</div>';
  var ov = openSheet(html, {center:true});
  ov.querySelector('#cfCancel').addEventListener('click', closeModal);
  ov.querySelector('#cfOk').addEventListener('click', function(){ closeModal(); if(sensitive) bioGate(title, onConfirm); else onConfirm(); });
}

