/* ============================== small chart helpers ============================== */
function lastNDaysTotals(list, n){
  var days = [];
  for(var i=n-1;i>=0;i--){
    var d = new Date(); d.setDate(d.getDate()-i);
    days.push({ key: todayKey(d), label: _fmtDate('w', d, uiLocale()), total:0 });
  }
  var map = {};
  days.forEach(function(d){ map[d.key]=d; });
  list.forEach(function(s){
    var k = dayKeyOfIso(s.createdAt);
    if(map[k]) map[k].total += s.total;
  });
  return days;
}
function sparklineSvg(days, opts){
  opts = opts || {};
  var w=280, h=56, pad=5;
  var vals = days.map(function(d){ return d.total; });
  var max = Math.max.apply(null, vals.concat([1]));
  var stepX = (w-pad*2) / (Math.max(vals.length-1,1));
  var pts = vals.map(function(v,i){
    var x = pad + i*stepX;
    var y = h-pad - (v/max)*(h-pad*2);
    return [x,y];
  });
  var lined = pts.map(function(p,i){ return (i===0?'M':'L') + p[0].toFixed(1) + ',' + p[1].toFixed(1); }).join(' ');
  var areaD = lined + ' L' + pts[pts.length-1][0].toFixed(1) + ',' + (h-pad) + ' L' + pts[0][0].toFixed(1) + ',' + (h-pad) + ' Z';
  var last = pts[pts.length-1];
  var stroke = opts.stroke || 'currentColor';
  var fill = opts.fill || 'rgba(255,255,255,0.2)';
  return '<svg viewBox="0 0 '+w+' '+h+'" preserveAspectRatio="none" style="width:100%;height:52px;display:block;" role="img" aria-label="Sales over the last '+days.length+' days">' +
    '<path d="'+areaD+'" fill="'+fill+'" stroke="none"></path>' +
    '<path d="'+lined+'" fill="none" stroke="'+stroke+'" stroke-width="2.25" stroke-linecap="round" stroke-linejoin="round"></path>' +
    '<circle cx="'+last[0].toFixed(1)+'" cy="'+last[1].toFixed(1)+'" r="3.5" fill="'+stroke+'"></circle>' +
  '</svg>';
}

/* Fast product search: each product's searchable text is built once and cached, every typed word must match
   (any order, accents ignored), names that start with the typed word come first, exact barcode always matches. */
var _srchCache = new WeakMap();
function _srchNorm(t){ t = String(t==null?'':t).toLowerCase(); try{ t = t.normalize('NFD').replace(/[\u0300-\u036f]/g,''); }catch(e){} return t; }
function _srchHay(p){
  var sig = (p.name||'')+'|'+(p.category||'')+'|'+(p.barcode==null?'':p.barcode)+'|'+(p.sku||'');
  var c = _srchCache.get(p);
  if(!c || c.sig !== sig){ c = { sig:sig, hay:_srchNorm(sig), name:_srchNorm(p.name||''), bc:String(p.barcode==null?'':p.barcode).trim() }; _srchCache.set(p, c); }
  return c;
}
function searchProducts(list, query){
  var q = _srchNorm(query).trim();
  if(!q) return list;
  var words = q.split(/\s+/), first = words[0], hits = [], rest = [];
  for(var i = 0; i < list.length; i++){
    var c = _srchHay(list[i]), ok = c.bc === q;
    if(!ok){ ok = true; for(var w = 0; w < words.length; w++){ if(c.hay.indexOf(words[w]) < 0){ ok = false; break; } } }
    if(!ok) continue;
    if(c.bc === q || c.name.indexOf(first) === 0) hits.push(list[i]); else rest.push(list[i]);
  }
  return hits.concat(rest);
}
/* ============================== TAB: SELL ============================== */
function categoriesFor(products){
  var set = {};
  products.forEach(function(p){ if(p.category) set[p.category]=true; });
  return Object.keys(set).sort();
}

function renderSell(){
  var q = State.sellSearch.trim().toLowerCase();
  var list = searchProducts(State.products, State.sellSearch);

  if(!State.ready.products){
    return '<div class="empty">Loading products…</div>';
  }
  if(State.products.length === 0){
    return '<div class="empty">' + ICONS.box + '<div class="t">'+tr('No products yet')+'</div><div class="s">'+tr('Add stock first, then come back to sell.')+'</div>' +
      '<div style="margin-top:14px;"><button class="btn btn-primary" id="goStock">'+tr('Go to Stock')+'</button></div></div>';
  }

  var html = namePriceBannerHtml() + brainCardHtml() + '<div style="display:flex;gap:8px;align-items:center;">' +
    '<div class="searchbar" style="flex:1;">' + ICONS.search + '<input id="sellSearchInput" placeholder="Search products…" value="'+esc(State.sellSearch)+'"></div>' +
    (voiceSupported() ? '<button class="icon-btn" id="sellVoiceBtn" type="button" title="Voice search" style="flex:0 0 auto;">'+MIC_ICON+'</button>' : '') +
    '<button class="icon-btn" id="sellScanBtn" type="button" title="Scan barcode" style="flex:0 0 auto;">'+ICONS.search+'</button>' +
  '</div>';

  if(list.length === 0){
    html += '<div class="empty"><div class="t">'+tr('No matches')+'</div><div class="s">'+tr('Try a different search.')+'</div></div>';
  } else {
    var sellLimit = State.sellLimit || LIST_PAGE;
    html += tickBarHtml() + '<div class="grid">' + list.slice(0, sellLimit).map(function(p){
      var low = (p.stockQty!=null) && p.stockQty <= (p.lowStock!=null?p.lowStock:State.settings.lowStockDefault);
      var out = (p.stockQty!=null) && p.stockQty <= 0;
      var badge = p.stockQty==null ? '' : '<div class="stockbadge '+(out?'out':(low?'low':''))+'">'+ (out?'Out':(p.stockQty+' '+(p.unit||'left'))) +'</div>';
      return '<button class="pcard" data-add="'+p.id+'" '+(out?'disabled style="opacity:.5"':'')+'>' +
        (out ? '' : tickHtml(p.id)) + badge +
        '<div class="pname">'+esc(p.name)+'</div>' +
        (p.category ? '<div class="pcat">'+esc(p.category)+'</div>' : '') +
        '<div class="pprice num">'+fmtMoney(p.sellPrice)+'</div>' +
      '</button>';
    }).join('') + '</div>';
    if(list.length > sellLimit) html += '<div style="text-align:center;margin:14px 0 4px;"><button class="btn btn-ghost" id="sellMoreBtn" type="button">Show more ('+(list.length - sellLimit).toLocaleString()+' more, or search)</button></div>';
  }
  return html;
}
var LIST_PAGE = 120;

function cartTotal(){ var c = 0; State.cart.forEach(function(i){ c += mMul(i.unitPrice, i.qty); }); return c / 100; }
function cartCost(){ var c = 0; State.cart.forEach(function(i){ c += mMul(i.cost || 0, i.qty); }); return c / 100; }
function cartCount(){ return State.cart.reduce(function(s,i){ return s + i.qty; }, 0); }


/* ---------- tick boxes and Select all / Deselect all wherever stock is picked ---------- */
function tickHtml(id){ var on = State.cart.some(function(i){ return i.productId === id; }); return '<span class="tick'+(on?' on':'')+'" data-tick="'+id+'" role="checkbox" aria-checked="'+on+'" aria-label="'+tr('Select')+'"><svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg></span>'; }
function tickBarHtml(){
  return '<div class="tickbar"><span class="tc"><b data-tickcount>'+State.cart.length+'</b> '+tr('selected')+'</span><button class="btn btn-ghost" type="button" data-tickall>'+tr('Select all')+'</button><button class="btn btn-ghost" type="button" data-tickclear>'+tr('Deselect all')+'</button></div>';
}
function syncTicks(){
  var inCart = {}; State.cart.forEach(function(i){ inCart[i.productId] = 1; });
  document.querySelectorAll('[data-tick]').forEach(function(el){ var on = !!inCart[el.getAttribute('data-tick')]; el.classList.toggle('on', on); el.setAttribute('aria-checked', on ? 'true' : 'false'); });
  document.querySelectorAll('[data-tickcount]').forEach(function(el){ el.textContent = State.cart.length; });
}
function wireTicks(root){
  if(!root) return;
  root.querySelectorAll('[data-tick]').forEach(function(t){ t.addEventListener('click', function(e){
    e.stopPropagation(); e.preventDefault();
    var id = t.getAttribute('data-tick');
    if(State.cart.some(function(i){ return i.productId === id; })){ State.cart = State.cart.filter(function(i){ return i.productId !== id; }); renderCartBar(); }
    else addToCart(id);
  }); });
  var scope = root.querySelector('.grid') ? root : root.parentNode;
  root.querySelectorAll('[data-tickall]').forEach(function(b){ b.addEventListener('click', function(){
    var ids = []; root.querySelectorAll('.pcard:not([disabled]) [data-tick]').forEach(function(t){ ids.push(t.getAttribute('data-tick')); });
    ids.forEach(function(id){ if(!State.cart.some(function(i){ return i.productId === id; })) addToCart(id); });
    toast(ids.length+' '+tr('selected'));
  }); });
  root.querySelectorAll('[data-tickclear]').forEach(function(b){ b.addEventListener('click', function(){
    var ids = {}; root.querySelectorAll('[data-tick]').forEach(function(t){ ids[t.getAttribute('data-tick')] = 1; });
    State.cart = State.cart.filter(function(i){ return !ids[i.productId]; }); renderCartBar();
  }); });
}
/* ---- departments: every product sits under a department header (its Category). Products with no Category are placed by their name
   (milk and yogurt go under Dairy products); anything Pesa cannot place goes last under Other products. ---- */
var DEPT_WORDS = [
  ['Dairy products', /\b(milk|yogh?urt|cheese|butter|cream|maas|amasi|custard|margarine|eggs?)\b/],
  ['Bakery', /\b(bread|buns?|rolls?|cakes?|muffins?|scones?|rusks?|pies?|vetkoek|biscuits?)\b/],
  ['Cold drinks and water', /\b(cola|coke|fanta|sprite|juice|water|soda|cooldrink|cool drink|energy drink|iced tea)\b/],
  ['Meat and fish', /\b(beef|chicken|mince|sausages?|boerewors|polony|fish|pork|lamb|bacon|biltong|ham)\b/],
  ['Fruit and vegetables', /\b(apples?|bananas?|tomato(es)?|onions?|potato(es)?|carrots?|oranges?|cabbage|spinach|lemons?|grapes?)\b/],
  ['Dry goods and groceries', /\b(rice|maize|mealie|flour|sugar|oil|pasta|spaghetti|salt|beans|lentils|oats|cereal|tea|coffee|jam|sauce)\b/],
  ['Household and cleaning', /\b(soap|bleach|detergent|washing powder|omo|toilet paper|dishwash|polish|sponge|candles?|matches)\b/],
  ['Toiletries and health', /\b(shampoo|toothpaste|toothbrush|deodorant|lotion|vaseline|razor|nappies|tissues?|painkiller|plasters?)\b/],
  ['Snacks and sweets', /\b(chips|chocolate|sweets?|candy|crisps|popcorn|lollipops?|gum)\b/]
];
function deptKey(label){ return String(label||'').toLowerCase().replace(/\bproducts?\b/g, '').replace(/[^a-z0-9]+/g, ' ').trim() || 'other'; }
function deptInfo(p){
  var c = String(p && p.category || '').trim();
  if(c){ return { key:deptKey(c), label:c.charAt(0).toUpperCase() + c.slice(1), explicit:true }; }
  var n = String(p && p.name || '').toLowerCase();
  for(var i = 0; i < DEPT_WORDS.length; i++) if(DEPT_WORDS[i][1].test(n)) return { key:deptKey(DEPT_WORDS[i][0]), label:DEPT_WORDS[i][0], explicit:false };
  return { key:'other', label:'Other products', explicit:false };
}
function deptGuess(name){ var d = deptInfo({ name:name }); return d.key === 'other' ? '' : d.label; }
var _deptColl = (typeof Intl !== 'undefined' && Intl.Collator) ? new Intl.Collator(undefined, { numeric:true, sensitivity:'base' }) : null;
function deptCmp(a, b){ return _deptColl ? _deptColl.compare(a, b) : (a < b ? -1 : a > b ? 1 : 0); }
/** Groups products by department: departments A to Z (Other products last), products A to Z inside each. */
function deptGroups(list){
  var map = {}, order = [];
  for(var i = 0; i < list.length; i++){
    var p = list[i], d = deptInfo(p), g = map[d.key];
    if(!g){ g = map[d.key] = { key:d.key, label:d.label, explicit:d.explicit, items:[] }; order.push(g); }
    else if(d.explicit && !g.explicit){ g.label = d.label; g.explicit = true; }
    g.items.push(p);
  }
  order.forEach(function(g){ g.items.sort(function(a, b){ return deptCmp(String(a.name||''), String(b.name||'')); }); });
  order.sort(function(a, b){ return ((a.key === 'other') - (b.key === 'other')) || deptCmp(a.label, b.label); });
  return order;
}
var _deptMemo = { src:null, len:-1, groups:null };
function deptGroupsFor(list){   // the full stock list is grouped once per change, not on every redraw
  if(list === State.products){
    if(_deptMemo.src === list && _deptMemo.len === list.length && _deptMemo.sig === deptSig(list)) return _deptMemo.groups;
    // names and departments are the same as last time (only stock or prices changed): keep the order, swap in the fresh products
    var h = deptHash(list);
    if(_deptMemo.hash === h && _deptMemo.len === list.length && _deptMemo.groups){
      var byId = new Map(); list.forEach(function(p){ byId.set(p.id, p); });
      var same = _deptMemo.groups.map(function(g){ return { key:g.key, label:g.label, explicit:g.explicit, items:g.items.map(function(p){ return byId.get(p.id) || p; }) }; });
      _deptMemo = { src:list, len:list.length, sig:deptSig(list), hash:h, groups:same };
      return same;
    }
    _deptMemo = { src:list, len:list.length, sig:deptSig(list), hash:h, groups:deptGroups(list) };
    return _deptMemo.groups;
  }
  return deptGroups(list);
}
function deptHash(list){   // one cheap pass over every id, name and category
  var h = 5381;
  for(var i = 0; i < list.length; i++){
    var p = list[i], t = p.id + '\u0001' + (p.name||'') + '\u0001' + (p.category||'');
    for(var j = 0; j < t.length; j++) h = ((h << 5) + h + t.charCodeAt(j)) | 0;
  }
  return h;
}
function deptSig(list){ var s = 0, n = Math.min(list.length, 50); for(var i = 0; i < n; i++){ var p = list[i]; s = (s * 31 + String(p.name||'').length * 7 + String(p.category||'').length) | 0; } var l = list[list.length - 1]; return s + '|' + (l ? String(l.name||'') + String(l.category||'') : ''); }

/* Inline picker: tick several products (with a quantity each), Select all / Deselect all, then add them in one go.
   Used on invoices and purchase orders. opts: { price:'sell'|'cost', onAdd(list:[{p,qty}]) } */
function mountStockPicker(box, opts){
  var sel = {}, q = '', grp = deptGroupsFor(State.products);
  function regroup(){
    var qq = q.trim().toLowerCase();
    grp = !qq ? deptGroupsFor(State.products) : deptGroups(State.products.filter(function(p){ return (p.name||'').toLowerCase().indexOf(qq) > -1 || (p.category||'').toLowerCase().indexOf(qq) > -1 || deptInfo(p).label.toLowerCase().indexOf(qq) > -1 || (p.barcode && String(p.barcode) === qq); }));
  }
  function matches(){ var out = []; grp.forEach(function(g){ out = out.concat(g.items); }); return out; }
  function count(){ return Object.keys(sel).length; }
  function rowHtml(p){
    var on = sel[p.id] != null, pr = opts.price === 'cost' ? (p.costPrice||0) : (p.sellPrice||0);
    return '<label class="spk-row'+(on?' on':'')+'" data-spkrow="'+p.id+'"><input type="checkbox" data-spk="'+p.id+'"'+(on?' checked':'')+'><span class="spk-main"><b>'+esc(p.name)+'</b><small>'+(p.stockQty!=null ? p.stockQty+' '+tr('in stock')+' · ' : '')+fmtMoney(pr)+'</small></span>' +
      (on ? '<input class="spk-qty" type="number" min="1" step="1" value="'+sel[p.id]+'" data-spkq="'+p.id+'" inputmode="numeric">' : '') + '</label>';
  }
  function paintList(){
    var el = box.querySelector('.spk-list'), total = 0, shown = 0, html = '', CAP = 150;
    grp.forEach(function(g){ total += g.items.length; });
    for(var gi = 0; gi < grp.length && shown < CAP; gi++){
      var g = grp[gi], part = g.items.slice(0, CAP - shown), allOn = g.items.every(function(p){ return sel[p.id] != null; });
      html += '<label class="spk-dept"><input type="checkbox" data-spkd="'+gi+'"'+(allOn?' checked':'')+'><b>'+esc(tr(g.label))+'</b><small>'+g.items.length+'</small></label>' + part.map(rowHtml).join('');
      shown += part.length;
    }
    el.innerHTML = total ? html + (total > shown ? '<div class="spk-more">'+(total-shown)+' '+tr('more, search to narrow down')+'</div>' : '') : '<div class="spk-more">'+tr('No matches')+'</div>';
    box.querySelector('[data-spkn]').textContent = count();
    box.querySelector('[data-spkadd]').disabled = !count();
    el.querySelectorAll('[data-spk]').forEach(function(c){ c.addEventListener('change', function(){ var id = c.getAttribute('data-spk'); if(c.checked) sel[id] = sel[id] || 1; else delete sel[id]; var top = el.scrollTop; paintList(); box.querySelector('.spk-list').scrollTop = top; }); });
    el.querySelectorAll('[data-spkd]').forEach(function(c){ c.addEventListener('change', function(){
      var g = grp[+c.getAttribute('data-spkd')]; if(!g) return;
      g.items.slice(0, 500).forEach(function(p){ if(c.checked) sel[p.id] = sel[p.id] || 1; else delete sel[p.id]; });
      var top = el.scrollTop; paintList(); box.querySelector('.spk-list').scrollTop = top;
    }); });
    el.querySelectorAll('[data-spkq]').forEach(function(i){ i.addEventListener('click', function(e){ e.stopPropagation(); }); i.addEventListener('input', function(){ sel[i.getAttribute('data-spkq')] = Math.max(1, parseInt(i.value,10) || 1); }); });
  }
  box.innerHTML = '<div class="spk"><div class="searchbar">'+ICONS.search+'<input data-spks placeholder="'+tr('Search products…')+'"></div>' +
    '<div class="tickbar"><span class="tc"><b data-spkn>0</b> '+tr('selected')+'</span><button class="btn btn-ghost" type="button" data-spkall>'+tr('Select all')+'</button><button class="btn btn-ghost" type="button" data-spkclr>'+tr('Deselect all')+'</button></div>' +
    '<div class="spk-list"></div><div class="actions"><button class="btn btn-ghost btn-block" type="button" data-spkcancel>'+tr('Cancel')+'</button><button class="btn btn-primary btn-block" type="button" data-spkadd disabled>'+tr('Add selected')+'</button></div></div>';
  box.querySelector('[data-spks]').addEventListener('input', debounce(function(e){ q = e.target.value; regroup(); paintList(); }, 150));
  box.querySelector('[data-spkall]').addEventListener('click', function(){ matches().slice(0, 500).forEach(function(p){ sel[p.id] = sel[p.id] || 1; }); paintList(); });
  box.querySelector('[data-spkclr]').addEventListener('click', function(){ sel = {}; paintList(); });
  box.querySelector('[data-spkcancel]').addEventListener('click', function(){ box.innerHTML = ''; });
  box.querySelector('[data-spkadd]').addEventListener('click', function(){
    var byId = {}; State.products.forEach(function(p){ byId[p.id] = p; });
    // keep the order the list is shown in: department by department, A to Z
    var out = []; grp.forEach(function(g){ g.items.forEach(function(p){ if(sel[p.id] != null) out.push({ p:p, qty:sel[p.id] }); }); });
    Object.keys(sel).forEach(function(id){ if(byId[id] && !out.some(function(x){ return x.p.id === id; })) out.push({ p:byId[id], qty:sel[id] }); });
    if(!out.length) return; box.innerHTML = ''; opts.onAdd(out);
  });
  paintList();
}
function addToCart(productId){
  var p = State.products.find(function(x){ return x.id===productId; });
  if(!p) return;
  var existing = State.cart.find(function(i){ return i.productId===productId; });
  var maxQty = p.stockQty==null ? Infinity : p.stockQty;
  if(existing){
    if(existing.qty >= maxQty){ toast('Only '+maxQty+' '+(p.unit||'in')+' stock'); return; }
    existing.qty += 1;
  } else {
    if(maxQty < 1){ toast('Out of stock'); return; }
    State.cart.push({ productId:p.id, name:p.name, unitPrice:p.sellPrice, cost:p.costPrice||0, qty:1, unit:p.unit||'', maxQty:maxQty });
  }
  renderCartBar();
}
function setCartQty(productId, qty){
  var item = State.cart.find(function(i){ return i.productId===productId; });
  if(!item) return;
  var p = State.products.find(function(x){ return x.id===productId; });
  var maxQty = p ? (p.stockQty==null?Infinity:p.stockQty) : Infinity;
  qty = Math.max(0, Math.min(qty, maxQty));
  if(qty === 0){
    State.cart = State.cart.filter(function(i){ return i.productId!==productId; });
  } else {
    item.qty = qty;
  }
  renderCartBar();
  if(document.getElementById('cartSheetBody')) renderCartSheetInPlace();
}

function renderCartBar(){
  if(POS.open) posRenderCart();
  try{ syncTicks(); }catch(e){}
  var slot = document.getElementById('cartbarSlot');
  if(!slot) return;
  if(State.tab !== 'sell' || State.cart.length === 0){ slot.innerHTML=''; return; }
  slot.innerHTML = '<div class="cartbar"><div class="cartbar-inner" id="openCartBtn">' +
    '<div class="cnt">'+cartCount()+'</div>' +
    '<div class="lbl">View cart</div>' +
    '<div class="tot num">'+fmtMoney(cartTotal())+'</div>' +
  '</div></div>';
  document.getElementById('openCartBtn').addEventListener('click', openCartSheet);
}

function cartSheetHtml(){
  if(State.cart.length === 0){
    return '<div class="sheet-head"><h2>'+tr('Cart')+'</h2></div><div class="empty" style="padding:24px 8px;">Cart is empty</div>';
  }
  var items = State.cart.map(function(i){
    return '<div class="cartitem">' +
      '<div style="flex:1;min-width:0;">' +
        '<div class="ci-name">'+esc(i.name)+'</div>' +
        '<div class="ci-price num">'+fmtMoney(i.unitPrice)+' each</div>' +
      '</div>' +
      '<div class="stepper">' +
        '<button data-qty-dec="'+i.productId+'">−</button>' +
        '<div class="qv">'+i.qty+'</div>' +
        '<button data-qty-inc="'+i.productId+'">+</button>' +
      '</div>' +
      '<div class="ci-line num">'+fmtMoney(i.unitPrice*i.qty)+'</div>' +
    '</div>';
  }).join('');
  return '<div class="sheet-head"><h2>'+tr('Cart')+'</h2><button class="icon-btn" id="clearCartBtn" style="background:var(--surface-2);border-color:var(--border);color:var(--text-muted);">'+ICONS.warn+'</button></div>' +
    '<div id="cartSheetBody">' + items + '</div>' + brainTogetherHtml() +
    '<div style="margin-top:6px;">' +
      '<div class="sumline total"><span>Total</span><span class="num">'+fmtMoney(cartTotal())+'</span></div>' +
    '</div>' +
    '<div class="actions"><button class="btn btn-accent btn-block" id="chargeBtn">Charge '+fmtMoney(cartTotal())+'</button></div>';
}
function renderCartSheetInPlace(){
  var ov = document.querySelector('.overlay');
  if(!ov) return;
  ov.querySelector('.sheet').innerHTML = '<div class="sheet-handle"></div>' + cartSheetHtml();
  wireCartSheet(ov);
}
function wireCartSheet(ov){
  ov.querySelectorAll('[data-qty-inc]').forEach(function(b){ b.addEventListener('click', function(){ var id=b.getAttribute('data-qty-inc'); var it=State.cart.find(function(i){return i.productId===id;}); setCartQty(id, it.qty+1); }); });
  ov.querySelectorAll('[data-qty-dec]').forEach(function(b){ b.addEventListener('click', function(){ var id=b.getAttribute('data-qty-dec'); var it=State.cart.find(function(i){return i.productId===id;}); setCartQty(id, it.qty-1); }); });
  var clearBtn = ov.querySelector('#clearCartBtn');
  if(clearBtn) clearBtn.addEventListener('click', function(){
    confirmSheet('Clear cart?', 'This removes all items from the current sale.', 'Clear', function(){ State.cart=[]; renderCartBar(); }, true);
  });
  ov.querySelectorAll('[data-br-add]').forEach(function(b){ b.addEventListener('click', function(){ addToCart(b.getAttribute('data-br-add')); renderCartSheetInPlace(); }); });
  var chargeBtn = ov.querySelector('#chargeBtn');
  if(chargeBtn) chargeBtn.addEventListener('click', openChargeSheet);
}
function openCartSheet(){
  var ov = openSheet(cartSheetHtml());
  wireCartSheet(ov);
}

var WALLET_PROVIDERS = ['PayToday','Blue Wallet','e@syWallet','MTC Maris','Bank transfer (EFT)','Other wallet'];
/* ---- discount at the till ----
   A discount is a negative line in the cart (the same way loyalty points are), so VAT, the till, the books and the receipt already
   handle it. Owners and managers apply it themselves; a cashier needs a manager or the owner to type their password. */
function cartDiscountLine(){ return State.cart.find(function(i){ return i.discount; }) || null; }
function cartPositiveTotal(){ var c = 0; State.cart.forEach(function(i){ if(!i.discount && Number(i.unitPrice) > 0) c += mMul(i.unitPrice, i.qty); }); return c / 100; }
function dscApply(kind, value, approver){
  var base = cartPositiveTotal(), amt = kind === 'pct' ? mRound2(base * Math.min(100, value) / 100) : mRound2(value);
  amt = Math.min(amt, base);
  if(!(amt > 0)) return false;
  State.cart = State.cart.filter(function(i){ return !i.discount; });
  State.cart.push({ productId:'discount-' + Date.now().toString(36), name:tr('Discount') + (kind === 'pct' ? ' (' + (Math.round(value * 100) / 100) + '%)' : ''), unitPrice:-amt, cost:0, qty:1, unit:'', maxQty:1, discount:true, discountBy:approver ? approver.name : (State.session ? State.session.name : '') });
  try{ logAudit('other', 'sale', null, 'Discount of ' + fmtMoney(amt) + ' on a sale of ' + fmtMoney(base) + (approver ? ' (approved by ' + approver.name + ')' : '')); }catch(e){}
  return true;
}
function dscWire(ov){
  var box = ov.querySelector('#dscBox'); if(!box) return;
  var cur = cartDiscountLine(), open = false, kind = 'pct';
  function paint(){
    if(cur){
      box.innerHTML = '<div class="banner" style="display:block;"><b>' + esc(cur.name) + '</b> · ' + fmtMoney(Math.abs(cur.unitPrice)) + (cur.discountBy ? ' · ' + tr('approved by') + ' ' + esc(cur.discountBy) : '') + '</div>' +
        '<div class="field"><button class="btn btn-ghost btn-block" id="dscRemove" type="button">' + tr('Remove discount') + '</button></div>';
      box.querySelector('#dscRemove').addEventListener('click', function(){ State.cart = State.cart.filter(function(i){ return !i.discount; }); closeModal(); renderCartBar(); try{ if(POS.open) posRender(); }catch(e){} openChargeSheet(); });
    } else if(open){
      box.innerHTML = '<div class="field"><label>' + tr('Discount') + '</label><div class="segbtns"><button class="segbtn' + (kind === 'pct' ? ' active' : '') + '" data-dk="pct" type="button">' + tr('Percent') + '</button><button class="segbtn' + (kind === 'amt' ? ' active' : '') + '" data-dk="amt" type="button">' + tr('Amount') + '</button></div></div>' +
        '<div class="field"><input id="dscVal" type="number" inputmode="decimal" step="0.01" min="0" placeholder="' + (kind === 'pct' ? '10' : '5.00') + '"><div id="dscPrev" style="font-size:12.5px;color:var(--text-muted);margin-top:4px;"></div></div>' +
        (isManagerOrOwner() ? '' : '<div class="banner" style="display:block;">' + tr('A manager or the owner must approve a discount.') + '</div>') +
        '<div class="actions"><button class="btn btn-primary btn-block" id="dscGo" type="button">' + tr('Apply discount') + '</button><button class="btn btn-ghost btn-block" id="dscNo" type="button" style="margin-top:8px;">' + tr('Cancel') + '</button></div>';
      var inp = box.querySelector('#dscVal'), prev = box.querySelector('#dscPrev');
      function pv(){ var v = parseFloat(inp.value), base = cartPositiveTotal(); if(!(v > 0)){ prev.textContent = ''; return; } var a = Math.min(base, kind === 'pct' ? mRound2(base * Math.min(100, v) / 100) : mRound2(v)); prev.textContent = tr('Takes off') + ' ' + fmtMoney(a) + ' · ' + tr('New total') + ' ' + fmtMoney(base - a); }
      inp.addEventListener('input', pv);
      box.querySelectorAll('[data-dk]').forEach(function(b){ b.addEventListener('click', function(){ kind = b.getAttribute('data-dk'); paint(); }); });
      box.querySelector('#dscNo').addEventListener('click', function(){ open = false; paint(); });
      box.querySelector('#dscGo').addEventListener('click', function(){
        var v = parseFloat(inp.value); if(!(v > 0)){ toast(tr('Enter the discount')); return; }
        if(kind === 'pct' && v > 100){ toast(tr('A discount cannot be more than 100%')); return; }
        function done(approver){ if(!dscApply(kind, v, approver)){ toast(tr('Enter the discount')); return; } closeModal(); renderCartBar(); try{ if(POS.open) posRender(); }catch(e){} openChargeSheet(); }
        if(isManagerOrOwner()) done(State.session ? { name:State.session.name } : null); else askApprovalSheet(tr('Approve this discount'), done);
      });
    } else {
      box.innerHTML = cartPositiveTotal() > 0 ? '<div class="field"><button class="btn btn-ghost btn-block" id="dscOpen" type="button">' + tr('Give a discount') + '</button></div>' : '';
      var b0 = box.querySelector('#dscOpen'); if(b0) b0.addEventListener('click', function(){ open = true; paint(); });
    }
  }
  paint();
}
function openChargeSheet(){
  if(cartHasMock()){ toast(tr('Test products cannot be sold. Remove them from the cart first.')); return; }
  var total = cartTotal();
  var custOptions = State.customers.map(function(c){ return '<option value="'+c.id+'">'+esc(c.name)+', owes '+fmtMoney(c.balance||0)+'</option>'; }).join('');
  var html =
    '<div class="sheet-head"><h2>Charge '+fmtMoney(total)+'</h2></div>' + btFxChargeHtml(total) + eliteAuditHtml() +
    '<div id="vchBox"></div><div id="dscBox"></div>' +
    '<div class="field" id="pmField"><label>'+tr('Payment method')+'</label>' +
      '<div class="segbtns">' +
        '<button class="segbtn active" data-pm="cash">'+tr('Cash')+'</button>' +
        '<button class="segbtn" data-pm="card">'+tr('Card')+'</button>' +
        '<button class="segbtn" data-pm="wallet">'+tr('Mobile wallet')+'</button>' +
        '<button class="segbtn" data-pm="credit">'+tr('Credit')+'</button>' +
        '<button class="segbtn" data-pm="split">'+tr('Split')+'</button>' +
      '</div>' +
    '</div>' +
    '<div id="pmExtra"></div>' + loyaltyBoxHtml() +
    '<div class="actions"><button class="btn btn-primary btn-block" id="confirmChargeBtn">'+tr('Confirm sale')+'</button></div>';
  var ov = openSheet(html, {center:true});
  loyaltyWire(ov); dscWire(ov);
  var pm = 'cash';
  var cardSt = { devId:null, mode:'Chip', override:null };
  // A voucher (Sanlam, BestHome and so on) pays all or part of the sale. total below is then what is still to be paid by the customer.
  var fullTotal = total, vch = null, vchOpen = false;
  function vchSeg(){ ov.querySelectorAll('[data-pm]').forEach(function(x){ x.classList.toggle('active', x.getAttribute('data-pm') === pm); }); }
  function vchPaint(){
    var box = ov.querySelector('#vchBox'); if(!box) return;
    var pmF = ov.querySelector('#pmField'), hd = ov.querySelector('.sheet-head h2');
    if(hd) hd.textContent = tr('Charge') + ' ' + fmtMoney(total);
    if(pmF) pmF.style.display = (vch && total <= 0) ? 'none' : '';
    if(vch){
      box.innerHTML = '<div class="banner" style="display:block;"><b>'+esc(vch.platform)+' '+tr('voucher')+'</b> · '+esc(vch.code)+'<br>'+tr('Voucher covers')+' <b>'+fmtMoney(vch.amount)+'</b>' +
        (total > 0 ? ' · '+tr('Customer pays')+' <b>'+fmtMoney(total)+'</b>' : ' · '+tr('Nothing more to pay')) +
        (vch.face > vch.amount ? '<br>'+tr('The voucher is worth more than this sale, so only')+' '+fmtMoney(vch.amount)+' '+tr('is used.') : '') + '</div>' +
        '<div class="field"><button class="btn btn-ghost btn-block" id="vchRemove" type="button">'+tr('Remove voucher')+'</button></div>';
      box.querySelector('#vchRemove').addEventListener('click', function(){ vch = null; total = fullTotal; vchOpen = false; if(pm === 'voucher') pm = 'cash'; vchSeg(); vchPaint(); renderExtra(); });
    } else if(vchOpen){
      box.innerHTML = '<div class="field"><label>'+tr('Voucher platform')+'</label><select id="vchPlat">' + voucherPlatforms().map(function(n){ return '<option value="'+esc(n)+'">'+esc(n)+'</option>'; }).join('') + '<option value="__other">'+tr('Another platform')+'</option></select></div>' +
        '<div class="field" id="vchOtherF" style="display:none;"><label>'+tr('Platform name')+'</label><input id="vchOther" autocomplete="off"></div>' +
        '<div class="field"><label>'+tr('Voucher code or number')+'</label><input id="vchCode" autocomplete="off"></div>' +
        '<div class="field"><label>'+tr('Voucher value')+'</label><input id="vchAmt" type="number" inputmode="decimal" step="0.01" placeholder="'+fullTotal.toFixed(2)+'"></div>' +
        '<div id="vchErr" class="banner" style="display:none;"></div>' +
        '<div class="actions"><button class="btn btn-primary btn-block" id="vchApply" type="button">'+tr('Use voucher')+'</button><button class="btn btn-ghost btn-block" id="vchCancel" type="button">'+tr('Cancel')+'</button></div>';
      var sel = box.querySelector('#vchPlat');
      sel.addEventListener('change', function(){ box.querySelector('#vchOtherF').style.display = sel.value === '__other' ? '' : 'none'; });
      box.querySelector('#vchCancel').addEventListener('click', function(){ vchOpen = false; vchPaint(); });
      box.querySelector('#vchApply').addEventListener('click', function(){
        var err = box.querySelector('#vchErr');
        function bad(m){ err.style.display = 'flex'; err.textContent = m; }
        var plat = sel.value === '__other' ? box.querySelector('#vchOther').value.trim() : sel.value;
        var code = box.querySelector('#vchCode').value.trim(), face = mRound2(parseFloat(box.querySelector('#vchAmt').value));
        if(!plat){ bad(tr('Enter the platform name')); return; }
        if(!code){ bad(tr('Enter the voucher code or number')); return; }
        if(!(face > 0)){ bad(tr('Enter the voucher value')); return; }
        var used = voucherCodeUsed(plat, code);
        if(used){ bad(tr('This voucher was already used on receipt') + ' ' + (used.receiptNo || fmtDateTime(used.createdAt)) + '.'); return; }
        var use = Math.min(face, fullTotal);
        vch = { platform:plat, code:code, face:face, amount:use };
        total = mRound2(fullTotal - use);
        if(total <= 0.004){ total = 0; pm = 'voucher'; } else if(pm === 'voucher') pm = 'cash';
        vchOpen = false; vchSeg(); vchPaint(); renderExtra();
      });
    } else {
      box.innerHTML = '<div class="field"><button class="btn btn-ghost btn-block" id="vchOpen" type="button">'+tr('Customer has a voucher')+'</button></div>';
      box.querySelector('#vchOpen').addEventListener('click', function(){ vchOpen = true; vchPaint(); });
    }
  }
  function chargeFinal(m, c, ex){
    ex = ex || {};
    if(vch){
      ex.voucher = { platform:vch.platform, code:vch.code, amount:vch.amount, face:vch.face };
      var pl = voucherPlatforms(); if(pl.indexOf(vch.platform) < 0) btSave({ voucherPlatforms: pl.concat([vch.platform]) });
    }
    finalizeSale(m, c, ex);
  }
  function renderExtra(){
    var extra = ov.querySelector('#pmExtra');
    if(pm === 'cash'){
      extra.innerHTML = '<div class="field"><label>'+tr('Cash received')+'</label><input id="cashRecv" type="number" inputmode="decimal" step="0.01" placeholder="'+total.toFixed(2)+'"></div><div id="changeDue" class="banner" style="display:none;"></div>';
      var input = extra.querySelector('#cashRecv');
      input.addEventListener('input', function(){
        var v = parseFloat(input.value);
        var cd = extra.querySelector('#changeDue');
        if(!isNaN(v) && v >= total){
          cd.style.display='flex'; cd.innerHTML = '<span>Change due: <strong class="num">'+fmtMoney(v-total)+'</strong></span>';
        } else { cd.style.display='none'; }
      });
    } else if(pm === 'card'){
      if(State.posDevices.length){
        extra.innerHTML = '<div class="banner">Record once the card has been swiped, tapped or inserted and approved on your card machine.</div>' + '<div class="field"><label>'+tr('Paid by (name, optional)')+'</label><input id="payerName" placeholder="'+tr('Who is paying?')+'"></div>' + '<div class="field"><label>'+tr('Cash back given to the customer (N$, optional)')+'</label><input id="cashBack" type="number" inputmode="decimal" step="0.01" placeholder="0.00"></div><div id="cbInfo" style="font-size:12.5px;color:var(--text-muted);margin:-6px 2px 10px;"></div>' + posCardHtml(total, cardSt);
        posCardWire(ov, total, cardSt);
      } else {
        extra.innerHTML = '<div class="banner">Record once the card has been swiped, tapped or inserted and approved on your card machine.</div>' + '<div class="field"><label>'+tr('Paid by (name, optional)')+'</label><input id="payerName" placeholder="'+tr('Who is paying?')+'"></div>' + '<div class="field"><label>'+tr('Cash back given to the customer (N$, optional)')+'</label><input id="cashBack" type="number" inputmode="decimal" step="0.01" placeholder="0.00"></div><div id="cbInfo" style="font-size:12.5px;color:var(--text-muted);margin:-6px 2px 10px;"></div>';
      }
      var cbIn = extra.querySelector('#cashBack');
      if(cbIn) cbIn.addEventListener('input', function(){ var v = Math.max(0, parseFloat(cbIn.value)||0); extra.querySelector('#cbInfo').textContent = v > 0 ? tr('Charge the card')+' '+fmtMoney(total+v)+' · '+tr('give the customer')+' '+fmtMoney(v)+' '+tr('in cash') : ''; });
    } else if(pm === 'wallet'){
      extra.innerHTML = '<div class="field"><label>'+tr('Wallet or transfer type')+'</label><select id="walletProv">' +
        WALLET_PROVIDERS.map(function(w){ return '<option value="'+esc(w)+'">'+esc(w)+'</option>'; }).join('') + '</select></div>' +
        '<div class="field"><label>'+tr('Reference or transaction number (optional)')+'</label><input id="walletRef" placeholder="e.g. TXN123456"></div>' + '<div class="field"><label>'+tr('Paid by (name, optional)')+'</label><input id="payerName" placeholder="'+tr('Who is paying?')+'"></div>' +
        '<div class="banner">Record once the payment has been confirmed on your phone or in your bank app.</div>';
    } else if(pm === 'split'){
      var spN = function(id){ var e = extra.querySelector('#'+id); return e ? Math.max(0, mRound2(parseFloat(e.value) || 0)) : 0; };
      extra.innerHTML = '<div class="banner" style="display:block;">'+tr('Enter how much is paid each way. The parts must add up to')+' <b>'+fmtMoney(total)+'</b>.</div>' +
        '<div class="field"><label>'+tr('Cash')+'</label><input id="spCash" type="number" inputmode="decimal" step="0.01" min="0" placeholder="0.00"></div>' +
        '<div class="field"><label>'+tr('Card')+'</label><input id="spCard" type="number" inputmode="decimal" step="0.01" min="0" placeholder="0.00"></div>' +
        '<div class="field"><label>'+tr('Mobile wallet')+'</label><input id="spWallet" type="number" inputmode="decimal" step="0.01" min="0" placeholder="0.00"></div>' +
        '<div class="field" id="spWF" style="display:none;"><label>'+tr('Wallet or transfer type')+'</label><select id="walletProv">'+WALLET_PROVIDERS.map(function(w){ return '<option value="'+esc(w)+'">'+esc(w)+'</option>'; }).join('')+'</select></div>' +
        '<div id="spLeft" class="banner" style="display:block;"></div>';
      var spPaint = function(){
        var c = spN('spCash'), k = spN('spCard'), w = spN('spWallet'), left = mRound2(total - c - k - w), el = extra.querySelector('#spLeft');
        extra.querySelector('#spWF').style.display = w > 0 ? '' : 'none';
        el.innerHTML = Math.abs(left) < 0.005 ? '<span style="color:var(--success);">'+tr('The parts add up')+'</span>' : (left > 0 ? tr('Still to enter')+' <b>'+fmtMoney(left)+'</b>' : tr('Too much by')+' <b>'+fmtMoney(-left)+'</b>');
      };
      ['spCash','spCard','spWallet'].forEach(function(id){ extra.querySelector('#'+id).addEventListener('input', spPaint); });
      spPaint();
    } else if(pm === 'voucher'){
      extra.innerHTML = '<div class="banner">'+tr('The voucher covers the whole sale. There is nothing more to collect.')+'</div>';
    } else {
      if(State.customers.length === 0){
        extra.innerHTML = '<div class="banner">'+ICONS.warn+'<span>No customers yet. Add one from the Credit tab first.</span></div>';
      } else {
        extra.innerHTML = '<div class="field"><label>'+tr('Customer')+'</label><select id="custSelect">'+custOptions+'</select></div>' +
          '<div class="banner">'+ICONS.warn+'<span>This adds '+fmtMoney(total)+' to the customer’s balance owed.</span></div>';
      }
    }
  }
  var _re0 = renderExtra; renderExtra = function(){ _re0(); btFxCash(ov, pm, total); };
  renderExtra();
  ov.querySelectorAll('[data-pm]').forEach(function(b){
    b.addEventListener('click', function(){
      ov.querySelectorAll('[data-pm]').forEach(function(x){ x.classList.remove('active'); });
      b.classList.add('active');
      pm = b.getAttribute('data-pm');
      renderExtra();
    });
  });
  vchPaint();
  ov.querySelector('#confirmChargeBtn').addEventListener('click', function(){
    if(pm === 'voucher'){ chargeFinal('voucher', null, {}); return; }
    if(pm === 'split'){
      var gv = function(id){ var e = ov.querySelector('#'+id); return e ? Math.max(0, mRound2(parseFloat(e.value) || 0)) : 0; };
      var sc = gv('spCash'), sk = gv('spCard'), sw = gv('spWallet'), parts = [];
      if(Math.abs(mRound2(total - sc - sk - sw)) >= 0.005){ toast(tr('The parts must add up to') + ' ' + fmtMoney(total)); return; }
      var wpv = ov.querySelector('#walletProv'), wprov = wpv ? wpv.value : '';
      if(sc > 0) parts.push({ method:'cash', amount:sc });
      if(sk > 0) parts.push({ method:'card', amount:sk });
      if(sw > 0) parts.push({ method:'wallet', amount:sw, walletProvider:wprov });
      if(parts.length < 2){ toast(tr('Use two or more ways to pay, or pick one payment method')); return; }
      var main = parts.slice().sort(function(a, b){ return b.amount - a.amount; })[0];
      chargeFinal(main.method, null, { payments:parts, cashReceived: sc || undefined, changeGiven: sc ? 0 : undefined, walletProvider: sw > 0 ? wprov : undefined });
      return;
    }
    if(pm === 'credit'){
      if(State.customers.length === 0){ toast('Add a customer first'); return; }
      var sel = ov.querySelector('#custSelect');
      var custId = sel.value;
      var cust = State.customers.find(function(c){ return c.id===custId; });
      if(cust && overCreditLimit(cust, total)){ confirmOverLimit(cust, total, function(){ chargeFinal(pm, cust); }); return; }
      chargeFinal(pm, cust);
    } else if(pm === 'wallet'){
      var wp = ov.querySelector('#walletProv'), wr = ov.querySelector('#walletRef');
      var pnw = ov.querySelector('#payerName');
      chargeFinal(pm, null, { walletProvider: wp ? wp.value : '', payRef: wr ? wr.value.trim() : '', payerName: pnw ? pnw.value.trim() : '' });
    } else if(pm === 'cash'){
      var cr = ov.querySelector('#cashRecv'), rv = cr ? parseFloat(cr.value) : NaN;
      if(cr && cr.value !== '' && (isNaN(rv) || rv < total)){ toast('Cash received is less than the total'); return; }
      var got = (cr && cr.value !== '') ? rv : total;
      chargeFinal(pm, null, { cashReceived: got, changeGiven: Math.max(0, Math.round((got-total)*100)/100) });
    } else if(pm === 'card'){
      posCardSubmit(ov, total, cardSt).then(function(ex){ if(ex){ var pn = ov.querySelector('#payerName'); ex.payerName = pn ? pn.value.trim() : ''; var cbi = ov.querySelector('#cashBack'), cbq = cbi ? Math.round((parseFloat(cbi.value)||0)*100)/100 : 0; if(cbq > 0){ ex.cashBack = cbq; ex.cardCharged = Math.round((total+cbq)*100)/100; } chargeFinal('card', null, ex); } });
    } else {
      chargeFinal(pm, null);
    }
  });
}

// Warns (and asks to confirm) when a credit sale would push a customer past
// their credit limit. A limit of 0 or empty means no limit.
function overCreditLimit(cust, addAmount){
  var lim = cust && cust.creditLimit > 0 ? cust.creditLimit : 0;
  return lim > 0 && ((cust.balance||0) + addAmount) > lim;
}
function confirmOverLimit(cust, addAmount, proceed){
  var go = function(approver){ logAudit('other','customer',cust.id,'Credit limit override for '+cust.name+': owes '+fmtMoney((cust.balance||0)+addAmount)+' against a limit of '+fmtMoney(cust.creditLimit)+(approver ? ' (approved by '+approver.name+')' : '')); proceed(); };
  confirmSheet(tr('Over credit limit'), cust.name+' '+tr('has a credit limit of')+' '+fmtMoney(cust.creditLimit)+'. '+tr('This sale would take what they owe to')+' '+fmtMoney((cust.balance||0)+addAmount)+'. '+tr('Sell anyway?'), tr('Sell anyway'), function(){
    if(isRestricted()) askApprovalSheet(tr('Approve selling over the credit limit'), go); else go(null);
  }, true);
}
function finalizeSale(method, customer, extra){
  if(!State.cart.length || !uiOnce('finalizeSale', 900)) return;   // a second tap on Complete sale does nothing
  if(cartHasMock()){ toast(tr('Test products cannot be sold. Remove them from the cart first.')); return; }
  loyaltyNormalize();
  var items = State.cart.map(function(i){ var tp = State.products.find(function(x){ return x.id===i.productId; }); return { productId:i.productId, name:i.name, qty:i.qty, unitPrice:i.unitPrice, cost:i.cost||0, lineTotal:mMul(i.unitPrice, i.qty) / 100, taxCategory:(tp && tp.taxCategory) || 'STANDARD' }; });
  var total = cartTotal();
  var cost = cartCost();
  var dscL = cartDiscountLine();
  var sale = {
    items: items,
    total: total,
    cost: cost,
    profit: total - cost,
    paymentMethod: method,
    customerId: customer ? customer.id : null,
    customerName: customer ? customer.name : null,
    tillId: State.till.current ? State.till.current.id : null,
    cashierName: State.session ? State.session.name : null,
    branchId: (State.settings.currentBranchId && State.settings.currentBranchId!=='all') ? State.settings.currentBranchId : null,
    stock: stockSnapshot(),   // whole-shop stock position when this sale was made (before it is taken off the shelf)
    createdAt: new Date().toISOString()
  };
  if(extra) Object.assign(sale, extra);
  Object.keys(sale).forEach(function(k){ if(sale[k] === undefined) delete sale[k]; });
  if(dscL) sale.discount = { amount:Math.abs(dscL.unitPrice), approvedBy:dscL.discountBy || '' };
  var _vm = null; try{ _vm = entSaleMeta(); if(_vm) Object.assign(sale, _vm.extra); }catch(e){}
  saleStamp(sale, items);
  loyaltyStamp(sale, customer);
  if(POS.open && POS.user){ sale.viaPos = true; sale.posUserId = POS.user.id; }
  var saleAddP = refs.sales.add(sale);
  Object.defineProperty(sale, '__fiscal', { value: Fiscal.track(sale, saleAddP), enumerable:false, configurable:true });
  saleAddP.then(function(ref){ logAudit('create','sale', ref&&ref.id, (items.length)+' item(s), '+fmtMoney(total)); if(sale.overrideBy) logAudit('other','sale', ref&&ref.id, 'Card limit override approved by '+sale.overrideBy+' on '+(sale.posDeviceName||'terminal')+': '+(sale.overrideNote||'')); });
  loyaltyApply(sale);
  try{ if(_vm) _vm.after(sale); }catch(e){}
  // decrement stock
  var stockChanges = [];
  items.forEach(function(it){
    var p = State.products.find(function(x){ return x.id===it.productId; });
    if(p && p.stockQty!=null){
      var newQty = Math.max(0, p.stockQty - it.qty);
      refs.products.doc(p.id).update({ stockQty: newQty });
      stockChanges.push({ product:p, newQty:newQty });
    }
  });
  checkLowStockAlerts(stockChanges);
  // credit ledger
  if(method === 'credit' && customer){
    var owedNow = salePaidAmt(sale);
    var newBal = (customer.balance||0) + owedNow;
    refs.customers.doc(customer.id).update({ balance: newBal });
    refs.customers.doc(customer.id).collection('ledger').add({ type:'charge', amount: owedNow, note:'Sale on credit', createdAt:new Date().toISOString(), balanceAfter:newBal });
  }
  if(method === 'cash' || sale.cashBack > 0 || (saleIsSplit(sale) && salePayParts(sale).some(function(q){ return q.method === 'cash'; }))) openCashDrawer(false);
  State.cart = [];
  closeModal();
  renderCartBar();
  toast('Sale recorded, ' + fmtMoney(total));
  offerSaleReceipt(sale, customer);
  if(POS.open) setTimeout(posRender, 60);
  touchUserActive(true); syncNowSafe();
}

function offerSaleReceipt(sale, customer){
  var number = sale.receiptNo || docNumberNext('INV', true);
  var draft = {
    number: number, saleReceipt: !!sale.receiptNo, taxSnap: sale.tax || null,
    servedBy: servedByName({}),
    billToName: customer ? customer.name : 'Customer',
    billToContact: customer ? [customer.phone, customer.email].filter(Boolean).join('\n') : '',
    dateStr: todayKey(),
    dueDateStr: '',
    notes: loyaltyNote(sale),
    at: sale.createdAt,
    payMethod: sale.paymentMethod,
    payments: saleIsSplit(sale) ? sale.payments : null,
    fiscalKey: sale.fiscalId || null,
    walletProvider: sale.walletProvider || '',
    cashBack: sale.cashBack || 0,
    voucher: sale.voucher ? { platform:sale.voucher.platform, amount:Math.abs(sale.voucher.amount) } : null,
    received: saleIsSplit(sale) ? null : sale.paymentMethod === 'voucher' ? null : (sale.paymentMethod === 'cash' ? (sale.cashReceived != null ? sale.cashReceived : sale.total) : (sale.paymentMethod === 'credit' ? 0 : salePaidAmt(sale))),
    items: (sale.items||[]).map(function(it){ return { desc: it.name, qty: it.qty, unitPrice: it.unitPrice, cat: it.taxCategory, productId: it.productId }; })
  };
  if(sale.__fiscal) sale.__fiscal.then(function(r){ if(r && r.record) draft.fiscalKey = r.record.id; });
  var sendKind = sale.paymentMethod === 'credit' ? 'invoice' : 'receipt';
  var html = '<div class="sheet-head"><h2>'+tr('Sale recorded')+'</h2></div>' +
    '<div style="font-size:14px;color:var(--text-muted);margin-bottom:16px;">Total '+fmtMoney(sale.total)+'. Print a receipt for the customer?'+(sale.loyaltyCustomerId && (sale.pointsEarned||sale.pointsRedeemed) ? '<br><b style="color:var(--success);">'+esc(loyaltyNote(sale))+'</b>' : '')+'</div>' +
    '<div class="actions" style="display:grid;grid-template-columns:1fr 1fr;gap:8px;">' +
      '<button class="btn btn-accent btn-block" id="salePrintBtn" type="button">'+tr('Print')+'</button>' +
      bluetoothPrintButtonHtml('saleBtPrintBtn') +
      '<button class="btn btn-ghost btn-block" id="saleSendBtn" type="button">'+tr('Email')+'</button>' +
      '<button class="btn btn-ghost btn-block" id="saleWaBtn" type="button">'+tr('WhatsApp')+'</button>' +
    '</div>' +
    '<div class="actions" style="margin-top:8px;"><button class="btn btn-ghost btn-block" id="saleReceiptBtn" type="button">'+tr('Download receipt')+'</button></div>' +
    '<div class="actions" style="margin-top:8px;"><button class="btn btn-ghost btn-block" id="saleSkipBtn" type="button">'+tr('Not now')+'</button></div>';
  var ov = openSheet(html, {center:true});
  ov.querySelector('#saleSkipBtn').addEventListener('click', closeModal);
  var saleNumberCommitted = false;
  // Email and WhatsApp each open the send sheet limited to that one channel; the full sheet stays on invoices and quotes
  function openSendOnly(flag){
    var sctx = documentSendCtx(draft, sendKind, {
      customerId: customer ? customer.id : null,
      onHandedOff: function(){ if(!saleNumberCommitted){ saleNumberCommitted = true; commitInvoiceNumber(draft, sendKind, customer ? customer.id : null); } }
    });
    sctx[flag] = true;
    openSendSheet(sctx);
  }
  ov.querySelector('#saleSendBtn').addEventListener('click', function(){ openSendOnly('emailOnly'); });
  ov.querySelector('#saleWaBtn').addEventListener('click', function(){ openSendOnly('waOnly'); });
  // normal print: the browser's own print dialog
  ov.querySelector('#salePrintBtn').addEventListener('click', async function(){
    var btn = ov.querySelector('#salePrintBtn');
    btn.disabled = true; var oldLabel = btn.textContent; btn.textContent = tr('Preparing…');
    var ready = await ensureJsPDF();
    var doc = ready ? buildReceiptPdf(draft) : null;
    btn.disabled = false; btn.textContent = oldLabel;
    if(!doc){ toast('Couldn’t load the PDF engine, check your connection and try again'); return; }
    printPdfDoc(doc); closeModal();
  });
  var btPrintBtn = ov.querySelector('#saleBtPrintBtn');
  if(btPrintBtn && !btPrintBtn.disabled) btPrintBtn.addEventListener('click', function(){ printReceiptViaBluetooth(draft, btPrintBtn); });
  ov.querySelector('#saleReceiptBtn').addEventListener('click', async function(){
    var btn = ov.querySelector('#saleReceiptBtn');
    btn.disabled = true; var oldLabel = btn.textContent; btn.textContent = 'Preparing…';
    var ready = await ensureJsPDF();
    if(!ready){ btn.disabled = false; btn.textContent = oldLabel; toast('Couldn’t load the PDF engine, check your connection and try again'); return; }
    var doc = buildReceiptPdf(draft);
    if(!doc){ btn.disabled = false; btn.textContent = oldLabel; toast('Couldn’t load the PDF engine, check your connection and try again'); return; }
    // a PDF straight to the device with no format question; the format chooser stays on the other download buttons
    saveBlobFile('receipt-'+todayKey()+'-'+sale.total+'.pdf', doc.output('blob')).then(function(ok){
      if(ok) toast('Receipt downloaded');
      closeModal();
    });
  });
}

/* ============================== POINT OF SALE (terminal) ==============================
   A POS terminal screen with its own staff login, a link to registered card machines /
   terminals, swipe limits and card batch settlement. Pesa records and controls card sales;
   it does not process cards or talk to the bank's card machine itself. */
var POS_PROVIDERS = ['FNB','Standard Bank','Bank Windhoek','Nedbank','PayToday','Other'];
var POS_KINDS = ['Card machine','POS terminal (phone or tablet)'];
var POS_MODES = ['Chip','Tap','Swipe','Manual'];
var POS_BRANDS = ['Visa','Mastercard','Maestro','Other'];
var POS = { recCat:'all', recRange:'today', open:false, user:null, orig:null, tab:'sell', search:'', key:'', idle:null, pick:null, typed:'' };

function posBoundKey(){ return 'pesa_pos_device_' + WS.id; }
function posBoundInfo(){ try{ return JSON.parse(localStorage.getItem(posBoundKey()) || 'null'); }catch(e){ return null; } }
function posBind(id){
  try{ if(id) localStorage.setItem(posBoundKey(), JSON.stringify({ deviceId:id, at:Date.now() })); else localStorage.removeItem(posBoundKey()); }catch(e){}
}
// The registered device this phone/tablet is linked to (or null).
function posDevice(){
  var b = posBoundInfo(); if(!b) return null;
  var d = State.posDevices.find(function(x){ return x.id === b.deviceId; });
  if(!d) return null;
  if(!d.linkedAt && Date.now() - (b.at||0) > 15000) return null;
  return d;
}
function posSum(list){ return list.reduce(function(s,x){ return s + (x.total||0) + (x.cashBack||0); }, 0); }
function posStats(dev){
  var now = Date.now(), tk = todayKey();
  var sales = State.sales.filter(function(s){ return s.paymentMethod === 'card' && s.posDeviceId === dev.id; });
  var today = sales.filter(function(s){ return todayKey(new Date(s.createdAt)) === tk; });
  var hour = sales.filter(function(s){ return now - new Date(s.createdAt).getTime() < 3600000; });
  var lastB = State.posBatches.filter(function(b){ return b.deviceId === dev.id; })[0];
  var since = lastB ? new Date(lastB.settledAt).getTime() : 0;
  var batch = sales.filter(function(s){ return new Date(s.createdAt).getTime() > since; });
  return { todayTotal:posSum(today), todayCount:today.length, hourCount:hour.length,
    batchTotal:posSum(batch), batchCount:batch.length, batchSince: lastB ? lastB.settledAt : null,
    lastSale: sales[0] ? sales[0].createdAt : null, recent: sales.slice(0,8) };
}
function posLim(dev, k){ var v = dev && dev.limits ? parseFloat(dev.limits[k]) : 0; return v > 0 ? v : 0; }
// Checks one card sale against the terminal's limits. Returns {blocked, issues[], notes[]}.
function posLimitCheck(dev, amount, mode){
  if(dev.status === 'blocked') return { blocked:true, issues:[tr('This terminal is blocked.')], notes:[] };
  var st = posStats(dev), out = [], notes = [];
  if(posLim(dev,'minCard') && amount < posLim(dev,'minCard')) out.push(tr('Card sales under')+' '+fmtMoney(posLim(dev,'minCard'))+' '+tr('are not allowed on this terminal.'));
  if(posLim(dev,'perSwipe') && amount > posLim(dev,'perSwipe')) out.push(tr('Over the per swipe limit of')+' '+fmtMoney(posLim(dev,'perSwipe'))+'.');
  if(mode === 'Tap' && posLim(dev,'tap') && amount > posLim(dev,'tap')) out.push(tr('Over the tap limit of')+' '+fmtMoney(posLim(dev,'tap'))+'. '+tr('Use chip and PIN instead.'));
  if(posLim(dev,'daily') && st.todayTotal + amount > posLim(dev,'daily')) out.push(tr('This would take today’s card total to')+' '+fmtMoney(st.todayTotal+amount)+', '+tr('over the daily limit of')+' '+fmtMoney(posLim(dev,'daily'))+'.');
  if(posLim(dev,'dailyCount') && st.todayCount + 1 > posLim(dev,'dailyCount')) out.push(tr('Daily swipe limit reached')+' ('+posLim(dev,'dailyCount')+').');
  if(posLim(dev,'hourlyCount') && st.hourCount + 1 > posLim(dev,'hourlyCount')) out.push(tr('Hourly swipe limit reached')+' ('+posLim(dev,'hourlyCount')+').');
  if(posLim(dev,'pinAbove') && amount > posLim(dev,'pinAbove') && (mode === 'Tap' || mode === 'Swipe')) notes.push(tr('Above')+' '+fmtMoney(posLim(dev,'pinAbove'))+' '+tr('the customer must enter their PIN.'));
  return { blocked:false, issues:out, notes:notes, stats:st };
}
function posLimitSummaryHtml(dev){
  var st = posStats(dev), bits = [];
  if(posLim(dev,'perSwipe')) bits.push(tr('Per swipe max')+' '+fmtMoney(posLim(dev,'perSwipe')));
  if(posLim(dev,'tap')) bits.push(tr('Tap max')+' '+fmtMoney(posLim(dev,'tap')));
  if(posLim(dev,'daily')) bits.push(tr('Today')+' '+fmtMoney(st.todayTotal)+' / '+fmtMoney(posLim(dev,'daily')));
  if(posLim(dev,'dailyCount')) bits.push(tr('Swipes today')+' '+st.todayCount+' / '+posLim(dev,'dailyCount'));
  if(posLim(dev,'hourlyCount')) bits.push(tr('This hour')+' '+st.hourCount+' / '+posLim(dev,'hourlyCount'));
  return bits.length ? bits.join(' · ') : tr('No limits set on this terminal.');
}
async function posVerifyManager(code){
  var list = State.users.filter(function(u){ return u.active !== false && (u.role === 'owner' || u.role === 'manager') && u.passHash; });
  for(var i=0;i<list.length;i++){ if(await pwCheck(code, list[i].passHash)){ pwUpgrade(list[i], code); return list[i]; } }
  return null;
}

/* ---- card section of the charge sheet ---- */
function posCardHtml(total, st){
  var devs = State.posDevices;
  var bound = posDevice();
  if(!st.devId) st.devId = bound && bound.status !== 'blocked' ? bound.id : (devs.filter(function(d){ return d.status !== 'blocked'; })[0] || devs[0]).id;
  return '<div class="field"><label>'+tr('Card terminal')+'</label><select id="posDev">' +
      devs.map(function(d){ return '<option value="'+d.id+'"'+(d.id===st.devId?' selected':'')+'>'+esc(d.name)+(d.terminalId?' · '+esc(d.terminalId):'')+(d.status==='blocked'?' ('+tr('blocked')+')':'')+'</option>'; }).join('') +
    '</select></div>' +
    '<div class="field"><label>'+tr('How was the card used?')+'</label><div class="segbtns">' +
      POS_MODES.map(function(m){ return '<button type="button" class="segbtn'+(m===st.mode?' active':'')+'" data-pmode="'+m+'">'+tr(m)+'</button>'; }).join('') +
    '</div></div>' +
    '<div class="field"><label>'+tr('Card type')+'</label><select id="posBrand">'+POS_BRANDS.map(function(b){ return '<option>'+b+'</option>'; }).join('')+'</select></div>' +
    '<div class="field"><label>'+tr('Last 4 digits of the card (optional)')+'</label><input id="posLast4" inputmode="numeric" maxlength="4" placeholder="1234"></div>' +
    '<div class="field"><label id="posAuthLbl">'+tr('Approval code from the terminal')+'</label><input id="posAuth" placeholder="e.g. 045821" autocomplete="off"></div>' +
    '<div id="posLimitInfo"></div><div id="posOverrideBox"></div>';
}
function posCardWire(ov, total, st){
  var baseTotal = total;
  function amt(){ var cb = ov.querySelector('#cashBack'); return baseTotal + (cb ? Math.max(0, parseFloat(cb.value)||0) : 0); }
  function dev(){ return State.posDevices.find(function(d){ return d.id === st.devId; }); }
  function refresh(){
    var d = dev(); if(!d) return;
    var chk = posLimitCheck(d, amt(), st.mode);
    var box = ov.querySelector('#posLimitInfo'), h = '';
    var lbl = ov.querySelector('#posAuthLbl');
    if(lbl) lbl.textContent = d.requireAuthCode ? tr('Approval code from the terminal (required)') : tr('Approval code from the terminal (optional)');
    if(chk.blocked || chk.issues.length){
      h = '<div class="banner" style="background:var(--danger-bg);color:var(--danger);">'+ICONS.warn+'<span>' + chk.issues.map(esc).join('<br>') + '</span></div>';
    } else {
      h = '<div class="banner">'+ICONS.check+'<span>'+tr('Within this terminal’s limits.')+'</span></div>';
    }
    if(chk.notes && chk.notes.length) h += '<div class="banner">'+ICONS.info+'<span>'+chk.notes.map(esc).join('<br>')+'</span></div>';
    h += '<div style="font-size:12px;color:var(--text-muted);margin:4px 2px 10px;">'+esc(posLimitSummaryHtml(d))+'</div>';
    box.innerHTML = h;
    st.override = null; ov.querySelector('#posOverrideBox').innerHTML = '';
  }
  ov.querySelector('#posDev').addEventListener('change', function(e){ st.devId = e.target.value; refresh(); });
  var cbEl = ov.querySelector('#cashBack'); if(cbEl) cbEl.addEventListener('input', refresh);
  ov.querySelectorAll('[data-pmode]').forEach(function(b){
    b.addEventListener('click', function(){
      ov.querySelectorAll('[data-pmode]').forEach(function(x){ x.classList.remove('active'); });
      b.classList.add('active'); st.mode = b.getAttribute('data-pmode'); refresh();
    });
  });
  refresh();
}
// Returns the extra sale fields, or null when the sale must not go ahead yet.
async function posCardSubmit(ov, total, st){
  if(!State.posDevices.length) return {};
  var d = State.posDevices.find(function(x){ return x.id === st.devId; });
  if(!d) return {};
  var last4 = ov.querySelector('#posLast4').value.trim();
  if(last4 && !/^\d{4}$/.test(last4)){ toast(tr('Last 4 digits must be 4 numbers')); return null; }
  var auth = ov.querySelector('#posAuth').value.trim();
  if(d.requireAuthCode && !auth){ toast(tr('Enter the approval code from the terminal')); return null; }
  var cbv = ov.querySelector('#cashBack'); var cashBackAmt = cbv ? Math.max(0, parseFloat(cbv.value)||0) : 0;
  var chk = posLimitCheck(d, total + cashBackAmt, st.mode);
  var extra = { posDeviceId:d.id, posDeviceName:d.name, terminalId:d.terminalId || '', cardBrand:ov.querySelector('#posBrand').value, cardLast4:last4, authCode:auth, entryMode:st.mode };
  if(chk.blocked){ toast(tr('This terminal is blocked.')); return null; }
  if(chk.issues.length){
    if(st.override){ extra.overrideBy = st.override; extra.overrideNote = chk.issues.join(' '); return extra; }
    var box = ov.querySelector('#posOverrideBox');
    if(isManagerOrOwner()){
      box.innerHTML = '<div class="actions"><button class="btn btn-danger btn-block" id="posOvBtn" type="button">'+tr('Approve over limit as')+' '+esc(State.session.name)+'</button></div>';
      box.querySelector('#posOvBtn').addEventListener('click', function(){ st.override = State.session.name; ov.querySelector('#confirmChargeBtn').click(); });
    } else {
      box.innerHTML = '<div class="field"><label>'+tr('Manager approval: enter a manager or owner PIN or password')+'</label><input id="posOvCode" type="password" autocomplete="off"></div>' +
        '<div class="actions"><button class="btn btn-danger btn-block" id="posOvBtn" type="button">'+tr('Approve')+'</button></div>';
      box.querySelector('#posOvBtn').addEventListener('click', async function(){
        var code = box.querySelector('#posOvCode').value; if(!code) return;
        if(authLeft('posmgr')){ toast(authLockText('posmgr')); return; }
        var m = await posVerifyManager(code);
        if(!m){ var fm = authFailed('posmgr', 'manager approval at the point of sale'); toast(fm.locked ? authLockText('posmgr') : tr('That code is not a manager or owner.')); return; }
        authOk('posmgr'); st.override = m.name; ov.querySelector('#confirmChargeBtn').click();
      });
    }
    toast(tr('Over the terminal limit. A manager must approve.'));
    return null;
  }
  return extra;
}

/* ---- registered devices (owner / manager) ---- */
function posNewCode(){ return String(Math.floor(100000 + Math.random()*900000)); }
function posFmtCode(c){ return c ? String(c).slice(0,3)+' '+String(c).slice(3) : ''; }
function openPosDevicesSheet(){
  var rows = State.posDevices.length ? '<div class="rowlist">' + State.posDevices.map(function(d){
    var st = posStats(d);
    return '<div class="row" data-posd="'+d.id+'"><div class="avatar">'+ICONS.till+'</div><div class="main"><div class="title">'+esc(d.name)+'</div>' +
      '<div class="sub">'+esc(d.provider||'')+(d.terminalId?' · '+esc(d.terminalId):'')+' · '+(d.status==='blocked'?tr('Blocked'):(d.linkedAt?tr('Linked'):tr('Not linked yet')))+'</div></div>' +
      '<div class="trail"><div class="amt num">'+fmtMoney(st.todayTotal)+'</div><div class="note">'+st.todayCount+' '+tr('swipes today')+'</div></div></div>';
  }).join('') + '</div>' : '<div class="empty" style="padding:14px 0;">'+tr('No card terminals registered yet. Add your card machine or POS terminal to set swipe limits and track card sales per device.')+'</div>';
  var ov = openSheet('<div class="sheet-head"><h2>'+tr('Card terminals and limits')+'</h2></div>' + rows +
    '<div class="actions"><button class="btn btn-primary btn-block" id="posAddBtn">'+tr('Add terminal')+'</button></div>' +
    '<div class="banner" style="margin-top:12px;">'+ICONS.info+'<span>'+tr('Pesa records and controls card sales. It does not process cards or connect directly to your bank’s card machine. Enter the sale on the machine, then record it here with the approval code.')+'</span></div>');
  ov.querySelector('#posAddBtn').addEventListener('click', function(){ openPosDeviceForm(null); });
  ov.querySelectorAll('[data-posd]').forEach(function(r){ r.addEventListener('click', function(){ openPosDeviceDetail(r.getAttribute('data-posd')); }); });
}
function openPosDeviceForm(d){
  d = d || {}; var L = d.limits || {};
  function f(id, label, val, ph, num){ return '<div class="field"><label>'+tr(label)+'</label><input id="'+id+'" '+(num?'type="number" inputmode="decimal" step="0.01" ':'')+'placeholder="'+(ph||'')+'" value="'+esc(val==null?'':val)+'"></div>'; }
  var html = '<div class="sheet-head"><h2>'+(d.id?tr('Edit terminal'):tr('Add terminal'))+'</h2></div>' +
    f('pdName','Name','' + (d.name||''),'e.g. Front counter machine') +
    '<div class="field"><label>'+tr('Type')+'</label><select id="pdKind">'+POS_KINDS.map(function(k){ return '<option value="'+k+'"'+(d.kind===k?' selected':'')+'>'+tr(k)+'</option>'; }).join('')+'</select></div>' +
    '<div class="field"><label>'+tr('Bank or provider')+'</label><select id="pdProv">'+POS_PROVIDERS.map(function(k){ return '<option'+(d.provider===k?' selected':'')+'>'+k+'</option>'; }).join('')+'</select></div>' +
    f('pdTid','Terminal ID',d.terminalId,'') + f('pdMid','Merchant ID',d.merchantId,'') + f('pdSer','Serial number',d.serial,'') +
    (State.branches.length ? '<div class="field"><label>'+tr('Branch')+'</label><select id="pdBranch"><option value="">'+tr('Any branch')+'</option>'+State.branches.map(function(b){ return '<option value="'+b.id+'"'+(d.branchId===b.id?' selected':'')+'>'+esc(b.name)+'</option>'; }).join('')+'</select></div>' : '') +
    '<div class="section-title">'+tr('Swipe limits')+'</div>' +
    '<div style="font-size:12px;color:var(--text-muted);margin-bottom:8px;">'+tr('Leave a limit empty or 0 for no limit.')+'</div>' +
    f('pdPer','Max per swipe (N$)',L.perSwipe,'0',1) + f('pdTap','Max per tap (contactless) (N$)',L.tap,'0',1) +
    f('pdMin','Minimum card sale (N$)',L.minCard,'0',1) + f('pdPin','Ask for PIN above (N$)',L.pinAbove,'0',1) +
    f('pdDay','Max card total per day (N$)',L.daily,'0',1) + f('pdDayN','Max swipes per day',L.dailyCount,'0',1) + f('pdHrN','Max swipes per hour',L.hourlyCount,'0',1) +
    '<div class="section-title">'+tr('Security')+'</div>' +
    f('pdLock','Auto lock after (minutes, 0 = never)',d.autoLockMin==null?5:d.autoLockMin,'5',1) +
    '<div class="field"><label><input type="checkbox" id="pdAuthReq"'+(d.requireAuthCode?' checked':'')+' style="width:auto;margin-right:8px;">'+tr('Require the approval code on every card sale')+'</label></div>' +
    '<div class="actions"><button class="btn btn-ghost btn-block" id="pdCancel">'+tr('Cancel')+'</button><button class="btn btn-primary btn-block" id="pdSave">'+tr('Save')+'</button></div>';
  var ov = openSheet(html);
  ov.querySelector('#pdCancel').addEventListener('click', function(){ d.id ? openPosDeviceDetail(d.id) : openPosDevicesSheet(); });
  ov.querySelector('#pdSave').addEventListener('click', function(){
    var name = ov.querySelector('#pdName').value.trim();
    if(!name){ toast(tr('Give the terminal a name')); return; }
    function n(id){ var v = parseFloat(ov.querySelector(id).value); return v > 0 ? v : 0; }
    var rec = { name:name, kind:ov.querySelector('#pdKind').value, provider:ov.querySelector('#pdProv').value,
      terminalId:ov.querySelector('#pdTid').value.trim(), merchantId:ov.querySelector('#pdMid').value.trim(), serial:ov.querySelector('#pdSer').value.trim(),
      branchId: ov.querySelector('#pdBranch') ? ov.querySelector('#pdBranch').value : '',
      limits:{ perSwipe:n('#pdPer'), tap:n('#pdTap'), minCard:n('#pdMin'), pinAbove:n('#pdPin'), daily:n('#pdDay'), dailyCount:n('#pdDayN'), hourlyCount:n('#pdHrN') },
      autoLockMin: n('#pdLock'), requireAuthCode: ov.querySelector('#pdAuthReq').checked };
    if(d.id){
      refs.posDevices.doc(d.id).update(rec); logAudit('update','posDevice',d.id,'Terminal '+name+' updated');
      toast(tr('Saved')); setTimeout(function(){ openPosDeviceDetail(d.id); }, 50);
    } else {
      Object.assign(rec, { status:'active', linkCode:posNewCode(), linkedAt:'', createdAt:new Date().toISOString() });
      refs.posDevices.add(rec).then(function(ref){ logAudit('create','posDevice',ref&&ref.id,'Terminal '+name+' added'); toast(tr('Terminal added')); openPosDeviceDetail(ref.id); });
    }
  });
}
function openPosDeviceDetail(id){
  var d = State.posDevices.find(function(x){ return x.id === id; });
  if(!d){ openPosDevicesSheet(); return; }
  var st = posStats(d);
  function line(a,b){ return '<div class="sumline"><span>'+a+'</span><span class="num">'+b+'</span></div>'; }
  var linkBlock = d.linkedAt
    ? '<div class="banner">'+ICONS.check+'<span>'+tr('Linked')+' · '+fmtDateTime(d.linkedAt)+(d.linkedInfo?' · '+esc(d.linkedInfo):'')+(d.lastSeen?'<br>'+tr('Last seen')+' '+fmtDateTime(d.lastSeen):'')+'</span></div>'
    : '<div class="field"><label>'+tr('Link code')+'</label><div style="font-size:30px;font-weight:700;letter-spacing:.12em;text-align:center;padding:10px;background:var(--surface-2);border-radius:12px;" class="num">'+esc(posFmtCode(d.linkCode))+'</div>' +
      '<div style="font-size:12px;color:var(--text-muted);margin-top:6px;">'+tr('On the phone or tablet you want to use as this terminal, open Point of sale and enter this code. That device must already share this business (see Advanced Pesa Connection).')+'</div></div>';
  var html = '<div class="sheet-head"><h2>'+esc(d.name)+'</h2></div>' +
    '<div style="font-size:13px;color:var(--text-muted);margin-bottom:10px;">'+esc([d.provider,d.kind&&tr(d.kind),d.terminalId&&('TID '+d.terminalId),d.merchantId&&('MID '+d.merchantId),d.serial&&('S/N '+d.serial)].filter(Boolean).join(' · '))+'</div>' +
    (d.status==='blocked'?'<div class="banner" style="background:var(--danger-bg);color:var(--danger);">'+ICONS.warn+'<span>'+tr('Blocked. No card sales can be recorded on this terminal.')+'</span></div>':'') +
    linkBlock +
    '<div class="section-title">'+tr('Limits')+'</div>' +
    '<div style="font-size:13px;margin-bottom:6px;">'+esc(posLimitSummaryHtml(d))+'</div>' +
    '<div class="section-title">'+tr('Card activity')+'</div>' +
    line(tr('Today'), fmtMoney(st.todayTotal)+' · '+st.todayCount) +
    line(tr('Since last settlement'), fmtMoney(st.batchTotal)+' · '+st.batchCount) +
    (st.lastSale ? line(tr('Last card sale'), fmtDateTime(st.lastSale)) : '') +
    '<div class="actions" style="margin-top:12px;"><button class="btn btn-accent btn-block" id="pdSettle">'+tr('Settle card batch')+'</button></div>' +
    '<div class="actions" style="margin-top:8px;"><button class="btn btn-ghost btn-block" id="pdEdit">'+tr('Edit')+'</button>' +
      (d.linkedAt ? '<button class="btn btn-ghost btn-block" id="pdUnlink">'+tr('Unlink device')+'</button>' : '<button class="btn btn-ghost btn-block" id="pdNewCode">'+tr('New code')+'</button>') + '</div>' +
    '<div class="actions" style="margin-top:8px;"><button class="btn btn-ghost btn-block" id="pdBlock">'+(d.status==='blocked'?tr('Unblock'):tr('Block terminal'))+'</button>' +
      '<button class="btn btn-danger btn-block" id="pdDel">'+tr('Remove')+'</button></div>' +
    '<div class="actions" style="margin-top:8px;"><button class="btn btn-ghost btn-block" id="pdBack">'+tr('Back')+'</button></div>';
  var ov = openSheet(html);
  ov.querySelector('#pdBack').addEventListener('click', openPosDevicesSheet);
  ov.querySelector('#pdEdit').addEventListener('click', function(){ openPosDeviceForm(d); });
  ov.querySelector('#pdSettle').addEventListener('click', function(){ openPosSettleSheet(d.id); });
  var un = ov.querySelector('#pdUnlink');
  if(un) un.addEventListener('click', function(){ confirmSheet(tr('Unlink device?'), tr('The phone or tablet linked to this terminal will stop being able to use it until it is linked again with a new code.'), tr('Unlink'), function(){
    refs.posDevices.doc(d.id).update({ linkedAt:'', linkedInfo:'', linkCode:posNewCode() }); logAudit('update','posDevice',d.id,'Terminal '+d.name+' unlinked'); setTimeout(function(){ openPosDeviceDetail(d.id); }, 80);
  }, true); });
  var nc = ov.querySelector('#pdNewCode');
  if(nc) nc.addEventListener('click', function(){ refs.posDevices.doc(d.id).update({ linkCode:posNewCode() }); setTimeout(function(){ openPosDeviceDetail(d.id); }, 80); });
  ov.querySelector('#pdBlock').addEventListener('click', function(){
    var b = d.status === 'blocked' ? 'active' : 'blocked';
    refs.posDevices.doc(d.id).update({ status:b }); logAudit('update','posDevice',d.id,'Terminal '+d.name+(b==='blocked'?' blocked':' unblocked'));
    setTimeout(function(){ openPosDeviceDetail(d.id); }, 80);
  });
  ov.querySelector('#pdDel').addEventListener('click', function(){
    if(!secAllow('manager', 'removing a terminal')) return;
    confirmSheet(tr('Remove terminal?'), tr('Past card sales keep their record. This only removes the terminal, its limits and its link to any phone or tablet. A copy is kept in the archive.'), tr('Remove'), function(){
      secAskEveryTime(tr('Enter your password to remove this terminal'), function(){
        secWithReason('Terminal removed', function(){ refs.posDevices.doc(d.id).delete(); });
        logAudit('delete','posDevice',d.id,'Terminal '+d.name+' removed'); toast(tr('Terminal removed')); setTimeout(openPosDevicesSheet, 80);
      });
    }, true, true); });
}
function openPosSettleSheet(id){
  var d = State.posDevices.find(function(x){ return x.id === id; }); if(!d) return;
  var st = posStats(d);
  var past = State.posBatches.filter(function(b){ return b.deviceId === id; }).slice(0,4);
  var html = '<div class="sheet-head"><h2>'+tr('Settle card batch')+'</h2></div>' +
    '<div class="banner">'+ICONS.info+'<span>'+tr('Run the end of day settlement on the card machine, then type in the totals it printed. Pesa compares them with the card sales recorded here.')+'</span></div>' +
    '<div class="sumline"><span>'+tr('Recorded in Pesa')+'</span><span class="num">'+fmtMoney(st.batchTotal)+' · '+st.batchCount+' '+tr('sales')+'</span></div>' +
    '<div class="field"><label>'+tr('Terminal batch total (N$)')+'</label><input id="sbTotal" type="number" inputmode="decimal" step="0.01" placeholder="0.00"></div>' +
    '<div class="field"><label>'+tr('Terminal transaction count')+'</label><input id="sbCount" type="number" inputmode="numeric" placeholder="0"></div>' +
    '<div id="sbRes"></div>' +
    (past.length ? '<div class="section-title">'+tr('Previous settlements')+'</div>' + past.map(function(b){
      return '<div class="sumline"><span>'+fmtDateTime(b.settledAt)+'</span><span class="num '+(Math.abs(b.variance)<0.01?'variance-ok':'variance-bad')+'">'+(Math.abs(b.variance)<0.01?tr('Balanced'):fmtMoney(b.variance))+'</span></div>';
    }).join('') : '') +
    '<div class="actions"><button class="btn btn-ghost btn-block" id="sbBack">'+tr('Back')+'</button><button class="btn btn-primary btn-block" id="sbSave">'+tr('Save settlement')+'</button></div>';
  var ov = openSheet(html);
  function calc(){
    var t = parseFloat(ov.querySelector('#sbTotal').value), c = parseInt(ov.querySelector('#sbCount').value, 10);
    var res = ov.querySelector('#sbRes');
    if(isNaN(t)){ res.innerHTML = ''; return null; }
    var v = Math.round((t - st.batchTotal)*100)/100;
    res.innerHTML = '<div class="banner" '+(Math.abs(v)<0.01?'':'style="background:var(--danger-bg);color:var(--danger);"')+'>'+(Math.abs(v)<0.01?ICONS.check:ICONS.warn)+'<span>' +
      (Math.abs(v)<0.01 ? tr('Balanced') : (v<0 ? tr('Terminal is lower than Pesa by')+' ' : tr('Terminal is higher than Pesa by')+' ')+(Math.abs(v)<0.01?'':fmtMoney(Math.abs(v)))) +
      (!isNaN(c) && c !== st.batchCount ? '<br>'+tr('Count differs')+': '+c+' vs '+st.batchCount : '') + '</span></div>';
    return { v:v, t:t, c:isNaN(c)?null:c };
  }
  ov.querySelector('#sbTotal').addEventListener('input', calc); ov.querySelector('#sbCount').addEventListener('input', calc);
  ov.querySelector('#sbBack').addEventListener('click', function(){ openPosDeviceDetail(id); });
  ov.querySelector('#sbSave').addEventListener('click', function(){
    var r = calc(); if(!r){ toast(tr('Enter the terminal batch total')); return; }
    refs.posBatches.add({ deviceId:id, deviceName:d.name, terminalId:d.terminalId||'', settledAt:new Date().toISOString(), by:State.session?State.session.name:'',
      systemTotal:st.batchTotal, systemCount:st.batchCount, terminalTotal:r.t, terminalCount:r.c, variance:r.v, fromAt:st.batchSince||null });
    logAudit('other','posDevice',id,'Card batch settled on '+d.name+': '+fmtMoney(r.t)+(Math.abs(r.v)<0.01?' balanced':' variance '+fmtMoney(r.v)));
    toast(tr('Settlement saved')); setTimeout(function(){ openPosDeviceDetail(id); }, 80);
  });
}

/* ---- POS terminal screen ---- */
function posLockKey(){ return 'pesa_pos_lock_' + WS.id; }
function posLockData(){ try{ return JSON.parse(localStorage.getItem(posLockKey()) || '{}'); }catch(e){ return {}; } }
function posLockSave(o){ try{ localStorage.setItem(posLockKey(), JSON.stringify(o)); }catch(e){} }
function posLockLeft(uid){ var o = posLockData()[uid]; return o && o.until && o.until > Date.now() ? Math.ceil((o.until - Date.now())/1000) : 0; }
function posRootEl(){
  var r = document.getElementById('posRoot');
  if(!r){ r = document.createElement('div'); r.id = 'posRoot'; var host = document.getElementById('app'), mr = document.getElementById('modalRoot'); if(host && mr && mr.parentNode === host) host.insertBefore(r, mr); else document.body.appendChild(r);
    ['pointerdown','keydown'].forEach(function(ev){ r.addEventListener(ev, posTouch, true); }); }
  return r;
}
function posTouch(){
  clearTimeout(POS.idle);
  if(!POS.open || !POS.user) return;
  var d = posDevice(), mins = d && d.autoLockMin != null ? d.autoLockMin : 5;
  if(mins > 0) POS.idle = setTimeout(function(){ if(POS.open && POS.user){ closeModal(); posLock(); toast(tr('Terminal locked')); } }, mins*60000);
}
function posOpen(){
  POS.open = true; POS.user = null; POS.orig = State.session ? { userId:State.session.userId, name:State.session.name, role:State.session.role } : null;
  POS.tab = 'sell'; POS.search = ''; POS.pick = null; POS.typed = '';
  var b = posBoundInfo();
  if(b && State.ready.posDevices && !State.posDevices.some(function(x){ return x.id === b.deviceId; })) posBind(null);
  posRootEl().style.display = 'block';
  posRender();
}
function posLock(){ POS.user = null; POS.pick = null; POS.typed = ''; clearTimeout(POS.idle); posRender(); }
function posClose(){
  POS.open = false; clearTimeout(POS.idle);
  if(POS.orig && State.session && State.session.userId !== POS.orig.userId){
    State.session = POS.orig; saveSessionLocal(POS.orig.userId);
    var mine = State.tillSessions.find(function(t){ return t.cashierId === POS.orig.userId && t.status === 'open'; });
    State.till.current = mine || null;
  }
  var r = posRootEl(); r.style.display = 'none'; r.innerHTML = '';
  closeModal(); render();
}
function posHead(sub){
  var d = posDevice(), co = State.company || {};
  return '<div class="pos-head"><div class="pos-logo" aria-hidden="true"></div><div style="min-width:0;flex:1;"><div class="pos-title">'+esc(co.tradingName||co.companyName||'Pesa')+' · '+tr('Point of sale')+'</div>' +
    '<div class="pos-sub">'+esc(d ? d.name+(d.terminalId?' · '+d.terminalId:'') : tr('This device is not linked to a card terminal'))+(sub?' · '+esc(sub):'')+'</div></div>' +
    '<div class="pos-head-btns">' + (POS.user ? '<button class="btn btn-ghost" id="posLockBtn">'+tr('Lock')+'</button>' : '') + '<button class="btn btn-ghost" id="posExitBtn">'+tr('Close')+'</button></div></div>';
}
function posRender(){
  var r = posRootEl();
  if(!POS.open) return;
  var d = posDevice();
  var wm = '<div class="app-watermark pos-wm" aria-hidden="true"></div>';
  applyBrandLogo();
  if(!POS.user){ r.innerHTML = wm + posLockHtml(d); posWireLock(r, d); return; }
  r.innerHTML = wm + posMainHtml(d);
  posWireMain(r, d);
  posTouch();
}
function posLockHtml(d){
  var h = '<div class="pos-wrap">' + posHead('');
  if(d && d.status === 'blocked'){
    return h + '<div class="pos-body"><div class="banner" style="background:var(--danger-bg);color:var(--danger);">'+ICONS.warn+'<span>'+tr('This terminal has been blocked by the owner. Sales cannot be taken here.')+'</span></div></div></div>';
  }
  var users = State.users.filter(function(u){ return u.active !== false && !u.pending && u.role !== 'stockclerk' && u.posAccess !== false; }).sort(function(a,b){ return (a.role==='cashier'?0:1) - (b.role==='cashier'?0:1) || (a.name||'').localeCompare(b.name||''); });
  if(!POS.pick){
    h += '<div class="pos-body"><div class="pos-lock-title">'+tr('Who is selling?')+'</div><div class="pos-tiles">' + users.map(function(u){
      var left = posLockLeft(u.id);
      return '<button class="pos-tile" data-pu="'+u.id+'"><div class="avatar">'+esc(initials(u.name))+'</div><div class="pos-tn">'+esc(u.name)+'</div><div class="pos-tr">'+tr(u.role.charAt(0).toUpperCase()+u.role.slice(1))+(left?' · '+tr('locked'):'')+'</div></button>';
    }).join('') + '</div></div></div>';
    return h;
  }
  var u = users.find(function(x){ return x.id === POS.pick; }) || {};
  var left = posLockLeft(u.id), isCash = u.role === 'cashier';
  h += '<div class="pos-body" style="max-width:360px;margin:0 auto;"><div class="pos-lock-title">'+esc(u.name)+'</div>';
  if(left){
    h += '<div class="banner" style="background:var(--danger-bg);color:var(--danger);">'+ICONS.warn+'<span>'+tr('Too many wrong tries. Try again in')+' <b id="posLeft">'+left+'</b> '+tr('seconds')+'.</span></div>';
  } else if(isCash){
    h += '<div class="pos-dots" id="posDots"><i></i><i></i><i></i><i></i></div><div id="posLockErr" class="pos-err"></div>' +
      '<div class="pos-pad">' + ['1','2','3','4','5','6','7','8','9','C','0','OK'].map(function(k){ return '<button class="pos-key" data-k="'+k+'">'+(k==='C'?'⌫':k)+'</button>'; }).join('') + '</div>';
  } else {
    h += '<div class="field"><label>'+tr('Password')+'</label><input id="posPw" type="password" autocomplete="off"></div><div id="posLockErr" class="pos-err"></div>' +
      '<div class="actions"><button class="btn btn-primary btn-block" id="posPwOk">'+tr('Unlock')+'</button></div>';
  }
  h += '<div class="actions" style="margin-top:12px;"><button class="btn btn-ghost btn-block" id="posBackTiles">'+tr('Back')+'</button></div></div></div>';
  return h;
}
function posWireLock(r, d){
  var ex = r.querySelector('#posExitBtn'); if(ex) ex.addEventListener('click', posClose);
  r.querySelectorAll('[data-pu]').forEach(function(b){ b.addEventListener('click', function(){ POS.pick = b.getAttribute('data-pu'); POS.typed = ''; posRender(); }); });
  var bk = r.querySelector('#posBackTiles'); if(bk) bk.addEventListener('click', function(){ POS.pick = null; POS.typed = ''; posRender(); });
  var lf = r.querySelector('#posLeft');
  if(lf){ var iv = setInterval(function(){ var n = posLockLeft(POS.pick); if(!document.getElementById('posLeft') || !POS.open){ clearInterval(iv); return; } if(n<=0){ clearInterval(iv); posRender(); } else lf.textContent = n; }, 1000); }
  var u = State.users.find(function(x){ return x.id === POS.pick; });
  function dots(){
    var el = r.querySelector('#posDots');
    if(el) el.innerHTML = Array.apply(null, Array(Math.max(4, POS.typed.length))).map(function(_,i){ return '<i class="'+(i<POS.typed.length?'on':'')+'"></i>'; }).join('');
  }
  async function attempt(code){
    if(!u || !code) return;
    if(posLockLeft(u.id)){ posRender(); return; }
    var okPin = await pwCheck(code, u.passHash), err = r.querySelector('#posLockErr');
    if(okPin){
      pwUpgrade(u, code);
      var all = posLockData(); delete all[u.id]; posLockSave(all);
      posSignIn(u);
    } else {
      var all2 = posLockData(), o = all2[u.id] || { fails:0, rounds:0 };
      o.fails++;
      if(o.fails >= 3){ var secs = [60,300,900][Math.min(o.rounds,2)]; o.until = Date.now() + secs*1000; o.rounds++; o.fails = 0; }
      all2[u.id] = o; posLockSave(all2);
      POS.typed = '';
      if(o.until && o.until > Date.now()){ posRender(); return; }
      if(err) err.textContent = (u.role==='cashier'?tr('Incorrect PIN.'):tr('Incorrect password.'))+' '+(3-o.fails)+' '+tr('tries left.');
      dots();
      var pw = r.querySelector('#posPw'); if(pw){ pw.value = ''; pw.focus(); }
    }
  }
  r.querySelectorAll('[data-k]').forEach(function(b){
    b.addEventListener('click', function(){
      var k = b.getAttribute('data-k');
      if(k === 'C'){ POS.typed = POS.typed.slice(0,-1); }
      else if(k === 'OK'){ attempt(POS.typed); return; }
      else if(POS.typed.length < 8){ POS.typed += k; }
      dots();
      // cashier PINs are 4 digits: submit as soon as the fourth is typed
      if(k !== 'C' && k !== 'OK' && POS.typed.length === 4 && u && u.role === 'cashier') attempt(POS.typed);
    });
  });
  var pw = r.querySelector('#posPw');
  if(pw){ pw.focus(); pw.addEventListener('keydown', function(e){ if(e.key === 'Enter') attempt(pw.value); }); r.querySelector('#posPwOk').addEventListener('click', function(){ attempt(pw.value); }); }
}
function posSignIn(u){
  POS.user = { id:u.id, name:u.name, role:u.role }; POS.pick = null; POS.typed = '';
  State.session = { userId:u.id, name:u.name, role:u.role };
  var mine = State.tillSessions.find(function(t){ return t.cashierId === u.id && t.status === 'open'; });
  State.till.current = mine || null;
  var d = posDevice();
  logAudit('other','staff',u.id,'POS sign in'+(d?' on '+d.name:''));
  if(d) refs.posDevices.doc(d.id).update({ lastSeen:new Date().toISOString() });
  POS.tab = 'sell';
  touchUserActive(true);
  posRender();
}
function posMainHtml(d){
  var till = State.till.current;
  var chips = '<div class="pos-chips"><span class="pos-chip '+(till?'ok':'warn')+'">'+(till?tr('Till open'):tr('Till closed'))+'</span>' +
    '<span class="pos-chip '+(navigator.onLine?'ok':'warn')+'">'+(navigator.onLine?tr('Online'):tr('Offline'))+'</span>' +
    (d ? '<span class="pos-chip ok">'+tr('Card terminal linked')+'</span>' : '<span class="pos-chip warn">'+tr('No card terminal')+'</span>') + '</div>';
  var tabs = ['sell','keypad','records','summary'].map(function(t){ return '<button class="segbtn'+(POS.tab===t?' active':'')+'" data-ptab="'+t+'" style="padding:10px 4px;">'+tr(t==='sell'?'Sell':(t==='keypad'?'Amount':(t==='records'?'Records':'Summary')))+'</button>'; }).join('');
  return '<div class="pos-wrap">' + posHead(POS.user.name) + '<div class="pos-body">' + chips + '<div class="segbtns" style="margin-bottom:10px;">'+tabs+'</div><div id="posTabBody">'+posTabHtml(d)+'</div></div><div id="posCart" class="pos-cart"></div></div>';
}
function posGridHtml(){
  var q = POS.search.trim().toLowerCase();
  var list = searchProducts(State.products, POS.search);
  if(!State.products.length) return '<div class="empty"><div class="t">'+tr('No products yet')+'</div><div class="s">'+tr('Add stock first, then come back to sell.')+'</div></div>';
  if(!list.length) return '<div class="empty"><div class="t">'+tr('No matches')+'</div></div>';
  var cap = Math.max(LIST_PAGE, POS.limit || 0), shown = list.slice(0, cap);
  return tickBarHtml() + '<div class="grid pos-grid">' + shown.map(function(p){
    var out = (p.stockQty!=null) && p.stockQty <= 0;
    return '<button class="pcard" data-padd="'+p.id+'" '+(out?'disabled style="opacity:.5"':'')+'>'+(out ? '' : tickHtml(p.id))+'<div class="pname">'+esc(p.name)+'</div><div class="pprice num">'+fmtMoney(p.sellPrice)+'</div></button>';
  }).join('') + '</div>' +
  (list.length > shown.length ? '<button class="btn btn-ghost btn-block" type="button" data-posmore style="margin-top:10px;">'+tr('Show more')+' ('+(list.length - shown.length)+' '+tr('more, search to narrow down')+')</button>' : '');
}
function posTabHtml(d){
  if(POS.tab === 'sell'){
    var h = '';
    if(!d) h += '<div class="banner">'+ICONS.info+'<span>'+tr('This device is not linked to a card terminal yet. Cash, wallet and credit sales work normally.')+' <a href="#" id="posLinkLink">'+tr('Link this device')+'</a></span></div>';
    return h + '<div class="searchbar">'+ICONS.search+'<input id="posSearch" placeholder="'+tr('Search products or scan a barcode')+'" value="'+esc(POS.search)+'"></div><div id="posGrid" style="margin-top:10px;">'+posGridHtml()+'</div>';
  }
  if(POS.tab === 'keypad'){
    var keys = ['1','2','3','4','5','6','7','8','9','.','0','C'];
    return '<div class="pos-amount num" id="posAmt">'+fmtMoney(parseFloat(POS.key)||0)+'</div><div class="pos-pad" style="max-width:340px;margin:0 auto;">' +
      keys.map(function(k){ return '<button class="pos-key" data-ak="'+k+'">'+(k==='C'?'⌫':k)+'</button>'; }).join('') + '</div>' +
      '<div class="actions" style="max-width:340px;margin:12px auto 0;"><button class="btn btn-ghost btn-block" id="posAmtClear">'+tr('Clear')+'</button><button class="btn btn-accent btn-block" id="posAmtAdd">'+tr('Add to sale')+'</button></div>';
  }
  if(POS.tab === 'records') return posRecordsHtml();
  // summary
  var till = State.till.current, tk = todayKey();
  var mine = State.sales.filter(function(s){ return todayKey(new Date(s.createdAt)) === tk && s.cashierName === POS.user.name; });
  var by = { cash:0, card:0, wallet:0, credit:0 };
  mine.forEach(function(s){ salePayParts(s).forEach(function(q){ by[q.method] = (by[q.method]||0) + q.amount; }); });
  function line(a,b){ return '<div class="sumline"><span>'+a+'</span><span class="num">'+b+'</span></div>'; }
  var h2 = '<div class="section-title" style="margin-top:0;">'+tr('Your sales today')+'</div>' + line(tr('Sales'), mine.length) + line(tr('Cash'), fmtMoney(by.cash)) + line(tr('Card'), fmtMoney(by.card)) + line(tr('Mobile wallet'), fmtMoney(by.wallet)) + line(tr('Credit'), fmtMoney(by.credit)) +
    '<div class="sumline total"><span>'+tr('Total')+'</span><span class="num">'+fmtMoney(posSum(mine))+'</span></div>' +
    '<div class="actions" style="margin-top:10px;">' + (till ? '<button class="btn btn-ghost btn-block" id="posCloseTill">'+tr('Close till')+'</button>' : '<button class="btn btn-primary btn-block" id="posOpenTill">'+tr('Open till')+'</button>') + '</div>';
  if(d){
    var st = posStats(d);
    function bar(label, val, max, fmt){ if(!max) return ''; var pct = Math.min(100, Math.round(val/max*100)); return '<div style="margin:8px 0;"><div style="display:flex;justify-content:space-between;font-size:12.5px;"><span>'+label+'</span><span class="num">'+fmt(val)+' / '+fmt(max)+'</span></div><div class="pos-bar"><i style="width:'+pct+'%;'+(pct>=90?'background:var(--danger);':'')+'"></i></div></div>'; }
    h2 += '<div class="section-title">'+esc(d.name)+'</div>' +
      bar(tr('Daily card total'), st.todayTotal, posLim(d,'daily'), fmtMoney) + bar(tr('Swipes today'), st.todayCount, posLim(d,'dailyCount'), String) + bar(tr('Swipes this hour'), st.hourCount, posLim(d,'hourlyCount'), String) +
      '<div style="font-size:12px;color:var(--text-muted);margin:4px 0 8px;">'+esc(posLimitSummaryHtml(d))+'</div>' +
      line(tr('Since last settlement'), fmtMoney(st.batchTotal)+' · '+st.batchCount) +
      (st.recent.length ? '<div class="section-title">'+tr('Recent card sales')+'</div>' + st.recent.slice(0,5).map(function(s){
        return line(new Date(s.createdAt).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})+' · '+esc(s.cardBrand||'')+(s.cardLast4?' ····'+esc(s.cardLast4):'')+' · '+esc(s.entryMode||''), fmtMoney(s.total)); }).join('') : '') +
      '<div class="actions" style="margin-top:10px;"><button class="btn btn-accent btn-block" id="posSettle">'+tr('Settle card batch')+'</button></div>';
  }
  if(isManagerOrOwner()){
    h2 += '<div class="actions" style="margin-top:10px;"><button class="btn btn-ghost btn-block" id="posStaff">'+tr('Employees on this terminal')+'</button></div>' +
      '<div class="actions" style="margin-top:8px;"><button class="btn btn-ghost btn-block" id="posMgr">'+tr('Card terminals and limits')+'</button></div>' +
      (d ? '<div class="actions" style="margin-top:8px;"><button class="btn btn-ghost btn-block" id="posUnbind">'+tr('Unlink this device')+'</button></div>' : '<div class="actions" style="margin-top:8px;"><button class="btn btn-ghost btn-block" id="posLinkBtn">'+tr('Link this device')+'</button></div>');
  } else if(!d){
    h2 += '<div class="actions" style="margin-top:10px;"><button class="btn btn-ghost btn-block" id="posLinkBtn">'+tr('Link this device')+'</button></div>';
  }
  return h2;
}
function posRenderCart(){
  var c = document.getElementById('posCart'); if(!c || !POS.open || !POS.user) return;
  if(!State.cart.length){ c.innerHTML = '<div class="pos-cart-empty">'+tr('Cart is empty')+'</div>'; return; }
  c.innerHTML = '<div class="pos-cart-list">' + State.cart.map(function(i){
    return '<div class="cartitem"><div style="flex:1;min-width:0;"><div class="ci-name">'+esc(i.name)+'</div><div class="ci-price num">'+fmtMoney(i.unitPrice)+'</div></div>' +
      '<div class="stepper"><button data-pdec="'+i.productId+'">−</button><div class="qv">'+i.qty+'</div><button data-pinc="'+i.productId+'">+</button></div>' +
      '<div class="ci-line num">'+fmtMoney(i.unitPrice*i.qty)+'</div></div>'; }).join('') + '</div>' +
    '<div class="pos-cart-bar"><button class="btn btn-ghost" id="posClr">'+tr('Clear')+'</button><button class="btn btn-accent" id="posCharge" style="flex:1;">'+tr('Charge')+' '+fmtMoney(cartTotal())+'</button></div>';
  c.querySelectorAll('[data-pinc]').forEach(function(b){ b.addEventListener('click', function(){ var id=b.getAttribute('data-pinc'); var it=State.cart.find(function(x){return x.productId===id;}); if(it) setCartQty(id, it.qty+1); }); });
  c.querySelectorAll('[data-pdec]').forEach(function(b){ b.addEventListener('click', function(){ var id=b.getAttribute('data-pdec'); var it=State.cart.find(function(x){return x.productId===id;}); if(it) setCartQty(id, it.qty-1); }); });
  c.querySelector('#posClr').addEventListener('click', function(){ State.cart = []; renderCartBar(); });
  c.querySelector('#posCharge').addEventListener('click', openChargeSheet);
}
function posWireMain(r, d){
  r.querySelector('#posExitBtn').addEventListener('click', posClose);
  r.querySelector('#posLockBtn').addEventListener('click', function(){ closeModal(); posLock(); });
  r.querySelectorAll('[data-ptab]').forEach(function(b){ b.addEventListener('click', function(){ POS.tab = b.getAttribute('data-ptab'); posRender(); }); });
  posRenderCart();
  var body = r.querySelector('#posTabBody');
  var ll = body.querySelector('#posLinkLink'); if(ll) ll.addEventListener('click', function(e){ e.preventDefault(); openPosLinkSheet(); });
  var sr = body.querySelector('#posSearch');
  if(sr){
    sr.addEventListener('input', debounce(function(){ POS.search = sr.value; POS.limit = 0; var g = body.querySelector('#posGrid'); if(!g) return; g.innerHTML = posGridHtml(); posWireGrid(g); }, 150));
    sr.addEventListener('keydown', function(e){ if(e.key === 'Enter'){ var m = findProductByBarcode(sr.value); if(m){ addToCart(m.id); POS.search=''; POS.limit=0; sr.value=''; var g = body.querySelector('#posGrid'); g.innerHTML = posGridHtml(); posWireGrid(g); } } });
    posWireGrid(body.querySelector('#posGrid'));
  }
  body.querySelectorAll('[data-ak]').forEach(function(b){ b.addEventListener('click', function(){
    var k = b.getAttribute('data-ak');
    if(k === 'C') POS.key = POS.key.slice(0,-1);
    else if(k === '.'){ if(POS.key.indexOf('.') === -1) POS.key += POS.key ? '.' : '0.'; }
    else if(!/\.\d\d$/.test(POS.key) && POS.key.length < 9) POS.key += k;
    body.querySelector('#posAmt').textContent = fmtMoney(parseFloat(POS.key)||0);
  }); });
  var ac = body.querySelector('#posAmtClear'); if(ac) ac.addEventListener('click', function(){ POS.key = ''; body.querySelector('#posAmt').textContent = fmtMoney(0); });
  var aa = body.querySelector('#posAmtAdd');
  if(aa) aa.addEventListener('click', function(){
    var v = parseFloat(POS.key); if(!(v > 0)){ toast(tr('Enter an amount')); return; }
    State.cart.push({ productId:'quick-'+Date.now().toString(36), name:tr('Quick sale'), unitPrice:Math.round(v*100)/100, cost:0, qty:1, unit:'', maxQty:Infinity });
    POS.key = ''; body.querySelector('#posAmt').textContent = fmtMoney(0); renderCartBar(); toast(tr('Added to sale'));
  });
  function on(id, fn){ var el = body.querySelector(id); if(el) el.addEventListener('click', fn); }
  on('#posOpenTill', openStartTillSheet);
  on('#posCloseTill', function(){ if(State.till.current) openCloseTillSheet(State.till.current); });
  on('#posSettle', function(){ openPosSettleSheet(d.id); });
  on('#posMgr', openPosDevicesSheet);
  on('#posStaff', openTeamSheet);
  body.querySelectorAll('[data-rcat]').forEach(function(b){ b.addEventListener('click', function(){ POS.recCat = b.getAttribute('data-rcat'); posRender(); }); });
  body.querySelectorAll('[data-rrange]').forEach(function(b){ b.addEventListener('click', function(){ POS.recRange = b.getAttribute('data-rrange'); posRender(); }); });
  body.querySelectorAll('[data-rsale]').forEach(function(b){ b.addEventListener('click', function(){ openPosSaleDetail(b.getAttribute('data-rsale')); }); });
  on('#posLinkBtn', openPosLinkSheet);
  on('#posUnbind', function(){ confirmSheet(tr('Unlink this device?'), tr('This phone or tablet will stop acting as the card terminal. You can link it again with a new code.'), tr('Unlink'), function(){
    var dd = posDevice(); if(dd) refs.posDevices.doc(dd.id).update({ linkedAt:'', linkedInfo:'', linkCode:posNewCode() });
    posBind(null); closeModal(); posRender();
  }, true); });
}
function posWireGrid(g){ if(!g) return; var mb = g.querySelector('[data-posmore]'); if(mb) mb.addEventListener('click', function(){ POS.limit = Math.max(LIST_PAGE, POS.limit || 0) + LIST_PAGE*2; g.innerHTML = posGridHtml(); posWireGrid(g); }); wireTicks(g); g.querySelectorAll('[data-padd]').forEach(function(b){ b.addEventListener('click', function(){ addToCart(b.getAttribute('data-padd')); }); }); }

/* ---- POS records: only sales made on the POS, one category per payment method ---- */
var POS_CATS = [['cash','Cash'],['card','Card'],['wallet','Mobile wallet'],['credit','Credit'],['voucher','Voucher']];
function posRecordSales(){
  var now = new Date(), tk = todayKey(), cut = now.getTime() - 7*86400000;
  return State.sales.filter(function(s){
    if(!s.viaPos) return false;
    if(!isManagerOrOwner() && s.cashierName !== (POS.user && POS.user.name)) return false;
    var t = new Date(s.createdAt).getTime();
    if(POS.recRange === 'today') return todayKey(new Date(s.createdAt)) === tk;
    if(POS.recRange === 'week') return t >= cut;
    return true;
  });
}
function posSaleWho(s){
  if(s.paymentMethod === 'credit') return s.customerName || tr('Customer');
  if(s.paymentMethod === 'voucher') return (s.voucher && s.voucher.platform ? s.voucher.platform + ' ' : '') + tr('voucher');
  if(s.payerName) return s.payerName;
  if(s.paymentMethod === 'card') return tr('Card customer');
  if(s.paymentMethod === 'wallet') return tr('Wallet customer');
  return tr('Cash customer');
}
function posSaleDetailLine(s){
  var m = s.paymentMethod;
  if(m === 'card') return [s.cardBrand, s.cashBack ? tr('Cash back')+' '+fmtMoney(s.cashBack) : '', s.cardLast4 ? '····'+s.cardLast4 : '', s.entryMode ? tr(s.entryMode) : '', s.authCode ? tr('Approval')+' '+s.authCode : '', s.posDeviceName].filter(Boolean).join(' · ');
  if(m === 'wallet') return [s.walletProvider, s.payRef].filter(Boolean).join(' · ');
  if(m === 'credit'){ var c = State.customers.find(function(x){ return x.id === s.customerId; }); return tr('On credit')+(c ? ' · '+tr('owes now')+' '+fmtMoney(c.balance||0) : ''); }
  return s.cashReceived != null ? tr('Received')+' '+fmtMoney(s.cashReceived)+' · '+tr('Change')+' '+fmtMoney(s.changeGiven||0) : '';
}
function posSaleRowHtml(s){
  return '<div class="row" data-rsale="'+s.id+'"><div class="main"><div class="title">'+esc(posSaleWho(s))+'</div>' +
    '<div class="sub">'+esc(fmtDateTime(s.createdAt))+' · '+esc(s.cashierName||'')+'</div>' +
    (posSaleDetailLine(s) ? '<div class="sub">'+esc(posSaleDetailLine(s))+'</div>' : '') + '</div>' +
    '<div class="trail"><div class="amt num">'+fmtMoney(s.total)+'</div></div></div>';
}
function posRecordsHtml(){
  var all = posRecordSales(), cat = POS.recCat;
  var by = {}; POS_CATS.forEach(function(c){ by[c[0]] = all.filter(function(s){ return (s.paymentMethod||'cash') === c[0]; }); });
  var h = '<div class="segbtns" style="margin-bottom:8px;">' + [['today','Today'],['week','Last 7 days'],['all','All']].map(function(r){ return '<button class="segbtn'+(POS.recRange===r[0]?' active':'')+'" data-rrange="'+r[0]+'" style="padding:8px 4px;font-size:12.5px;">'+tr(r[1])+'</button>'; }).join('') + '</div>';
  h += '<div class="segbtns" style="margin-bottom:10px;flex-wrap:wrap;">' + [['all','All']].concat(POS_CATS).map(function(c){
    var n = c[0]==='all' ? all.length : by[c[0]].length;
    return '<button class="segbtn'+(cat===c[0]?' active':'')+'" data-rcat="'+c[0]+'" style="padding:8px 4px;font-size:12px;">'+tr(c[1])+' ('+n+')</button>'; }).join('') + '</div>';
  var cats = cat === 'all' ? POS_CATS : POS_CATS.filter(function(c){ return c[0] === cat; });
  if(!all.length) return h + '<div class="empty"><div class="t">'+tr('No point of sale records yet')+'</div><div class="s">'+tr('Sales made on this terminal appear here, sorted by how they were paid.')+'</div></div>';
  cats.forEach(function(c){
    var list = by[c[0]];
    h += '<div class="section-title" style="display:flex;justify-content:space-between;"><span>'+tr(c[1])+' · '+list.length+'</span><span class="num">'+fmtMoney(posSum(list))+'</span></div>';
    h += list.length ? '<div class="rowlist">'+list.slice(0,60).map(posSaleRowHtml).join('')+'</div>' : '<div style="font-size:13px;color:var(--text-muted);padding:4px 2px 8px;">'+tr('None')+'</div>';
  });
  if(cat === 'all') h += '<div class="sumline total" style="margin-top:12px;"><span>'+tr('Total')+'</span><span class="num">'+fmtMoney(posSum(all))+'</span></div>';
  return h;
}
function openPosSaleDetail(id){
  var s = State.sales.find(function(x){ return x.id === id; }); if(!s) return;
  function line(a,b){ return b ? '<div class="sumline"><span>'+a+'</span><span style="text-align:right;">'+esc(b)+'</span></div>' : ''; }
  var m = s.paymentMethod || 'cash';
  var html = '<div class="sheet-head"><h2>'+tr(m==='wallet'?'Mobile wallet':m.charAt(0).toUpperCase()+m.slice(1))+' · '+fmtMoney(s.total)+'</h2></div>' +
    line(tr(m==='credit'?'Customer':'Paid by'), posSaleWho(s)) + line(tr('Date and time'), fmtDateTime(s.createdAt)) + line(tr('Cashier'), s.cashierName||'') +
    (m==='card' ? line(tr('Terminal'), (s.posDeviceName||'')+(s.terminalId?' · '+s.terminalId:'')) + line(tr('Card type'), s.cardBrand) + line(tr('Card number'), s.cardLast4 ? '···· ···· ···· '+s.cardLast4 : '') + line(tr('How the card was used'), s.entryMode ? tr(s.entryMode) : '') + line(tr('Approval code'), s.authCode) + (s.cashBack ? line(tr('Cash back'), fmtMoney(s.cashBack)) + line(tr('Charged to card'), fmtMoney(s.total+s.cashBack)) : '') + (s.overrideBy ? line(tr('Limit override approved by'), s.overrideBy) : '') : '') +
    (s.voucher ? line(tr('Voucher'), s.voucher.platform+' · '+s.voucher.code+' · '+fmtMoney(Math.abs(s.voucher.amount))) : '') +
    (m==='wallet' ? line(tr('Wallet or transfer type'), s.walletProvider) + line(tr('Reference'), s.payRef) : '') +
    (m==='cash' && s.cashReceived != null ? line(tr('Cash received'), fmtMoney(s.cashReceived)) + line(tr('Change given'), fmtMoney(s.changeGiven||0)) : '') +
    (m==='credit' ? line(tr('Status'), posSaleDetailLine(s)) : '') +
    '<div class="section-title">'+tr('Items')+'</div>' + (s.items||[]).map(function(i){ return '<div class="sumline"><span>'+esc(i.name)+' × '+i.qty+'</span><span class="num">'+fmtMoney(i.lineTotal != null ? i.lineTotal : i.unitPrice*i.qty)+'</span></div>'; }).join('') +
    '<div class="actions"><button class="btn btn-ghost btn-block" id="rdClose">'+tr('Close')+'</button></div>';
  var ov = openSheet(html); ov.querySelector('#rdClose').addEventListener('click', closeModal);
}
function openPosLinkSheet(){
  var ov = openSheet('<div class="sheet-head"><h2>'+tr('Link this device')+'</h2></div>' +
    '<div class="banner">'+ICONS.info+'<span>'+tr('The owner or a manager adds a terminal under Card terminals and limits and gets a 6 digit link code. Enter it here.')+'</span></div>' +
    '<div class="field"><label>'+tr('Link code')+'</label><input id="plCode" inputmode="numeric" maxlength="7" placeholder="123 456" autocomplete="off"></div><div id="plErr" class="pos-err"></div>' +
    '<div class="actions"><button class="btn btn-ghost btn-block" id="plCancel">'+tr('Cancel')+'</button><button class="btn btn-primary btn-block" id="plOk">'+tr('Link')+'</button></div>', {center:true});
  ov.querySelector('#plCancel').addEventListener('click', closeModal);
  ov.querySelector('#plOk').addEventListener('click', function(){
    var code = ov.querySelector('#plCode').value.replace(/\D/g,'');
    var d = State.posDevices.find(function(x){ return x.linkCode && x.linkCode === code && !x.linkedAt; });
    var err = ov.querySelector('#plErr');
    if(!d){ err.textContent = tr('That code was not found. Check it, or make sure this device is connected to the same business.'); return; }
    if(d.status === 'blocked'){ err.textContent = tr('This terminal is blocked.'); return; }
    var info = (navigator.userAgentData && navigator.userAgentData.platform) || (navigator.platform || 'device');
    refs.posDevices.doc(d.id).update({ linkedAt:new Date().toISOString(), linkedInfo:String(info).slice(0,40), lastSeen:new Date().toISOString(), linkCode:'' });
    posBind(d.id); logAudit('update','posDevice',d.id,'Device linked to terminal '+d.name);
    closeModal(); toast(tr('Linked to')+' '+d.name); setTimeout(posRender, 120);
  });
}

/* Whole-shop stock position: items, units, value at cost and at selling price. Cached until the product list changes. */
var _stockTotalsCache = null;
function stockTotals(){
  if(_stockTotalsCache && _stockTotalsCache.src === State.products) return _stockTotalsCache;
  var t = { src:State.products, items:State.products.length, qty:0, cost:0, retail:0, out:0 };
  State.products.forEach(function(p){
    var q = Number(p.stockQty)||0;
    t.qty += q; t.cost += (Number(p.costPrice)||0)*q; t.retail += (Number(p.sellPrice)||0)*q;
    if(p.stockQty != null && q <= 0) t.out++;
  });
  t.cost = Math.round(t.cost*100)/100; t.retail = Math.round(t.retail*100)/100;
  _stockTotalsCache = t; return t;
}
/** Small snapshot saved onto invoices, receipts, sales and reports so the stock value at that moment is on record. */
function stockSnapshot(){ var t = stockTotals(); return { at:new Date().toISOString(), items:t.items, qty:t.qty, cost:t.cost, retail:t.retail }; }

/* ============================== TAB: STOCK ============================== */
function renderStock(){
  if(!State.ready.products) return '<div class="empty">Loading…</div>';
  var lowCount = State.products.filter(function(p){ return p.stockQty!=null && p.stockQty <= (p.lowStock!=null?p.lowStock:State.settings.lowStockDefault); }).length;
  var html = namePriceBannerHtml();
  if(lowCount > 0){
    html += '<div class="banner">'+ICONS.warn+'<span><strong>'+lowCount+'</strong> item'+(lowCount>1?'s':'')+' running low on stock.</span></div>';
  }
  if(State.products.length === 0){
    html += mockStripHtml();
    html += '<div class="empty">'+ICONS.box+'<div class="t">'+tr('No products yet')+'</div><div class="s">'+tr('Add items one at a time, or all at once.')+'</div>' +
      '<div style="margin-top:14px;display:flex;gap:8px;justify-content:center;flex-wrap:wrap;"><button class="btn btn-primary" id="emptyAddOneBtn">'+tr('Add product')+'</button><button class="btn btn-ghost" id="bulkAddBtnEmpty">'+tr('Add in bulk')+'</button></div></div>';
    return html;
  }
  html += mockStripHtml();
  html += renderSelectToolbar('stock');
  html += '<div style="display:flex;gap:8px;margin-bottom:12px;">' +
    '<button class="btn btn-ghost" id="bulkAddBtn" style="flex:1;">'+ICONS.stack+' '+tr('Add stock in bulk')+'</button>' +
    '<button class="btn btn-ghost" id="stockScanBtn" style="flex:1;">'+ICONS.search+' Scan barcode</button>' +
  '</div>' +
  (isManagerOrOwner() ? '<div style="margin-bottom:12px;"><button class="btn btn-ghost btn-block" id="stockVarBtn" type="button">Stock take &amp; variances</button></div>' : '');
  var selS = selState('stock');
  var sq = (State.stockSearch||'').trim().toLowerCase();
  var stockList = !sq ? State.products : searchProducts(State.products, State.stockSearch);
  var stockLimit = State.stockLimit || LIST_PAGE;
  var stTot = stockTotals();
  html += '<div class="searchbar" style="margin-bottom:10px;">'+ICONS.search+'<input id="stockSearchInput" placeholder="'+esc(tr('Search products…'))+'" value="'+esc(State.stockSearch||'')+'"></div>';
  html += '<div class="banner" style="display:block;"><strong>'+stTot.items.toLocaleString()+'</strong> products · <strong>'+stTot.qty.toLocaleString()+'</strong> units · stock at cost <strong>'+fmtMoney(stTot.cost)+'</strong> · at selling price <strong>'+fmtMoney(stTot.retail)+'</strong></div>';
  if(sq && stockList.length === 0) html += '<div class="empty"><div class="t">'+tr('No matches')+'</div></div>';
  var stockGroups = deptGroupsFor(stockList), stShown = 0;
  function stockRow(p){
    var low = p.stockQty!=null && p.stockQty <= (p.lowStock!=null?p.lowStock:State.settings.lowStockDefault);
    var out = p.stockQty!=null && p.stockQty <= 0;
    var checked = !!selS.ids[p.id];
    return '<div class="row'+(checked?' checked':'')+'" data-product="'+p.id+'" data-select-id="'+p.id+'">' +
      (selS.active ? rowCheckHtml('stock', p.id) : '') +
      '<div class="avatar">'+esc(initials(p.name))+'</div>' +
      '<div class="main">' +
        '<div class="title">'+esc(p.name)+'</div>' +
        '<div class="sub">'+esc(deptInfo(p).label)+' · cost '+fmtMoney(p.costPrice)+'</div>' +
      '</div>' +
      '<div class="trail">' +
        '<div class="amt num">'+fmtMoney(p.sellPrice)+'</div>' +
        '<div class="note">'+(out?'<span class="chip low">Out of stock</span>':(low?'<span class="chip low">'+p.stockQty+' '+(p.unit||'left')+'</span>':(p.stockQty+' '+(p.unit||'in stock'))))+'</div>' +
      '</div>' +
    '</div>';
  }
  html += '<div class="rowlist">';
  for(var sgi = 0; sgi < stockGroups.length && stShown < stockLimit; sgi++){
    var sg = stockGroups[sgi], sPart = sg.items.slice(0, stockLimit - stShown);
    html += '<div class="dept-h" data-dept="'+esc(sg.key)+'"><span>'+esc(tr(sg.label))+'</span><small>'+sg.items.length+'</small></div>' + sPart.map(stockRow).join('');
    stShown += sPart.length;
  }
  html += '</div>';
  if(stockList.length > stockLimit) html += '<div style="text-align:center;margin:14px 0 4px;"><button class="btn btn-ghost" id="stockMoreBtn" type="button">Show more ('+(stockList.length - stockLimit).toLocaleString()+' more, or search)</button></div>';
  html += renderSelectBar('stock');
  return html;
}

function openProductSheet(product, prefillBarcode){
  var isEdit = !!product;
  var html =
    '<div class="sheet-head"><h2>'+(isEdit?tr('Edit product'):tr('Add product'))+'</h2></div>' +
    '<div class="field"><label>'+tr('Name')+'</label><input id="pfName" placeholder="e.g. Omaere 500ml" value="'+esc(product?product.name:'')+'"></div>' +
    '<div class="field-row">' +
      '<div class="field"><label>'+tr('Category')+'</label><input id="pfCat" placeholder="e.g. Drinks" value="'+esc(product?product.category||'':'')+'"></div>' +
      '<div class="field"><label>'+tr('Unit')+'</label><input id="pfUnit" placeholder="e.g. bottle, kg" value="'+esc(product?product.unit||'':'')+'"></div>' +
    '</div>' +
    '<div class="field-row">' +
      '<div class="field"><label>'+tr('Cost price')+'</label><input id="pfCost" type="number" inputmode="decimal" step="0.01" placeholder="0.00" value="'+(product?product.costPrice:'')+'"></div>' +
      '<div class="field"><label>'+tr('Sell price')+'</label><input id="pfSell" type="number" inputmode="decimal" step="0.01" placeholder="0.00" value="'+(product?product.sellPrice:'')+'"></div>' +
    '</div>' +
    '<div class="field-row">' +
      '<div class="field"><label>'+(isEdit?tr('Current stock'):tr('Starting stock'))+'</label><input id="pfStock" type="number" inputmode="numeric" placeholder="0" value="'+(product?product.stockQty:'')+'"></div>' +
      '<div class="field"><label>'+tr('Low stock alert at')+'</label><input id="pfLow" type="number" inputmode="numeric" placeholder="'+State.settings.lowStockDefault+'" value="'+(product&&product.lowStock!=null?product.lowStock:'')+'"></div>' +
    '</div>' +
    '<div class="field-row">' +
      '<div class="field"><label>'+tr('Expiry date (optional)')+'</label><input id="pfExpiry" type="date" value="'+esc(product&&product.expiryDate||'')+'"></div>' +
      '<div class="field"><label>'+tr('Usual supplier (optional)')+'</label><select id="pfSup"><option value="">'+tr('None')+'</option>'+State.suppliers.map(function(sp){ return '<option value="'+esc(sp.id)+'"'+(product&&product.supplierId===sp.id?' selected':'')+'>'+esc(sp.name)+'</option>'; }).join('')+'</select></div>' +
    '</div>' +
    ((Fiscal.on() || isVatVendor()) ? '<div class="field"><label>'+tr('Tax category')+'</label><select id="pfTax">'+[['STANDARD',tr('Standard rate')+' ('+Fiscal.vatRate()+'%)'],['ZERO_RATED',tr('Zero rated (0%)')],['EXEMPT',tr('Exempt')],['NON_VAT',tr('Not a VAT item')]].map(function(o){ return '<option value="'+o[0]+'"'+(((product&&product.taxCategory)||'STANDARD')===o[0]?' selected':'')+'>'+esc(o[1])+'</option>'; }).join('')+'</select></div>' : '') +
    '<div class="field"><label>Barcode (optional)</label><div style="display:flex;gap:8px;"><input id="pfBarcode" placeholder="Scan or type a barcode" value="'+esc(product?product.barcode||'':(prefillBarcode||''))+'" style="flex:1;"><button class="btn btn-ghost" id="pfScanBtn" type="button" style="flex:0 0 auto;padding:0 14px;">'+ICONS.search+'</button></div></div>' +
    '<div class="actions">' +
      (isEdit ? '<button class="btn btn-danger" id="pfDelete">'+tr('Delete')+'</button>' : '') +
      '<button class="btn btn-primary btn-block" id="pfSave">'+(isEdit?'Save changes':tr('Add product'))+'</button>' +
    '</div>';
  var ov = openSheet(html);
  (function(){   // suggest a department from the name while the Category box is empty (milk, yogurt: Dairy products)
    var nm = ov.querySelector('#pfName'), ct = ov.querySelector('#pfCat'), auto = '';
    nm.addEventListener('input', function(){
      if(ct.value.trim() && ct.value !== auto) return;
      auto = deptGuess(nm.value); ct.value = auto;
    });
  })();
  ov.querySelector('#pfScanBtn').addEventListener('click', function(){
    openBarcodeScanSheet(function(code){
      ov.querySelector('#pfBarcode').value = code;
    });
  });
  ov.querySelector('#pfSave').addEventListener('click', function(){
    var name = ov.querySelector('#pfName').value.trim();
    if(!name){ toast('Enter a product name'); return; }
    var data = {
      name: name,
      category: ov.querySelector('#pfCat').value.trim(),
      unit: ov.querySelector('#pfUnit').value.trim(),
      costPrice: parseFloat(ov.querySelector('#pfCost').value) || 0,
      sellPrice: parseFloat(ov.querySelector('#pfSell').value) || 0,
      stockQty: ov.querySelector('#pfStock').value === '' ? 0 : parseInt(ov.querySelector('#pfStock').value,10),
      lowStock: ov.querySelector('#pfLow').value === '' ? null : parseInt(ov.querySelector('#pfLow').value,10),
      updatedAt: new Date().toISOString()
    };
    data.barcode = (ov.querySelector('#pfBarcode') ? ov.querySelector('#pfBarcode').value.trim() : (product?product.barcode:'')) || '';
    data.expiryDate = (ov.querySelector('#pfExpiry') ? ov.querySelector('#pfExpiry').value : '') || '';
    data.supplierId = (ov.querySelector('#pfSup') ? ov.querySelector('#pfSup').value : '') || '';
    if(ov.querySelector('#pfTax')) data.taxCategory = ov.querySelector('#pfTax').value; else if(product && product.taxCategory) data.taxCategory = product.taxCategory;
    if(State.settings.currentBranchId && State.settings.currentBranchId!=='all' && !isEdit) data.branchId = State.settings.currentBranchId;
    if(isEdit){
      // keep the stock movement record honest: a quantity or price edit is a manual adjustment
      var oldQ = Number(product.stockQty)||0, newQ = Number(data.stockQty)||0;
      var oldC = (Number(product.costPrice)||0)*oldQ, newC = (Number(data.costPrice)||0)*newQ;
      var oldR = (Number(product.sellPrice)||0)*oldQ, newR = (Number(data.sellPrice)||0)*newQ;
      if(Math.abs(newQ-oldQ) > 0 || Math.abs(newC-oldC) > 0.004 || Math.abs(newR-oldR) > 0.004) recordStockMove('manual', newQ-oldQ, newC-oldC, newR-oldR, 'Edited '+name);
      refs.products.doc(product.id).update(data);
      logAudit('update','product',product.id,'Edited '+name);
      toast('Product updated');
    } else {
      data.createdAt = new Date().toISOString();
      var nq = Number(data.stockQty)||0;
      if(nq) recordStockMove('manual', nq, nq*(Number(data.costPrice)||0), nq*(Number(data.sellPrice)||0), 'Added '+name);
      refs.products.doc().set(data);
      logAudit('create','product',null,'Added '+name);
      toast('Product added');
    }
    closeModal();
  });
  if(isEdit){
    ov.querySelector('#pfDelete').addEventListener('click', function(){
      confirmSheet('Delete '+product.name+'?', 'This removes it from your stock list. Past sales already recorded are not affected.', 'Delete', function(){
        withRemoval(product.name, function(){
        refs.products.doc(product.id).delete();
        logAudit('delete','product',product.id,'Deleted '+product.name);
        toast('Product deleted'); });
      }, true, true);
    });
  }
}

/* ============================== BULK STOCK IMPORT ============================== */
var Bulk = { rows: [], dup: 'skip' };
var BULK_PREVIEW = 50;

/* A price typed into the product name (for example "Polana Maize Meal (3kg): N$ 79.99") belongs in the price,
   not the name. This splits the two, and also drops a list number such as "12. " at the start. */
function splitPriceFromName(raw){
  var name = String(raw||'').trim(), price = null;
  var m = /^(.*?)\s*[:\-–—=@]?\s*(?:N\$|NAD|N\s?\$)\s*(\d[\d ]*(?:[.,]\d{1,2})?)\s*$/i.exec(name);
  if(m && m[1]){ name = m[1].trim(); price = parseFloat(m[2].replace(/\s/g,'').replace(',', '.')); if(isNaN(price)) price = null; }
  var n = name.replace(/^\d{1,3}[.)]\s+/, '').trim();
  if(n) name = n;
  return { name:name, price:price, changed: price!=null || name !== String(raw||'').trim() };
}
var _npCache = { ref:null, list:[] };
/** Products whose price is sitting inside the name (and whose own price is empty). */
function productsWithPriceInName(){
  if(_npCache.ref === State.products) return _npCache.list;
  var out = [];
  (State.products||[]).forEach(function(p){
    if(p._mock || (MockStock && MockStock.items && MockStock.items.indexOf(p) > -1)) return;
    var r = splitPriceFromName(p.name);
    if(r.price != null && !(Number(p.sellPrice) > 0)) out.push({ p:p, name:r.name, price:r.price });
  });
  _npCache = { ref:State.products, list:out };
  return out;
}
function namePriceBannerHtml(){
  if(!isManagerOrOwner || !isManagerOrOwner()) return '';
  var n = productsWithPriceInName().length;
  if(!n) return '';
  return '<div class="banner" style="display:flex;gap:10px;align-items:center;flex-wrap:wrap;">'+ICONS.warn+'<span style="flex:1;min-width:180px;"><strong>'+n.toLocaleString()+'</strong> '+tr('products have their price written in the name.')+'</span><button class="btn btn-primary" type="button" id="fixNamePrices">'+tr('Fix prices')+'</button></div>';
}
function fixNamePrices(){
  var list = productsWithPriceInName();
  if(!list.length){ toast(tr('Nothing to fix')); return; }
  confirmSheet(tr('Fix prices'), tr('Pesa will move the price out of each product name into its selling price, and tidy the name. Your stock counts stay the same.'), tr('Fix')+' '+list.length.toLocaleString(), function(){
    var rows = list.map(function(e){ var d = Object.assign({}, e.p); delete d.id; d.name = e.name; d.sellPrice = e.price; d.updatedAt = new Date().toISOString(); return { id:e.p.id, data:d }; });
    var wasBulk = BULK_HOLD; BULK_HOLD = true;
    (async function(){
      try{
        for(var i=0;i<rows.length;i+=1500){ await refs.products.setMany(rows.slice(i,i+1500)); await new Promise(function(r){ setTimeout(r,0); }); }
        BULK_HOLD = wasBulk;
        try{ logAudit('update','product','bulk','Moved prices out of '+rows.length+' product names'); }catch(e){}
        try{ await Persist.saved(); }catch(e){}
        _npCache = { ref:null, list:[] }; render();
        toast(rows.length.toLocaleString()+' '+tr('products fixed'));
      }catch(err){ BULK_HOLD = wasBulk; console.warn(err); toast(tr('Stopped part way. Try again to finish.')); render(); }
    })();
  });
}

function parseNum(s){
  if(s==null || s==='') return 0;
  var n = parseFloat(String(s).replace(/[^\d.\-]/g,''));
  return isNaN(n) ? 0 : n;
}

function parsePastedText(text){
  var lines = String(text||'').split(/\r?\n/).map(function(l){ return l.trim(); }).filter(Boolean);
  var rows = [], skipped = 0;
  lines.forEach(function(line){
    if(/^name\s*,/i.test(line)) return; // skip an obvious header line
    var parts = line.split(',').map(function(p){ return p.trim(); });
    var name = parts[0];
    if(!name){ skipped++; return; }
    var sp = splitPriceFromName(name), sellP = parseNum(parts[2]);
    if(sp.price != null && !(sellP > 0)){ sellP = sp.price; } if(sp.price != null) name = sp.name;
    rows.push({
      id: uid(), name: name,
      costPrice: parseNum(parts[1]),
      sellPrice: sellP,
      stockQty: parts[3]!=null ? (parseInt(parts[3],10)||0) : 0,
      category: parts[4] || '',
      unit: parts[5] || '',
      lowStock: null
    });
  });
  return { rows:rows, skipped:skipped };
}

function parseCsvLine(line){
  var result = [], cur = '', inQuotes = false;
  for(var i=0;i<line.length;i++){
    var c = line[i];
    if(c === '"'){ inQuotes = !inQuotes; }
    else if(c === ',' && !inQuotes){ result.push(cur); cur=''; }
    else cur += c;
  }
  result.push(cur);
  return result.map(function(s){ return s.trim().replace(/^"|"$/g,''); });
}

function parseCsvText(text){
  var lines = String(text||'').split(/\r?\n/).filter(function(l){ return l.trim().length>0; });
  if(lines.length===0) return { rows:[], skipped:0 };
  var header = parseCsvLine(lines[0]).map(function(h){ return h.toLowerCase(); });
  var hasHeader = header.some(function(h){ return /name|product|item/.test(h); });
  var idx = { name:0, cost:1, sell:2, qty:3, category:4, unit:5, low:-1, barcode:-1 };
  if(hasHeader){
    idx = { name:-1, cost:-1, sell:-1, qty:-1, category:-1, unit:-1, low:-1, barcode:-1 };
    header.forEach(function(h,i){
      if(/barcode|ean|sku|code/.test(h)) idx.barcode=i;
      else if(/name|product|item|desc/.test(h)) idx.name=i;
      else if(/categ/.test(h)) idx.category=i;
      else if(/unit/.test(h)) idx.unit=i;
      else if(/cost/.test(h)) idx.cost=i;
      else if(/sell|price/.test(h)) idx.sell=i;
      else if(/qty|quantity|stock/.test(h)) idx.qty=i;
      else if(/low/.test(h)) idx.low=i;
    });
  }
  var dataLines = hasHeader ? lines.slice(1) : lines;
  var rows = [], skipped = 0;
  dataLines.forEach(function(line){
    var parts = parseCsvLine(line);
    var name = idx.name>-1 ? parts[idx.name] : '';
    if(!name){ skipped++; return; }
    var sp2 = splitPriceFromName(name), sell2 = idx.sell>-1 ? parseNum(parts[idx.sell]) : 0;
    if(sp2.price != null){ if(!(sell2 > 0)) sell2 = sp2.price; name = sp2.name; }
    rows.push({
      id: uid(), name: name,
      category: idx.category>-1 ? (parts[idx.category]||'') : '',
      unit: idx.unit>-1 ? (parts[idx.unit]||'') : '',
      costPrice: idx.cost>-1 ? parseNum(parts[idx.cost]) : 0,
      sellPrice: sell2,
      stockQty: idx.qty>-1 ? (Math.round(parseNum(parts[idx.qty])*1000)/1000) : 0,
      barcode: idx.barcode>-1 ? (parts[idx.barcode]||'') : '',
      lowStock: idx.low>-1 && parts[idx.low] ? (parseInt(parts[idx.low],10)||null) : null
    });
  });
  return { rows:rows, skipped:skipped };
}

function handleCsvImport(file, statusEl){
  statusEl.innerHTML = '<div class="banner">Reading file…</div>';
  var reader = new FileReader();
  reader.onload = function(){
    try{
      var res = parseCsvText(String(reader.result||''));
      if(res.rows.length===0){
        statusEl.innerHTML = '<div class="banner">'+ICONS.warn+'<span>No products found in that file.</span></div>';
        return;
      }
      Bulk.rows = Bulk.rows.concat(res.rows);
      statusEl.innerHTML = '<div class="banner" style="color:var(--success);"><span>Found '+res.rows.length+' product'+(res.rows.length===1?'':'s')+(res.skipped?' ('+res.skipped+' row'+(res.skipped===1?'':'s')+' skipped)':'')+'.</span></div>';
      renderBulkPreview();
    }catch(e){
      statusEl.innerHTML = '<div class="banner">'+ICONS.warn+'<span>Couldn’t read that file. Make sure it’s a .csv file.</span></div>';
    }
  };
  reader.onerror = function(){ statusEl.innerHTML = '<div class="banner">'+ICONS.warn+'<span>Couldn’t read that file.</span></div>'; };
  reader.readAsText(file);
}

function renderBulkPreview(){
  var wrap = document.getElementById('bulkPreviewWrap');
  var actions = document.getElementById('bulkActions');
  if(!wrap) return;
  if(Bulk.rows.length === 0){ wrap.innerHTML=''; if(actions) actions.style.display='none'; return; }
  var shown = Bulk.rows.slice(0, BULK_PREVIEW);
  var bt = Bulk.rows.reduce(function(a,r){ a.qty += Number(r.stockQty)||0; a.cost += (Number(r.costPrice)||0)*(Number(r.stockQty)||0); a.retail += (Number(r.sellPrice)||0)*(Number(r.stockQty)||0); return a; }, {qty:0,cost:0,retail:0});
  wrap.innerHTML = '<div class="section-title">Review ('+Bulk.rows.length.toLocaleString()+')</div>' +
    '<div class="banner" style="display:block;"><strong>'+Bulk.rows.length.toLocaleString()+'</strong> products · <strong>'+bt.qty.toLocaleString()+'</strong> units · value at cost <strong>'+fmtMoney(bt.cost)+'</strong> · at selling price <strong>'+fmtMoney(bt.retail)+'</strong>' +
      (Bulk.rows.length > BULK_PREVIEW ? '<br>Showing the first '+BULK_PREVIEW+' to check. All '+Bulk.rows.length.toLocaleString()+' will be added.' : '') + '</div>' +
    '<div class="field"><label>If a product with the same name (or barcode) already exists</label><select id="bulkDupMode">' +
      '<option value="skip"'+(Bulk.dup==='skip'?' selected':'')+'>Skip it (keep what I have), recommended</option>' +
      '<option value="replace"'+(Bulk.dup==='replace'?' selected':'')+'>Update its prices and set stock to this number</option>' +
      '<option value="add"'+(Bulk.dup==='add'?' selected':'')+'>Update its prices and add this number to stock</option>' +
      '<option value="new"'+(Bulk.dup==='new'?' selected':'')+'>Add it again as a new product</option>' +
    '</select></div>' +
    '<div class="rowlist" id="bulkRowList">' + shown.map(function(r){
      return '<div class="card pad bulk-row-card" data-brow="'+r.id+'">' +
        '<div class="bulk-row-top">' +
          '<input data-bf="name" value="'+esc(r.name)+'" placeholder="Product name">' +
          '<button class="bulk-del" data-bdel type="button">×</button>' +
        '</div>' +
        '<div class="bulk-row-grid">' +
          '<input data-bf="costPrice" type="number" step="0.01" value="'+r.costPrice+'" placeholder="Cost">' +
          '<input data-bf="sellPrice" type="number" step="0.01" value="'+r.sellPrice+'" placeholder="Sell">' +
          '<input data-bf="stockQty" type="number" value="'+r.stockQty+'" placeholder="Qty">' +
          '<input data-bf="category" value="'+esc(r.category||'')+'" placeholder="Category">' +
        '</div>' +
      '</div>';
    }).join('') + '</div>';
  if(actions) actions.style.display='flex';
  var commitBtn = document.getElementById('bulkCommitBtn');
  if(commitBtn) commitBtn.textContent = 'Add ' + Bulk.rows.length.toLocaleString() + ' product' + (Bulk.rows.length===1?'':'s');
  var dm = document.getElementById('bulkDupMode'); if(dm) dm.addEventListener('change', function(){ Bulk.dup = dm.value; });
  wireBulkPreview();
}

function wireBulkPreview(){
  var list = document.getElementById('bulkRowList');
  if(!list) return;
  list.querySelectorAll('[data-brow]').forEach(function(cardEl){
    var id = cardEl.getAttribute('data-brow');
    var row = Bulk.rows.find(function(r){ return r.id===id; });
    if(!row) return;
    cardEl.querySelectorAll('[data-bf]').forEach(function(inp){
      inp.addEventListener('input', function(){
        var f = inp.getAttribute('data-bf');
        if(f==='costPrice' || f==='sellPrice'){ row[f] = parseFloat(inp.value)||0; }
        else if(f==='stockQty'){ row[f] = parseInt(inp.value,10)||0; }
        else { row[f] = inp.value; }
      });
    });
    var delBtn = cardEl.querySelector('[data-bdel]');
    if(delBtn) delBtn.addEventListener('click', function(){
      Bulk.rows = Bulk.rows.filter(function(r){ return r.id!==id; });
      renderBulkPreview();
    });
  });
}

function commitBulkRows(){
  var rows = Bulk.rows.filter(function(r){ return r.name && r.name.trim(); });
  if(rows.length===0){ toast('Add at least one product name'); return; }
  var now = new Date().toISOString();
  var commitBtn = document.getElementById('bulkCommitBtn');
  if(commitBtn){ commitBtn.disabled = true; commitBtn.textContent = 'Adding…'; }
  var mode = Bulk.dup || 'skip';
  // look up existing products by barcode and by name so nothing is added twice by accident
  var byName = {}, byCode = {}, byId = {};
  State.products.forEach(function(p){ byId[p.id] = p; byName[String(p.name||'').trim().toLowerCase()] = p; if(p.barcode) byCode[String(p.barcode).trim()] = p; });
  var addList = [], updList = [], skipped = 0, seenInFile = {};
  rows.forEach(function(r){
    var nm = r.name.trim(), key = nm.toLowerCase(), code = String(r.barcode||'').trim();
    var ex = (code && byCode[code]) || byName[key];
    if(!ex && mode !== 'new'){
      if(seenInFile[key] || (code && seenInFile['#'+code])){ skipped++; return; }   // the same product twice inside the file
      seenInFile[key] = 1; if(code) seenInFile['#'+code] = 1;
    }
    if(ex && mode !== 'new'){
      if(mode === 'skip'){ skipped++; return; }
      var q = Number(r.stockQty)||0;
      updList.push({ id:ex.id, data:Object.assign({}, ex, { name:nm, category:(r.category||ex.category||'').trim(), unit:(r.unit||ex.unit||'').trim(),
        costPrice:r.costPrice||0, sellPrice:r.sellPrice||0, stockQty: mode==='add' ? (Number(ex.stockQty)||0)+q : q, updatedAt:now }) });
      return;
    }
    var data = { name:nm, category:(r.category||'').trim(), unit:(r.unit||'').trim(),
      costPrice:r.costPrice||0, sellPrice:r.sellPrice||0, stockQty:Number(r.stockQty)||0,
      lowStock:r.lowStock!=null ? r.lowStock : null, createdAt:now, updatedAt:now };
    if(r.barcode) data.barcode = String(r.barcode).trim();
    addList.push({ id:uid(), data:data });
  });
  var total = addList.length + updList.length;
  var all = addList.concat(updList);
  var CH = 1500, done = 0;
  function status(){ if(commitBtn) commitBtn.textContent = 'Saving '+done.toLocaleString()+' of '+total.toLocaleString()+'…'; }
  // the screen would otherwise redraw after every batch; hold it until the end
  var wasBulk = BULK_HOLD; BULK_HOLD = true;
  (async function(){
    try{
      for(var i=0; i<all.length; i+=CH){
        await refs.products.setMany(all.slice(i, i+CH));
        done = Math.min(all.length, i+CH); status();
        await new Promise(function(r){ setTimeout(r, 0); });
      }
      BULK_HOLD = wasBulk;
      if(commitBtn) commitBtn.textContent = 'Saving to this device…';
      try{
        var mvQ = 0, mvC = 0, mvR = 0;
        addList.forEach(function(e){ var q=Number(e.data.stockQty)||0; mvQ+=q; mvC+=q*(e.data.costPrice||0); mvR+=q*(e.data.sellPrice||0); });
        updList.forEach(function(e){ var ex = byId[e.id], q=Number(e.data.stockQty)||0, oq=Number(ex&&ex.stockQty)||0;
          mvQ += q-oq; mvC += q*(e.data.costPrice||0) - oq*(Number(ex&&ex.costPrice)||0); mvR += q*(e.data.sellPrice||0) - oq*(Number(ex&&ex.sellPrice)||0); });
        if(mvQ || mvC || mvR) recordStockMove('upload', mvQ, mvC, mvR, 'Bulk stock upload ('+total.toLocaleString()+' products)');
      }catch(e){}
      try{ logAudit('create','product','bulk','Bulk stock upload: '+addList.length+' added, '+updList.length+' updated, '+skipped+' skipped'); }catch(e){}
      await Persist.saved();
      closeModal();
      toast(addList.length.toLocaleString()+' added'+(updList.length?', '+updList.length.toLocaleString()+' updated':'')+(skipped?', '+skipped.toLocaleString()+' skipped (already in your stock)':''));
      render();
    }catch(err){
      BULK_HOLD = wasBulk;
      console.warn(err);
      toast('Stopped after '+done.toLocaleString()+' products, try again to finish');
      if(commitBtn){ commitBtn.disabled = false; commitBtn.textContent = 'Add ' + rows.length.toLocaleString() + ' products'; }
    }
  })();
}
