/* ============================== IMAGE HELPERS (logo) ============================== */
function resizeImageFile(file, maxDim, quality){
  return new Promise(function(resolve, reject){
    var reader = new FileReader();
    reader.onload = function(){
      var img = new Image();
      img.onload = function(){
        var w = img.naturalWidth, h = img.naturalHeight;
        var scale = Math.min(1, maxDim/Math.max(w,h));
        var tw = Math.max(1, Math.round(w*scale)), th = Math.max(1, Math.round(h*scale));
        var canvas = document.createElement('canvas');
        canvas.width = tw; canvas.height = th;
        var ctx = canvas.getContext('2d');
        ctx.fillStyle = '#ffffff'; ctx.fillRect(0,0,tw,th);
        ctx.drawImage(img, 0, 0, tw, th);
        resolve({ dataUrl: canvas.toDataURL('image/jpeg', quality||0.85), w:tw, h:th });
      };
      img.onerror = function(){ reject(new Error('bad image')); };
      img.src = String(reader.result||'');
    };
    reader.onerror = function(){ reject(new Error('read failed')); };
    reader.readAsDataURL(file);
  });
}

/* ============================== PDF HELPERS ============================== */

/* ============================== DOCUMENT AND APP FONTS ==============================
   Three professional pairings. The chosen one styles the headings and text in
   the app, and every PDF (invoices, receipts, reports, VAT summary, About). */
var FONT_SETS = {
  elegant:{ label:'Elegant: Playfair Display headings with Inter text', cssHead:"'Pesa Playfair', Georgia, serif", cssBody:"'Pesa Inter', 'Inter', system-ui, sans-serif",
    head:'PlayfairDisplay-Bold', body:{ normal:'Inter-Regular', bold:'Inter-Bold', italic:'Inter-Italic' } },
  modern:{ label:'Modern: Montserrat headings with Inter text', cssHead:"'Pesa Montserrat', 'Pesa Inter', system-ui, sans-serif", cssBody:"'Pesa Inter', 'Inter', system-ui, sans-serif",
    head:'Montserrat-Bold', body:{ normal:'Inter-Regular', bold:'Inter-Bold', italic:'Inter-Italic' } },
  classic:{ label:'Classic: Lora throughout', cssHead:"'Pesa Lora', Georgia, serif", cssBody:"'Pesa Lora', Georgia, serif",
    head:'Lora-Bold', body:{ normal:'Lora-Regular', bold:'Lora-Bold', italic:'Lora-Italic' } }
};
// PDFs use the Modern pairing (closest to the PESA document design) unless a font was chosen on purpose.
function pdfFontKey(){
  var k = State && State.settings && State.settings.docFont;
  return FONT_SETS[k] ? k : 'modern';
}
function currentFontKey(){
  var k = (State && State.settings && State.settings.docFont) || null;
  if(!k){ try{ k = localStorage.getItem('pesa_docfont'); }catch(e){} }
  return FONT_SETS[k] ? k : 'elegant';
}
function applyAppFont(){
  var k = currentFontKey(), f = FONT_SETS[k], r = document.documentElement.style;
  r.setProperty('--font-head', f.cssHead); r.setProperty('--font-sans', f.cssBody);
  try{ localStorage.setItem('pesa_docfont', k); }catch(e){}
}
var PDF_FONT_CACHE = {}, PDF_FONT_FAIL = {};
function bufToB64(buf){
  var bytes = new Uint8Array(buf), s = '', CH = 0x8000;
  for(var i=0;i<bytes.length;i+=CH) s += String.fromCharCode.apply(null, bytes.subarray(i, i+CH));
  return btoa(s);
}
function loadPdfFontFile(name){
  if(PDF_FONT_CACHE[name]) return Promise.resolve(true);
  if(PDF_FONT_FAIL[name] && Date.now() - PDF_FONT_FAIL[name] < 30000) return Promise.resolve(false);
  return fetch('fonts/'+name+'.ttf').then(function(r){ if(!r.ok) throw new Error('HTTP '+r.status); return r.arrayBuffer(); })
    .then(function(b){ PDF_FONT_CACHE[name] = bufToB64(b); return true; }, function(){ PDF_FONT_FAIL[name] = Date.now(); return false; });
}
// Loads the fonts for the chosen pairing (a few seconds at most). If they can
// not be loaded, PDFs are drawn in the built in font instead.
function loadPdfFonts(){
  var f = FONT_SETS[pdfFontKey()], names = [f.head, f.body.normal, f.body.bold, f.body.italic];
  var job = Promise.all(names.map(loadPdfFontFile));
  var timeout = new Promise(function(res){ setTimeout(function(){ res([]); }, 6000); });
  return Promise.race([job, timeout]);
}
function applyPdfFonts(doc){
  var f = FONT_SETS[pdfFontKey()], all = [f.head, f.body.normal, f.body.bold, f.body.italic];
  if(!all.every(function(n){ return PDF_FONT_CACHE[n]; })) return false;   // not loaded: keep built in font
  all.forEach(function(n){ if(!doc.__pesaFont || !doc.__pesaFont[n]){ doc.addFileToVFS(n+'.ttf', PDF_FONT_CACHE[n]); doc.addFont(n+'.ttf', n, 'normal'); (doc.__pesaFont = doc.__pesaFont || {})[n] = 1; } });
  var origFont = doc.setFont.bind(doc), origSize = doc.setFontSize.bind(doc), cur = { style:'normal', size:(doc.getFontSize ? doc.getFontSize() : 16) };
  function eff(){
    var name = (cur.style === 'bold' && cur.size >= 9.5) ? f.head : (f.body[cur.style] || f.body.normal);
    origFont(name, 'normal');
  }
  doc.setFont = function(name, style){
    if(String(name||'').toLowerCase() === 'helvetica'){
      style = String(style||'normal');
      cur.style = style.indexOf('bold') !== -1 ? 'bold' : (style.indexOf('italic') !== -1 ? 'italic' : 'normal');
      eff(); return doc;
    }
    return origFont.apply(doc, arguments);
  };
  doc.setFontSize = function(sz){ cur.size = sz; origSize(sz); eff(); return doc; };
  eff(); return true;
}
function newPdfDoc(Ctor, opts){
  var d = new Ctor(opts);
  try{ applyPdfFonts(d); }catch(e){}
  // documents are printed in the chosen language too: exact matches with the dictionary are swapped
  if(currentLangCode() !== 'en'){
    var _tx = d.text.bind(d), _sp = d.splitTextToSize.bind(d);
    var tz = function(v){ return (typeof v === 'string') ? (i18nLookup(v.trim()) || v) : v; };
    d.text = function(t){ var a = Array.prototype.slice.call(arguments); a[0] = Array.isArray(t) ? t.map(tz) : tz(t); return _tx.apply(d, a); };
    d.splitTextToSize = function(t){ var a = Array.prototype.slice.call(arguments); a[0] = tz(t); return _sp.apply(d, a); };
  }
  ['output','save'].forEach(function(fn){
    var orig = d[fn].bind(d);
    d[fn] = function(){
      try{ drawLetterheadFooter(d); }catch(e){}
      var type = arguments[0];
      // jsPDF writes an /OpenAction (open at full width) into every PDF. It is harmless, but some antivirus programs treat any
      // PDF with an open action as suspicious. It is blanked out here, with spaces of the same length so the file stays valid.
      if(fn === 'output' && (type === 'blob' || type === 'arraybuffer')){
        try{
          var buf = orig.apply(d, ['arraybuffer']);
          pdfNoOpenAction(new Uint8Array(buf));
          return type === 'blob' ? new Blob([buf], { type:'application/pdf' }) : buf;
        }catch(e){}
      }
      return orig.apply(d, arguments);
    };
  });
  try{ xpCapture(d); }catch(e){}
  return d;
}
function pdfNoOpenAction(u8){
  var n = u8.length, sizes = [8192, 65536, n], re = /\/OpenAction\s*\[[^\]]*\]/;
  for(var s = 0; s < sizes.length; s++){
    var from = Math.max(0, n - sizes[s]), txt = '';
    for(var i = from; i < n; i += 8192) txt += String.fromCharCode.apply(null, u8.subarray(i, Math.min(n, i + 8192)));
    var m = re.exec(txt);
    if(m){ for(var k = 0; k < m[0].length; k++) u8[from + m.index + k] = 32; return u8; }
    if(from === 0) break;
  }
  return u8;
}
function getJsPDF(){ if(!(window.jspdf && window.jspdf.jsPDF)){ try{ window.__loadJsPdf && window.__loadJsPdf(); }catch(e){} } return (window.jspdf && window.jspdf.jsPDF) ? window.jspdf.jsPDF : null; }
// The PDF library loads from an external CDN via a <script> tag; on a slow
// connection or right after a cold app launch it may not have finished
// loading yet by the time someone taps a PDF button. Poll briefly instead
// of failing immediately, so a slow-but-working load isn't mistaken for a
// broken one.
function ensureJsPDF(maxWaitMs){
  return ensureJsPDFLib(maxWaitMs).then(function(ok){ return ok ? loadPdfFonts().then(function(){ return true; }, function(){ return true; }) : false; });
}
function ensureJsPDFLib(maxWaitMs){
  if(getJsPDF()) return Promise.resolve(true);
  maxWaitMs = maxWaitMs || 6000;
  return new Promise(function(resolve){
    var waited = 0, step = 150;
    var timer = setInterval(function(){
      if(getJsPDF()){ clearInterval(timer); resolve(true); return; }
      waited += step;
      if(waited >= maxWaitMs){ clearInterval(timer); resolve(false); }
    }, step);
  });
}
function pad2(n){ return (n<10?'0':'')+n; }
function timeText(d){ d = new Date(d); return pad2(d.getHours())+':'+pad2(d.getMinutes()); }
/** The moment a document belongs to: the saved time if it has one, otherwise
 * the current time when the document's date is today. Null if unknown. */
function draftAt(draft){
  if(draft.at) return draft.at;
  var ds = draft.dateStr || todayKey();
  if(draft.createdAt && String(draft.createdAt).slice(0,10) === ds) return draft.createdAt;
  if(ds === todayKey()) return new Date().toISOString();
  return null;
}
function docStamp(draft){
  var at = draftAt(draft);
  var d = fmtDateNice(draft.dateStr || todayKey());
  return at ? d+'  '+timeText(at) : d;
}
var PAY_LABELS = { cash:'Cash', card:'Card', wallet:'Mobile wallet', credit:'On credit', voucher:'Voucher' };
/* Vouchers. A voucher is a way of PAYING, not a discount: the platform (Sanlam, BestHome and so on) settles it with the shop later.
   sale.voucher = { platform, code, amount } is the part of the sale covered by the voucher. sale.paymentMethod is how the REST was paid,
   or 'voucher' when the voucher covered everything. Refunds carry the same fields with a negative amount. */
function voucherPlatforms(){ var l = State.settings && State.settings.voucherPlatforms; return (Array.isArray(l) && l.length) ? l : ['Sanlam', 'BestHome']; }
function voucherClaims(){ var l = State.settings && State.settings.voucherClaims; return Array.isArray(l) ? l : []; }
function saleVoucherAmt(s){ var v = s && s.voucher; if(!v) return 0; var a = Math.abs(Number(v.amount) || 0); return (Number(s.total) || 0) < 0 ? -a : a; }
function salePaidAmt(s){ return mRound2((Number(s && s.total) || 0) - saleVoucherAmt(s)); }
/* Split payments. A sale paid in more than one way keeps sale.paymentMethod as its main way (so older code still works) and
   sale.payments = [{ method, amount, walletProvider }], which add up to what the customer paid (the total less any voucher).
   Everything that adds money up by payment method reads salePayParts, so a normal sale comes back as one part. */
function saleIsSplit(s){ return !!(s && Array.isArray(s.payments) && s.payments.length > 1); }
function salePayParts(s){
  if(saleIsSplit(s)) return s.payments.map(function(x){ return { method:x.method || 'cash', amount:mRound2(Number(x.amount) || 0), walletProvider:x.walletProvider || '' }; });
  return [{ method:(s && s.paymentMethod) || 'cash', amount:salePaidAmt(s), walletProvider:(s && s.walletProvider) || '' }];
}
function voucherCodeUsed(platform, code){
  var c = String(code || '').trim().toLowerCase(), p = String(platform || '').trim().toLowerCase();
  return State.sales.find(function(s){ return s.voucher && s.type !== 'refund' && s.type !== 'void' && String(s.voucher.code || '').trim().toLowerCase() === c && String(s.voucher.platform || '').trim().toLowerCase() === p; }) || null;
}
function voucherSummary(){
  var by = {};
  function P(n){ return by[n] || (by[n] = { platform:n, redeemed:0, claimed:0, count:0, owed:0 }); }
  State.sales.forEach(function(s){ var a = saleVoucherAmt(s); if(!a || !s.voucher) return; var p = P(s.voucher.platform || 'Other'); p.redeemed = mRound2(p.redeemed + a); if(a > 0) p.count++; });
  voucherClaims().forEach(function(c){ var p = P(c.platform || 'Other'); p.claimed = mRound2(p.claimed + (Number(c.amount) || 0)); });
  voucherPlatforms().forEach(P);
  return Object.keys(by).map(function(k){ var p = by[k]; p.owed = mRound2(p.redeemed - p.claimed); return p; });
}
function openVouchersSheet(){
  var sum = voucherSummary(), canClaim = isManagerOrOwner();
  var reds = State.sales.filter(function(s){ return s.voucher && s.type !== 'refund' && s.type !== 'void'; })
    .sort(function(a, b){ return String(b.createdAt).localeCompare(String(a.createdAt)); });
  var owedAll = sum.reduce(function(a, p){ return a + p.owed; }, 0);
  var html = '<div class="sheet-head"><h2>'+tr('Vouchers')+'</h2></div>' +
    '<div class="banner" style="display:block;">'+tr('Pesa records the vouchers customers use and how much each platform owes you. It does not check a voucher with the platform and it does not collect the money. Claim the money from the platform, then record the payment here.')+'</div>' +
    '<div class="sumline total"><span>'+tr('Platforms owe you')+'</span><span class="num">'+fmtMoney(owedAll)+'</span></div>' +
    '<div class="rowlist">' + sum.map(function(p){
      return '<div class="row"><div class="main"><div class="title">'+esc(p.platform)+'</div><div class="sub">'+tr('Used')+' '+fmtMoney(p.redeemed)+' · '+tr('Paid to you')+' '+fmtMoney(p.claimed)+'</div></div>' +
        '<div class="trail"><div class="amt num">'+fmtMoney(p.owed)+'</div>' + (canClaim && p.owed > 0 ? '<button class="btn btn-ghost" type="button" data-vclaim="'+esc(p.platform)+'" style="padding:4px 10px;">'+tr('Record payment')+'</button>' : '') + '</div></div>';
    }).join('') + '</div>' +
    '<div class="section-title">'+tr('Recent vouchers used')+'</div>' +
    (reds.length ? '<div class="rowlist">' + reds.slice(0, 40).map(function(s){
      return '<div class="row"><div class="main"><div class="title">'+esc(s.voucher.platform)+' · '+esc(s.voucher.code)+'</div><div class="sub">'+esc(fmtDateTime(s.createdAt))+' · '+esc(s.receiptNo || '')+'</div></div><div class="trail"><div class="amt num">'+fmtMoney(Math.abs(s.voucher.amount))+'</div></div></div>';
    }).join('') + '</div>' : '<div style="font-size:13px;color:var(--text-muted);padding:4px 2px 8px;">'+tr('No vouchers used yet. Choose Customer has a voucher when you charge a sale.')+'</div>') +
    '<div class="actions">' + (canClaim ? '<button class="btn btn-ghost btn-block" type="button" id="vchAddPlat">'+tr('Add a platform')+'</button>' : '') +
    '<button class="btn btn-ghost btn-block" type="button" id="vchCsv">'+tr('Download list')+'</button></div>' + smartBackBtn();
  var ov = openSheet(html); wireSmartBack(ov);
  ov.querySelectorAll('[data-vclaim]').forEach(function(b){ b.addEventListener('click', function(){ openVoucherClaimSheet(b.getAttribute('data-vclaim')); }); });
  var ap = ov.querySelector('#vchAddPlat');
  if(ap) ap.addEventListener('click', function(){
    var nm = (window.prompt(tr('Platform name'), '') || '').trim(); if(!nm) return;
    var l = voucherPlatforms(); if(l.indexOf(nm) < 0) btSave({ voucherPlatforms: l.concat([nm]) });
    closeModal(); openVouchersSheet();
  });
  ov.querySelector('#vchCsv').addEventListener('click', function(){
    var rows = [['Date', 'Receipt', 'Platform', 'Voucher code', 'Amount']].concat(State.sales.filter(function(s){ return s.voucher; }).sort(function(a, b){ return String(a.createdAt).localeCompare(String(b.createdAt)); })
      .map(function(s){ return [String(s.createdAt).slice(0, 10), s.receiptNo || '', s.voucher.platform || '', s.voucher.code || '', String(saleVoucherAmt(s))]; }));
    rows.push([]); rows.push(['Payments received from platforms']); rows.push(['Date', 'Platform', 'Reference', 'Amount']);
    voucherClaims().forEach(function(c){ rows.push([c.date || '', c.platform || '', c.ref || '', String(c.amount)]); });
    btSaveCsv('Pesa-vouchers-' + todayKey() + '.csv', rows);
  });
}
function openVoucherClaimSheet(platform){
  var p = voucherSummary().find(function(x){ return x.platform === platform; }) || { owed:0 };
  var html = '<div class="sheet-head"><h2>'+tr('Payment from')+' '+esc(platform)+'</h2></div>' +
    '<div class="field"><label>'+tr('Amount received')+'</label><input id="vcAmt" type="number" inputmode="decimal" step="0.01" value="'+(p.owed > 0 ? p.owed.toFixed(2) : '')+'"></div>' +
    '<div class="field"><label>'+tr('Date')+'</label><input id="vcDate" type="date" value="'+todayKey()+'"></div>' +
    '<div class="field"><label>'+tr('Reference (optional)')+'</label><input id="vcRef" placeholder="'+tr('Bank reference or remittance number')+'"></div>' +
    '<div class="banner" style="display:block;">'+tr('Record this only once the money is in your bank account. It is booked as money in the bank and clears what the platform owed.')+'</div>' +
    '<div class="actions"><button class="btn btn-primary btn-block" id="vcSave" type="button">'+tr('Save payment')+'</button></div>' + smartBackBtn();
  var ov = openSheet(html); wireSmartBack(ov);
  ov.querySelector('#vcSave').addEventListener('click', function(){
    var amt = mRound2(parseFloat(ov.querySelector('#vcAmt').value)), d = ov.querySelector('#vcDate').value || todayKey();
    if(!(amt > 0)){ toast(tr('Enter the amount received')); return; }
    var c = { id:'vc' + Date.now().toString(36), platform:platform, amount:amt, date:d, ref:ov.querySelector('#vcRef').value.trim().slice(0, 60), by:State.session ? State.session.name : '', createdAt:new Date().toISOString() };
    btSave({ voucherClaims: voucherClaims().concat([c]) });
    logAudit('create', 'voucher', c.id, 'Voucher payment of ' + fmtMoney(amt) + ' received from ' + platform + (c.ref ? ' (' + c.ref + ')' : ''));
    toast(tr('Payment recorded')); closeModal(); openVouchersSheet();
  });
}
/** Payment rows for a document: method, amount received, change or balance. */
function payRows(draft, total){
  var rows = [];
  var vA = draft.voucher ? Math.abs(Number(draft.voucher.amount) || 0) : 0, due = total >= 0 ? Math.max(0, mRound2(total - vA)) : total;
  if(Array.isArray(draft.payments) && draft.payments.length > 1){
    draft.payments.forEach(function(q){ rows.push(['Paid by ' + (q.method === 'wallet' && q.walletProvider ? q.walletProvider : (PAY_LABELS[q.method] || q.method)), fmtMoney(q.amount)]); });
  } else if(draft.payMethod && draft.payMethod !== 'voucher'){
    var lbl = PAY_LABELS[draft.payMethod] || draft.payMethod;
    if(draft.payMethod === 'wallet' && draft.walletProvider) lbl = draft.walletProvider;
    rows.push(['Paid by', lbl]);
  }
  if(vA > 0) rows.push(['Voucher' + (draft.voucher.platform ? ' (' + draft.voucher.platform + ')' : ''), fmtMoney(vA)]);
  if(draft.cashBack > 0){ rows.push(['Cash back', fmtMoney(draft.cashBack)]); rows.push(['Charged to card', fmtMoney(total + Number(draft.cashBack))]); }
  if(draft.received != null && draft.received !== '' && !isNaN(Number(draft.received))){
    var rc = Number(draft.received);
    rows.push(['Amount received', fmtMoney(rc)]);
    if(rc >= due) rows.push(['Change given', fmtMoney(rc-due)]);
    else rows.push(['Balance due', fmtMoney(due-rc)]);
  }
  return rows;
}
function fmtDateNice(d){ return new Date(d).toLocaleDateString(uiLocale(),{day:'2-digit',month:'short',year:'numeric'}); }

function hexToRgb(hex){
  hex = String(hex||'').replace('#','').trim();
  if(hex.length===3) hex = hex.split('').map(function(c){ return c+c; }).join('');
  if(!/^[0-9a-fA-F]{6}$/.test(hex)) hex = '16463B';
  var num = parseInt(hex,16);
  return [(num>>16)&255, (num>>8)&255, num&255];
}

var DOC_TEMPLATES = {
  classic: { key:'classic', name:'Classic', primary:[11,74,56], accent:[201,150,42], muted:[110,120,115], dark:[27,36,32],
    totalLabel:'TOTAL DUE', defaultNote:'Thank you for your business. Payment is due within the terms agreed above.' },
  mono: { key:'mono', name:'Black & White', primary:[35,35,35], accent:[95,95,95], muted:[125,125,125], dark:[15,15,15],
    totalLabel:'TOTAL DUE', defaultNote:'Thank you for your business. Please settle this invoice by the due date shown above.' },
  slate: { key:'slate', name:'Slate', primary:[35,54,74], accent:[74,110,143], muted:[112,120,130], dark:[24,30,38],
    totalLabel:'AMOUNT PAYABLE', defaultNote:'We appreciate your prompt payment. Please quote the invoice number above as reference.' },
  warm: { key:'warm', name:'Warm', primary:[92,38,32], accent:[196,132,64], muted:[132,112,102], dark:[41,28,24],
    totalLabel:'TOTAL DUE', defaultNote:'Thank you for choosing us. Kindly settle this invoice by the due date shown above.' }
};

function getActiveTemplate(){
  var key = State.settings.invoiceTemplate || 'classic';
  if(key === 'custom'){
    var c = State.settings.customTemplate || {};
    return {
      key:'custom', name: c.name || 'Custom',
      primary: hexToRgb(c.primaryHex||'#16463B'),
      accent: hexToRgb(c.accentHex||'#D98E2B'),
      muted:[115,120,118], dark:[27,30,29],
      totalLabel:'TOTAL DUE',
      defaultNote: c.note || 'Thank you for your business. Payment is due within the terms agreed above.'
    };
  }
  return DOC_TEMPLATES[key] || DOC_TEMPLATES.classic;
}

/* ============================== PESA DOCUMENT DESIGN (PDF) ==============================
   One look for every A4 document: emerald header band with a gold swoosh, the Pesa lockup on the left and the
   business logo (or name) on the right, mint cards, an emerald table header, an emerald total bar, and a branded
   footer with the business contact and page numbers on every page. Colours follow the chosen document template. */
function pdMix(a, b, k){ return [Math.round(a[0] + (b[0]-a[0])*k), Math.round(a[1] + (b[1]-a[1])*k), Math.round(a[2] + (b[2]-a[2])*k)]; }
function pdPal(t){
  if(t.key === 'classic'){
    return { deep:[8,46,34], mid:[11,74,56], light:[14,106,80], gold:[201,150,42], gold2:[233,199,102], mint:[242,248,245], border:[210,227,218], line:[143,179,162], text:[16,33,26], muted:[78,98,88], teal:[14,124,102] };
  }
  var P = t.primary, G = t.accent, W = [255,255,255];
  return { deep:pdMix(P,[0,0,0],.4), mid:P, light:pdMix(P,W,.16), gold:G, gold2:pdMix(G,W,.4), mint:pdMix(P,W,.955), border:pdMix(P,W,.84), line:pdMix(P,W,.6), text:[20,26,24], muted:[84,96,90], teal:pdMix(P,W,.1) };
}
function pdSet(doc, kind, c){ if(kind === 'f') doc.setFillColor(c[0], c[1], c[2]); else if(kind === 'd') doc.setDrawColor(c[0], c[1], c[2]); else doc.setTextColor(c[0], c[1], c[2]); }
function pdGrad(doc, x, y, w, h, c1, c2){
  var n = Math.max(6, Math.round(w / 2.2)), sw = w / n;
  for(var i = 0; i < n; i++){ pdSet(doc, 'f', pdMix(c1, c2, n === 1 ? 0 : i/(n-1))); doc.rect(x + i*sw, y, sw + 0.35, h, 'F'); }
}
function pdCS(doc, v){ try{ doc.setCharSpace(v); }catch(e){} }
function pdTop(doc, fb){ return doc.__pd ? 34 : fb; }
function pdLines(text){ return String(text || '').split('\n').map(function(s){ return s.trim(); }).filter(Boolean); }
function pdContacts(){
  var txt = State.settings.businessContact || '', c = contactFromText(txt), web = '';
  pdLines(txt).forEach(function(l){ if(!web && !/@/.test(l) && /(www\.|https?:\/\/|\.com\b|\.co\.|\.na\b|\.org\b)/i.test(l)) web = l.replace(/^(web(site)?|www)\s*[:\-]?\s*/i, function(m0){ return /^www/i.test(m0) ? m0 : ''; }); });
  return { phone:c.phone, email:c.email, web:web };
}
function pdBand(doc, st, H, compact){ var cp = doc.__cap; if(cp) cp.chrome++; try{ return pdBandRaw(doc, st, H, compact); } finally{ if(cp) cp.chrome--; } }
function pdBandRaw(doc, st, H, compact){
  var pal = st.pal, pageW = 210, S = State.settings;
  pdGrad(doc, 0, 0, pageW, H, pal.deep, pal.light);
  var bh = compact ? 7.4 : 11.6, y0 = H - bh, k = bh / 11.6;
  try{ doc.setLineCap('round'); }catch(e){}
  pdSet(doc, 'd', pal.gold2); doc.setLineWidth(compact ? 0.55 : 0.85);
  doc.lines([[60.8, -5.2*k, 142.8, -4.1*k, 210, 1.8*k]], 0, y0 + 5.8*k, [1,1], 'S', false);
  pdSet(doc, 'd', pal.gold); doc.setLineWidth(0.25);
  doc.lines([[60.8, -5.3*k, 142.8, -4.1*k, 210, 2.0*k]], 0, y0 + 3.8*k, [1,1], 'S', false);
  doc.setFillColor(255,255,255);
  doc.lines([[60.8, -5.3*k, 142.8, -4.1*k, 210, 1.7*k], [0, bh + 0.3 - 8.7*k], [-210, 0]], 0, y0 + 7.0*k, [1,1], 'F', true);
  // lockup
  var mh = compact ? 10.5 : 11, mw = mh / PESA_LOGO_ASPECT, my = 7;
  try{ doc.addImage(PESA_LOGO_DATA_URL, 'PNG', 14, my, mw, mh); }catch(e){}
  var tx = 14 + mw + 3.6;
  doc.setFont('helvetica','bold'); doc.setFontSize(compact ? 15 : 17); doc.setTextColor(255,255,255);
  pdCS(doc, 0.6); doc.text('PESA', tx, my + (compact ? 6 : 6.4)); pdCS(doc, 0);
  doc.setFont('helvetica','bold'); doc.setFontSize(5); pdSet(doc, 't', pal.gold2);
  pdCS(doc, compact ? 0.7 : 0.8); doc.text('YOUR MULA, YOUR PRIDE', tx, my + 9.6); pdCS(doc, 0);
  // right side: the business logo on a white plate, else the business name
  var name = S.shopName || '';
  if(compact){
    doc.setFont('helvetica','bold'); doc.setFontSize(9.5); doc.setTextColor(255,255,255);
    doc.text(doc.splitTextToSize(name, 90)[0] || '', pageW - 14, 12, { align:'right' });
    doc.setFont('helvetica','bold'); doc.setFontSize(6.5); pdSet(doc, 't', pal.gold2);
    doc.text(tr('CONTINUED'), pageW - 14, 16.6, { align:'right' });
  } else if(S.logoDataUrl){
    var lg = S.logoImgMeta || {}, LH = 12, LW = 12, MAXW = 40;   // a little bigger than the Pesa mark (11)
    if(lg.w && lg.h){ LW = LH*lg.w/lg.h; if(LW > MAXW){ LW = MAXW; LH = MAXW*lg.h/lg.w; } }
    var px = pageW - 14 - LW - 3, py = my - 1.5 + (mh - LH)/2;
    // a cleaned (transparent) logo sits straight on the header like the Pesa mark; only a dark one gets a soft round plate so it stays readable
    // no plate, circle or frame of any kind: a dark logo is drawn as its white twin
    var plate = !lg.clean, imgUrl = (lg.clean && lg.tone < 0.45 && S.logoLightDataUrl) ? S.logoLightDataUrl : S.logoDataUrl;
    if(plate){ doc.setFillColor(255,255,255); doc.roundedRect(px, py, LW + 3, LH + 3, 2.2, 2.2, 'F'); }
    try{ doc.addImage(imgUrl, logoImgType(imgUrl), px + 1.5, py + 1.5, LW, LH); }catch(e){}
  } else if(name){
    doc.setFont('helvetica','bold'); doc.setFontSize(11); doc.setTextColor(255,255,255);
    var nl = doc.splitTextToSize(name, 92).slice(0, 2);
    doc.text(nl, pageW - 14, 12.4, { align:'right' });
    if(S.businessSlogan){
      doc.setFont('helvetica','italic'); doc.setFontSize(6.5); pdSet(doc, 't', pal.gold2);
      doc.text(doc.splitTextToSize(S.businessSlogan, 92)[0], pageW - 14, 12.4 + nl.length*4.6 + 0.4, { align:'right' });
    }
  }
}
function pdFooter(doc, pal, pg, total){ var cp = doc.__cap; if(cp) cp.chrome++; try{ return pdFooterRaw(doc, pal, pg, total); } finally{ if(cp) cp.chrome--; } }
function pdFooterRaw(doc, pal, pg, total){
  var y = 275, pageW = 210;
  pdGrad(doc, 0, y, pageW, 22, pal.light, pal.deep);
  pdSet(doc, 'd', pal.gold2); doc.setLineWidth(0.7); try{ doc.setLineCap('round'); }catch(e){}
  doc.lines([[60, 5.8, 150, 5.8, 210, 0.4]], 0, y + 3.0, [1,1], 'S', false);
  doc.setFillColor(255,255,255);
  doc.lines([[210, 0], [0, 1.9], [-70, 3.4, -140, 3.4, -210, -0.1]], 0, y - 1, [1,1], 'F', true);
  // small lockup
  var mh = 8.5, mw = mh / PESA_LOGO_ASPECT;
  try{ doc.addImage(PESA_LOGO_DATA_URL, 'PNG', 14, y + 8.6, mw, mh); }catch(e){}
  doc.setFont('helvetica','bold'); doc.setFontSize(11); doc.setTextColor(255,255,255); pdCS(doc, 0.4); doc.text('PESA', 14 + mw + 2.6, y + 13.6); pdCS(doc, 0);
  doc.setFont('helvetica','bold'); doc.setFontSize(4.2); pdSet(doc, 't', pal.gold2); pdCS(doc, 0.5); doc.text('YOUR MULA, YOUR PRIDE', 14 + mw + 2.6, y + 16.4); pdCS(doc, 0);
  // contacts
  var c = pdContacts(), items = [];
  if(c.phone) items.push(['phone', c.phone]); if(c.email) items.push(['mail', c.email]); if(c.web) items.push(['web', c.web]);
  var cx = 70, cyy = y + 13.1, fs = 7.4;
  doc.setFont('helvetica','normal');
  function totalW(sz){ doc.setFontSize(sz); var s = 0; items.forEach(function(it){ s += 6.4 + 2 + doc.getTextWidth(it[1]) + 6; }); return s; }
  while(items.length && fs > 5.6 && totalW(fs) > 104) fs -= 0.4;
  doc.setFontSize(fs);
  items.forEach(function(it){
    pdSet(doc, 'd', pal.gold2); doc.setLineWidth(0.35); doc.circle(cx + 3.2, cyy - 1.2, 3.2, 'S');
    var gx = cx + 3.2, gy = cyy - 1.2;
    doc.setLineWidth(0.3);
    if(it[0] === 'mail'){ doc.rect(gx - 1.6, gy - 1.1, 3.2, 2.2, 'S'); doc.lines([[1.6, 1.2], [1.6, -1.2]], gx - 1.6, gy - 1.1, [1,1], 'S', false); }
    else if(it[0] === 'web'){ doc.circle(gx, gy, 1.7, 'S'); doc.line(gx - 1.7, gy, gx + 1.7, gy); doc.line(gx, gy - 1.7, gx, gy + 1.7); }
    else { doc.roundedRect(gx - 0.9, gy - 1.7, 1.8, 3.4, 0.5, 0.5, 'S'); }
    doc.setTextColor(255,255,255); doc.text(it[1], cx + 8.4, cyy);
    cx += 6.4 + 2 + doc.getTextWidth(it[1]) + 6;
  });
  doc.setFont('helvetica','normal'); doc.setFontSize(7.4); doc.setTextColor(255,255,255);
  doc.text(tr('Page') + ' ' + pg + ' ' + tr('of') + ' ' + total, pageW - 14, cyy, { align:'right' });
}
// Cards, titles and fields shared by the documents
function pdTitle(doc, pal, x, y, title){
  doc.setFont('helvetica','bold'); doc.setFontSize(14); pdSet(doc, 't', pal.mid);
  pdCS(doc, 0.7); doc.text(String(title).toUpperCase(), x, y + 5); pdCS(doc, 0);
  return y + 11;
}
function pdCard(doc, pal, x, y, w, h, heading){
  pdSet(doc, 'f', pal.mint); pdSet(doc, 'd', pal.border); doc.setLineWidth(0.25);
  doc.roundedRect(x, y, w, h, 2.6, 2.6, 'FD');
  if(heading) pdCardHead(doc, pal, x + 4, y + 6, w - 8, heading);
}
function pdCardHead(doc, pal, x, y, w, text){
  pdSet(doc, 'f', pal.teal); doc.roundedRect(x, y - 3.1, 1.3, 3.7, 0.4, 0.4, 'F');
  doc.setFont('helvetica','bold'); doc.setFontSize(7); pdSet(doc, 't', pal.mid);
  pdCS(doc, 0.4); var s = String(tr(text)).toUpperCase(); doc.text(s, x + 3.2, y); pdCS(doc, 0);
}
function pdInfoH(a){ return 10.4 + (a.name ? 4.8 : 0) + Math.min(6, a.lines.length)*3.7 + 3; }
function pdInfoCard(doc, pal, x, y, w, h, a){
  pdCard(doc, pal, x, y, w, h, a.heading);
  var ty = y + 11.8;
  doc.setFont('helvetica','normal'); doc.setFontSize(7.5); pdSet(doc, 't', pal.text);
  if(a.name){ doc.text(doc.splitTextToSize(String(a.name), w - 8)[0], x + 4, ty); ty += 4.6; }
  a.lines.slice(0, 6).forEach(function(l){ doc.text(doc.splitTextToSize(l, w - 8)[0], x + 4, ty); ty += 3.7; });
  return h;
}
function pdTwoCards(doc, pal, x, y, W, a, b){
  var w = (W - 6) / 2, h = Math.max(pdInfoH(a), pdInfoH(b), 24);
  pdInfoCard(doc, pal, x, y, w, h, a); pdInfoCard(doc, pal, x + w + 6, y, w, h, b);
  return h;
}
function pdStrip(doc, pal, x, y, W, heading, fields){
  fields = fields.filter(function(f){ return f[1] !== '' && f[1] != null; }).map(function(f){ return [String(tr(f[0])), String(f[1])]; });
  var h = 16, avail = W - 52 - 4, vs = 9.2;
  function measure(sz){
    return fields.map(function(f){
      doc.setFont('helvetica','normal'); doc.setFontSize(sz); var v = doc.getTextWidth(f[1]);
      doc.setFontSize(6.4); var l = doc.getTextWidth(f[0].toUpperCase()) + f[0].length*0.3;
      return Math.max(v, l) + 5;
    });
  }
  var ws = measure(vs), sum = ws.reduce(function(a, b){ return a + b; }, 0);
  while(sum > avail && vs > 6.6){ vs -= 0.4; ws = measure(vs); sum = ws.reduce(function(a, b){ return a + b; }, 0); }
  var extra = Math.max(0, (avail - sum) / Math.max(1, fields.length)), scale = sum > avail ? avail / sum : 1;
  pdCard(doc, pal, x, y, W, h, null);
  pdSet(doc, 'f', pal.teal); doc.roundedRect(x + 4, y + 5.2, 1.3, 3.7, 0.4, 0.4, 'F');
  doc.setFont('helvetica','bold'); doc.setFontSize(8); pdSet(doc, 't', pal.mid); pdCS(doc, 0.5); doc.text(String(tr(heading)).toUpperCase(), x + 7.2, y + 8.4); pdCS(doc, 0);
  var fx = x + 52;
  fields.forEach(function(f, i){
    var fw = ws[i]*scale + extra;
    doc.setFont('helvetica','bold'); doc.setFontSize(6.4); pdSet(doc, 't', pal.muted); pdCS(doc, 0.3); doc.text(f[0].toUpperCase(), fx, y + 6.2); pdCS(doc, 0);
    doc.setFont('helvetica','normal'); doc.setFontSize(vs); pdSet(doc, 't', pal.text); doc.text(f[1], fx, y + 11.6);
    fx += fw;
  });
  return h;
}
function pdSection(doc, pal, x, y, w, text){
  doc.setFont('helvetica','bold'); doc.setFontSize(10); pdSet(doc, 't', pal.mid);
  pdCS(doc, 0.5); var s = String(tr(text)).toUpperCase(); doc.text(s, x, y); pdCS(doc, 0);
  var tw = doc.getTextWidth(s) + s.length*0.5 + 3, rest = w - tw;
}
function pdTotalRows(doc, pal, x, y, w, rows){
  var rh = 6.2;
  pdSet(doc, 'd', pal.border); doc.setLineWidth(0.25);
  rows.forEach(function(r, i){
    pdSet(doc, 'f', pal.mint); doc.rect(x, y + i*rh, w*0.52, rh, 'F');
    doc.setFillColor(255,255,255); doc.rect(x + w*0.52, y + i*rh, w*0.48, rh, 'F');
    doc.rect(x, y + i*rh, w, rh, 'S');
    doc.setFont('helvetica','bold'); doc.setFontSize(6.4); pdSet(doc, 't', pal.muted); pdCS(doc, 0.3); doc.text(String(tr(r[0])).toUpperCase(), x + 3, y + i*rh + 4.1); pdCS(doc, 0);
    doc.setFont('helvetica','bold'); doc.setFontSize(8); pdSet(doc, 't', pal.text); doc.text(String(r[1]), x + w - 3, y + i*rh + 4.3, { align:'right' });
  });
  return rows.length*rh;
}
function pdTotalBar(doc, pal, x, y, w, label, value, h){
  h = h || 10;
  pdGrad(doc, x, y, w, h, pal.mid, pal.light);
  pdSet(doc, 'f', pal.gold); doc.rect(x, y, w, 0.8, 'F');
  doc.setFont('helvetica','bold'); doc.setFontSize(8.2); doc.setTextColor(255,255,255); pdCS(doc, 0.4);
  doc.text(String(tr(label)).toUpperCase(), x + 4, y + h/2 + 1.9); pdCS(doc, 0);
  doc.setFontSize(10.5); doc.text(String(value), x + w - 4, y + h/2 + 2.1, { align:'right' });
  return h;
}
function pdNotesCard(doc, pal, x, y, w, heading, text, minH){
  var lines = doc.splitTextToSize(String(text || ''), w - 8);
  doc.setFont('helvetica','normal'); doc.setFontSize(7.5);
  lines = doc.splitTextToSize(String(text || ''), w - 8);
  var h = Math.max(minH || 20, 10.4 + lines.length*3.7 + 3);
  pdCard(doc, pal, x, y, w, h, heading);
  doc.setFont('helvetica','normal'); doc.setFontSize(7.5); pdSet(doc, 't', pal.text);
  lines.forEach(function(l, i){ doc.text(l, x + 4, y + 12 + i*3.7); });
  return h;
}
function pdSignBlock(doc, pal, x, y, w, heading){
  doc.setFont('helvetica','bold'); doc.setFontSize(7.2); pdSet(doc, 't', pal.mid); pdCS(doc, 0.4); doc.text(String(tr(heading)).toUpperCase(), x, y); pdCS(doc, 0);
  var cols = [['Name', 0.38], ['Signature', 0.38], ['Date', 0.24]], cx = x, gap = 3;
  cols.forEach(function(c){
    var cw = (w - gap*2) * c[1];
    pdSet(doc, 'd', pal.muted); doc.setLineWidth(0.35); doc.line(cx, y + 13, cx + cw, y + 13);
    doc.setFont('helvetica','bold'); doc.setFontSize(6.2); pdSet(doc, 't', pal.muted); doc.text(String(tr(c[0])).toUpperCase(), cx, y + 16.4);
    cx += cw + gap;
  });
}

function pdPage(doc){ try{ return doc.getCurrentPageInfo().pageNumber; }catch(e){ return doc.internal.getNumberOfPages(); } }
function pdPill(doc, pal, xr, y, text){
  doc.setFont('helvetica','bold'); doc.setFontSize(7.4); pdCS(doc, 0.5);
  var s = String(tr(text)).toUpperCase(), w = doc.getTextWidth(s) + s.length*0.5 + 9;
  pdSet(doc, 'd', pal.gold); doc.setLineWidth(0.5); pdSet(doc, 'f', [255,255,255]);
  doc.roundedRect(xr - w, y, w, 7.6, 3.8, 3.8, 'FD');
  pdSet(doc, 't', pal.mid); doc.text(s, xr - w/2 + 0.25, y + 5.1, { align:'center' }); pdCS(doc, 0);
}

/* ---- Every A4 document gets the PESA header band on page one, a slim band on later pages and the branded
   footer (contact details, page x of y) on every page. The footer is drawn once, when the file is produced. */
function lhFooterHeight(doc){ return 0; }
function drawLetterheadFooter(doc){
  var st = doc.__pd; if(!st || st.footed) return;
  st.footed = true;
  var n = doc.getNumberOfPages(), cur = pdPage(doc);
  for(var p = 1; p <= n; p++){ doc.setPage(p); pdFooter(doc, st.pal, p, n); }
  try{ doc.setPage(cur); }catch(e){}
}

/** Shared header for every A4 document. Safe to call again on a later page: that page is only drawn once.
 * Returns where the content starts (y), the template (t), its palette (pal) and the page limits. */
function drawDocHeader(doc, opts){
  var t = getActiveTemplate(), st = doc.__pd;
  if(!st){
    st = doc.__pd = { pal:pdPal(t), t:t, drawn:{}, footed:false };
    var origAdd = doc.addPage.bind(doc);
    doc.addPage = function(){
      var r = origAdd.apply(doc, arguments);
      var n = doc.getNumberOfPages();
      if(!st.drawn[n]){ st.drawn[n] = true; pdBand(doc, st, 26, true); }
      return r;
    };
  }
  var pg = pdPage(doc);
  if(!st.drawn[pg]){ st.drawn[pg] = true; pdBand(doc, st, pg === 1 ? 31 : 26, pg !== 1); }
  return { y: pg === 1 ? 40 : 34, t:st.t, pal:st.pal, margin:14, contentW:182, pageW:210, limit:265, footerH:0 };
}

function pdfSummaryLine(doc, x, y, width, label, value, opts){
  opts = opts || {};
  doc.setFont('helvetica', opts.bold?'bold':'normal');
  doc.setFontSize(opts.size || 10);
  var color = opts.color || [27,36,32];
  doc.setTextColor(color[0],color[1],color[2]);
  doc.text(label, x, y);
  doc.text(value, x+width, y, {align:'right'});
}

/** Branded table: emerald header, mint stripes, fine green rules. Columns can wrap ({wrap:true}) and the table
 * carries on to the next page with its header repeated. boldRows lists the row numbers to print in bold. */
function pdfTable(doc, opts){
  var pal = doc.__pd ? doc.__pd.pal : pdPal(getActiveTemplate());
  var x = opts.x, y = opts.y, W = opts.width, cols = opts.columns, rowH = opts.rowHeight || 6.2, hdrH = 7, LH = 3.5, limit = opts.limit || 265;
  var bold = opts.boldRows || [], stripe = pdMix(pal.mint, [255,255,255], 0.4);
  var _cap = doc.__cap; if(_cap){ try{ _cap.tables.push({ p:doc.internal.getCurrentPageInfo().pageNumber, y:y, cols:cols.map(function(c){ return { label:String(tr(c.label)), align:c.align || 'left', width:c.width }; }), rows:opts.rows.map(function(r){ return cols.map(function(c, i){ return String(r[i] == null ? '' : r[i]); }); }), bold:bold.slice() }); }catch(e){} _cap.intbl++; }
  function drawHeader(){
    pdGrad(doc, x, y, W, hdrH, pal.mid, pal.light);
    doc.setFont('helvetica','bold'); doc.setFontSize(6.4); doc.setTextColor(255,255,255); pdCS(doc, 0.3);
    var cx = x;
    cols.forEach(function(col){
      var s = String(tr(col.label)).toUpperCase(), r = col.align === 'right';
      doc.text(s, r ? cx + col.width - 3 : cx + 3, y + hdrH/2 + 1, { align: r ? 'right' : 'left' });
      cx += col.width;
    });
    pdCS(doc, 0);
    y += hdrH;
  }
  drawHeader();
  opts.rows.forEach(function(row, ri){
    var isBold = bold.indexOf(ri) !== -1;
    doc.setFont('helvetica', isBold ? 'bold' : 'normal'); doc.setFontSize(7.4);
    var cells = cols.map(function(col, ci){
      var s = String(row[ci] == null ? '' : row[ci]);
      return col.wrap ? doc.splitTextToSize(s, col.width - 6) : [s];
    });
    var lines = cells.reduce(function(m, c){ return Math.max(m, c.length); }, 1);
    var rh = Math.max(rowH, lines*LH + 2.8);
    if(y + rh > limit){
      doc.addPage(); y = pdTop(doc, 16); drawHeader();
      doc.setFont('helvetica', isBold ? 'bold' : 'normal'); doc.setFontSize(7.4);
    }
    if(ri % 2 === 1){ pdSet(doc, 'f', stripe); doc.rect(x, y, W, rh, 'F'); }
    pdSet(doc, 'd', pal.border); doc.setLineWidth(0.15);
    doc.line(x, y + rh, x + W, y + rh); doc.line(x, y, x, y + rh); doc.line(x + W, y, x + W, y + rh);
    var cx = x, base = y + (rh - lines*LH)/2 + 2.7;
    cols.forEach(function(col, ci){
      if(ci > 0) doc.line(cx, y, cx, y + rh);
      var r = col.align === 'right';
      pdSet(doc, 't', pal.text);
      doc.setFont('helvetica', isBold ? 'bold' : 'normal'); doc.setFontSize(7.4);
      doc.text(cells[ci], r ? cx + col.width - 3 : cx + 3, base, { align: r ? 'right' : 'left' });
      cx += col.width;
    });
    y += rh;
  });
  if(_cap) _cap.intbl--;
  return y;
}

// Standard browser download, works anywhere the app is opened as a normal
// web page (e.g. installed from GitHub Pages), unlike the Claude-only
// 'downloads' capability which only exists inside the artifact host.
function browserDownload(filename, blob){
  try{
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url; a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(function(){ URL.revokeObjectURL(url); }, 4000);
    return true;
  }catch(e){
    return false;
  }
}

/*EXPORT:START (document formats: Word, Excel, CSV, web page, rich text, plain text, pictures)
 * Every PDF is drawn with jsPDF. newPdfDoc() records what is drawn (text with its position, shapes, images), so the other
 * formats are built from the very same document: text and tables for Word, Excel, CSV, web page, rich text and plain text,
 * and a faithful redraw on a canvas for the picture formats. No extra library is needed and nothing leaves the device. */
var XP_FORMATS = [
  { k:'pdf',  ext:'pdf',  label:'PDF document',        note:'Looks the same everywhere. Best for sending and printing.' },
  { k:'docx', ext:'docx', label:'Word document',       note:'Opens in Microsoft Word, Google Docs and LibreOffice, so you can edit it.' },
  { k:'xlsx', ext:'xlsx', label:'Excel spreadsheet',   note:'Opens in Excel and Google Sheets. Amounts are real numbers you can add up.' },
  { k:'csv',  ext:'csv',  label:'CSV (comma separated)', note:'Plain table data for Excel, accounting programs and imports.' },
  { k:'html', ext:'html', label:'Web page',            note:'Opens in any browser and can be printed from there.' },
  { k:'rtf',  ext:'rtf',  label:'Rich text',           note:'Opens in WordPad, TextEdit, Word and most editors.' },
  { k:'txt',  ext:'txt',  label:'Plain text',          note:'Words and numbers only. Works anywhere.' },
  { k:'png',  ext:'png',  label:'Picture (PNG)',       note:'A sharp picture of the document, handy for WhatsApp.' },
  { k:'jpg',  ext:'jpg',  label:'Picture (JPG)',       note:'A smaller picture of the document.' }
];
function xpGetFmt(){
  var v = 'pdf';
  try{ v = localStorage.getItem('pesa_export_fmt') || 'pdf'; }catch(e){}
  return XP_FORMATS.some(function(f){ return f.k === v; }) ? v : 'pdf';
}
function xpSetFmt(v){ try{ localStorage.setItem('pesa_export_fmt', v); }catch(e){} }
