  items.forEach(function(it){
    if(it.ty === 'tb'){ rows.push(it); cur = null; return; }
    var dy = cur && cur.p === it.p ? Math.abs(it.y - cur.y) : 99;
    // same line, or a label that sits half a line higher or lower beside other text (a card title beside its field names)
    if(cur && dy <= 1.3 || (cur && dy <= 2.5 && cur.runs.every(function(r){ return it.x1 <= r.x0 - 0.3 || it.x0 >= r.x1 + 0.3; }))) cur.runs.push(it);
    else { cur = { ty:'row', p:it.p, y:it.y, runs:[it] }; rows.push(cur); }
  });
