    var pos = c.al === 'r' ? c.x1 : (c.al === 'c' ? (c.x0 + c.x1)/2 : c.x0), k = null;
    for(var i = 0; i < keys.length; i++){ if(keys[i].al === c.al && Math.abs(keys[i].pos - pos) <= 2.6){ k = keys[i]; break; } }
    if(!k){ k = { al:c.al, pos:pos, min:c.x0, max:c.x1 }; keys.push(k); } else { k.min = Math.min(k.min, c.x0); k.max = Math.max(k.max, c.x1); }
