    var row = keys.map(function(){ return { t:'', b:false, fs:9 }; });
    cells.forEach(function(c){ var cell = row[c._k.i]; cell.t = cell.t ? cell.t + ' ' + c.t : c.t; cell.b = c.b; cell.fs = c.fs; });
