function emailAlertsOn(){ try{ return emailAlertCfg().ready; }catch(e){ return false; } }
/** Sends one alert email. The same alert (same tag) is sent at most once every 6 hours and no more than 10 a day,
 * so a busy shop cannot use up the free EmailJS allowance. A failed send is written to the log and never stops a sale. */
function sendEmailAlert(title, body, tag){
  try{
    var c = emailAlertCfg(); if(!c.ready || navigator.onLine === false) return false;
    var log = {}; try{ log = JSON.parse(localStorage.getItem(EMAIL_ALERT_LOG) || '{}') || {}; }catch(e){}
    var now = Date.now(), day = new Date().toISOString().slice(0,10), t = String(tag || title);
    if(log.day !== day){ log = { day:day, n:0, tags:log.tags || {} }; }
    if(log.n >= 10) return false;
    if(log.tags && log.tags[t] && now - log.tags[t] < 6*3600000) return false;
    log.tags = log.tags || {}; log.tags[t] = now; log.n++;
    Object.keys(log.tags).forEach(function(k){ if(now - log.tags[k] > 86400000) delete log.tags[k]; });
    try{ localStorage.setItem(EMAIL_ALERT_LOG, JSON.stringify(log)); }catch(e){}
    var shop = (State.settings && State.settings.shopName) || 'Pesa';
    fetch('https://api.emailjs.com/api/v1.0/email/send', {
      method:'POST', headers:{ 'Content-Type':'application/json' },
      body: JSON.stringify({ service_id:c.service, template_id:c.template, user_id:c.key, template_params:{ to_email:c.to, subject:title + ' (' + shop + ')', message:body, shop_name:shop, app_name:'Pesa' } })
    }).then(function(r){ if(!r.ok) try{ localStorage.setItem('pesa_lasterr', new Date().toISOString() + ' email alert not sent (' + r.status + ')'); }catch(e){} }).catch(function(){});
    return true;
  }catch(e){ return false; }
}
function showDeviceNotification(title, body, tag){
  try{ sendEmailAlert(title, body, tag); }catch(e){}
  if(!notifyActive()) return false;
  var opts = { body: body, tag: tag || undefined, icon: 'icon-192.png' };
  function direct(){ try{ new Notification(title, opts); return true; }catch(e){ return false; } }
  try{
    if(navigator.serviceWorker && navigator.serviceWorker.getRegistration){
      navigator.serviceWorker.getRegistration().then(function(reg){
        if(reg && reg.showNotification) return reg.showNotification(title, opts).catch(direct);
        direct();
      }).catch(direct);
      return true;
    }
  }catch(e){}
  return direct();
}
