function voiceSupported(){ return !!(window.SpeechRecognition || window.webkitSpeechRecognition); }
// Say a product name; the words are put into the search box.
function startVoiceSearch(btn, done){
  var SR = window.SpeechRecognition || window.webkitSpeechRecognition;
  if(!SR){ toast(tr('Voice search is not available in this browser')); return; }
  var rec = new SR();
  rec.lang = ({af:'af-ZA', de:'de-DE'})[State.settings.language] || 'en-ZA';
  rec.interimResults = false; rec.maxAlternatives = 1;
  btn.style.background = 'var(--danger)'; btn.style.color = '#fff';
  toast(tr('Listening… say the product name'));
  function reset(){ btn.style.background = ''; btn.style.color = ''; }
  rec.onresult = function(e){ var t = e.results && e.results[0] && e.results[0][0] ? e.results[0][0].transcript : ''; reset(); if(t) done(t.replace(/[.,!?]+$/,'')); };
  rec.onerror = function(){ reset(); toast(tr('Could not hear that. Try again.')); };
  rec.onend = reset;
  try{ rec.start(); }catch(e){ reset(); }
}
function lowThresholdOf(p){ return p.lowStock != null ? p.lowStock : State.settings.lowStockDefault; }
/** changes: [{ product, newQty }] for products whose stock just went down.
 * Alerts once per product; the product is released for a new alert only after
 * it has been restocked above its threshold. */
function checkLowStockAlerts(changes){
  try{
    var seen = lowAlertedMap(), changed = {}, fresh = [];
    (changes||[]).forEach(function(c){
      var p = c.product;
      if(!p || c.newQty == null) return;
      changed[p.id] = true;
      // It was restocked above its threshold since the last alert: release it.
      if(seen[p.id] && p.stockQty != null && p.stockQty > lowThresholdOf(p)) delete seen[p.id];
      if(c.newQty <= lowThresholdOf(p)){
        if(!seen[p.id]){ seen[p.id] = new Date().toISOString(); fresh.push({ p:p, qty:c.newQty }); }
      } else if(seen[p.id]) delete seen[p.id];
    });
    State.products.forEach(function(p){
      if(!changed[p.id] && seen[p.id] && p.stockQty != null && p.stockQty > lowThresholdOf(p)) delete seen[p.id];
    });
    saveLowAlerted();
    if(!fresh.length) return;
    var title = fresh.length === 1 ? 'Low stock: ' + fresh[0].p.name : fresh.length + ' products are low on stock';
    var body = fresh.map(function(f){ return f.p.name + ': ' + f.qty + ' left'; }).join(', ') + '. Time to reorder.';
    showDeviceNotification(title, body, 'pesa-lowstock-' + (fresh.length === 1 ? fresh[0].p.id : 'multi'));
    // In-app message regardless of notification permission (after the
    // "Sale recorded" message has had its turn on screen).
    setTimeout(function(){ toast(title + ' (' + fresh.map(function(f){ return f.qty + ' left'; }).join(', ') + ')'); }, 2300);
    try{
      if(navigator.setAppBadge){
        var qtyNow = {};
        (changes||[]).forEach(function(c){ if(c.product) qtyNow[c.product.id] = c.newQty; });
        var lowCount = State.products.filter(function(p){
          var q = qtyNow[p.id] != null ? qtyNow[p.id] : p.stockQty;
          return q != null && q <= lowThresholdOf(p);
        }).length;
        navigator.setAppBadge(lowCount).catch(function(){});
      }
    }catch(e){}
  }catch(e){ /* alerts must never break a sale */ }
}
