function notifyDeviceHtml(){
  var html = '<div class="section-title">'+tr('Notifications')+'</div>';
  if(!notifySupported()){
    return html + '<div class="banner">'+tr('This browser can’t show device notifications, so the switch is hidden. Low-stock warnings still appear inside Pesa as messages and under Needs attention on the dashboard.')+'</div>';
  }
  var on = notifyActive();
  return html +
    '<div class="field"><label>'+tr('Low-stock and till alerts on this device')+'</label>' +
      '<div class="segbtns" id="stNotifySeg">' +
        '<button type="button" class="segbtn'+(on?'':' active')+'" data-notify="off">'+tr('Off')+'</button>' +
        '<button type="button" class="segbtn'+(on?' active':'')+'" data-notify="on">'+tr('On')+'</button>' +
      '</div></div>' +
    '<div class="banner" id="stNotifyNote">'+esc(notifyStatusCopy())+'</div>';
}
function wireNotificationSettings(ov){
  try{ wireEmailAlertSettings(ov); }catch(e){}
  try{ wireWaSettings(ov); }catch(e){}
  var seg = ov.querySelector('#stNotifySeg');
  if(!seg) return;
  function paint(){
    var on = notifyActive();
    seg.querySelectorAll('[data-notify]').forEach(function(b){ b.classList.toggle('active', (b.getAttribute('data-notify') === 'on') === on); });
    var note = ov.querySelector('#stNotifyNote'); if(note) note.textContent = notifyStatusCopy();
  }
  seg.querySelectorAll('[data-notify]').forEach(function(b){
    b.addEventListener('click', function(){
      if(b.getAttribute('data-notify') === 'off'){ setNotifyPref(false); paint(); toast(tr('Device alerts off')); return; }
      function granted(){
        setNotifyPref(true); paint();
        toast(tr('Device alerts on'));
        showDeviceNotification('Pesa alerts are on', 'You will see low-stock and till alerts here on this device.', 'pesa-test');
      }
      if(Notification.permission === 'granted'){ granted(); return; }
      if(Notification.permission === 'denied'){ setNotifyPref(false); paint(); toast(tr('Notifications are blocked in this browser’s settings')); return; }
      var done = false;
      function handle(perm){
        if(done) return; done = true;
        if(perm === 'granted') granted();
        else { setNotifyPref(false); paint(); toast(tr('Notifications weren’t allowed, so alerts stay inside Pesa')); }
      }
      try{
        var p = Notification.requestPermission(handle);
        if(p && p.then) p.then(handle, function(){ handle('denied'); });
      }catch(e){ handle('denied'); }
    });
  });
}

/* ============================== INVOICES ============================== */
var InvoiceDraft = { items: [] };

function invAddItem(desc, qty, unitPrice, productId){
  InvoiceDraft.items.push({ id:uid(), desc: desc||'', qty: qty!=null?qty:1, unitPrice: unitPrice!=null?unitPrice:0, productId: productId||undefined });
}

function invStockOptions(selId){
  var list = State.products.slice().sort(function(a,b){ return String(a.name||'').localeCompare(String(b.name||'')); });
  return '<option value="">'+tr('Choose from stock…')+'</option>' + list.map(function(p){
    var st = p.stockQty!=null ? ' · '+p.stockQty+' '+tr('in stock') : '';
    return '<option value="'+esc(p.id)+'"'+(selId===p.id?' selected':'')+'>'+esc(p.name)+', '+fmtMoney(p.sellPrice||0)+st+'</option>';
  }).join('');
}
function invRenderItems(container){
  container.innerHTML = InvoiceDraft.items.map(function(it){
    var amt = (Number(it.qty)||0) * (Number(it.unitPrice)||0);
    return '<div class="card pad" style="margin-bottom:8px;" data-invrow="'+it.id+'">' +
      (State.products.length ? '<select data-ifstock style="width:100%;margin-bottom:8px;border:1px solid var(--border);background:var(--surface-2);border-radius:8px;padding:8px 10px;font-size:13px;color:var(--text);">'+invStockOptions(it.productId)+'</select>' : '') +
      '<div style="display:flex;gap:8px;align-items:center;margin-bottom:8px;">' +
        '<input data-if="desc" placeholder="Item or service" value="'+esc(it.desc)+'" style="flex:1;border:1px solid var(--border);background:var(--surface-2);border-radius:8px;padding:8px 10px;font-size:13.5px;font-weight:600;color:var(--text);">' +
        '<button class="bulk-del" data-ivdel type="button">×</button>' +
      '</div>' +
      '<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px;">' +
        '<input data-if="qty" type="number" min="0" step="1" placeholder="Qty" value="'+it.qty+'" style="width:100%;min-width:0;border:1px solid var(--border);background:var(--surface-2);border-radius:8px;padding:6px 7px;font-size:12.5px;color:var(--text);">' +
        '<input data-if="unitPrice" type="number" min="0" step="0.01" placeholder="Price" value="'+it.unitPrice+'" style="width:100%;min-width:0;border:1px solid var(--border);background:var(--surface-2);border-radius:8px;padding:6px 7px;font-size:12.5px;color:var(--text);">' +
        '<div class="num" data-ivamt style="display:flex;align-items:center;justify-content:flex-end;font-weight:600;font-size:12.5px;">'+fmtMoney(amt)+'</div>' +
      '</div>' +
    '</div>';
  }).join('');
  container.querySelectorAll('[data-invrow]').forEach(function(rowEl){
    var id = rowEl.getAttribute('data-invrow');
    var item = InvoiceDraft.items.find(function(r){ return r.id===id; });
    if(!item) return;
    var stockSel = rowEl.querySelector('[data-ifstock]');
    if(stockSel) stockSel.addEventListener('change', function(){
      var p = State.products.find(function(x){ return x.id===stockSel.value; });
      if(!p){ item.productId = null; return; }
      item.productId = p.id; item.desc = p.name || ''; item.unitPrice = Number(p.sellPrice)||0;
      if(!(Number(item.qty) > 0)) item.qty = 1;
      rowEl.querySelector('[data-if="desc"]').value = item.desc;
      rowEl.querySelector('[data-if="unitPrice"]').value = item.unitPrice;
      rowEl.querySelector('[data-if="qty"]').value = item.qty;
      var amtEl0 = rowEl.querySelector('[data-ivamt]');
      if(amtEl0) amtEl0.textContent = fmtMoney((Number(item.qty)||0)*(Number(item.unitPrice)||0));
      invUpdateTotal();
      if(p.stockQty!=null && item.qty > p.stockQty) toast('Only '+p.stockQty+' of '+p.name+' in stock');
    });
    rowEl.querySelectorAll('[data-if]').forEach(function(inp){
      inp.addEventListener('input', function(){
        var f = inp.getAttribute('data-if');
        if(f==='qty'){ item.qty = parseFloat(inp.value)||0; }
        else if(f==='unitPrice'){ item.unitPrice = parseFloat(inp.value)||0; }
        else { item.desc = inp.value; }
        if(f==='desc' && stockSel && item.productId){ item.productId = null; stockSel.value = ''; }
        var amt = (Number(item.qty)||0) * (Number(item.unitPrice)||0);
        var amtEl = rowEl.querySelector('[data-ivamt]');
        if(amtEl) amtEl.textContent = fmtMoney(amt);
        invUpdateTotal();
      });
    });
    var delBtn = rowEl.querySelector('[data-ivdel]');
    if(delBtn) delBtn.addEventListener('click', function(){
      InvoiceDraft.items = InvoiceDraft.items.filter(function(r){ return r.id!==id; });
      invRenderItems(container);
      invUpdateTotal();
    });
  });
}

function invUpdateTotal(){
  var total = InvoiceDraft.items.reduce(function(s,it){ return s + (Number(it.qty)||0)*(Number(it.unitPrice)||0); }, 0);
  var el = document.getElementById('invTotalDisplay');
  if(el) el.textContent = fmtMoney(total);
  return total;
}

/** A business with a VAT registration number on its company profile is a VAT vendor, so its invoices are Tax invoices. */
/** Splits invoice lines into the tax figures a Namibian tax invoice shows. Prices include VAT, so VAT is taken out of the standard rated lines.
 *  Net = standard rated value without VAT. Net + VAT + Zero rated + Exempt = Gross, so the four lines always add up to the total due. */
function invoiceTaxBreakdown(items, dateKey){
  var d = taxFromItems(items, dateKey);
  return { rate:d.rate, v:d.v, net:mF(d.stdNet), vat:mF(d.vat), zero:mF(d.zero), exempt:mF(d.exempt), non:mF(d.non), gross:mF(d.total) };
}
/** The employee who handled the sale or wrote the document, shown on receipts and invoices. */
function servedByName(d){
  var n = (d && (d.servedBy || d.cashierName)) || '';
  if(!n && State.session) n = State.session.name || '';
  return String(n||'').trim();
}

function buildInvoicePdf(draft){
  var jsPDFCtor = getJsPDF();
  if(!jsPDFCtor) return null;
  var doc = newPdfDoc(jsPDFCtor, { unit:'mm', format:'a4' });
  var head = drawDocHeader(doc), pal = head.pal, t = head.t, m = head.margin, W = head.contentW, y = head.y;
  var S = State.settings, items = draft.items || [];
  var subtotal = items.reduce(function(s, it){ return s + (Number(it.qty)||0)*(Number(it.unitPrice)||0); }, 0);
  var pr = payRows(draft, subtotal);

  // status pill: paid, balance due or on credit
  var status = '';
  if(draft.payMethod === 'credit') status = 'On credit';
  else if(draft.received != null && draft.received !== '' && !isNaN(Number(draft.received))) status = Number(draft.received) >= subtotal ? 'Paid' : 'Balance due';
  else if(draft.payMethod) status = 'Paid';
  var docDay = taxDayOf(draft.dateStr || draft.at);
  var taxProblems = taxInvoiceProblems(draft);
  var vend = taxRegisteredOn(docDay) && !taxProblems.some(function(p){ return /VAT registration number|business name/.test(p); }), tb = vend ? invoiceTaxBreakdown(items, docDay) : null;
  var ty = y; y = pdTitle(doc, pal, m, y, tr(vend ? 'Tax invoice' : 'Invoice'));
  if(status) pdPill(doc, pal, m + W, ty + 1.5, status);

  // business and bill to cards: the seller's TIN and VAT registration number come first so they are never cut off
  var sellerTin = String((S.fiscal && S.fiscal.tin) || '').trim(), bizLines = [];
  if(sellerTin) bizLines.push(tr('TIN') + ': ' + sellerTin);
  if(State.company && State.company.vatNumber) bizLines.push(tr('VAT registration no.') + ': ' + State.company.vatNumber);
  bizLines = bizLines.concat(pdLines(S.businessContact));
  var billLines = pdLines(draft.billToContact);
  if(draft.billToTin) billLines.unshift(tr('TIN') + ': ' + draft.billToTin);
  y += pdTwoCards(doc, pal, m, y, W,
    { heading:'Business details', name:S.shopName || 'My Shop', lines:bizLines },
    { heading:'Bill to', name:draft.billToName || 'Customer', lines:billLines }) + 5;
  y += pdStrip(doc, pal, m, y, W, 'Invoice details', [['Invoice no.', draft.number], ['Issue date', docStamp(draft)], ['Due date', draft.dueDateStr ? fmtDateNice(draft.dueDateStr) : ''], ['Handled by', servedByName(draft)]]) + 6;

  // line items
  var rows = items.map(function(it){ var q = Number(it.qty)||0, p = Number(it.unitPrice)||0; return [it.desc || '', String(q), fmtMoney(p), fmtMoney(q*p)]; });
  y = pdfTable(doc, { x:m, y:y, width:W, columns:[ {label:'Description', width:W-90, wrap:true}, {label:'Qty', width:20, align:'right'}, {label:'Unit price', width:34, align:'right'}, {label:'Amount', width:36, align:'right'} ], rows:rows });
  y += 7;

  // notes on the left, totals on the right
  var tw = 76, lw = W - tw - 6, barH = 12;
  var topRows = vend ? [['Net total excl. VAT', fmtMoney(tb.net)], ['VAT ' + tb.rate + '%', fmtMoney(tb.vat)], ['Zero rated (0%)', fmtMoney(tb.zero)], ['Exempt', fmtMoney(tb.exempt)]] : [['Subtotal', fmtMoney(subtotal)]];
  var rightH = topRows.length*7 + barH + (pr.length ? 3 + pr.length*7 : 0);
  var note = draft.notes || t.defaultNote || '';
  doc.setFont('helvetica','normal'); doc.setFontSize(8.5);
  var noteH = Math.max(24, 12 + doc.splitTextToSize(String(note), lw - 8).length*4.3 + 4), blockH = Math.max(rightH, noteH);
  if(y + blockH > head.limit){ doc.addPage(); y = pdTop(doc, 16); }
  pdNotesCard(doc, pal, m, y, lw, 'Notes', note, blockH);
  var ry = y;
  ry += pdTotalRows(doc, pal, m + W - tw, ry, tw, topRows);
  ry += pdTotalBar(doc, pal, m + W - tw, ry, tw, vend ? 'Gross total due' : t.totalLabel, fmtMoney(vend ? tb.gross : subtotal), barH);
  if(pr.length){ ry += 3; pdTotalRows(doc, pal, m + W - tw, ry, tw, pr); }

  // Document verification signature: a tax invoice keeps a labelled place for a cryptographic verification code.
  // draft.verificationHash prints it when one exists. Until then the box stays empty and the text says so.
  if(vend){
    var vy = y + blockH + 6, vh = 33;
    if(vy + vh > head.limit){ doc.addPage(); vy = pdTop(doc, 16); }
    pdCard(doc, pal, m, vy, W, vh, 'Document verification signature');
    doc.setFont('helvetica','normal'); doc.setFontSize(7.6); pdSet(doc, 't', pal.muted);
    doc.text(doc.splitTextToSize(tr('Reserved for a verification code. Requirements are to be confirmed with the relevant authorities of Namibia.'), W - 8), m + 4, vy + 13.4);
    doc.setFont('helvetica','bold'); doc.setFontSize(6.6); pdSet(doc, 't', pal.muted); pdCS(doc, 0.3); doc.text(String(tr('Verification code')).toUpperCase(), m + 4, vy + 21.4); pdCS(doc, 0);
    doc.setFillColor(255,255,255); pdSet(doc, 'd', pal.border); doc.setLineWidth(0.25); doc.setLineDashPattern(draft.verificationHash ? [] : [1, 1], 0);
    doc.roundedRect(m + 4, vy + 23, W - 8, 7, 1.2, 1.2, 'FD'); doc.setLineDashPattern([], 0);
    if(draft.verificationHash){ doc.setFont('courier','normal'); doc.setFontSize(6.8); pdSet(doc, 't', pal.text); doc.text(String(draft.verificationHash).slice(0, 96), m + 6, vy + 27.7); }
  }
  return doc;
}

/** Compact, narrow (80mm) till-style receipt, company logo + slogan up top,
 * itemized list, total, and a small Pesa attribution in the footer. Uses the
 * same draft shape as buildInvoicePdf (number/dateStr/billToName/items/notes). */
function buildReceiptPdf(draft){
  var jsPDFCtor = getJsPDF();
  if(!jsPDFCtor) return null;
  var t = getActiveTemplate();
  var primary=t.primary, accent=t.accent, muted=t.muted, dark=t.dark;
  var pageW = 72, margin = 4, contentW = pageW - margin*2;
  var items = draft.items || [];
  var subtotal = items.reduce(function(s,it){ return s + (Number(it.qty)||0)*(Number(it.unitPrice)||0); }, 0);
  var vatNo = State.company && State.company.vatNumber ? State.company.vatNumber : '';
  var rcptDay = taxDayOf(draft.at || draft.dateStr), rcptTax = (draft.taxSnap && draft.taxSnap.v != null) ? draft.taxSnap : taxSnap(taxFromItems(items, rcptDay));
  var shopName = State.settings.shopName || (State.company && (State.company.tradingName || State.company.companyName)) || 'My Shop';
  var fz = Fiscal.pdfInfo(draft);   // tax record rows, or null when tax records are off for this receipt

  // Everything is drawn by one function. It runs once on a tall scratch page to
  // measure how long the receipt is, then again on a page cut to that length.
  function draw(doc){
    var y = margin;
    // ---- header: colour logo at the top left, shop details beside it
    var LOGO = 10, boxW = 10, boxH = 10, logoData = null, logoType = 'PNG';
    if(State.settings.logoDataUrl){
      logoData = State.settings.logoDataUrl; logoType = logoImgType(logoData);
      var lg = State.settings.logoImgMeta || {};
      if(lg.w && lg.h){ boxH = Math.max(6, Math.min(LOGO, 26*lg.h/lg.w)); boxW = boxH*lg.w/lg.h; }   // same height as the Pesa mark, wide logos kept readable
    } else {
      logoData = PESA_LOGO_DATA_URL; boxW = LOGO / PESA_LOGO_ASPECT; boxH = LOGO; if(boxW > LOGO){ boxH = LOGO / (boxW/LOGO); boxW = LOGO; }
    }
    try{ doc.addImage(logoData, logoType, margin, y, boxW, boxH); }catch(e){}
    var pesaW = 0;
    if(State.settings.logoDataUrl){   // company logo left, Pesa mark right, same size
      var ph = Math.min(boxH, 8); pesaW = ph / PESA_LOGO_ASPECT;
      try{ doc.addImage(PESA_LOGO_DATA_URL, 'PNG', pageW-margin-pesaW, y, pesaW, ph); }catch(e){}
    }
    var tx = margin + boxW + 3, leftW = contentW - boxW - 3 - (pesaW ? pesaW + 3 : 0), ly = y + 2.6;
    doc.setFont('helvetica','bold'); doc.setFontSize(8.2); doc.setTextColor(primary[0],primary[1],primary[2]);
    var nameLines = doc.splitTextToSize(shopName, leftW);
    doc.text(nameLines, tx, ly); ly += nameLines.length*3.3;
    if(State.settings.businessSlogan){
      doc.setFont('helvetica','italic'); doc.setFontSize(5.2); doc.setTextColor(accent[0],accent[1],accent[2]);
      var sl = doc.splitTextToSize(State.settings.businessSlogan, leftW); doc.text(sl, tx, ly); ly += sl.length*2.3 + 0.4;
    }
    doc.setFont('helvetica','normal'); doc.setFontSize(4.9); doc.setTextColor(muted[0],muted[1],muted[2]);
    (State.settings.businessContact||'').split('\n').filter(Boolean).slice(0,3).forEach(function(line){
      var cl = doc.splitTextToSize(line, leftW); doc.text(cl, tx, ly); ly += cl.length*2.2;
    });
    if(vatNo){ doc.text('VAT No. '+vatNo, tx, ly); ly += 2.2; }
    y = Math.max(ly, y + boxH) + 1.1;
    doc.setDrawColor(accent[0],accent[1],accent[2]); doc.setLineWidth(0.4); doc.line(margin, y, pageW-margin, y);
    doc.setLineWidth(0.2); y += 3.6;

    // ---- title and details
    doc.setFont('helvetica','bold'); doc.setFontSize(6.8); doc.setTextColor(primary[0],primary[1],primary[2]);
    doc.text('RECEIPT', margin, y, { charSpace:0.7 });
    doc.setFont('helvetica','normal'); doc.setFontSize(5.4); doc.setTextColor(dark[0],dark[1],dark[2]);
    doc.text('No. '+draft.number, pageW-margin, y, { align:'right' }); y += 3.2;
    function detail(label, value){
      doc.setFont('helvetica','normal'); doc.setFontSize(4.9); doc.setTextColor(muted[0],muted[1],muted[2]); doc.text(label, margin, y);
      doc.setFont('helvetica','bold'); doc.setFontSize(5.4); doc.setTextColor(dark[0],dark[1],dark[2]);
      var vl = doc.splitTextToSize(String(value), contentW - 20); doc.text(vl, pageW-margin, y, { align:'right' }); y += Math.max(1, vl.length)*2.5;
    }
    detail('Date', docStamp(draft));
    var _sb = servedByName(draft); if(_sb) detail('Served by', _sb);
    if(draft.billToName && draft.billToName !== 'Customer') detail('Customer', draft.billToName);
    y += 0.6;

    // ---- items
    doc.setFillColor(primary[0],primary[1],primary[2]); doc.rect(margin, y, contentW, 3, 'F');
    doc.setFont('helvetica','bold'); doc.setFontSize(4.8); doc.setTextColor(255,255,255);
    doc.text('ITEM', margin+2, y+2.1, { charSpace:0.25 }); doc.text('AMOUNT', pageW-margin-2, y+2.1, { align:'right', charSpace:0.25 });
    y += 3;
    items.forEach(function(it, i){
      var qty = Number(it.qty)||0, price = Number(it.unitPrice)||0, amt = qty*price;
      doc.setFont('helvetica','bold'); doc.setFontSize(5.8);
      var lines = doc.splitTextToSize(it.desc || '', contentW - 4 - 16);
      var h = lines.length*2.5 + 3;
      if(i % 2 === 1){ doc.setFillColor(245,246,245); doc.rect(margin, y, contentW, h, 'F'); }
      doc.setFont('helvetica','bold'); doc.setFontSize(5.8); doc.setTextColor(dark[0],dark[1],dark[2]);
      doc.text(lines, margin+2, y+2.4);
      doc.setFont('helvetica','bold'); doc.text(fmtMoney(amt), pageW-margin-2, y+2.4, { align:'right' });
      doc.setFont('helvetica','normal'); doc.setFontSize(4.9); doc.setTextColor(muted[0],muted[1],muted[2]);
      doc.text(qty+' × '+fmtMoney(price), margin+2, y+2.4+lines.length*2.5 - 0.1);
      y += h;
    });
    doc.setDrawColor(210,212,210); doc.line(margin, y, pageW-margin, y); y += 2.8;

    // ---- totals
    function sum(label, value){
      doc.setFont('helvetica','normal'); doc.setFontSize(5.4); doc.setTextColor(muted[0],muted[1],muted[2]);
      doc.text(label, margin+2, y); doc.setTextColor(dark[0],dark[1],dark[2]); doc.text(value, pageW-margin-2, y, { align:'right' }); y += 2.8;
    }
    sum('Items', String(items.reduce(function(a,it){ return a + (Number(it.qty)||0); }, 0)));
    if(fz) fz.pools.forEach(function(q){ sum(q.label, fmtMoney(q.amount)); });
    else if(vatNo && rcptTax.registered && rcptTax.stdGross !== 0){
      sum('VAT ('+rcptTax.rate+'%) included', fmtMoney(rcptTax.vat));
      if(rcptTax.zero) sum('Zero rated items', fmtMoney(rcptTax.zero));
      if(rcptTax.exempt) sum('VAT exempt items', fmtMoney(rcptTax.exempt));
    } else if(vatNo && rcptTax.registered && (rcptTax.zero || rcptTax.exempt)){
      if(rcptTax.zero) sum('Zero rated items', fmtMoney(rcptTax.zero));
      if(rcptTax.exempt) sum('VAT exempt items', fmtMoney(rcptTax.exempt));
    }
    y += 0.6;
    doc.setFillColor(primary[0],primary[1],primary[2]); doc.roundedRect(margin, y, contentW, 4.4, 0.8, 0.8, 'F');
    doc.setFont('helvetica','bold'); doc.setFontSize(5); doc.setTextColor(255,255,255);
    doc.text('TOTAL', margin+2, y+3, { charSpace:0.3 });
    doc.setFontSize(6.4); doc.text(fmtMoney(subtotal), pageW-margin-2, y+3.1, { align:'right' });
    y += 4.4 + 2.4;
    payRows(draft, subtotal).forEach(function(row){
      doc.setFont('helvetica','normal'); doc.setFontSize(5.4); doc.setTextColor(muted[0],muted[1],muted[2]);
      doc.text(row[0], margin+2, y);
      doc.setFont('helvetica','bold'); doc.setTextColor(dark[0],dark[1],dark[2]);
      doc.text(row[1], pageW-margin-2, y, { align:'right' }); y += 3;
    });
    y += 1.5;
    if(fz){   // tax record: reference, signature and verify address
      doc.setDrawColor(210,212,210); doc.line(margin, y, pageW-margin, y); y += 3;
      fz.lines.forEach(function(l){ doc.setFont('helvetica','normal'); doc.setFontSize(4.9); doc.setTextColor(muted[0],muted[1],muted[2]); var wl = doc.splitTextToSize(l, contentW - 4); doc.text(wl, pageW/2, y, { align:'center' }); y += wl.length*2.2; });
      y += 2;
    }

    // ---- footer: thank you
    doc.setDrawColor(accent[0],accent[1],accent[2]); doc.setLineDashPattern([0.8,1], 0); doc.line(margin, y, pageW-margin, y); doc.setLineDashPattern([], 0);
    y += 4;
    doc.setFont('helvetica','bold'); doc.setFontSize(7.4); doc.setTextColor(primary[0],primary[1],primary[2]);
    var ty = doc.splitTextToSize('Thank you for your business!', contentW);
    doc.text(ty, pageW/2, y, { align:'center' }); y += ty.length*3.2;
    doc.setFont('helvetica','italic'); doc.setFontSize(4.9); doc.setTextColor(muted[0],muted[1],muted[2]);
    var sub = doc.splitTextToSize('We appreciate your support. Please keep this receipt for your records.', contentW - 6);
    doc.text(sub, pageW/2, y, { align:'center' }); y += sub.length*2.3 + 0.8;
    doc.setFont('helvetica','bold'); doc.setFontSize(4.9); doc.setTextColor(dark[0],dark[1],dark[2]);
    var rf = doc.splitTextToSize('This receipt is proof of purchase. Keep it: it is required for any return or refund.', contentW - 6);
    doc.text(rf, pageW/2, y, { align:'center' }); y += rf.length*2.3 + 0.8;
    doc.setFont('helvetica','italic'); doc.setTextColor(muted[0],muted[1],muted[2]);
    var custom = (draft.notes || '').trim();
    if(custom && custom !== (t.defaultNote||'').trim()){
      var nl = doc.splitTextToSize(custom, contentW - 6); doc.setFont('helvetica','normal'); doc.text(nl, pageW/2, y, { align:'center' }); y += nl.length*2.3 + 0.8;
    }
    y += 1;
    return y;
  }
  var probe = newPdfDoc(jsPDFCtor, { unit:'mm', format:[pageW, 1500] });
  var total = draw(probe);
  var doc = newPdfDoc(jsPDFCtor, { unit:'mm', format:[pageW, Math.max(70, Math.ceil(total + margin))] });
  draw(doc);
  return doc;
}

function openInvoiceSheet(prefill){
  InvoiceDraft.items = [];
  if(prefill && prefill.items && prefill.items.length){
    prefill.items.forEach(function(it){ invAddItem(it.desc, it.qty, it.unitPrice, it.productId); });
  } else {
    invAddItem('', 1, 0);
  }
  var number = docNumberNext('INV', true);
  var html =
    '<div class="sheet-head"><h2>'+tr('New invoice')+'</h2></div>' +
    '<div class="banner">'+(isVatVendor() ? tr('Tax invoice') : 'Invoice')+' '+number+'</div>' +
    (isVatVendor() && !String((State.settings.fiscal && State.settings.fiscal.tin) || '').trim() ? '<div class="banner">'+ICONS.warn+'<span>'+tr('Your TIN is not set, so it will not print on this tax invoice. Add it in Settings, Tax records.')+'</span></div>' : '') +
    '<div class="field"><label>'+tr('Bill to')+'</label><input id="invBillName" placeholder="Customer or business name" value="'+esc(prefill&&prefill.billToName||'')+'"></div>' +
    '<div class="field"><label>'+tr('Customer contact (optional)')+'</label><textarea id="invBillContact" rows="2" placeholder="Phone, address…">'+esc(prefill&&prefill.billToContact||'')+'</textarea></div>' +
    '<div class="field"><label>'+tr('Customer TIN (optional, for business customers)')+'</label><input id="invBillTin" autocomplete="off" placeholder="e.g. 1234567890" value="'+esc(prefill&&prefill.billToTin||'')+'"></div>' +
    '<div class="field-row">' +
      '<div class="field"><label>'+tr('Invoice date')+'</label><input id="invDate" type="date" value="'+todayKey()+'"></div>' +
      '<div class="field"><label>'+tr('Due date (optional)')+'</label><input id="invDue" type="date"></div>' +
    '</div>' +
    '<div class="section-title" style="margin-top:14px;">'+tr('Gather from sales')+'</div>' +
    '<div class="banner" style="display:block;">'+tr('Pick a date, or a range of dates, and optionally a customer. Pesa collects the matching sales and fills in the items for you. The invoice date becomes the last date picked.')+'</div>' +
    '<div class="field-row"><div class="field"><label>'+tr('Sales from')+'</label><input id="invGFrom" type="date" value="'+todayKey()+'"></div><div class="field"><label>'+tr('Sales to')+'</label><input id="invGTo" type="date" value="'+todayKey()+'"></div></div>' +
    '<div class="field"><label>'+tr('Customer')+'</label><select id="invGCust"><option value="">'+tr('All sales')+'</option>'+State.customers.map(function(c){ return '<option value="'+esc(c.id)+'"'+((prefill&&prefill.customerId===c.id)?' selected':'')+'>'+esc(c.name)+'</option>'; }).join('')+'</select></div>' +
    '<button class="btn btn-ghost btn-block" id="invGather" type="button">'+tr('Gather sales and fill items')+'</button><div id="invGMsg" style="margin-top:8px;"></div>' +
    '<div class="section-title" style="margin-top:14px;">'+tr('Items')+'</div>' +
    '<div id="invItemsList"></div>' +
    '<button class="btn btn-ghost btn-block" id="invAddItemBtn" type="button">+ Add line item</button>' +
    (State.products.length ? '<button class="btn btn-ghost btn-block" id="invPickBtn" type="button" style="margin-top:8px;">☑ '+tr('Pick items from stock')+'</button><div id="invPickBox"></div>' : '') +
    '<div class="field" style="margin-top:14px;"><label>'+tr('Notes (optional)')+'</label><textarea id="invNotes" rows="3" placeholder="Payment details, thank-you note, terms…">'+esc(tr(prefill&&prefill.notes||getActiveTemplate().defaultNote||''))+'</textarea></div>' +
    '<div class="sumline total"><span>Total</span><span class="num" id="invTotalDisplay">N$0.00</span></div>' +
    '<div class="field" style="margin-top:12px;"><label>'+tr('Amount received (optional)')+'</label><input id="invReceived" type="number" inputmode="decimal" step="0.01" placeholder="0.00"></div>' +
    '<div id="invChangeNote" class="banner" style="display:none;"></div>' +
    '<div class="actions">' +
      '<button class="btn btn-ghost" id="invReceiptBtn" type="button">'+tr('Receipt')+'</button>' +
      '<button class="btn btn-accent" style="flex:2;" id="invGenerateBtn" type="button">'+tr('Download invoice')+'</button>' +
    '</div>' +
    '<div class="actions" style="margin-top:10px;"><button class="btn btn-primary btn-block" id="invSendBtn" type="button">'+tr('Send invoice')+' · '+tr('Email')+', '+tr('WhatsApp')+', '+tr('SMS')+'</button></div>' +
    '<div class="actions">' + bluetoothPrintButtonHtml('invBtPrintBtn') + '</div>';
  var ov = openSheet(html);
  var prefillCustomerId = prefill && prefill.customerId || null;
  // The invoice number is used up once, whether the invoice is downloaded,
  // sent, or both, so the next invoice never repeats it.
  var numberCommitted = false;
  function commitNumberOnce(draft){
    if(!numberCommitted){ numberCommitted = true; commitInvoiceNumber(draft, 'invoice', invoiceCustomerId(draft)); }
    else saveInvoiceRecord(draft, 'invoice', invoiceCustomerId(draft)); // edited and generated again under the same number
  }
  ov.querySelector('#invSendBtn').addEventListener('click', function(){
    var draft = readDraft();
    if(!draft) return;
    openSendSheet(documentSendCtx(draft, 'invoice', { customerId: invoiceCustomerId(draft), onHandedOff: function(){ commitNumberOnce(draft); } }));
  });
  // Default the recipient to the customer the invoice was started from, as
  // long as the "Bill to" name still matches them (otherwise match by name).
  function invoiceCustomerId(draft){
    if(!prefillCustomerId) return null;
    var c = State.customers.find(function(x){ return x.id===prefillCustomerId; });
    return (c && (c.name||'').trim().toLowerCase() === (draft.billToName||'').trim().toLowerCase()) ? c.id : null;
  }
  var btPrintBtn2 = ov.querySelector('#invBtPrintBtn');
  if(btPrintBtn2 && !btPrintBtn2.disabled) btPrintBtn2.addEventListener('click', function(){
    var draft = readDraft();
    if(draft) printReceiptViaBluetooth(draft, btPrintBtn2);
  });
  var itemsList = ov.querySelector('#invItemsList');
  (function(){
    var rin = ov.querySelector('#invReceived'), note = ov.querySelector('#invChangeNote');
    function upd(){
      var v = parseFloat(rin.value); var tot = InvoiceDraft.items.reduce(function(a,it){ return a + (Number(it.qty)||0)*(Number(it.unitPrice)||0); }, 0);
      if(rin.value === '' || isNaN(v)){ note.style.display='none'; return; }
      note.style.display='flex';
      note.innerHTML = v >= tot ? '<span>Change to give: <strong class="num">'+fmtMoney(v-tot)+'</strong></span>' : '<span>Balance still due: <strong class="num">'+fmtMoney(tot-v)+'</strong></span>';
    }
    rin.addEventListener('input', upd); ov.addEventListener('input', upd);
  })();
  invRenderItems(itemsList);
  invUpdateTotal();
  ov.querySelector('#invGather').addEventListener('click', function(){
    var from = ov.querySelector('#invGFrom').value, to = ov.querySelector('#invGTo').value, cid = ov.querySelector('#invGCust').value;
    var msg = ov.querySelector('#invGMsg');
    if(!from || !to || from > to){ msg.innerHTML = '<div class="banner">'+ICONS.warn+'<span>'+tr('Pick a start date that is not after the end date.')+'</span></div>'; return; }
    var s0 = new Date(from+'T00:00:00'), e0 = new Date(to+'T00:00:00'); e0.setDate(e0.getDate()+1);
    var sales = State.sales.filter(function(x){ var d = new Date(x.createdAt); return d >= s0 && d < e0 && (!cid || x.customerId === cid); });
    if(!sales.length){ msg.innerHTML = '<div class="banner">'+ICONS.warn+'<span>'+tr('No sales found for those dates.')+'</span></div>'; return; }
    var agg = {}, order = [];
    sales.forEach(function(x){ (x.items||[]).forEach(function(it){ var k = it.name+'|'+it.unitPrice; if(!agg[k]){ agg[k] = { desc:it.name, qty:0, unitPrice:it.unitPrice, productId:it.productId||null }; order.push(k); } agg[k].qty += it.qty||0; }); });
    InvoiceDraft.items = [];
    order.forEach(function(k){ invAddItem(agg[k].desc, agg[k].qty, agg[k].unitPrice, agg[k].productId); });
    invRenderItems(itemsList); invUpdateTotal();
    ov.querySelector('#invDate').value = to;
    if(cid){
      var c = State.customers.find(function(y){ return y.id === cid; });
      if(c){ prefillCustomerId = c.id; ov.querySelector('#invBillName').value = c.name || ''; var ct = [c.phone, c.email, c.address].filter(Boolean).join('\n'); ov.querySelector('#invBillContact').value = ct; }
    }
    var total = sales.reduce(function(a,x){ return a + (x.total||0); }, 0);
    msg.innerHTML = '<div class="banner" style="display:block;color:var(--success);">'+sales.length+' '+tr('sales gathered')+' · '+order.length+' '+tr('items')+' · '+fmtMoney(total)+'</div>';
  });
  var pickBtn = ov.querySelector('#invPickBtn');
  if(pickBtn) pickBtn.addEventListener('click', function(){
    var box = ov.querySelector('#invPickBox'); if(box.innerHTML){ box.innerHTML = ''; return; }
    mountStockPicker(box, { price:'sell', onAdd:function(list){
      list.forEach(function(x){ InvoiceDraft.items.push({ id:uid(), desc:x.p.name||'', qty:x.qty, unitPrice:Number(x.p.sellPrice)||0, productId:x.p.id }); });
      invRenderItems(itemsList); invUpdateTotal(); toast(list.length+' '+tr('items added'));
    } });
  });
  ov.querySelector('#invAddItemBtn').addEventListener('click', function(){
    invAddItem('', 1, 0);
    invRenderItems(itemsList);
    invUpdateTotal();
  });
  function readDraft(){
    var items = InvoiceDraft.items.filter(function(it){ return it.desc && it.desc.trim(); });
    if(items.length===0){ toast('Add at least one line item'); return null; }
    return {
      number: number,
      servedBy: servedByName({}),
      billToName: ov.querySelector('#invBillName').value.trim() || 'Customer',
      billToContact: ov.querySelector('#invBillContact').value.trim(),
      billToTin: (ov.querySelector('#invBillTin').value || '').trim(),
      dateStr: ov.querySelector('#invDate').value || todayKey(),
      dueDateStr: ov.querySelector('#invDue').value || '',
      notes: ov.querySelector('#invNotes').value.trim(),
      received: ov.querySelector('#invReceived').value === '' ? null : (parseFloat(ov.querySelector('#invReceived').value) || 0),
      items: items
    };
  }
  ov.querySelector('#invGenerateBtn').addEventListener('click', async function(){
    var draft = readDraft();
    if(!draft) return;
    var btn = ov.querySelector('#invGenerateBtn');
    var oldLabel = btn.textContent;
    btn.disabled = true; btn.textContent = 'Preparing…';
    var ready = await ensureJsPDF();
    if(!ready){ btn.disabled = false; btn.textContent = oldLabel; toast('Couldn’t load the PDF engine, check your connection and try again'); return; }
    var doc = buildInvoicePdf(draft);
    if(!doc){ btn.disabled = false; btn.textContent = oldLabel; toast('Couldn’t load the PDF engine, check your connection and try again'); return; }
    saveGeneratedPdf(doc, 'invoice-'+draft.number+'.pdf').then(function(ok){
      btn.disabled = false; btn.textContent = 'Download invoice';
      if(ok){
        commitNumberOnce(draft);
        toast('Invoice downloaded');
        openInvoiceReadySheet(draft, invoiceCustomerId(draft));
      }
    });
  });
  ov.querySelector('#invReceiptBtn').addEventListener('click', async function(){
    var draft = readDraft();
    if(!draft) return;
    var btn = ov.querySelector('#invReceiptBtn');
    var oldLabel = btn.textContent;
    btn.disabled = true; btn.textContent = 'Preparing…';
    var ready = await ensureJsPDF();
    if(!ready){ btn.disabled = false; btn.textContent = oldLabel; toast('Couldn’t load the PDF engine, check your connection and try again'); return; }
    var doc = buildReceiptPdf(draft);
    if(!doc){ btn.disabled = false; btn.textContent = oldLabel; toast('Couldn’t load the PDF engine, check your connection and try again'); return; }
    saveGeneratedPdf(doc, 'receipt-'+draft.number+'.pdf').then(function(ok){
      btn.disabled = false; btn.textContent = oldLabel;
      if(ok) toast('Receipt downloaded');
    });
  });
}

/* ============================== MONTHLY REPORT ============================== */
function monthOptionsHtml(){
  var opts = [], d = new Date(); d.setDate(1);
  for(var i=0;i<12;i++){
    var val = d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');
    var label = d.toLocaleDateString(uiLocale(),{month:'long',year:'numeric'});
    opts.push('<option value="'+val+'"'+(i===0?' selected':'')+'>'+label+'</option>');
    d.setMonth(d.getMonth()-1);
  }
  return opts.join('');
}

/** Work out every figure the report shows for [start, end). This is the one
 * place the report maths lives, so the live Dashboard report and archived
 * (saved) monthly reports can never disagree.
 * opts.scope: 'all' (default) or a branch id (strict match on branchId).
 * opts.snapshot: true builds the compact, storable version used by the
 * report archive (adds payments, VAT, wastage, till figures and caps the
 * long lists). The live Dashboard report never sets it. */
function computeReportFigures(start, end, opts){
  opts = opts || {};
  var scope = opts.scope || 'all';
  var snap = !!opts.snapshot;
  function inScope(x){ return scope === 'all' || x.branchId === scope; }

  var salesIn = State.sales.filter(function(s){ var d=new Date(s.createdAt); return d>=start && d<end && inScope(s); });
  var expensesIn = State.expenses.filter(function(e){ var d=new Date(e.createdAt); return d>=start && d<end && inScope(e); });
  var revenue = mSum(salesIn, function(x){ return x.total; });
  var cogs = mSum(salesIn, function(x){ return x.cost || 0; });
  var grossProfit = mRound2(revenue-cogs);
  var expByCat = {};
  expensesIn.forEach(function(e){ expByCat[e.category]=mRound2((expByCat[e.category]||0)+e.amount); });
  var expensesTotal = mSum(expensesIn, function(e){ return e.amount; });
  var netProfit = mRound2(grossProfit-expensesTotal);
  var totalOwed = State.customers.reduce(function(s,c){return s+(c.balance||0);},0);

  var byProduct = {};
  salesIn.forEach(function(s){ (s.items||[]).forEach(function(it){
    var k = it.name;
    if(!byProduct[k]) byProduct[k] = {qty:0, revenue:0, cost:0};
    byProduct[k].qty += it.qty; byProduct[k].revenue += it.lineTotal; byProduct[k].cost += (it.cost||0)*it.qty;
  }); });
  var productRows = Object.keys(byProduct).map(function(k){ var p=byProduct[k]; return {name:k, qty:p.qty, revenue:p.revenue, profit:p.revenue-p.cost}; })
    .sort(function(a,b){ return b.revenue-a.revenue; });

  var totalStockValue = State.products.reduce(function(s,p){ return s+(p.costPrice||0)*(p.stockQty||0); }, 0);
  var expenseRows = Object.keys(expByCat).sort(function(a,b){return expByCat[b]-expByCat[a];}).map(function(k){ return { category:String(k), amount:expByCat[k] }; });
  var stockRows = State.products.map(function(p){
    return { name:p.name, cost:p.costPrice, sell:p.sellPrice, qty:p.stockQty };
  });

  var stT = stockTotals();
  var fig = {
    revenue:revenue, cogs:cogs, grossProfit:grossProfit, expensesTotal:expensesTotal, netProfit:netProfit,
    expenseRows:expenseRows, productRows:productRows, totalOwed:totalOwed, totalStockValue:totalStockValue, stockRows:stockRows,
    totalStockRetail:stT.retail, totalStockQty:stT.qty, stockCount:stT.items, stockOutCount:stT.out
  };
  if(!snap){
    // the live PDF lists the highest-value lines; the totals above always cover every product
    if(fig.stockRows.length > 500){
      fig.stockTruncated = true;
      fig.stockRows = fig.stockRows.slice().sort(function(a,b){ return (Number(b.cost)||0)*(Number(b.qty)||0) - (Number(a.cost)||0)*(Number(a.qty)||0); }).slice(0, 500);
    }
    return fig;
  }

  var PRODUCT_CAP = 300, STOCK_CAP = 200;
  fig.salesCount = salesIn.filter(function(s){ return s.type !== 'refund' && s.type !== 'void'; }).length;
  fig.refundCount = salesIn.length - fig.salesCount;
  var pay = { cash:0, card:0, wallet:0, credit:0 };
  salesIn.forEach(function(s){ var m = s.paymentMethod || 'cash'; salePayParts(s).forEach(function(q){ pay[q.method] = mRound2((pay[q.method]||0) + q.amount); }); var vA = saleVoucherAmt(s); if(vA && m !== 'voucher') pay.voucher = mRound2((pay.voucher||0) + vA); });
  fig.payments = pay;
  var taxP = taxPeriod(salesIn), rateNow = taxRateAt(todayKey());
  fig.vat = { rate:rateNow.rate, version:rateNow.v, output: taxP.vat, input: taxInputVat(expensesIn), zero:taxP.zero, exempt:taxP.exempt, nonVat:taxP.non, registered:taxRegisteredOn(todayKey()) };
  fig.vat.net = mRound2(fig.vat.output - fig.vat.input);
  fig.productsOmitted = Math.max(0, productRows.length - PRODUCT_CAP);
  fig.productRows = productRows.slice(0, PRODUCT_CAP);
  if(scope === 'all'){
    var wIn = State.wastage.filter(function(w){ var d=new Date(w.createdAt); return d>=start && d<end; });
    fig.wastageCount = wIn.length;
    fig.wastageValue = wIn.reduce(function(s,w){
      var p = State.products.find(function(x){ return x.id===w.productId; });
      return s + (w.qty||0) * (p ? p.costPrice||0 : 0);
    }, 0);
    var tIn = State.tillSessions.filter(function(t){ if(t.status!=='closed' || !t.closedAt) return false; var d=new Date(t.closedAt); return d>=start && d<end; });
    fig.tills = { closedCount:tIn.length,
      cashCounted: tIn.reduce(function(s,t){ return s + (Number(t.closingCash)||0); }, 0),
      variance: tIn.reduce(function(s,t){ return s + (Number(t.variance)||0); }, 0) };
    fig.stockCount = stockRows.length;   // every product, not just the ones listed
    var byValue = stockRows.slice().sort(function(a,b){ return (Number(b.cost)||0)*(Number(b.qty)||0) - (Number(a.cost)||0)*(Number(a.qty)||0); }).slice(0, STOCK_CAP);
    fig.stockRows = byValue.map(function(p){ return { name:p.name||'', cost:Number(p.cost)||0, sell:Number(p.sell)||0, qty:Number(p.qty)||0 }; });
    fig.stockTruncated = stockRows.length > STOCK_CAP;
  } else {
    // credit, stock, wastage and tills are shop wide, not tracked per branch
    fig.totalOwed = null; fig.totalStockValue = null; fig.totalStockRetail = null; fig.stockRows = null;
  }
  return JSON.parse(JSON.stringify(fig));
}

/** Draw the report PDF from a figures object. With no meta it is the live
 * Dashboard report, exactly as before. With meta ({archived:true, interim,
 * shopName, scopeLabel, generatedAt, generatedBy}) it is a saved monthly
 * report: same layout plus the extra sections and the record footer. */
function drawReportPdf(fig, monthLabel, meta){
  var jsPDFCtor = getJsPDF();
  if(!jsPDFCtor) return null;
  var arch = !!meta;
  var gen = arch ? new Date(meta.generatedAt) : null;
  var genText = arch ? (fmtDateNice(gen) + ' ' + gen.toLocaleTimeString(uiLocale(),{hour:'2-digit',minute:'2-digit'})) : fmtDateNice(new Date());

  var doc = newPdfDoc(jsPDFCtor, { unit:'mm', format:'a4' });
  var head = drawDocHeader(doc), pal = head.pal;
  var m = head.margin, W = head.contentW, y = head.y;
  function need(h){ if(y+h>head.limit){ doc.addPage(); y = pdTop(doc, 16); } }
  // the live report keeps its original minus sign; saved reports use a plain hyphen, which every PDF font draws correctly
  var MINUS = arch ? '-' : '−';
  function sect(title, h){ need(h || 34); pdSection(doc, pal, m, y + 3, W, title); y += 7; }
  function kv(rows, h1, h2, bold){
    y = pdfTable(doc, { x:m, y:y, width:W, columns:[{label:h1, width:W-54}, {label:h2, width:54, align:'right'}], rows:rows, boldRows:bold });
    y += 7;
  }
  function note(text){
    doc.setFont('helvetica','normal'); doc.setFontSize(7.8); pdSet(doc, 't', pal.muted);
    doc.splitTextToSize(String(tr(text)), W).forEach(function(l){ need(4.5); doc.text(l, m, y); y += 3.9; });
    y += 4;
  }
  function kpi(x, w, label, val){
    pdCard(doc, pal, x, y, w, 19, null);
    doc.setFont('helvetica','bold'); doc.setFontSize(6.4); pdSet(doc, 't', pal.muted); pdCS(doc, 0.3); doc.text(String(tr(label)).toUpperCase(), x + 4, y + 6.4); pdCS(doc, 0);
    var sz = 11.5; doc.setFont('helvetica','bold'); doc.setFontSize(sz);
    while(sz > 7.5 && doc.getTextWidth(val) > w - 8){ sz -= 0.5; doc.setFontSize(sz); }
    pdSet(doc, 't', pal.text); doc.text(val, x + 4, y + 14.2);
  }

  // title, status and the details strip
  var ty = y;
  y = pdTitle(doc, pal, m, y, (arch && !meta.custom) ? 'Monthly report' : 'Business report');
  if(arch && meta.interim) pdPill(doc, pal, m + W, ty + 1.5, 'Interim');
  y += pdStrip(doc, pal, m, y, W, 'Report details', [
    ['Business', (arch ? meta.shopName : State.settings.shopName) || 'Pesa'],
    ['Report', monthLabel],
    ['Scope', arch ? meta.scopeLabel : ''],
    ['Generated', genText]
  ]) + 5;
  if(arch && meta.periodText) note(tr('Period') + ': ' + meta.periodText);
  if(arch && meta.interim) note('Figures so far. The final report for this month is filed automatically after month end.');
  if(!arch || (!meta.periodText && !meta.interim)) y += 1;

  // summary: four key figures and the net result
  sect('Summary', 60);
  var kw = (W - 12) / 4;
  kpi(m, kw, 'Sales revenue', fmtMoney(fig.revenue));
  kpi(m + (kw+4), kw, 'Cost of goods sold', MINUS + fmtMoney(fig.cogs));
  kpi(m + (kw+4)*2, kw, 'Gross profit', fmtMoney(fig.grossProfit));
  kpi(m + (kw+4)*3, kw, 'Operating expenses', MINUS + fmtMoney(fig.expensesTotal));
  y += 19 + 5;
  var netProfit = fig.netProfit;
  y += pdTotalBar(doc, pal, m, y, W, netProfit >= 0 ? 'Net profit' : 'Net loss', fmtMoney(Math.abs(netProfit)), 13) + 8;

  if(fig.totalOwed != null){
    var asAt = arch ? tr('as at')+' '+fmtDateNice(gen) : tr('as of today');
    var pos = [
      [tr('Outstanding customer credit')+' ('+asAt+')', fmtMoney(fig.totalOwed)],
      [tr('Stock on hand, valued at cost')+' ('+asAt+')', fmtMoney(fig.totalStockValue)]
    ];
    if(fig.totalStockRetail != null){
      pos.push([tr('Stock on hand, at selling price')+' ('+asAt+')', fmtMoney(fig.totalStockRetail)]);
      pos.push([tr('Products in stock list')+' / '+tr('units on hand'), (fig.stockCount||0).toLocaleString()+' / '+(fig.totalStockQty||0).toLocaleString()]);
    }
    sect('Credit and stock', 40);
    kv(pos, 'Item', 'Value');
  } else if(arch){
    note('Customer credit and stock are shop wide, so they appear only on the whole shop report.');
  }

  if(arch){
    sect('Sales and payment methods', 46);
    kv([[tr('Number of sales'), String(fig.salesCount||0)], [tr('Average sale'), fmtMoney(fig.salesCount ? fig.revenue/fig.salesCount : 0)]], 'Measure', 'Value');
    var pay = fig.payments || {};
    var payNames = { cash:'Cash', card:'Card', wallet:'Mobile wallet', credit:'Credit' };
    var payKeys = Object.keys(pay);
    if(payKeys.length){
      need(12 + payKeys.length*7.6);
      y = pdfTable(doc, { x:m, y:y, width:W,
        columns:[{label:'Payment method', width:W-70},{label:'Amount', width:40, align:'right'},{label:'Share', width:30, align:'right'}],
        rows: payKeys.map(function(k){ return [tr(payNames[k]||k), fmtMoney(pay[k]), (fig.revenue ? Math.round(pay[k]/fig.revenue*1000)/10 : 0)+'%']; })
      });
      y += 8;
    }

    var v = fig.vat || {rate:0, output:0, input:0, net:0};
    sect('VAT summary (working figures)', 70);
    var vrows = [];
    if(meta.vatNumber) vrows.push([tr('VAT number'), meta.vatNumber]);
    vrows.push([tr('VAT rate applied'), v.rate+'%'], [tr('Output VAT (on sales)'), fmtMoney(v.output)], [tr('Input VAT (on expenses)'), fmtMoney(v.input)], [(v.net>=0?tr('Net VAT payable'):tr('Net VAT refundable')), fmtMoney(Math.abs(v.net))]);
    kv(vrows, 'Item', 'Value', [vrows.length-1]);
    y -= 3;
    note('Sales and expenses are treated as VAT inclusive. Please confirm filing requirements with NamRA.');

    if(fig.wastageValue != null || fig.tills){
      var orows = [];
      if(fig.wastageValue != null) orows.push([tr('Wastage recorded, at cost')+' ('+(fig.wastageCount||0)+' '+tr('entries')+')', fmtMoney(fig.wastageValue)]);
      if(fig.tills){
        orows.push([tr('Tills closed'), String(fig.tills.closedCount)], [tr('Cash counted at till close'), fmtMoney(fig.tills.cashCounted)], [tr('Total till variance'), (fig.tills.variance<0?'-':'')+fmtMoney(Math.abs(fig.tills.variance))]);
      }
      sect(meta && meta.custom ? 'Other records for the period' : 'Other records for the month', 40);
      kv(orows, 'Item', 'Value');
    }
  }

  if(fig.expenseRows.length){
    sect('Expenses by category', 36);
    y = pdfTable(doc, { x:m, y:y, width:W,
      columns:[{label:'Category', width:W-40},{label:'Amount', width:40, align:'right'}],
      rows: fig.expenseRows.map(function(r){ return [r.category, fmtMoney(r.amount)]; })
    });
    y += 8;
  }

  if(fig.productRows.length){
    sect('Product performance', 40);
    y = pdfTable(doc, { x:m, y:y, width:W,
      columns:[{label:'Product', width:W-90},{label:'Qty sold', width:30, align:'right'},{label:'Revenue', width:30, align:'right'},{label:'Profit', width:30, align:'right'}],
      rows: fig.productRows.map(function(p){ return [p.name, String(p.qty), fmtMoney(p.revenue), fmtMoney(p.profit)]; })
    });
    y += 5;
    if(arch && fig.productsOmitted){
      note('Top '+fig.productRows.length+' products by revenue shown. '+fig.productsOmitted+' smaller products are not listed.');
    }
  }

  if(fig.stockRows){
    doc.addPage(); y = pdTop(doc, 16);
    sect(arch ? 'Stock on hand when this report was filed' : 'Current stock', 30);
    y = pdfTable(doc, { x:m, y:y, width:W,
      columns:[{label:'Product', width:W-100},{label:'Cost', width:25,align:'right'},{label:'Sell', width:25,align:'right'},{label:'Qty', width:20,align:'right'},{label:'Stock value', width:30,align:'right'}],
      rows: fig.stockRows.map(function(p){ return [p.name, fmtMoney(p.cost), fmtMoney(p.sell), String(p.qty), fmtMoney((p.cost||0)*(p.qty||0))]; })
    });
    y += 6;
    if(fig.stockTruncated){
      note('The '+fig.stockRows.length+' products with the highest stock value are listed, out of '+(fig.stockCount||'all')+'. The totals below cover every product.');
    }
    need(30);
    var trows = [[tr('Total stock value (at cost)'), fmtMoney(fig.totalStockValue)]];
    if(fig.totalStockRetail != null) trows.push([tr('Total stock value (at selling price)'), fmtMoney(fig.totalStockRetail)]);
    kv(trows, 'Totals', 'Value', trows.map(function(r, i){ return i; }));
  }

  if(arch){
    var pages = doc.getNumberOfPages();
    for(var pg=1; pg<=pages; pg++){
      doc.setPage(pg);
      doc.setFont('helvetica','normal'); doc.setFontSize(6.8); pdSet(doc, 't', pal.muted);
      doc.text(tr(meta.custom ? 'Report for the dates chosen. Figures were gathered from the records in Pesa when this report was generated.' : meta.interim ? 'Interim report. A snapshot of the month so far; the final report replaces it after month end.' : 'Archived monthly report. The saved figures do not change if records are edited later.'), m, 268.4);
      doc.text(tr('Generated by Pesa on')+' '+genText+(meta.generatedBy ? ' '+tr('by')+' '+meta.generatedBy : ''), m, 271.8);
    }
  }
  return doc;
}

/** Build the report PDF for an explicit date range [start, end).
 * rangeLabel is the human-readable heading shown on the report. */
function buildReportPdf(start, end, rangeLabel){
  if(!getJsPDF()) return null;
  return drawReportPdf(computeReportFigures(start, end), rangeLabel, null);
}

/** Legacy helper: build a report for a whole calendar month ("YYYY-MM"). */
function buildMonthlyReportPdf(monthValue){
  var parts = monthValue.split('-');
  var yr = parseInt(parts[0],10), mo = parseInt(parts[1],10);
  var start = new Date(yr, mo-1, 1), end = new Date(yr, mo, 1);
  var label = start.toLocaleDateString('en-GB',{month:'long',year:'numeric'});
  return buildReportPdf(start, end, label);
}

/** Build a report for an arbitrary date range picked from the calendar UI.
 * fromStr/toStr are "YYYY-MM-DD" (inclusive on both ends). */
function buildReportPdfForRange(fromStr, toStr){
  var start = new Date(fromStr+'T00:00:00');
  var end = new Date(toStr+'T00:00:00'); end.setDate(end.getDate()+1); // make end exclusive, inclusive of the picked day
  var label = fmtDateNice(start) + ' to ' + fmtDateNice(new Date(toStr+'T00:00:00'));
  return buildReportPdf(start, end, label);
}


/* ============================== REPORT FOR ANY DATES ==============================
   Pick any start and end date (or a shortcut). Pesa gathers the sales,
   expenses, VAT, payments, wastage and tills for exactly those days, shows a
   preview, and draws the same full report as the monthly archive. */
function reportPresetRange(k){
  var now = new Date(), y = now.getFullYear(), m = now.getMonth(), d = now.getDate(), from, to;
  if(k === 'today'){ from = to = new Date(y,m,d); }
  else if(k === 'yesterday'){ from = to = new Date(y,m,d-1); }
  else if(k === 'week'){ var wd = (now.getDay()+6)%7; from = new Date(y,m,d-wd); to = new Date(y,m,d); }
  else if(k === '7'){ from = new Date(y,m,d-6); to = new Date(y,m,d); }
  else if(k === '30'){ from = new Date(y,m,d-29); to = new Date(y,m,d); }
  else if(k === 'month'){ from = new Date(y,m,1); to = new Date(y,m,d); }
  else if(k === 'lastmonth'){ from = new Date(y,m-1,1); to = new Date(y,m,0); }
  else if(k === 'quarter'){ from = new Date(y, Math.floor(m/3)*3, 1); to = new Date(y,m,d); }
  else if(k === 'year'){ from = new Date(y,0,1); to = new Date(y,m,d); }
  else return null;
  return { from:todayKey(from), to:todayKey(to) };
}
function customReportFigures(fromStr, toStr, scope){
  var start = new Date(fromStr+'T00:00:00'), end = new Date(toStr+'T00:00:00'); end.setDate(end.getDate()+1);
  return computeReportFigures(start, end, { scope:scope||'all', snapshot:true });
}
async function customReportPdf(fromStr, toStr, scope){
  var ready = await ensureJsPDF();
  if(!ready){ toast('Couldn’t load the PDF engine, check your connection and try again'); return null; }
  var fig = customReportFigures(fromStr, toStr, scope);
  var a = new Date(fromStr+'T00:00:00'), b = new Date(toStr+'T00:00:00');
  var label = fromStr === toStr ? fmtDateNice(a) : fmtDateNice(a)+' to '+fmtDateNice(b);
  var br = scope && scope !== 'all' ? State.branches.find(function(x){ return x.id === scope; }) : null;
  return drawReportPdf(fig, label, {
    archived:true, custom:true, interim:false, shopName:(State.company && (State.company.tradingName||State.company.companyName)) || State.settings.shopName || 'Pesa',
    scopeLabel: br ? br.name : 'All branches', generatedAt:new Date().toISOString(), generatedBy: State.session ? State.session.name : '',
    vatNumber: State.company ? State.company.vatNumber : '', periodText: label
  });
}
function openCustomReportSheet(){
  var init = reportPresetRange('month');
  var presets = [['today','Today'],['yesterday','Yesterday'],['week','This week'],['7','Last 7 days'],['30','Last 30 days'],['month','This month'],['lastmonth','Last month'],['quarter','This quarter'],['year','This year']];
  var html = '<div class="sheet-head"><h2>'+tr('Report for any dates')+'</h2></div>' +
    '<div class="banner" style="display:block;">'+tr('Choose the dates. Pesa gathers everything that happened on those days and builds the report.')+'</div>' +
    '<div style="display:flex;flex-wrap:wrap;gap:6px;margin-bottom:10px;">' + presets.map(function(p){ return '<button class="segbtn" type="button" data-rp="'+p[0]+'" style="flex:0 0 auto;">'+tr(p[1])+'</button>'; }).join('') + '</div>' +
    '<div class="field-row"><div class="field"><label>'+tr('From')+'</label><input id="crFrom" type="date" value="'+init.from+'"></div><div class="field"><label>'+tr('To')+'</label><input id="crTo" type="date" value="'+init.to+'"></div></div>' +
    (State.branches.length ? '<div class="field"><label>'+tr('Branch')+'</label><select id="crScope"><option value="all">'+tr('All branches')+'</option>'+State.branches.map(function(b){ return '<option value="'+esc(b.id)+'">'+esc(b.name)+'</option>'; }).join('')+'</select></div>' : '') +
    '<div id="crPreview"></div><div id="crErr"></div>' +
    '<div class="actions"><button class="btn btn-primary" id="crDl" type="button">'+tr('Download report')+'</button><button class="btn btn-ghost" id="crPrint" type="button">'+tr('Print')+'</button></div>';
  var ov = openSheet(html);
  function vals(){ var sc = ov.querySelector('#crScope'); return { from:ov.querySelector('#crFrom').value, to:ov.querySelector('#crTo').value, scope: sc ? sc.value : 'all' }; }
  function valid(v){ if(!v.from || !v.to) return 'Pick a start and end date'; if(v.from > v.to) return 'The start date must be before the end date'; return ''; }
  function paint(){
    var v = vals(), e = valid(v), pv = ov.querySelector('#crPreview');
    ov.querySelector('#crErr').innerHTML = e ? '<div class="banner">'+ICONS.warn+'<span>'+esc(tr(e))+'</span></div>' : '';
    if(e){ pv.innerHTML = ''; return; }
    var f = customReportFigures(v.from, v.to, v.scope);
    pv.innerHTML = '<div class="rowlist">' +
      '<div class="row"><div class="main"><div class="title">'+tr('Sales')+'</div><div class="sub">'+f.salesCount+' '+tr('sales')+'</div></div><div class="trail num">'+fmtMoney(f.revenue)+'</div></div>' +
      '<div class="row"><div class="main"><div class="title">'+tr('Expenses')+'</div></div><div class="trail num">'+fmtMoney(f.expensesTotal)+'</div></div>' +
      '<div class="row"><div class="main"><div class="title">'+tr('Profit after expenses')+'</div></div><div class="trail num"><b>'+fmtMoney(f.netProfit)+'</b></div></div>' +
      (f.vat ? '<div class="row"><div class="main"><div class="title">'+tr('Net VAT')+' ('+f.vat.rate+'%)</div></div><div class="trail num">'+fmtMoney(f.vat.net)+'</div></div>' : '') + '</div>' +
      (f.salesCount === 0 && f.expensesTotal === 0 ? '<div class="banner" style="display:block;margin-top:8px;">'+tr('Nothing was recorded on those dates.')+'</div>' : '');
  }
  ov.querySelectorAll('[data-rp]').forEach(function(b){ b.addEventListener('click', function(){ var r = reportPresetRange(b.getAttribute('data-rp')); ov.querySelector('#crFrom').value = r.from; ov.querySelector('#crTo').value = r.to; paint(); }); });
  ov.querySelector('#crFrom').addEventListener('change', paint); ov.querySelector('#crTo').addEventListener('change', paint);
  var sc = ov.querySelector('#crScope'); if(sc) sc.addEventListener('change', paint);
  ov.querySelector('#crDl').addEventListener('click', async function(){
    var v = vals(); if(valid(v)) return toast(tr(valid(v)));
    var b = ov.querySelector('#crDl'); b.disabled = true; var old = b.textContent; b.textContent = 'Preparing…';
    var doc = await customReportPdf(v.from, v.to, v.scope);
    b.disabled = false; b.textContent = old; if(!doc) return;
    var ok = await saveGeneratedPdf(doc, 'pesa-report-'+v.from+(v.from===v.to?'':'_to_'+v.to)+'.pdf');
    if(ok){ logAudit('report_generated','report', null, 'Report for '+v.from+' to '+v.to+' downloaded'); toast(tr('Report downloaded')); }
  });
  ov.querySelector('#crPrint').addEventListener('click', async function(){
    var v = vals(); if(valid(v)) return toast(tr(valid(v)));
    var doc = await customReportPdf(v.from, v.to, v.scope); if(doc) printPdfDoc(doc);
  });
  paint();
}

/* ============================== MONTHLY REPORT ARCHIVE ==============================
 * Every finished calendar month is filed as an immutable snapshot: the
 * computed figures are stored (not a pointer to live data), so an archived
 * report keeps showing what was true when it was filed even if sales,
 * expenses or products are edited or deleted afterwards. The PDF is rebuilt
 * on demand from the stored figures with drawReportPdf(), the same drawing
 * code as the Dashboard report. There is deliberately no "regenerate" on a
 * saved report: that would silently replace the record. To redo one, the
 * owner deletes it and files the month again. */
var REPORT_SNAPSHOT_VERSION = 1;
var REPORT_CATCHUP_MONTHS = 24;
var _reportsAutoFileDone = false;
function periodKeyOf(d){ return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0'); }
function periodLabelOf(key){ var p = key.split('-'); return new Date(+p[0], +p[1]-1, 1).toLocaleDateString('en-GB',{month:'long',year:'numeric'}); }
function reportId(periodKey, scope, interim){ return (interim ? 'interim-' : 'monthly-') + periodKey + '-' + scope; }
function reportScopeLabel(rec){
  if(rec.branchId === 'all') return tr('Whole shop');
  var b = State.branches.find(function(x){ return x.id === rec.branchId; });
  return (b && b.name) || rec.branchName || tr('Branch');
}
function reportBranchName(scope){
  if(scope === 'all') return 'Whole shop';
  var b = State.branches.find(function(x){ return x.id === scope; });
  return b ? b.name : 'Branch';
}
/** periodKey -> { all:true, branches:{id:true} } for every month with a sale or expense. */
function reportMonthActivity(){
  var act = {};
  function mark(list){
    list.forEach(function(x){
      if(!x.createdAt) return;
      var d = new Date(x.createdAt); if(isNaN(d)) return;
      var k = periodKeyOf(d);
      var a = act[k] || (act[k] = { branches:{} });
      if(x.branchId) a.branches[x.branchId] = true;
    });
  }
  mark(State.sales); mark(State.expenses);
  return act;
}
function reportScopesFor(activity){
  var scopes = ['all'];
  if(State.branches.length >= 1){
    State.branches.forEach(function(b){ if(activity.branches[b.id]) scopes.push(b.id); });
  }
  return scopes;
}
/** Builds the storable record. `now` is the one canonical Date for this filing. */
function buildReportSnapshot(periodKey, scope, interim, now){
  var p = periodKey.split('-'), yr = +p[0], mo = +p[1];
  var start = new Date(yr, mo-1, 1), end = new Date(yr, mo, 1);
  var lastDay = new Date(yr, mo, 0);
  return {
    type: 'monthly',
    version: REPORT_SNAPSHOT_VERSION,
    interim: !!interim,
    periodKey: periodKey,
    label: periodLabelOf(periodKey),
    periodStart: todayKey(start),
    periodEnd: interim ? todayKey(now) : todayKey(lastDay),
    branchId: scope,
    branchName: reportBranchName(scope),
    generatedAt: now.toISOString(),
    generatedBy: State.session ? State.session.name : null,
    generatedById: State.session ? State.session.userId : null,
    shopName: State.settings.shopName || 'Pesa',
    vatNumber: (State.company && State.company.vatNumber) || '',
    figures: computeReportFigures(start, end, { scope: scope, snapshot: true })
  };
}
function fileMonthlyReports(periodKey, scopes, now, opts){
  opts = opts || {};
  var filed = 0;
  scopes.forEach(function(scope){
    var id = reportId(periodKey, scope, false);
    if(State.reports.some(function(r){ return r.id === id; })) return;
    refs.reports.doc(id).set(buildReportSnapshot(periodKey, scope, false, now));
    filed++;
    // the final report supersedes the interim one for the same month and scope
    var iid = reportId(periodKey, scope, true);
    if(State.reports.some(function(r){ return r.id === iid; })) refs.reports.doc(iid).delete();
  });
  return filed;
}
function reportsTombstones(){ return Array.isArray(State.settings.deletedReportIds) ? State.settings.deletedReportIds : []; }
/** Runs once per session for the owner or a manager, after all data has loaded. */
function maybeAutoFileReports(){
  if(_reportsAutoFileDone) return;
  if(!State.session || !isManagerOrOwner()) return;
  var r = State.ready;
  if(!(r.reports && r.sales && r.expenses && r.products && r.customers && r.settings && r.branches && r.wastage && r.tills)) return;
  _reportsAutoFileDone = true;
  try{
    var now = new Date();
    var cur = periodKeyOf(now);
    var act = reportMonthActivity();
    var keys = Object.keys(act).filter(function(k){ return k < cur; }).sort().reverse().slice(0, REPORT_CATCHUP_MONTHS);
    var dead = reportsTombstones();
    var filed = 0;
    keys.forEach(function(k){
      var scopes = reportScopesFor(act[k]).filter(function(s){ return dead.indexOf(reportId(k, s, false)) === -1; });
      filed += fileMonthlyReports(k, scopes, now);
    });
    // interim reports for months that have finished and now have a final report
    State.reports.forEach(function(rec){
      if(!rec.interim || !(rec.periodKey < cur)) return;
      var hasFinal = State.reports.some(function(x){ return x.id === reportId(rec.periodKey, rec.branchId, false); });
      if(hasFinal) refs.reports.doc(rec.id).delete();
    });
    if(filed > 0){
      logAudit('report_filed', 'report', null, 'Filed ' + filed + ' monthly report' + (filed === 1 ? '' : 's') + ' automatically', now);
      toast(filed + ' ' + (filed === 1 ? tr('monthly report filed in Reports') : tr('monthly reports filed in Reports')));
    }
  }catch(e){ /* filing must never break the app */ }
}
/** Manual: file (or refresh) the interim report for the month so far. */
function generateInterimReports(){
  var now = new Date();
  var key = periodKeyOf(now);
  var act = reportMonthActivity()[key];
  if(!act){ toast(tr('No sales or expenses recorded yet this month')); return; }
  var scopes = reportScopesFor(act);
  scopes.forEach(function(scope){ refs.reports.doc(reportId(key, scope, true)).set(buildReportSnapshot(key, scope, true, now)); });
  logAudit('report_generated', 'report', null, 'Generated interim report for ' + periodLabelOf(key), now);
  toast(tr('Report for the month so far saved'));
}
/** Manual: file a finished month that has no report (older than the automatic catch up, or deleted earlier). */
function openFileMonthSheet(){
  var now = new Date(), cur = periodKeyOf(now), act = reportMonthActivity();
  var keys = Object.keys(act).filter(function(k){
    return k < cur && !State.reports.some(function(r){ return r.id === reportId(k, 'all', false); });
  }).sort().reverse();
  var html = '<div class="sheet-head"><h2>'+tr('File a past month')+'</h2></div>';
  if(keys.length === 0){
    html += '<div class="banner">'+tr('Every finished month with sales or expenses already has a report.')+'</div>' +
      '<div class="actions"><button class="btn btn-ghost btn-block" id="fmClose" type="button">'+tr('Done')+'</button></div>';
    var ov0 = openSheet(html, {center:true});
    ov0.querySelector('#fmClose').addEventListener('click', closeModal);
    return;
  }
  html += '<div class="banner">'+tr('The report is built from the records in Pesa today and saved as a permanent copy.')+'</div>' +
    '<div class="field"><label>'+tr('Month')+'</label><select id="fmMonth">' +
      keys.map(function(k){ return '<option value="'+k+'">'+esc(periodLabelOf(k))+'</option>'; }).join('') + '</select></div>' +
    '<div class="actions"><button class="btn btn-primary btn-block" id="fmGo" type="button">'+tr('File report')+'</button></div>';
  var ov = openSheet(html, {center:true});
  ov.querySelector('#fmGo').addEventListener('click', function(){
    var k = ov.querySelector('#fmMonth').value;
    var scopes = reportScopesFor(act[k]);
    var ids = scopes.map(function(s){ return reportId(k, s, false); });
    var left = reportsTombstones().filter(function(id){ return ids.indexOf(id) === -1; });
    if(left.length !== reportsTombstones().length){
      State.settings = Object.assign({}, State.settings, { deletedReportIds: left });
      refs.settings.set(State.settings);
    }
    var n = fileMonthlyReports(k, scopes, new Date());
    logAudit('report_generated', 'report', null, 'Filed monthly report for ' + periodLabelOf(k));
    closeModal();
    toast(n ? tr('Report filed') : tr('That report already exists'));
  });
}

/* ---- records: PDF, CSV, print, share, delete ---- */
function reportFilename(rec, ext){
  var slug = rec.branchId === 'all' ? '' : '-' + String(reportScopeLabel(rec)).toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
  return 'report-' + rec.periodKey + slug + (rec.interim ? '-interim' : '') + '.' + ext;
}
async function reportRecordPdf(rec){
  var ready = await ensureJsPDF();
  var doc = ready ? drawReportPdf(rec.figures, rec.label, {
    archived: true, interim: !!rec.interim, shopName: rec.shopName, scopeLabel: reportScopeLabel(rec),
    generatedAt: rec.generatedAt, generatedBy: rec.generatedBy, vatNumber: rec.vatNumber,
    periodText: fmtDateNice(rec.periodStart+'T00:00:00') + ' to ' + fmtDateNice(rec.periodEnd+'T00:00:00')
  }) : null;
  if(!doc) toast('Couldn’t load the PDF engine, check your connection and try again');
  return doc;
}
async function downloadReportRecord(rec){
  var doc = await reportRecordPdf(rec);
  if(!doc) return;
  var ok = await saveGeneratedPdf(doc, reportFilename(rec, 'pdf'));
  if(ok) toast(tr('Report downloaded'));
}
async function printReportRecord(rec){
  var doc = await reportRecordPdf(rec);
  if(doc) printPdfDoc(doc);
}
function reportCsv(rec){
  var f = rec.figures || {};
  function q(v){ v = csvGuard(v); return /[",\n\r]/.test(v) ? '"' + v.replace(/"/g,'""') + '"' : v; }
  var rows = [];
  function add(){ rows.push(Array.prototype.map.call(arguments, q).join(',')); }
  function m(n){ return (Math.round((Number(n)||0)*100)/100).toFixed(2); }
  add('Pesa monthly report', rec.label + (rec.interim ? ' (interim)' : ''));
  add('Shop', rec.shopName); add('Scope', reportScopeLabel(rec));
  add('Period', rec.periodStart + ' to ' + rec.periodEnd);
  add('Generated', rec.generatedAt); add('Generated by', rec.generatedBy || '');
  add('Amounts in', 'N$'); add();
  add('Summary', 'Amount');
  add('Sales revenue', m(f.revenue)); add('Number of sales', f.salesCount||0);
  add('Cost of goods sold', m(f.cogs)); add('Gross profit', m(f.grossProfit));
  add('Operating expenses', m(f.expensesTotal)); add('Net profit (loss)', m(f.netProfit));
  if(f.totalOwed != null){ add('Outstanding customer credit when filed', m(f.totalOwed)); add('Stock on hand at cost when filed', m(f.totalStockValue)); if(f.totalStockRetail != null){ add('Stock on hand at selling price when filed', m(f.totalStockRetail)); add('Units on hand when filed', String(f.totalStockQty||0)); } }
  add();
  add('Payment method', 'Amount');
  Object.keys(f.payments||{}).forEach(function(k){ add(k, m(f.payments[k])); });
  add();
  if(f.vat){ add('VAT', 'Amount'); add('VAT rate percent', f.vat.rate); add('Output VAT', m(f.vat.output)); add('Input VAT', m(f.vat.input)); add('Net VAT payable (refundable if negative)', m(f.vat.net)); add(); }
  if(f.wastageValue != null){ add('Wastage recorded at cost', m(f.wastageValue)); }
  if(f.tills){ add('Tills closed', f.tills.closedCount); add('Cash counted at till close', m(f.tills.cashCounted)); add('Total till variance', m(f.tills.variance)); }
  add();
  add('Expense category', 'Amount');
  (f.expenseRows||[]).forEach(function(r){ add(r.category, m(r.amount)); });
  add();
  add('Product', 'Quantity sold', 'Revenue', 'Profit');
  (f.productRows||[]).forEach(function(p){ add(p.name, p.qty, m(p.revenue), m(p.profit)); });
  if(f.productsOmitted) add('(' + f.productsOmitted + ' smaller products not listed)');
  return '﻿' + rows.join('\r\n') + '\r\n';
}
async function downloadReportCsv(rec){
  var ok = await saveBlobFile(reportFilename(rec, 'csv'), new Blob([reportCsv(rec)], { type:'text/csv;charset=utf-8' }));
  if(ok) toast(tr('CSV downloaded'));
}
function reportSendCtx(rec){
  var me = senderIdentity(), contactLine = senderContactLine();
  var f = rec.figures || {};
  var scope = reportScopeLabel(rec);
  var title = rec.label + (rec.interim ? ' (interim)' : '') + (rec.branchId === 'all' ? '' : ', ' + scope);
  var net = (f.netProfit < 0 ? 'Net loss ' : 'Net profit ') + fmtMoney(Math.abs(f.netProfit || 0));
  return {
    title: tr('Send report'),
    summaryHtml: esc(title) + ' · <strong class="num">' + esc(fmtMoney(f.revenue || 0)) + '</strong>',
    subject: 'Monthly report ' + title + ' from ' + me.name,
    emailBody: function(name, hasPdf){
      var lines = ['Dear ' + (name || 'Sir/Madam') + ',', ''];
      lines.push((hasPdf ? 'Please find attached' : 'Here is') + ' the monthly report for ' + title + ' from ' + me.name + '.', '');
      lines.push('Sales: ' + fmtMoney(f.revenue || 0), 'Expenses: ' + fmtMoney(f.expensesTotal || 0), net, '');
      if(hasPdf) lines.push('The report is attached as a PDF (' + reportFilename(rec, 'pdf') + ').', '');
      lines.push(contactLine ? 'If you have any questions, please contact us on ' + contactLine + '.' : 'If you have any questions, simply reply to this message.', '');
      lines.push('Kind regards,', me.name);
      return lines.join('\n');
    },
    shortText: function(name){
      return 'Hello' + (name ? ' ' + name : '') + ', monthly report for ' + title + ' from ' + me.name + '. Sales ' + fmtMoney(f.revenue || 0) + ', expenses ' + fmtMoney(f.expensesTotal || 0) + ', ' + net.toLowerCase() + '.' + (contactLine ? ' Questions? ' + contactLine : '');
    },
    buildFile: async function(){
      var doc = await reportRecordPdf(rec);
      if(!doc) return null;
      return new File([doc.output('blob')], reportFilename(rec, 'pdf'), { type:'application/pdf' });
    },
    defaultRecipient: 'manual',
    allowCustomers: false, allowSuppliers: false,
    audit: { action:'report_shared', entityType:'report', entityId: rec.id, label: 'Monthly report ' + title, reference: rec.periodKey }
  };
}
function deleteReportRecord(rec, after){
  if(!isOwner()){ toast(tr('Only the owner can delete reports')); return; }
  var name = rec.label + (rec.interim ? ' (' + tr('Interim') + ')' : '') + ' · ' + reportScopeLabel(rec);
  confirmSheet(tr('Delete') + ' ' + name + '?',
    tr('This removes the stored copy from the Reports list only. Your sales, expenses and stock are not changed. Copies you already downloaded, printed or sent stay with you. A deleted report is not filed again automatically; you can file that month again from File a past month.'),
    tr('Delete'), function(){
      refs.reports.doc(rec.id).delete();
      if(!rec.interim){
        var dead = reportsTombstones().filter(function(id){ return id !== rec.id; }); dead.push(rec.id);
        State.settings = Object.assign({}, State.settings, { deletedReportIds: dead.slice(-500) });
        refs.settings.set(State.settings);
      }
      logAudit('report_deleted', 'report', rec.id, 'Deleted ' + (rec.interim ? 'interim ' : 'monthly ') + 'report ' + rec.label + ' (' + reportScopeLabel(rec) + ', sales ' + fmtMoney((rec.figures||{}).revenue||0) + ')');
      toast(tr('Report deleted'));
      if(after) after();
    }, true, true);
}
function reportRunAction(act, rec){
  if(act === 'view') openReportDetailSheet(rec);
  else if(act === 'share') openSendSheet(reportSendCtx(rec));
  else if(act === 'download') downloadReportRecord(rec);
  else if(act === 'print') printReportRecord(rec);
  else if(act === 'csv') downloadReportCsv(rec);
  else if(act === 'delete') deleteReportRecord(rec);
}

/* ---- page ---- */
function repSortedList(){
  return State.reports.slice().sort(function(a,b){
    if(a.periodKey !== b.periodKey) return a.periodKey < b.periodKey ? 1 : -1;
    var sa = a.branchId === 'all' ? 0 : 1, sb = b.branchId === 'all' ? 0 : 1;
    if(sa !== sb) return sa - sb;
    if(!!a.interim !== !!b.interim) return a.interim ? 1 : -1;
    return String(reportScopeLabel(a)).localeCompare(String(reportScopeLabel(b)));
  });
}
function repFilteredList(){
  var f = State.repFilter || {};
  return repSortedList().filter(function(r){
    if(f.year && f.year !== 'all' && String(r.periodKey).slice(0,4) !== f.year) return false;
    if(f.scope && f.scope !== 'any' && r.branchId !== f.scope) return false;
    return true;
  });
}
function repProfitHtml(fig){
  var n = (fig && fig.netProfit) || 0;
  return '<span class="num" style="color:var(--' + (n < 0 ? 'danger' : 'success') + ');">' + esc((n < 0 ? tr('Loss') : tr('Profit')) + ' ' + fmtMoney(Math.abs(n))) + '</span>';
}
function repRowHtml(r){
  var fig = r.figures || {};
  var canDelete = isOwner();
  return '<div class="inv-card" data-rep="'+esc(r.id)+'">' +
    '<div class="inv-top" data-rep-act="view" role="button" tabindex="0">' +
      '<div class="main"><div class="title"><span>'+esc(r.label)+'</span><span class="chip inv-type">'+esc(r.interim ? tr('Interim') : tr('Final'))+'</span></div>' +
      '<div class="sub">'+esc(reportScopeLabel(r)+' · '+tr('Generated')+' '+fmtDateNice(r.generatedAt))+'</div>' +
      '<div class="sub rep-figs">'+esc(tr('Expenses')+' '+fmtMoney(fig.expensesTotal||0))+' · '+repProfitHtml(fig)+'</div></div>' +
      '<div class="rep-sales"><div class="amt num">'+esc(fmtMoney(fig.revenue||0))+'</div><div class="rep-cap">'+esc(tr('Sales'))+'</div></div>' +
    '</div>' +
    '<div class="inv-actions">' +
      '<button type="button" data-rep-act="share">'+INV_ICO.share+'<span>'+tr('Share')+'</span></button>' +
      '<button type="button" data-rep-act="download">'+INV_ICO.download+'<span>PDF</span></button>' +
      '<button type="button" data-rep-act="print">'+INV_ICO.print+'<span>'+tr('Print')+'</span></button>' +
      (canDelete ? '<button type="button" class="danger" data-rep-act="delete">'+INV_ICO.trash+'<span>'+tr('Delete')+'</span></button>' : '') +
    '</div>' +
  '</div>';
}
function repListHtml(){
  var list = repFilteredList();
  if(list.length === 0) return '<div class="empty">'+ICONS.search+'<div class="t">'+tr('No matches')+'</div><div class="s">'+tr('Try a different year or branch.')+'</div></div>';
  var html = '', year = null;
  list.forEach(function(r){
    var y = String(r.periodKey).slice(0,4);
    if(y !== year){ if(year !== null) html += '</div>'; year = y; html += '<div class="section-title">'+esc(y)+'</div><div class="rowlist">'; }
    html += repRowHtml(r);
  });
  return html + '</div>';
}
function reportsHelpHtml(){
  return '<div class="rep-note">'+tr('A report for each finished month is filed here automatically when the owner or a manager opens Pesa. Months with no sales or expenses are skipped, and only the latest 24 months are filed at first. Pesa cannot rebuild records from before it was used. Each saved report keeps its figures even if sales or products are changed later. Customer credit and stock are counted as at the day the report was filed.')+'</div>';
}
function renderReportsPage(){
  if(!State.ready.reports) return '<div class="empty">Loading…</div>';
  var f = State.repFilter || (State.repFilter = { year:'all', scope:'any' });
  var all = State.reports;
  var html = '<div class="rep-tools"><button class="btn btn-primary" id="repGenBtn" type="button">'+tr('Generate this month so far')+'</button>' +
    '<button class="btn btn-ghost" id="repFileBtn" type="button">'+tr('File a past month')+'</button>' +
    '<button class="btn btn-accent" id="repCustomBtn" type="button">'+tr('Report for any dates')+'</button></div>';
  if(all.length === 0){
    html += '<div class="empty">'+ICONS.chartbar.replace('width="18" height="18"','width="26" height="26"')+'<div class="t">'+tr('No reports filed yet')+'</div>' +
      '<div class="s">'+tr('Monthly reports are saved here for your records, ready to download, print or share. The first ones are filed automatically once a month has finished and had sales or expenses.')+'</div></div>' + reportsHelpHtml();
    return html;
  }
  var years = [], scopes = {};
  all.forEach(function(r){ var y = String(r.periodKey).slice(0,4); if(years.indexOf(y) === -1) years.push(y); scopes[r.branchId] = reportScopeLabel(r); });
  years.sort().reverse();
  var scopeIds = Object.keys(scopes);
  html += '<div class="rep-filters"><select id="repYearSel" aria-label="'+esc(tr('Year'))+'"><option value="all">'+esc(tr('All years'))+'</option>' +
    years.map(function(y){ return '<option value="'+y+'"'+(f.year===y?' selected':'')+'>'+y+'</option>'; }).join('') + '</select>' +
    (scopeIds.length > 1 ? '<select id="repScopeSel" aria-label="'+esc(tr('Branch'))+'"><option value="any">'+esc(tr('All branches'))+'</option>' +
      scopeIds.map(function(id){ return '<option value="'+esc(id)+'"'+(f.scope===id?' selected':'')+'>'+esc(scopes[id])+'</option>'; }).join('') + '</select>' : '') +
    '</div><div id="repListWrap">' + repListHtml() + '</div>' + reportsHelpHtml();
  return html;
}
function wireReportsPage(content){
  var g = content.querySelector('#repGenBtn'); if(g) g.addEventListener('click', generateInterimReports);
  var fb = content.querySelector('#repFileBtn'); if(fb) fb.addEventListener('click', openFileMonthSheet);
  var cb = content.querySelector('#repCustomBtn'); if(cb) cb.addEventListener('click', openCustomReportSheet);
  var wrap = content.querySelector('#repListWrap');
  function wireList(){
    if(!wrap) return;
    wrap.querySelectorAll('[data-rep-act]').forEach(function(el){
      function go(){
        var card = el.closest('[data-rep]');
        var rec = card && State.reports.find(function(r){ return r.id === card.getAttribute('data-rep'); });
        if(rec) reportRunAction(el.getAttribute('data-rep-act'), rec);
      }
      el.addEventListener('click', go);
      if(el.getAttribute('role') === 'button') el.addEventListener('keydown', function(e){ if(e.key === 'Enter' || e.key === ' '){ e.preventDefault(); go(); } });
    });
  }
  function refreshList(){ if(wrap){ wrap.innerHTML = repListHtml(); wireList(); } }
  wireList();
  var ys = content.querySelector('#repYearSel'); if(ys) ys.addEventListener('change', function(){ State.repFilter.year = ys.value; refreshList(); });
  var ss = content.querySelector('#repScopeSel'); if(ss) ss.addEventListener('change', function(){ State.repFilter.scope = ss.value; refreshList(); });
}
function openReportDetailSheet(rec){
  var f = rec.figures || {};
  function row(l, v, cls){ return '<div class="tillrow'+(cls?' '+cls:'')+'"><span class="l">'+esc(l)+'</span><span class="v num">'+esc(v)+'</span></div>'; }
  var pn = { cash:tr('Cash'), card:tr('Card'), wallet:tr('Mobile wallet'), credit:tr('Credit') };
  var net = f.netProfit || 0;
  var html = '<div class="sheet-head"><h2>'+esc(rec.label)+'</h2><span class="chip inv-type">'+esc(rec.interim ? tr('Interim') : tr('Final'))+'</span></div>' +
    '<div class="inv-meta">' +
      '<div><div class="l">'+tr('Scope')+'</div><div>'+esc(reportScopeLabel(rec))+'</div></div>' +
      '<div><div class="l">'+tr('Period')+'</div><div>'+esc(fmtDateNice(rec.periodStart+'T00:00:00')+' to '+fmtDateNice(rec.periodEnd+'T00:00:00'))+'</div></div>' +
      '<div><div class="l">'+tr('Generated')+'</div><div>'+esc(fmtDateTime(rec.generatedAt))+'</div></div>' +
      '<div><div class="l">'+tr('Generated by')+'</div><div>'+esc(rec.generatedBy || '')+'</div></div>' +
    '</div>' +
    (rec.interim ? '<div class="banner">'+tr('Figures so far. The final report is filed automatically after the month ends.')+'</div>' : '') +
    '<div class="tillcard">' +
      row(tr('Sales revenue'), fmtMoney(f.revenue||0)) + row(tr('Number of sales'), String(f.salesCount||0)) +
      row(tr('Cost of goods sold'), fmtMoney(f.cogs||0)) + row(tr('Gross profit'), fmtMoney(f.grossProfit||0)) +
      row(tr('Operating expenses'), fmtMoney(f.expensesTotal||0)) +
      row(net >= 0 ? tr('Net profit') : tr('Net loss'), fmtMoney(Math.abs(net)), 'grand') +
    '</div>' +
    '<div class="section-title" style="margin-top:0;">'+tr('Payment methods')+'</div><div class="tillcard">' +
      Object.keys(f.payments||{}).map(function(k){ return row(pn[k]||k, fmtMoney(f.payments[k])); }).join('') + '</div>' +
    (f.vat ? '<div class="section-title" style="margin-top:0;">'+tr('VAT (working figures)')+'</div><div class="tillcard">' +
      row(tr('Output VAT'), fmtMoney(f.vat.output)) + row(tr('Input VAT'), fmtMoney(f.vat.input)) +
      row(f.vat.net >= 0 ? tr('Net VAT payable') : tr('Net VAT refundable'), fmtMoney(Math.abs(f.vat.net)), 'grand') + '</div>' : '') +
    ((f.expenseRows||[]).length ? '<div class="section-title" style="margin-top:0;">'+tr('Expenses by category')+'</div><div class="tillcard">' +
      f.expenseRows.map(function(r){ return row(r.category, fmtMoney(r.amount)); }).join('') + '</div>' : '') +
    ((f.productRows||[]).length ? '<div class="section-title" style="margin-top:0;">'+tr('Top products')+'</div><div class="tillcard">' +
      f.productRows.slice(0,8).map(function(p){ return row(p.name+' × '+p.qty, fmtMoney(p.revenue)); }).join('') +
      (f.productRows.length > 8 ? '<div style="font-size:11.5px;color:var(--text-muted);padding-top:6px;">'+esc(tr('The PDF lists them all.'))+'</div>' : '') + '</div>' : '') +
    ((f.wastageValue != null || f.tills || f.totalOwed != null) ? '<div class="section-title" style="margin-top:0;">'+tr('Other records')+'</div><div class="tillcard">' +
      (f.wastageValue != null ? row(tr('Wastage at cost'), fmtMoney(f.wastageValue)) : '') +
      (f.tills ? row(tr('Tills closed'), String(f.tills.closedCount)) + row(tr('Total till variance'), (f.tills.variance<0?'-':'')+fmtMoney(Math.abs(f.tills.variance))) : '') +
      (f.totalOwed != null ? row(tr('Customer credit when filed'), fmtMoney(f.totalOwed)) + row(tr('Stock at cost when filed'), fmtMoney(f.totalStockValue)) +
        (f.totalStockRetail != null ? row(tr('Stock at selling price when filed'), fmtMoney(f.totalStockRetail)) + row(tr('Products / units on hand'), (f.stockCount||0).toLocaleString()+' / '+(f.totalStockQty||0).toLocaleString()) : '') : '') + '</div>' : '') +
    '<div class="inv-card" style="margin-top:14px;"><div class="inv-actions">' +
      '<button type="button" data-d="share">'+INV_ICO.share+'<span>'+tr('Share')+'</span></button>' +
      '<button type="button" data-d="download">'+INV_ICO.download+'<span>PDF</span></button>' +
      '<button type="button" data-d="csv">'+INV_ICO.download+'<span>CSV</span></button>' +
      '<button type="button" data-d="print">'+INV_ICO.print+'<span>'+tr('Print')+'</span></button>' +
      (isOwner() ? '<button type="button" class="danger" data-d="delete">'+INV_ICO.trash+'<span>'+tr('Delete')+'</span></button>' : '') +
    '</div></div>';
  var ov = openSheet(html);
  ov.querySelectorAll('[data-d]').forEach(function(b){
    b.addEventListener('click', function(){
      var a = b.getAttribute('data-d');
      if(a === 'delete') deleteReportRecord(rec, function(){ closeModal(); });
      else reportRunAction(a, rec);
    });
  });
}

/* ============================== TAB: CREDIT ============================== */
function renderCredit(){
  if(!State.ready.customers) return '<div class="empty">Loading…</div>';
  var totalOwed = State.customers.reduce(function(s,c){ return s+(c.balance||0); }, 0);
  var html = '<div class="stats" style="margin-bottom:14px;"><div class="stat wide"><div class="lbl">Total owed to you</div><div class="v num" style="color:var(--danger)">'+fmtMoney(totalOwed)+'</div></div></div>' +
    '<div class="actions" style="margin-bottom:14px;"><button class="btn btn-primary btn-block" id="newCreditSaleBtn" type="button">+ '+tr('New credit sale')+' · '+tr('products and amount owed')+'</button></div>';
  if(State.customers.length === 0){
    html += '<div class="empty">'+ICONS.people+'<div class="t">'+tr('No customers yet')+'</div><div class="s">'+tr('Add regulars who buy on credit.')+'</div></div>';
    return html;
  }
  html += renderSelectToolbar('credit');
  var selC = selState('credit');
  html += '<div class="rowlist">' + State.customers.map(function(c){
    var bal = c.balance||0;
    var checked = !!selC.ids[c.id];
    return '<div class="row'+(checked?' checked':'')+'" data-customer="'+c.id+'" data-select-id="'+c.id+'">' +
      (selC.active ? rowCheckHtml('credit', c.id) : '') +
      '<div class="avatar">'+esc(initials(c.name))+'</div>' +
      '<div class="main">' +
        '<div class="title">'+esc(c.name)+'</div>' +
        '<div class="sub">'+esc([c.phone, c.email].filter(Boolean).join(' · ') || 'No phone number')+'</div>' +
      '</div>' +
      '<div class="trail">' +
        '<div class="amt num '+(bal>0?'owe':'ok')+'">'+fmtMoney(bal)+'</div>' +
        '<div class="note">'+(bal>0?'owing':'settled')+'</div>' +
      '</div>' +
    '</div>';
  }).join('') + '</div>';
  html += renderSelectBar('credit');
  return html;
}

/* ============================== CREDIT SALE (products + customer details) ==============================
   One form to record everything about a credit sale: who the customer is
   (existing or new, with full details), what they took (picked from Stock —
   price and total are filled in automatically, or typed in for items that
   aren't in Stock), any older balance they already owed, and any part paid
   now. It updates stock, records the sale, and writes the customer ledger. */
function openCreditSaleSheet(preCustomer){
  var lines = [{ productId:'', name:'', qty:1, price:0 }];
  var customers = State.customers.slice();
  var startNew = !preCustomer && customers.length === 0;
  function prodOptions(sel){
    return '<option value="">'+tr('Choose product from stock…')+'</option>' +
      State.products.map(function(p){
        var left = p.stockQty == null ? '' : ' · '+p.stockQty+' '+tr('left');
        return '<option value="'+esc(p.id)+'" '+(sel===p.id?'selected':'')+'>'+esc(p.name)+', '+fmtMoney(p.sellPrice||0)+esc(left)+'</option>';
      }).join('') +
      '<option value="custom" '+(sel==='custom'?'selected':'')+'>'+tr('Other item (type name and price)')+'</option>';
  }
  var html = '<div class="sheet-head"><h2>'+tr('New credit sale')+'</h2></div>' +
    '<div class="section-title" style="margin-top:0;">'+tr('Customer')+'</div>' +
    '<div class="field"><select id="csCust">' +
      customers.map(function(c){ return '<option value="'+esc(c.id)+'" '+((preCustomer&&preCustomer.id===c.id)?'selected':'')+'>'+esc(c.name)+', '+tr('owes')+' '+fmtMoney(c.balance||0)+'</option>'; }).join('') +
      '<option value="__new__" '+(startNew?'selected':'')+'>+ '+tr('New customer')+'</option>' +
    '</select></div>' +
    '<div id="csNewBox" style="display:'+(startNew?'block':'none')+';">' +
      '<div class="field"><label>'+tr('Name')+' *</label><input id="csName" placeholder="Full name"></div>' +
      '<div class="field-row"><div class="field"><label>'+tr('Phone (optional)')+'</label><input id="csPhone" type="tel" inputmode="tel" placeholder="081 234 5678"></div>' +
      '<div class="field"><label>'+tr('Email (optional)')+'</label><input id="csEmail" type="email" placeholder="name@example.com"></div></div>' +
      '<div class="field"><label>'+tr('Address (optional)')+'</label><input id="csAddress" placeholder="Street, suburb, town"></div>' +
      '<div class="field"><label>'+tr('ID number / reference (optional)')+'</label><input id="csIdNo" placeholder="e.g. ID number or employer"></div>' +
    '</div>' +
    '<div class="section-title">'+tr('Products taken')+'</div>' +
    '<div id="csLines"></div>' +
    '<button class="btn btn-ghost btn-block" id="csAddLine" type="button">+ '+tr('Add another item')+'</button>' +
    '<div class="section-title">'+tr('Amounts')+'</div>' +
    '<div class="field-row">' +
      '<div class="field"><label>'+tr('Older balance already owed (optional)')+'</label><input id="csOlder" type="number" inputmode="decimal" step="0.01" placeholder="0.00"></div>' +
      '<div class="field"><label>'+tr('Paid now (optional)')+'</label><input id="csPaid" type="number" inputmode="decimal" step="0.01" placeholder="0.00"></div>' +
    '</div>' +
    '<div class="field"><label>'+tr('Note (optional)')+'</label><input id="csNote" placeholder="e.g. Pay on the 25th"></div>' +
    '<div class="cs-sum" id="csSum"></div>' +
    '<div id="csError"></div>' +
    '<div class="actions"><button class="btn btn-primary btn-block" id="csSave" type="button">'+tr('Save credit sale')+'</button></div>';
  var ov = openSheet(html);
  var $ = function(q){ return ov.querySelector(q); };

  function lineTotal(l){ return (parseFloat(l.qty)||0) * (parseFloat(l.price)||0); }
  function itemsTotal(){ return lines.reduce(function(s,l){ return s + lineTotal(l); }, 0); }
  function currentCustomer(){ var v = $('#csCust').value; return v === '__new__' ? null : (State.customers.find(function(c){ return c.id === v; }) || null); }
  function updateSummary(){
    var items = itemsTotal(), older = parseFloat($('#csOlder').value)||0, paid = parseFloat($('#csPaid').value)||0;
    var c = currentCustomer(), before = c ? (c.balance||0) : 0;
    var after = before + items + older - paid;
    $('#csSum').innerHTML =
      '<div class="r"><span>'+tr('Products total')+'</span><span class="num">'+fmtMoney(items)+'</span></div>' +
      (older ? '<div class="r"><span>'+tr('Older balance')+'</span><span class="num">'+fmtMoney(older)+'</span></div>' : '') +
      (paid ? '<div class="r"><span>'+tr('Paid now')+'</span><span class="num">−'+fmtMoney(paid)+'</span></div>' : '') +
      (before ? '<div class="r"><span>'+tr('Already owed before')+'</span><span class="num">'+fmtMoney(before)+'</span></div>' : '') +
      '<div class="r big"><span>'+tr('Total they owe you')+'</span><span class="num" style="color:'+(after>0?'var(--danger)':'var(--success)')+'">'+fmtMoney(after)+'</span></div>';
    lines.forEach(function(l, i){ var el = ov.querySelector('[data-tot="'+i+'"]'); if(el) el.textContent = fmtMoney(lineTotal(l)); });
  }
  function renderLines(){
    $('#csLines').innerHTML = lines.map(function(l, i){
      var custom = l.productId === 'custom';
      return '<div class="cs-line" data-i="'+i+'">' +
        (lines.length > 1 ? '<button class="cs-x" type="button" data-rm="'+i+'" aria-label="Remove">×</button>' : '') +
        '<div class="field"><label>'+tr('Product')+'</label><select data-prod="'+i+'">'+prodOptions(l.productId)+'</select></div>' +
        (custom ? '<div class="field"><label>'+tr('Item name')+'</label><input data-name="'+i+'" placeholder="e.g. Airtime" value="'+esc(l.name)+'"></div>' : '') +
        '<div class="field-row">' +
          '<div class="field"><label>'+tr('Quantity')+'</label><input data-qty="'+i+'" type="number" inputmode="decimal" min="0" step="any" value="'+esc(l.qty)+'"></div>' +
          '<div class="field"><label>'+tr('Price each')+'</label><input data-price="'+i+'" type="number" inputmode="decimal" min="0" step="0.01" value="'+esc(l.price)+'"></div>' +
        '</div>' +
        '<div class="cs-tot num" data-tot="'+i+'">'+fmtMoney(lineTotal(l))+'</div>' +
      '</div>';
    }).join('');
    ov.querySelectorAll('[data-prod]').forEach(function(sel){
      sel.addEventListener('change', function(){
        var i = +sel.getAttribute('data-prod'), v = sel.value, l = lines[i];
        l.productId = v;
        if(v && v !== 'custom'){
          var p = State.products.find(function(x){ return x.id === v; });
          if(p){ l.name = p.name; l.price = p.sellPrice || 0; if(!(parseFloat(l.qty) > 0)) l.qty = 1; }   // price filled in automatically from Stock
        } else if(v === 'custom'){ l.name = ''; l.price = 0; }
        renderLines(); updateSummary();
      });
    });
    ov.querySelectorAll('[data-qty]').forEach(function(el){ el.addEventListener('input', function(){ lines[+el.getAttribute('data-qty')].qty = el.value; updateSummary(); }); });
    ov.querySelectorAll('[data-price]').forEach(function(el){ el.addEventListener('input', function(){ lines[+el.getAttribute('data-price')].price = el.value; updateSummary(); }); });
    ov.querySelectorAll('[data-name]').forEach(function(el){ el.addEventListener('input', function(){ lines[+el.getAttribute('data-name')].name = el.value; }); });
    ov.querySelectorAll('[data-rm]').forEach(function(el){ el.addEventListener('click', function(){ lines.splice(+el.getAttribute('data-rm'), 1); renderLines(); updateSummary(); }); });
  }
  renderLines(); updateSummary();
  $('#csAddLine').addEventListener('click', function(){ lines.push({ productId:'', name:'', qty:1, price:0 }); renderLines(); updateSummary(); });
  $('#csCust').addEventListener('change', function(){ $('#csNewBox').style.display = $('#csCust').value === '__new__' ? 'block' : 'none'; updateSummary(); });
  $('#csOlder').addEventListener('input', updateSummary);
  $('#csPaid').addEventListener('input', updateSummary);

  var csOverride = false;
  $('#csSave').addEventListener('click', function(){
    var err = $('#csError');
    function fail(m){ err.innerHTML = '<div class="banner">'+ICONS.warn+'<span>'+esc(m)+'</span></div>'; }
    err.innerHTML = '';
    var isNew = $('#csCust').value === '__new__';
    var cust = currentCustomer();
    var custData = null;
    if(isNew){
      var name = $('#csName').value.trim(), email = $('#csEmail').value.trim();
      if(!name) return fail(tr('Enter the customer’s name.'));
      if(email && !looksLikeEmail(email)) return fail(tr('Enter a valid email address'));
      custData = { name:name, phone:$('#csPhone').value.trim(), email:email, address:$('#csAddress').value.trim(), idNumber:$('#csIdNo').value.trim(), balance:0, createdAt:new Date().toISOString() };
    } else if(!cust){ return fail(tr('Choose a customer.')); }
    // validate + collect the product lines
    var items = [], older = parseFloat($('#csOlder').value)||0, paid = parseFloat($('#csPaid').value)||0;
    for(var i=0;i<lines.length;i++){
      var l = lines[i];
      var untouched = !l.productId && !(parseFloat(l.price) > 0) && !l.name;
      if(untouched) continue;
      if(!l.productId) return fail(tr('Choose a product for every line, or remove the empty line.'));
      var qty = parseFloat(l.qty)||0, price = parseFloat(l.price)||0;
      if(qty <= 0) return fail(tr('Enter a quantity for every product.'));
      if(l.productId === 'custom'){
        if(!String(l.name).trim()) return fail(tr('Type a name for the “Other item”.'));
        items.push({ productId:null, name:String(l.name).trim(), qty:qty, unitPrice:price, cost:0, lineTotal:qty*price });
      } else {
        var p = State.products.find(function(x){ return x.id === l.productId; });
        if(!p) return fail(tr('That product is no longer in Stock.'));
        if(p.stockQty != null && qty > p.stockQty) return fail(tr('Only')+' '+p.stockQty+' '+tr('of')+' '+p.name+' '+tr('in stock.'));
        items.push({ productId:p.id, name:p.name, qty:qty, unitPrice:price, cost:p.costPrice||0, lineTotal:qty*price });
      }
    }
    var total = items.reduce(function(s,it){ return s + it.lineTotal; }, 0);
    if(!items.length && !(older > 0)) return fail(tr('Add at least one product, or enter an older balance.'));
    if(paid < 0 || older < 0) return fail(tr('Amounts cannot be negative.'));
    var note = $('#csNote').value.trim();
    var now = new Date().toISOString();
    if(!isNew && !csOverride && cust && overCreditLimit(cust, total + older - paid)){
      confirmOverLimit(cust, total + older - paid, function(){ csOverride = true; $('#csSave').click(); });
      return;
    }
    csOverride = false;

    // 1) the customer (create if new)
    var custRef, balance;
    if(isNew){ custRef = refs.customers.doc(); balance = 0; }
    else { custRef = refs.customers.doc(cust.id); balance = cust.balance || 0; }
    var custName = isNew ? custData.name : cust.name;
    var saved = isNew ? Object.assign({ id:custRef.id }, custData) : cust;
    // 2) the sale (so Dashboard, Reports and Till include it)
    var sale = null;
    if(items.length){
      var cost = items.reduce(function(s,it){ return s + (it.cost||0)*it.qty; }, 0);
      sale = { items:items, total:total, cost:cost, profit:total-cost, paymentMethod:'credit', customerId:custRef.id, customerName:custName,
        tillId: State.till.current ? State.till.current.id : null, cashierName: State.session ? State.session.name : null,
        branchId: (State.settings.currentBranchId && State.settings.currentBranchId!=='all') ? State.settings.currentBranchId : null, stock: stockSnapshot(), createdAt:now };
      var creditAddP = refs.sales.add(sale);
      Fiscal.track(sale, creditAddP);
      creditAddP.then(function(ref){ logAudit('create','sale', ref&&ref.id, 'Credit sale to '+custName+', '+items.length+' item(s), '+fmtMoney(total)); });
      var stockChanges = [];
      items.forEach(function(it){
        if(!it.productId) return;
        var p = State.products.find(function(x){ return x.id === it.productId; });
        if(p && p.stockQty != null){ var nq = Math.max(0, p.stockQty - it.qty); refs.products.doc(p.id).update({ stockQty:nq }); stockChanges.push({ product:p, newQty:nq }); }
      });
      checkLowStockAlerts(stockChanges);
    }
    // 3) the customer's balance and ledger
    var led = custRef.collection('ledger');
    if(items.length){ balance += total; led.add({ type:'charge', amount:total, note:note || 'Sale on credit', items:items.map(function(it){ return { name:it.name, qty:it.qty, unitPrice:it.unitPrice, lineTotal:it.lineTotal }; }), createdAt:now, balanceAfter:balance }); }
    if(older > 0){ balance += older; led.add({ type:'charge', amount:older, note:'Previous balance', createdAt:new Date(Date.now()+1).toISOString(), balanceAfter:balance }); }
    if(paid > 0){ balance -= paid; led.add({ type:'payment', amount:paid, note:'Paid at time of sale', createdAt:new Date(Date.now()+2).toISOString(), balanceAfter:balance }); }
    if(isNew) custRef.set(Object.assign({}, custData, { balance:balance }));
    else custRef.update({ balance:balance });
    saved = Object.assign({}, saved, { balance:balance });
    try{ logAudit('create','credit', custRef.id, custName+' owes '+fmtMoney(balance)); }catch(e){}
    closeModal();
    toast(tr('Credit sale saved')+', '+custName+' '+tr('owes')+' '+fmtMoney(balance));
    if(sale) offerSaleReceipt(sale, saved);
  });
}

function openCustomerSheet(customer){
  var isEdit = !!customer;
  var html =
    '<div class="sheet-head"><h2>'+(isEdit?tr('Edit customer'):tr('Add customer'))+'</h2></div>' +
    '<div class="field"><label>'+tr('Name')+'</label><input id="cfName" placeholder="Full name" value="'+esc(customer?customer.name:'')+'"></div>' +
    '<div class="field"><label>'+tr('Phone (optional)')+'</label><input id="cfPhone" type="tel" inputmode="tel" placeholder="081 234 5678" value="'+esc(customer?customer.phone||'':'')+'"></div>' +
    '<div class="field"><label>'+tr('Email (optional)')+'</label><input id="cfEmail" type="email" inputmode="email" autocomplete="off" placeholder="name@example.com" value="'+esc(customer?customer.email||'':'')+'"></div>' +
    '<div class="field"><label>'+tr('Address (optional)')+'</label><input id="cfAddress" placeholder="Street, suburb, town" value="'+esc(customer?customer.address||'':'')+'"></div>' +
    '<div class="field"><label>'+tr('ID number / reference (optional)')+'</label><input id="cfIdNo" placeholder="e.g. ID number or employer" value="'+esc(customer?customer.idNumber||'':'')+'"></div>' +
    '<div class="field"><label>'+tr('Notes (optional)')+'</label><input id="cfNotes" placeholder="Anything worth remembering" value="'+esc(customer?customer.notes||'':'')+'"></div>' +
    '<div class="field"><label>'+tr('Credit limit (optional)')+'</label><input id="cfLimit" type="number" inputmode="decimal" step="0.01" placeholder="0.00 = no limit" value="'+(customer&&customer.creditLimit?customer.creditLimit:'')+'"></div>' +
    (isEdit ? '<div class="field"><label>'+tr('Balance owed')+'</label><input id="cfBalance" type="number" inputmode="decimal" step="0.01" value="'+(customer.balance||0)+'"></div>' : '') +
    '<div class="actions">' +
      (isEdit ? '<button class="btn btn-danger" id="cfDelete">'+tr('Delete')+'</button>' : '') +
      '<button class="btn btn-primary btn-block" id="cfSave">'+(isEdit?'Save changes':tr('Add customer'))+'</button>' +
    '</div>';
  var ov = openSheet(html);
  ov.querySelector('#cfSave').addEventListener('click', function(){
    var name = ov.querySelector('#cfName').value.trim();
    if(!name){ toast('Enter a name'); return; }
    var email = ov.querySelector('#cfEmail').value.trim();
    if(email && !looksLikeEmail(email)){ toast(tr('Enter a valid email address')); ov.querySelector('#cfEmail').focus(); return; }
    if(isEdit){
      refs.customers.doc(customer.id).update({ name:name, phone: ov.querySelector('#cfPhone').value.trim(), email: email, address: ov.querySelector('#cfAddress').value.trim(), idNumber: ov.querySelector('#cfIdNo').value.trim(), notes: ov.querySelector('#cfNotes').value.trim(), creditLimit: parseFloat(ov.querySelector('#cfLimit').value)||0, balance: parseFloat(ov.querySelector('#cfBalance').value)||0 });
      toast('Customer updated');
    } else {
      refs.customers.doc().set({ name:name, phone: ov.querySelector('#cfPhone').value.trim(), email: email, address: ov.querySelector('#cfAddress').value.trim(), idNumber: ov.querySelector('#cfIdNo').value.trim(), notes: ov.querySelector('#cfNotes').value.trim(), creditLimit: parseFloat(ov.querySelector('#cfLimit').value)||0, balance:0, createdAt:new Date().toISOString() });
      toast('Customer added');
    }
    closeModal();
  });
  if(isEdit){
    ov.querySelector('#cfDelete').addEventListener('click', function(){
      confirmSheet('Delete '+customer.name+'?', 'This removes the customer record. Do this only once their balance is settled.', 'Delete', function(){
        withRemoval(customer.name, function(){ refs.customers.doc(customer.id).delete();
        toast('Customer deleted'); });
      }, true, true);
    });
  }
}

function openLedgerSheet(customer){
  var html = '<div class="sheet-head"><h2>'+esc(customer.name)+'</h2><button class="icon-btn" id="ledgerEditBtn" style="background:var(--surface-2);border-color:var(--border);color:var(--text);">'+ICONS.edit+'</button></div>' +
    '<div class="stats" style="margin-bottom:14px;">' +
      '<div class="stat wide"><div class="lbl">'+tr('Balance owed')+'</div><div class="v num" style="color:'+((customer.balance||0)>0?'var(--danger)':'var(--success)')+'">'+fmtMoney(customer.balance||0)+'</div></div>' +
    '</div>' +
    ((customer.phone||customer.email||customer.address||customer.idNumber||customer.notes) ? '<div class="banner" style="display:block;line-height:1.6;">' + [customer.phone, customer.email, customer.address, customer.idNumber ? tr('ID / ref')+': '+customer.idNumber : '', customer.notes].filter(Boolean).map(esc).join('<br>') + '</div>' : '') +
    '<div class="actions" style="margin:0 0 12px;"><button class="btn btn-primary btn-block" id="ledgerCreditSaleBtn" type="button">+ '+tr('New credit sale')+'</button></div>' +
    '<div class="section-title" style="margin-top:0;">'+tr('Recent activity')+'</div>' +
    '<div id="ledgerList"><div class="empty" style="padding:20px 0;">Loading…</div></div>' +
    '<div class="actions"><button class="btn btn-ghost" id="invoiceCustomerBtn">'+tr('Invoice')+'</button><button class="btn btn-accent" style="flex:2;" id="recordPaymentBtn">'+tr('Record payment')+'</button></div>' +
    '<div class="actions" style="margin-top:10px;"><button class="btn btn-ghost btn-block" id="statementBtn" type="button">'+tr('Statement of account')+'</button></div>' +
    ((customer.balance||0) > 0 ? '<div class="actions" style="margin-top:10px;"><button class="btn btn-ghost btn-block" id="sendReminderBtn" type="button">'+tr('Send reminder')+' · '+tr('Email')+', '+tr('WhatsApp')+', '+tr('SMS')+'</button></div>' : '');
  var ov = openSheet(html);
  ov.querySelector('#ledgerEditBtn').addEventListener('click', function(){ closeModal(); openCustomerSheet(customer); });
  ov.querySelector('#recordPaymentBtn').addEventListener('click', function(){ openPaymentSheet(customer); });
  ov.querySelector('#statementBtn').addEventListener('click', function(){ openStatementSheet(customer); });
  ov.querySelector('#ledgerCreditSaleBtn').addEventListener('click', function(){ var fresh = State.customers.find(function(c){ return c.id===customer.id; }) || customer; closeModal(); openCreditSaleSheet(fresh); });
  var reminderBtn = ov.querySelector('#sendReminderBtn');
  if(reminderBtn) reminderBtn.addEventListener('click', function(){
    var fresh = State.customers.find(function(c){ return c.id===customer.id; }) || customer;
    openSendSheet(paymentReminderSendCtx(fresh));
  });
  ov.querySelector('#invoiceCustomerBtn').addEventListener('click', function(){
    closeModal();
    openInvoiceSheet({
      customerId: customer.id,
      billToName: customer.name,
      billToContact: [customer.phone, customer.email].filter(Boolean).join('\n'),
      items: [{ desc:'Outstanding balance', qty:1, unitPrice: customer.balance||0 }]
    });
  });
  var ledgerRef = refs.customers.doc(customer.id).collection('ledger');
  var unsub = ledgerRef.onSnapshot(function(docs){
    var list = docs.map(function(d){ return Object.assign({id:d.id}, d.data); }).sort(function(a,b){ return new Date(b.createdAt)-new Date(a.createdAt); });
    var body = ov.querySelector('#ledgerList');
    if(!body) { unsub(); return; }
    if(list.length === 0){ body.innerHTML = '<div class="empty" style="padding:16px 0;">No transactions on this account yet.</div>'; return; }
    body.innerHTML = list.slice(0,30).map(function(t){
      var isCharge = t.type === 'charge';
      var itemsHtml = (t.items && t.items.length) ? '<span class="lt-items">'+t.items.map(function(it){ return esc(it.qty)+' × '+esc(it.name)+' @ '+fmtMoney(it.unitPrice)+' = '+fmtMoney(it.lineTotal); }).join('<br>')+'</span>' : '';
      var label = isCharge ? (t.note && t.note !== 'Sale on credit' && /^Previous balance$/.test(t.note) ? 'Previous balance' : 'Sale on credit') : 'Payment received';
      return '<div class="ledgeritem"><div class="lt-l">'+label+'<span class="d">'+fmtDateTime(t.createdAt)+(t.note && !/^(Sale on credit|Previous balance)$/.test(t.note) ? ' · '+esc(t.note) : '')+'</span>'+itemsHtml+'</div>' +
        '<div class="lt-v num" style="color:'+(isCharge?'var(--danger)':'var(--success)')+'">'+(isCharge?'+':'−')+fmtMoney(t.amount)+
        (!isCharge && t.note !== 'Paid at time of sale' && isManagerOrOwner() ? '<br><button class="btn btn-ghost" data-ldel="'+t.id+'" type="button" style="padding:3px 9px;font-size:11.5px;margin-top:3px;">'+tr('Remove')+'</button>' : '')+'</div></div>';
    }).join('');
    body.querySelectorAll('[data-ldel]').forEach(function(b){ b.addEventListener('click', function(){
      var t = list.find(function(x){ return x.id === b.getAttribute('data-ldel'); }); if(!t) return;
      confirmSheet(tr('Remove this payment?'), customer.name+' will owe '+fmtMoney(t.amount)+' more again, because this payment is taken off their account. Use this only if it was entered by mistake.', tr('Remove payment'), function(){
        var c = State.customers.find(function(x){ return x.id === customer.id; }) || customer;
        askRemovalSheet(tr('a customer payment of')+' '+fmtMoney(t.amount), function(ap, reason){
          refs.customers.doc(customer.id).update({ balance:r2((c.balance||0) + (Number(t.amount)||0)) });
          archiveRemoved('customerPayments', t.id, Object.assign({ customerId:customer.id }, t));
          ledgerRef.doc(t.id).delete();
          logAudit('delete','customerPayment',customer.id,'Removed a payment of '+fmtMoney(t.amount)+' from '+customer.name+'. Approved by '+ap.name+'. Reason: '+reason);
          toast(tr('Payment removed'));
        });
      }, true, true);
    }); });
  });
}

function openPaymentSheet(customer){
  var html = '<div class="sheet-head"><h2>'+tr('Record payment')+'</h2></div>' +
    '<div class="banner">'+esc(customer.name)+' currently owes <strong class="num">'+fmtMoney(customer.balance||0)+'</strong></div>' +
    '<div class="field"><label>'+tr('Amount received')+'</label><input id="payAmt" type="number" inputmode="decimal" step="0.01" placeholder="0.00"></div>' +
    '<div class="field"><label>'+tr('Note (optional)')+'</label><input id="payNote" placeholder="e.g. Cash, EFT, wallet"></div>' +
    '<div class="actions"><button class="btn btn-primary btn-block" id="paySave">'+tr('Save payment')+'</button></div>';
  var ov = openSheet(html, {center:true});
  ov.querySelector('#paySave').addEventListener('click', function(){
    var amt = parseFloat(ov.querySelector('#payAmt').value);
    if(!amt || amt <= 0){ toast('Enter an amount'); return; }
    var newBal = (customer.balance||0) - amt;
    refs.customers.doc(customer.id).update({ balance:newBal, lastPaymentAt:new Date().toISOString() });
    refs.customers.doc(customer.id).collection('ledger').add({ type:'payment', amount:amt, note: ov.querySelector('#payNote').value.trim(), createdAt:new Date().toISOString(), balanceAfter:newBal });
    closeModal();
    toast('Payment recorded, '+fmtMoney(amt));
  });
}

