var EXPENSE_CATEGORIES = ['Stock purchase','Rent','Electricity','Water','Transport','Wages','Airtime/Data','Maintenance','Other'];

function renderExpenses(){
  if(!State.ready.expenses) return '<div class="empty">Loading…</div>';
  var todayTotal = State.expenses.filter(function(e){ return todayKey(new Date(e.createdAt)) === todayKey(); }).reduce(function(s,e){return s+e.amount;},0);
  var monthTotal = State.expenses.filter(function(e){ return new Date(e.createdAt) >= startOfMonth(new Date()); }).reduce(function(s,e){return s+e.amount;},0);
  var html = '<div class="stats" style="margin-bottom:14px;">' +
    '<div class="stat"><div class="lbl">Today</div><div class="v num">'+fmtMoney(todayTotal)+'</div></div>' +
    '<div class="stat"><div class="lbl">This month</div><div class="v num">'+fmtMoney(monthTotal)+'</div></div>' +
  '</div>';
  if(State.expenses.length === 0){
    html += '<div class="empty">'+ICONS.receipt+'<div class="t">'+tr('No expenses logged')+'</div><div class="s">'+tr('Track what goes out to see your real profit.')+'</div></div>';
    return html;
  }
  html += renderSelectToolbar('expenses');
  var selE = selState('expenses');
  html += '<div class="rowlist">' + State.expenses.slice(0,60).map(function(e){
    var checked = !!selE.ids[e.id];
    return '<div class="row'+(checked?' checked':'')+'" data-expense="'+e.id+'" data-select-id="'+e.id+'">' +
      (selE.active ? rowCheckHtml('expenses', e.id) : '') +
      '<div class="avatar">'+ICONS.receipt.replace(/width="26" height="26"/,'width="17" height="17"')+'</div>' +
      '<div class="main"><div class="title">'+esc(e.category)+'</div><div class="sub">'+esc(e.note||fmtDay(e.createdAt))+'</div></div>' +
      '<div class="trail"><div class="amt num">'+fmtMoney(e.amount)+'</div><div class="note">'+fmtDay(e.createdAt)+'</div></div>' +
    '</div>';
  }).join('') + '</div>';
  html += renderSelectBar('expenses');
  return html;
}

function openExpenseSheet(expense){
  var isEdit = !!expense;
  var opts = EXPENSE_CATEGORIES.map(function(c){ return '<option '+(expense&&expense.category===c?'selected':'')+'>'+c+'</option>'; }).join('');
  var html = '<div class="sheet-head"><h2>'+(isEdit?tr('Edit expense'):tr('Add expense'))+'</h2></div>' +
    '<div class="field"><label>'+tr('Category')+'</label><select id="efCat">'+opts+'</select></div>' +
    '<div class="field"><label>'+tr('Amount')+'</label><input id="efAmt" type="number" inputmode="decimal" step="0.01" placeholder="0.00" value="'+(expense?expense.amount:'')+'"></div>' +
    '<div class="field"><label>'+tr('Note (optional)')+'</label><input id="efNote" placeholder="Details" value="'+esc(expense?expense.note||'':'')+'"></div>' +
    '<div class="field-row"><div class="field"><label>Paid from</label><select id="efPaid">' +
      ['Cash drawer','Bank','Card','Mobile wallet','Other'].map(function(o){ return '<option'+((expense&&expense.paidFrom===o)?' selected':'')+'>'+o+'</option>'; }).join('') +
    '</select></div><div class="field"><label>Receipt / reference no.</label><input id="efRef" placeholder="Optional" value="'+esc(expense?expense.ref||'':'')+'"></div></div>' +
    (isVatVendor() ? '<div class="field"><label>'+tr('VAT on the supplier tax invoice (N$, optional)')+'</label><input id="efVat" type="number" inputmode="decimal" step="0.01" placeholder="0.00" value="'+(expense && expense.vat ? expense.vat : '')+'"><div style="font-size:11.5px;color:var(--text-muted);margin-top:4px;">'+tr('Only enter VAT you hold a valid tax invoice for. It is counted as input VAT in the Accountant.')+'</div></div>' : '') +
    '<div class="actions">' +
      (isEdit ? '<button class="btn btn-danger" id="efDelete">'+tr('Delete')+'</button>' : '') +
      '<button class="btn btn-primary btn-block" id="efSave">'+(isEdit?'Save':tr('Add expense'))+'</button>' +
    '</div>';
  var ov = openSheet(html, {center:true});
  ov.querySelector('#efSave').addEventListener('click', function(){
    var amt = parseFloat(ov.querySelector('#efAmt').value);
    if(!amt || amt<=0){ toast('Enter an amount'); return; }
    var data = { category: ov.querySelector('#efCat').value, amount:amt, note: ov.querySelector('#efNote').value.trim(),
      paidFrom: ov.querySelector('#efPaid').value, ref: ov.querySelector('#efRef').value.trim() };
    var efVatEl = ov.querySelector('#efVat');
    if(efVatEl){ var efv = parseFloat(efVatEl.value); data.vat = (isFinite(efv) && efv > 0 && efv <= amt) ? Math.round(efv*100)/100 : 0; }
    if(isEdit){
      refs.expenses.doc(expense.id).update(data);
      logAudit('update','expense',expense.id,'Edited expense '+fmtMoney(amt)+' ('+data.category+')');
      toast('Expense updated');
    } else {
      data.createdAt = new Date().toISOString();
      refs.expenses.doc().set(data);
      logAudit('create','expense',null,'Added expense '+fmtMoney(amt)+' ('+data.category+')');
      toast('Expense added');
    }
    closeModal();
  });
  if(isEdit){
    ov.querySelector('#efDelete').addEventListener('click', function(){
      confirmSheet('Delete expense?', 'This cannot be undone.', 'Delete', function(){ withRemoval('an expense', function(){ refs.expenses.doc(expense.id).delete(); logAudit('delete','expense',expense.id,'Deleted expense'); toast('Expense deleted'); }); }, true, true);
    });
  }
}

