function dashWrap(inner){
  var logo = (typeof PESA_LOGO_DATA_URL !== 'undefined' && PESA_LOGO_DATA_URL) ? PESA_LOGO_DATA_URL : '';
  return DKD_CSS + '<div class="dkd" style="--dkd-logo:url(\'' + logo + '\');"><div class="dkd-gold"></div><h2 class="dkd-h">' + tr('Dashboard') + '</h2><div class="dkd-tag">' + tr('Your Mula, Your Pride') + '<span class="slogan-sub">(Retail Automated System)</span></div>' + inner +
    '<div class="dkd-foot">' + tr('Your numbers. Our focus.') + '</div></div>';
}
function renderDashboard(){
  if(!State.ready.sales || !State.ready.expenses || !State.ready.products || !State.ready.customers){
    return '<div class="empty">Loading your shop…</div>';
  }
  // Multi-branch: an owner viewing a specific branch sees dashboard figures
  // scoped to it (records with no branchId, i.e. everything made before
  // multi-branch existed, still count everywhere, so nothing disappears).
  // Non-owners, and owners who never create a second branch, see the exact
  // same combined figures as before.
  var realSales = State.sales, realProducts = State.products;
  var branchBannerHtml = '';
  if(isOwner() && State.branches.length>0){
    var bid = State.settings.currentBranchId || 'all';
    State.sales = branchScoped(realSales);
    State.products = branchScoped(realProducts);
    if(bid !== 'all'){
      var b = State.branches.find(function(x){ return x.id===bid; });
      branchBannerHtml = '<div class="banner">Viewing: <strong>'+esc(b?b.name:'branch')+'</strong>, switch branches in Settings.</div>';
    }
  }
  var now = new Date();
  var wk = startOfWeek(now), mo = startOfMonth(now);
  var sumOf = function(list){ return list.reduce(function(s,x){return s+x.total;},0); };
  function since(d){ var t = d.getTime(); return State.sales.filter(function(s){ return tms(s.createdAt) >= t; }); }

  var days7 = lastNDaysTotals(State.sales, 7);
  var todayTotal = days7[days7.length-1].total;
  var yestTotal = days7[days7.length-2] ? days7[days7.length-2].total : 0;
  var delta = yestTotal > 0 ? ((todayTotal-yestTotal)/yestTotal*100) : (todayTotal>0?100:0);
  var deltaUp = delta >= 0;

  var _tk = todayKey(), todaySales = State.sales.filter(function(s){ return dayKeyOfIso(s.createdAt)===_tk; });
  var weekSales = since(wk);
  var monthSales = since(mo);
  var _mot = mo.getTime(), monthExpenses = State.expenses.filter(function(e){ return tms(e.createdAt) >= _mot; }).reduce(function(s,e){return s+e.amount;},0);
  var monthRevenue = monthSales.reduce(function(s,x){return s+x.total;},0);
  var monthProfit = monthSales.reduce(function(s,x){return s+(x.profit!=null?x.profit:0);},0) - monthExpenses;
  var totalOwed = State.customers.reduce(function(s,c){return s+(c.balance||0);},0);

  var pmTotals = {cash:0, card:0, wallet:0, credit:0};
  todaySales.forEach(function(s){ salePayParts(s).forEach(function(q){ pmTotals[q.method] = (pmTotals[q.method]||0) + q.amount; }); });

  var lowStockProducts = State.products.filter(function(p){ return p.stockQty!=null && p.stockQty <= (p.lowStock!=null?p.lowStock:State.settings.lowStockDefault); })
    .sort(function(a,b){ return a.stockQty-b.stockQty; });
  var debtors = State.customers.filter(function(c){ return (c.balance||0) > 0; }).sort(function(a,b){ return b.balance-a.balance; });

  var byProduct = {};
  monthSales.forEach(function(s){ (s.items||[]).forEach(function(it){ byProduct[it.name] = (byProduct[it.name]||0) + it.lineTotal; }); });
  var top = Object.keys(byProduct).map(function(k){ return {name:k, v:byProduct[k]}; }).sort(function(a,b){return b.v-a.v;}).slice(0,5);
  var topMax = top.length ? top[0].v : 1;

  /* ---- hero ---- */
  var html = pilotHomeNote() + '<div class="hero-card">' +
    '<div class="hero-top"><div>' +
      '<div class="hero-lbl">Today’s sales</div>' +
      '<div class="hero-val num">'+fmtMoney(todayTotal)+'</div>' +
      '<div class="hero-delta'+(deltaUp?'':' down')+'">'+(deltaUp?ICONS.trendUp:ICONS.trendDown)+' '+Math.abs(Math.round(delta))+'% vs yesterday</div>' +
    '</div></div>' +
    '<div class="hero-chart">' + sparklineSvg(days7, {stroke:'currentColor', fill:'rgba(44,255,176,0.26)'}) +
      '<div class="hero-ticks">' + days7.map(function(d){ return '<span>'+d.label+'</span>'; }).join('') + '</div>' +
    '</div>' +
  '</div>';

  html += '<div class="paysplit-label">'+tr('Today’s sales by payment method')+'</div>';
  html += '<div class="paysplit">' +
    '<div class="pt"><div class="l">'+tr('Cash sales')+'</div><div class="v">'+fmtMoney(pmTotals.cash)+'</div></div>' +
    '<div class="pt"><div class="l">'+tr('Card sales')+'</div><div class="v">'+fmtMoney(pmTotals.card)+'</div></div>' +
    '<div class="pt"><div class="l">'+tr('Mobile wallet sales')+'</div><div class="v">'+fmtMoney(pmTotals.wallet)+'</div></div>' +
    '<div class="pt"><div class="l">'+tr('Credit sales')+'</div><div class="v">'+fmtMoney(pmTotals.credit)+'</div></div>' +
  '</div>';

  /* ---- quick actions ---- */
  html += '<div class="qa-row">' +
    '<button class="qa-btn" data-qa="sell"><span class="qa-ico i3d">'+ico3('sell')+'</span><span class="qa-lbl">'+tr('Sell')+'</span></button>' +
    '<button class="qa-btn" data-qa="stock"><span class="qa-ico i3d">'+ico3('stock')+'</span><span class="qa-lbl">'+tr('Stock')+'</span></button>' +
    '<button class="qa-btn" data-qa="expense"><span class="qa-ico i3d">'+ico3('expenses')+'</span><span class="qa-lbl">'+tr('Expenses')+'</span></button>' +
    '<button class="qa-btn" data-qa="customer"><span class="qa-ico i3d">'+ico3('credit')+'</span><span class="qa-lbl">'+tr('Customer')+'</span></button>' +
  '</div>';

  /* ---- stat grid ---- */
  html += tmDashHtml();
  html += '<div class="section-title">'+tr('Overview')+'</div><div class="stats">' +
    '<div class="stat"><div class="lbl">This week</div><div class="v num">'+fmtMoney(sumOf(weekSales))+'</div></div>' +
    '<div class="stat"><div class="lbl">This month</div><div class="v num">'+fmtMoney(monthRevenue)+'</div></div>' +
    '<div class="stat"><div class="lbl">Est. profit (mo.)</div><div class="v num small" style="color:'+(monthProfit>=0?'var(--success)':'var(--danger)')+'">'+fmtMoney(monthProfit)+'</div></div>' +
    '<div class="stat"><div class="lbl">Owed to you</div><div class="v num small" style="color:var(--danger)">'+fmtMoney(totalOwed)+'</div></div>' +
  '</div>';

  /* ---- needs attention ---- */
  var attnCount = lowStockProducts.length + debtors.length;
  html += '<div class="section-title">'+tr('Needs attention')+(attnCount?' <span style="text-transform:none;letter-spacing:0;color:var(--text-muted);font-weight:500;">('+attnCount+')</span>':'')+'</div><div class="card pad">';
  if(attnCount === 0){
    html += '<div class="all-clear">'+ICONS.check+'<span>All caught up, stock is healthy and no one owes you.</span></div>';
  } else {
    lowStockProducts.slice(0,3).forEach(function(p){
      var out = p.stockQty<=0;
      html += '<div class="att-row" data-goto-product="'+p.id+'">' +
        '<div class="att-dot'+(out?'':' warn')+'"></div>' +
        '<div class="att-main"><div class="att-title">'+esc(p.name)+'</div><div class="att-sub">'+(out?'Out of stock':'Running low')+'</div></div>' +
        '<div class="att-val">'+p.stockQty+' '+(p.unit||'left')+'</div>' +
      '</div>';
    });
    debtors.slice(0,3).forEach(function(c){
      html += '<div class="att-row" data-goto-customer="'+c.id+'">' +
        '<div class="att-dot"></div>' +
        '<div class="att-main"><div class="att-title">'+esc(c.name)+'</div><div class="att-sub">Owes since last visit</div></div>' +
        '<div class="att-val num">'+fmtMoney(c.balance)+'</div>' +
      '</div>';
    });
  }
  html += '</div>';

  /* ---- top sellers ---- */
  html += '<div class="section-title">'+tr('Top sellers this month')+'</div><div class="card pad">' +
    (top.length===0 ? '<div style="color:var(--text-muted);font-size:13px;">No sales yet this month.</div>' :
      top.map(function(t){ return '<div class="barrow"><div class="bl">'+esc(t.name)+'</div><div class="btrack"><div class="bfill" style="width:'+(t.v/topMax*100)+'%"></div></div><div class="bv num">'+fmtMoney(t.v)+'</div></div>'; }).join('')) +
  '</div>';

  /* ---- sales insights (collapsible) ---- */
  html += dashboardInsightsHtml();

  /* ---- recent sales ---- */
  html += '<div class="section-title">'+tr('Recent sales')+'</div>';
  if(State.sales.length === 0){
    html += '<div class="card pad" style="color:var(--text-muted);font-size:13px;">No sales recorded yet.</div>';
  } else {
    html += '<div class="rowlist">' + State.sales.slice(0,5).map(function(s){
      var pmLabel = saleIsSplit(s)?tr('Split payment'):s.paymentMethod==='cash'?tr('Cash'):(s.paymentMethod==='card'?tr('Card'):(s.paymentMethod==='wallet'?(s.walletProvider||tr('Mobile wallet')):(s.paymentMethod==='voucher'?tr('Voucher')+(s.voucher?' · '+s.voucher.platform:''):tr('Credit'))));
      var itemCount = (s.items||[]).reduce(function(a,i){return a+i.qty;},0);
      return '<div class="row" style="cursor:default;">' +
        '<div class="avatar">'+ICONS.cart.replace(/width="26" height="26"/,'width="16" height="16"')+'</div>' +
        '<div class="main"><div class="title">'+itemCount+' item'+(itemCount===1?'':'s')+'</div><div class="sub">'+pmLabel+' · '+fmtDateTime(s.createdAt)+'</div></div>' +
        '<div class="trail"><div class="amt num">'+fmtMoney(s.total)+'</div><button class="note" data-invoice-sale="'+s.id+'" style="background:none;border:none;padding:0;color:var(--primary-dim);font-weight:600;font-size:10.5px;cursor:pointer;">'+tr('Invoice')+'</button></div>' +
      '</div>';
    }).join('') + '</div>';
    if(isOwner()) html += '<div class="actions" style="margin-top:8px;"><button class="btn btn-ghost btn-block" id="clearSalesBtn" type="button" style="color:var(--danger);">'+tr('Clear all')+'</button></div>';
  }

  /* ---- invoicing ---- */
  html += '<div class="section-title">'+tr('Invoicing')+'</div><div class="card pad" style="display:flex;flex-direction:column;gap:10px;">' +
    '<button class="btn btn-accent btn-block" id="createInvoiceBtn">'+tr('Create an invoice')+'</button>' +
    '<div style="font-size:11.5px;color:var(--text-muted);text-align:center;">Downloads as a PDF you can print or share. Add your logo in Settings to brand it.</div>' +
  '</div>';

  /* ---- report ---- */
  var todayISO = todayKey();
  var monthStartISO = (function(){ var d=new Date(); d.setDate(1); return todayKey(d); })();
  html += '<div class="section-title">'+tr('Reports')+'</div><div class="card pad" style="display:flex;flex-direction:column;gap:10px;">' +
    '<div class="segbtns" id="reportPresetBtns">' +
      '<button type="button" class="segbtn active" data-preset="month">'+tr('This month')+'</button>' +
      '<button type="button" class="segbtn" data-preset="lastmonth">'+tr('Last month')+'</button>' +
      '<button type="button" class="segbtn" data-preset="custom">'+tr('Custom')+'</button>' +
    '</div>' +
    '<div class="field-row" id="reportRangeRow" style="display:none;margin:0;">' +
      '<div class="field" style="margin:0;"><label>'+tr('From')+'</label><input type="date" id="reportFrom" value="'+monthStartISO+'" max="'+todayISO+'"></div>' +
      '<div class="field" style="margin:0;"><label>'+tr('To')+'</label><input type="date" id="reportTo" value="'+todayISO+'" max="'+todayISO+'"></div>' +
    '</div>' +
    '<button class="btn btn-ghost btn-block" id="downloadReportBtn">'+tr('Download report')+'</button>' +
    (isManagerOrOwner() ? '<button class="btn btn-ghost btn-block" id="viewReportArchiveBtn" type="button">'+tr('View report archive')+'</button>' : '') +
    '<div style="font-size:11.5px;color:var(--text-muted);text-align:center;">Revenue, cost of goods, expenses, profit or loss, and a full stock valuation for any date range you pick.</div>' +
  '</div>';

  /* ---- data ---- */
  html += '<div class="section-title">'+tr('Data')+'</div><div class="card pad" style="display:flex;flex-direction:column;gap:10px;">' +
    '<button class="btn btn-ghost btn-block" id="exportDataBtn">'+tr('Export all data (.json)')+'</button>' +
    '<div style="font-size:11.5px;color:var(--text-muted);text-align:center;">'+(Store.isCloud()?'Saved securely and synced automatically.':'Saved on this device only.')+'</div>' +
  '</div>';

  State.sales = realSales; State.products = realProducts;
  return dashWrap(licBannerHtml() + teamCardHtml() + branchBannerHtml + html);
}

function exportData(){
  gatherLedgers().then(function(l){ var p = backupPayload(); p.ledgers = l; return backupSeal(p); }).then(function(p){ doExportData(p); });
}
function doExportData(payload){
  var json = JSON.stringify(payload, null, 2);
  var filename = 'pesa-export-'+todayKey()+'.json';
  (async function(){
    try{
      if(window.claude && window.claude.use){
        var dl = await window.claude.use('downloads');
        if(dl){
          await dl.save({ filename: filename, data: json });
          toast('Export ready');
          return;
        }
      }
    }catch(e){
      if(e && e.code === 'declined') return;
    }
    if(browserDownload(filename, new Blob([json], {type:'application/json'}))){
      toast('Export ready');
    } else {
      toast('Downloads not available in this view');
    }
  })();
}

