// Builds the app's one complete navigation menu, used both for the mobile
// overlay drawer (openDashboardDrawer(), below the desktop breakpoint) and
// for the persistent pinned sidebar (renderSidebar(), at/above it), so the
// two surfaces can never drift out of sync. Tab rows are filtered by the
// signed-in role the same way the old bottom nav used to (roleTabs()).
var GEAR_ICON_SMALL = '<span class="gear-tile"><svg width="26" height="26" viewBox="0 0 48 48" aria-hidden="true"><defs><linearGradient id="gearG2" x1="0.1" y1="0" x2="0.9" y2="1"><stop offset="0" stop-color="#fbe3a2"/><stop offset=".45" stop-color="#d1a352"/><stop offset="1" stop-color="#8c632b"/></linearGradient></defs><path d="M38.78 20.45 L44.81 21.20 L44.81 26.80 L38.78 27.55 L36.96 31.94 L40.69 36.74 L36.74 40.69 L31.94 36.96 L27.55 38.78 L26.80 44.81 L21.20 44.81 L20.45 38.78 L16.06 36.96 L11.26 40.69 L7.31 36.74 L11.04 31.94 L9.22 27.55 L3.19 26.80 L3.19 21.20 L9.22 20.45 L11.04 16.06 L7.31 11.26 L11.26 7.31 L16.06 11.04 L20.45 9.22 L21.20 3.19 L26.80 3.19 L27.55 9.22 L31.94 11.04 L36.74 7.31 L40.69 11.26 L36.96 16.06Z M18.80 24.00 a5.20 5.20 0 1 0 10.40 0 a5.20 5.20 0 1 0 -10.40 0Z" fill="url(#gearG2)" fill-rule="evenodd" stroke="#ffeebd" stroke-opacity=".75" stroke-width=".7" stroke-linejoin="round"/><circle cx="24" cy="24" r="9" fill="none" stroke="#7a5522" stroke-opacity=".55" stroke-width="1.6"/><circle cx="24" cy="24" r="8.2" fill="none" stroke="#ffe9b0" stroke-opacity=".55" stroke-width=".7"/></svg></span>';
/* ---- menu pages: features that belong together share one page, so the menu list is short ---- */
var MENU_HUBS = {
  'hub-tools': { name:'Smart tools', icon:null, items:[['insights', 'Sales insights', 'chartbar', 'm'], ['bizhub', 'Business tools', 'stack', 'm'], ['smart', 'Pesa Smart Tools', 'bolt', 'm'], ['agent', 'Pesa AI Assistant', 'agent', 'm']] },
  'hub-stock': { name:'Stock and suppliers', icon:null, items:[['stocktake', 'Stock take & variances', 'clipboard', 'm'], ['suppliers', 'Suppliers', 'truck', 'm'], ['pos', 'Purchase orders', 'clipboard', 'm'], ['wastage', 'Wastage & shrinkage', 'trash', 'm']] },
  'hub-money': { name:'Money and tax', icon:null, items:[['tab-reconcile', 'Reconciliation', 'check', 'm'], ['vat', 'NamRA VAT summary', 'percent', 'm'], ['accountant', 'Accountant', 'chartbar', 'm']] },
  'hub-team':  { name:'Team and branches', icon:null, items:[['tab-team', 'Employee tracking', 'people', 'm'], ['branches', 'Branches', 'branch', 'o']] },
  'hub-pesa':  { name:'Pesa account and ads', icon:null, items:[['pay', 'Pay for Pesa', 'receipt', 'o'], ['pesaad', 'Pesa Ad', 'bolt', 'm']] }
};
function menuItemCount(k){
  try{
    if(k === 'bizhub') return btStockAttention() || null;
    if(k === 'smart'){ var c = smartAlertCount(); return c ? c : null; }
    if(k === 'agent'){ var g = agentAlerts().length; return g ? g : null; }
    if(k === 'suppliers') return State.suppliers.length;
    if(k === 'pos') return State.purchaseOrders.length;
    if(k === 'branches') return State.branches.length + 1;
  }catch(e){}
  return null;
}
// the items of one menu page this person may see (owners only, managers, and the business type's own short menu)
function menuHubItems(hk){
  var h = MENU_HUBS[hk]; if(!h) return [];
  return h.items.filter(function(it){
    if(it[3] === 'o' ? !isOwner() : !isManagerOrOwner()) return false;
    return true;
  }).map(function(it){ return { k:it[0], label:it[1], icon:ICONS[it[2]] || ICONS.clipboard, count:menuItemCount(it[0]) }; });
}
function menuHubCount(hk){
  var n = 0, any = false; menuHubItems(hk).forEach(function(i){ if(i.k === 'bizhub' || i.k === 'smart' || i.k === 'agent'){ if(i.count){ n += i.count; any = true; } } });
  return any ? n : null;
}
function openMenuHub(hk){
  var h = MENU_HUBS[hk]; if(!h) return;
  var items = menuHubItems(hk);
  var ov = openSheet('<div class="sheet-head"><h2>' + tr(h.name) + '</h2></div><div class="menu-hub">' + items.map(function(i){ return drawerRowHtml(i.k, i.icon, i.label, i.count); }).join('') + '</div>' +
    '<div class="actions"><button class="btn btn-ghost btn-block" id="mhClose" type="button">' + tr('Close') + '</button></div>');
  ov.querySelector('#mhClose').addEventListener('click', closeModal);
  ov.querySelectorAll('[data-drawer-row]').forEach(function(b){ b.addEventListener('click', function(){ var k = b.getAttribute('data-drawer-row'); closeModal(); setTimeout(function(){ handleDrawerAction(k); }, 180); }); });
}
function menuRowsHtml(){
  var allowedTabs = State.session ? roleTabs(State.session.role) : ['dashboard','sell','stock','credit','invoices','reports','expenses','till'];
  var rows = '';
  rows += '<div class="drawer-sub">Main menu</div>';
  if(allowedTabs.indexOf('me')!==-1) rows += drawerRowHtml('tab-me', ICONS.dashboard, 'My dashboard');
  if(allowedTabs.indexOf('records')!==-1) rows += drawerRowHtml('tab-records', ICONS.clipboard, 'My records');
  var _um = unreadMessages().length; rows += drawerRowHtml('inbox', ICONS.bolt, 'Messages', _um ? _um : null);
  if(allowedTabs.indexOf('dashboard')!==-1) rows += drawerRowHtml('tab-dashboard', ICONS.dashboard, 'Dashboard');
  if(allowedTabs.indexOf('sell')!==-1) rows += drawerRowHtml('tab-sell', ICONS.cart, 'Sell');
  if(allowedTabs.indexOf('stock')!==-1) rows += drawerRowHtml('tab-stock', ICONS.box, 'Stock');
  if(allowedTabs.indexOf('credit')!==-1) rows += drawerRowHtml('tab-credit', ICONS.people, 'Credit');
  if(allowedTabs.indexOf('invoices')!==-1) rows += drawerRowHtml('tab-invoices', ICONS.invoice, 'Invoices');
  if(allowedTabs.indexOf('reports')!==-1) rows += drawerRowHtml('tab-reports', ICONS.chartbar, 'Reports');
  if(allowedTabs.indexOf('expenses')!==-1) rows += drawerRowHtml('tab-expenses', ICONS.receipt, 'Expenses');
  if(allowedTabs.indexOf('till')!==-1) rows += drawerRowHtml('tab-till', ICONS.till, 'Till');
  if(State.session && State.session.role === 'stockclerk') rows += drawerRowHtml('wastage', ICONS.trash, 'Wastage & shrinkage');
  else rows += drawerRowHtml('terminal', ICONS.till, 'Point of sale');
  if(isManagerOrOwner()){
    // related features live together on one page, so the menu stays short; each page keeps its own icons
    rows += '<div class="drawer-sub">Manage your business</div>';
    ['hub-tools', 'hub-stock', 'hub-money', 'hub-team', 'hub-pesa'].forEach(function(k){ if(menuHubItems(k).length) rows += drawerRowHtml(k, MENU_HUBS[k].icon, MENU_HUBS[k].name, menuHubCount(k)); });
  }
  rows += '<div class="drawer-sub">More</div>';
  rows += drawerRowHtml('settings', GEAR_ICON_SMALL, 'Settings', pfDue() ? '!' : null);
  rows += comingSoonHtml();
  return rows;
}
