function wireShareApp(root){
  var msg = 'Try Pesa, a shop and point of sale app for Namibia. Your Mula, Your Pride. ';
  var g = function(id){ return root.querySelector(id); };
  if(!g('#shCopy')) return;
  g('#shCopy').addEventListener('click', function(){ copyText(appShareLink(), tr('Link copied')); });
  g('#shWa').addEventListener('click', function(){ window.open('https://wa.me/?text='+encodeURIComponent(msg+appShareLink()), '_blank'); });
  g('#shMore').addEventListener('click', function(){
    if(navigator.share){ navigator.share({ title:'Pesa', text:msg, url:appShareLink() }).catch(function(){}); }
    else copyText(msg+appShareLink(), tr('Link copied'));
  });
}
