  var rows = ACCT_CHART.map(function(a){
    var mv = within[a.code] || { dr:0, cr:0 }, open = before[a.code] || 0;
    return { code:a.code, name:a.name, type:a.type, open:open, dr:mv.dr, cr:mv.cr, close:open + mv.dr - mv.cr };
  }).filter(function(r){ return r.open !== 0 || r.dr !== 0 || r.cr !== 0 || r.close !== 0; });
