  var pl = { salesStandard:sStd, salesZero:sZero, salesExempt:sEx, salesNonVat:sNon, revenue:revenue, cogs:cogs, wastage:waste, grossProfit:gross, expenses:exp, opex:opex, net:gross - opex };
