  var assets = tb.rows.filter(function(r){ return r.type === 'ASSET'; }).map(function(r){ return { code:r.code, name:r.name, amount:r.close }; });
  var liabs = tb.rows.filter(function(r){ return r.type === 'LIABILITY'; }).map(function(r){ return { code:r.code, name:r.name, amount:-r.close }; });
