/* ---- VAT periods (NamRA category A ends in odd months, B in even months; the return is due by the 25th of the next month) ---- */
function acctVatCategory(){ var c = State.settings.vatCategory; return c === 'A' || c === 'B' ? c : ''; }
function acctVatPeriodsFor(cat, nowKey, keysWithActivity){
  var parity = cat === 'A' ? 1 : 0, out = [], seen = {};
  function endFor(key){ var p = key.split('-'), y = +p[0], mo = +p[1]; if(mo % 2 !== parity) mo += 1; if(mo > 12){ mo = 1; y += 1; } return y + '-' + String(mo).padStart(2, '0'); }
  keysWithActivity.forEach(function(k){ var e = endFor(k); if(!seen[e]){ seen[e] = true; out.push(e); } });
  return out.sort().reverse().map(function(e){
    var p = e.split('-'), y = +p[0], mo = +p[1], py = mo === 1 ? y - 1 : y, pm = mo === 1 ? 12 : mo - 1;
    var startKey = py + '-' + String(pm).padStart(2, '0');
    var due = new Date(mo === 12 ? y + 1 : y, mo === 12 ? 0 : mo, 25);
    return { end:e, start:startKey, months:[startKey, e], due:todayKey(due), open:e >= nowKey };
  });
}
function acctVatLabel(p){ return acctLabelOf(p.start) + ' to ' + acctLabelOf(p.end); }
