  var parts = p.months.map(function(k){ return have[k] ? { rec:have[k], v:have[k] } : { rec:null, v:acctView(G, B, k + '-01', acctMonthEnd(k)) }; });
  var vat = { standardNet:0, standardGross:0, zeroRated:0, exempt:0, outputVat:0, inputVat:0 };
  parts.forEach(function(x){ Object.keys(vat).forEach(function(k){ vat[k] += x.v.vat[k] || 0; }); });
