  function note(text){ doc.setFont('helvetica', 'normal'); doc.setFontSize(7.8); pdSet(doc, 't', pal.muted); doc.splitTextToSize(String(tr(text)), W).forEach(function(l){ doc.text(l, m, y); y += 3.9; }); y += 3; }
