  note([G.tin ? tr('TIN') + ' ' + G.tin : '', G.vatNumber ? tr('VAT number') + ' ' + G.vatNumber : tr('Not VAT registered'), State.session ? tr('Prepared by') + ' ' + State.session.name : ''].filter(Boolean).join('   |   '));
  pdSection(doc, pal, m, y + 3, W, 'VAT working figures'); y += 7;
  var rows = [[tr('Standard rated supplies, excluding VAT'), acctM(vat.standardNet)], [tr('Standard rated supplies, including VAT'), acctM(vat.standardGross)], [tr('Zero rated supplies'), acctM(vat.zeroRated)], [tr('Exempt supplies'), acctM(vat.exempt)],
    [tr('Total supplies, including VAT'), acctM(vat.standardGross + vat.zeroRated + vat.exempt)],
    [tr('Output VAT (charged on sales)'), acctM(vat.outputVat)], [tr('Input VAT (on supplier tax invoices recorded)'), acctM(vat.inputVat)], [vat.netPayable >= 0 ? tr('Net VAT payable to NamRA') : tr('Net VAT refundable from NamRA'), acctM(Math.abs(vat.netPayable))]];
  y = pdfTable(doc, { x:m, y:y, width:W, columns:[{ label:'Item', width:W - 50 }, { label:'Amount', width:50, align:'right' }], rows:rows, boldRows:[4, 7] }); y += 7;
  pdSection(doc, pal, m, y + 3, W, 'By month'); y += 7;
  y = pdfTable(doc, { x:m, y:y, width:W, columns:[{ label:'Month', width:W - 128, wrap:true }, { label:'Source', width:38 }, { label:'Output VAT', width:30, align:'right' }, { label:'Input VAT', width:30, align:'right' }, { label:'Net', width:30, align:'right' }],
    rows:parts.map(function(x, i){ return [acctLabelOf(p.months[i]), x.rec ? tr('Filed') + ' r' + x.rec.revision : tr('Interim'), acctM(x.v.vat.outputVat), acctM(x.v.vat.inputVat), acctM(x.v.vat.netPayable)]; }) }); y += 7;
