      (shown.length ? acctTableHtml([tr('Date'), tr('Description'), { l:'Debit', r:true }, { l:'Credit', r:true }, { l:'Balance', r:true }], shown.map(function(x){ return [x.date, x.memo, x.dr ? acctM(x.dr) : '', x.cr ? acctM(x.cr) : '', acctM(x.bal)]; })) : '') + '</details>';
