      j.lines.map(function(l){ return '<div class="r"><span>' + esc(l.account + ' ' + (ACCT_BY[l.account] ? ACCT_BY[l.account].name : '')) + '</span><span class="num">' + esc(l.dr ? acctM(l.dr) + ' Dr' : acctM(l.cr) + ' Cr') + '</span></div>'; }).join('') + '</div>';
