/* ============================== PESA SMART TOOLS ==============================
   Everything here is worked out on the device from the shop's own records. No
   information is sent anywhere. Owners and managers only. */
var DAY_MS = 86400000;
function smartNow(){ return Date.now(); }
function smartSalesSince(days){
  return brainMemo('since|' + days, function(){
    var from = smartNow() - days*DAY_MS;
    return State.sales.filter(function(s){ return saleMs(s) >= from; });
  });
}
// units sold and revenue per product over the last N days
function smartVelocity(days){ return brainMemo('vel|' + days, function(){ return smartVelocityRaw(days); }); }
function smartVelocityRaw(days){
  var map = {};
  smartSalesSince(days).forEach(function(s){
    (s.items||[]).forEach(function(it){
      var k = it.productId || it.name;
      var m = map[k] || (map[k] = { key:k, name:it.name, qty:0, revenue:0, profit:0 });
      m.qty += it.qty||0; m.revenue += it.lineTotal||0; m.profit += ((it.unitPrice||0)-(it.cost||0))*(it.qty||0);
    });
  });
  return map;
}
function customerLastActivity(c){
  var last = c.lastPaymentAt ? new Date(c.lastPaymentAt).getTime() : 0, first = 0;
  State.sales.forEach(function(s){
    if(s.customerId === c.id && s.paymentMethod === 'credit'){
      var t = new Date(s.createdAt).getTime();
      if(!first || t < first) first = t;
    }
  });
  return { lastPayment:last, firstCredit:first };
}
var CREDIT_LATE_DAYS = 30;
function customerDaysLate(c){
  if(!(c.balance > 0)) return 0;
  var a = customerLastActivity(c);
  var ref = a.lastPayment || a.firstCredit || (c.createdAt ? new Date(c.createdAt).getTime() : 0);
  return ref ? Math.floor((smartNow() - ref) / DAY_MS) : 0;
}
function lateCustomers(){
  return State.customers.filter(function(c){ return c.balance > 0 && customerDaysLate(c) >= CREDIT_LATE_DAYS; })
    .sort(function(a,b){ return b.balance - a.balance; });
}
function overLimitCustomers(){
  return State.customers.filter(function(c){ return c.creditLimit > 0 && c.balance > c.creditLimit; });
}
function reorderSuggestions(){
  var vel = smartVelocity(30), out = [];
  State.products.forEach(function(p){
    if(p.stockQty == null) return;
    var v = vel[p.id] ? vel[p.id].qty/30 : 0, th = lowThresholdOf(p) || 0;
    var daysLeft = v > 0 ? p.stockQty / v : Infinity;
    if(p.stockQty <= th || daysLeft < 7){
      var qty = Math.ceil(Math.max(v*14 - p.stockQty, th*2 - p.stockQty, 1));
      out.push({ product:p, stock:p.stockQty, perDay:v, daysLeft:daysLeft, qty:qty });
    }
  });
  return out.sort(function(a,b){ return a.daysLeft - b.daysLeft; });
}
function smartAlerts(){
  var al = [];
  var re = reorderSuggestions();
  if(re.length) al.push({ id:'reorder', level: re.some(function(r){ return r.stock <= 0; }) ? 'high' : 'med', title: re.length+' '+(re.length===1?'product needs':'products need')+' restocking', body: re.slice(0,3).map(function(r){ return r.product.name+' ('+r.stock+' left)'; }).join(', ')+(re.length>3?' and more':''), go:'reorder', label:'Open reorder list' });
  var late = lateCustomers();
  if(late.length) al.push({ id:'late', level:'high', title: late.length+' '+(late.length===1?'customer is':'customers are')+' late paying', body: late.slice(0,3).map(function(c){ return c.name+' owes '+fmtMoney(c.balance); }).join(', '), go:'customers', label:'Open customers' });
  var over = overLimitCustomers();
  if(over.length) al.push({ id:'overlimit', level:'med', title: over.length+' '+(over.length===1?'customer is':'customers are')+' over their credit limit', body: over.slice(0,3).map(function(c){ return c.name; }).join(', '), go:'customers', label:'Open customers' });
  State.tillSessions.forEach(function(t){
    if(t.status === 'open' && t.openedAt && smartNow() - new Date(t.openedAt).getTime() > 14*3600000)
      al.push({ id:'till-'+t.id, level:'med', title:'A till has been open for over 14 hours', body: (t.cashierName||'A cashier')+' opened it '+fmtDateTime(t.openedAt)+'. Remember to close it and count the cash.' });
  });
  try{
    var ss = Sync.status();
    if(ss.state === 'error') al.push({ id:'syncerr', level:'med', title:'Cloud connection has a problem', body:'Changes are kept safely on this device and will send when the problem clears.' });
  }catch(e){}
  try{ al = al.concat(btExtraAlerts()); }catch(e){}
  try{ al = al.concat(brainAlerts()); }catch(e){}
  try{ al = al.concat(acctAlerts()); }catch(e){}
  try{ al = al.concat(agentAlerts()); }catch(e){}
  return al;
}
/* The number on the side menu badge. Working out every alert reads all sales, so it is kept for a short time and only worked out again when the
   shop's records change in size or 20 seconds pass. This runs every time a page is drawn on a wide screen, so without it a big shop felt slow on a computer. */
var _smartCnt = { at:0, key:'', n:0 };
function smartAlertCount(){
  try{
    var key = [State.products.length, State.sales.length, State.expenses.length, State.customers.length, State.tillSessions.length, State.wastage.length, State.suppliers.length, State.supplierInvoices.length, State.supplierPayments.length, (State.session && State.session.userId) || ''].join('|');
    var now = Date.now();
    if(_smartCnt.key === key && now - _smartCnt.at < 20000) return _smartCnt.n;
    var n = smartAlerts().length; _smartCnt = { at:now, key:key, n:n }; return n;
  }catch(e){ return 0; }
}
/* ============================== PESA BRAIN ==============================
   The "thinking" part of Pesa. It reads the shop's own records on this device and works out what is
   unusual, what will run out, what is not selling and what to do next. It can also answer plain
   questions typed or spoken in the Ask Pesa box. Nothing is sent anywhere. Owners and managers only. */
/* The "brain" reads every sale to work out today's takings, usual days, hours and last sale per product. It is drawn on the Sell page and in the side menu,
   so on a big shop the same scan used to run again on every page switch. The answers are kept until a sale is added or removed, or 15 seconds pass. */
