  cart.forEach(function(i){ var m = pairs[i.productId]; if(m) Object.keys(m).forEach(function(y){ if(!inCart[y]) score[y] = (score[y]||0) + m[y]; }); });
  return Object.keys(score).filter(function(id){ return score[id] >= 2; }).sort(function(x,y){ return score[y] - score[x]; })
    .map(function(id){ return State.products.find(function(p){ return p.id === id; }); })
    .filter(function(p){ return p && !(p.stockQty != null && p.stockQty <= 0); }).slice(0, max || 3);
