function brainTogetherHtml(){
  try{
    if(!State.session || isRestricted() || !State.cart.length) return '';
    var list = brainTogether(State.cart, 3); if(!list.length) return '';
    return '<div id="brTogether" style="margin-top:10px;"><div class="sub" style="font-size:12px;color:var(--text-muted);margin-bottom:6px;">'+tr('Often bought together')+'</div><div style="display:flex;gap:6px;flex-wrap:wrap;">' +
      list.map(function(p){ return '<button class="btn btn-ghost" type="button" data-br-add="'+p.id+'" style="padding:6px 10px;font-size:13px;">+ '+esc(p.name)+' '+esc(fmtMoney(p.sellPrice))+'</button>'; }).join('') + '</div></div>';
  }catch(e){ return ''; }
}
function brainFmtPct(p){ return (p >= 0 ? 'up ' : 'down ') + Math.abs(p) + '%'; }
// the briefing: a short list of things worth knowing right now, most useful first
function brainBriefing(){
  var items = [], now = new Date(), t = brainToday(now);
  if(t.count || t.usual){
    var line = 'Today so far: '+fmtMoney(t.total)+' from '+t.count+' '+(t.count===1?'sale':'sales')+'.';
    if(t.pct != null && t.usual) line += ' By now you usually have about '+fmtMoney(t.expectedNow)+', so you are '+brainFmtPct(t.pct)+'.';
    else if(t.usual) line += ' A normal '+['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][now.getDay()]+' brings about '+fmtMoney(t.usual)+'.';
    items.push({ id:'today', level: t.pct != null && t.pct <= -35 && now.getHours() >= 12 ? 'med' : 'info', text:line });
  }
  var re = reorderSuggestions();
  if(re.length){
    var r0 = re[0], when = r0.stock <= 0 ? 'is out of stock' : (r0.daysLeft === Infinity ? 'is low' : 'will run out in about '+Math.max(1,Math.round(r0.daysLeft))+' '+(Math.round(r0.daysLeft)<=1?'day':'days'));
    items.push({ id:'reorder', level:'med', text:r0.product.name+' '+when+(re.length>1 ? ', and '+(re.length-1)+' more '+(re.length===2?'product needs':'products need')+' restocking.' : '.'), go:'reorder', label:'Open reorder list' });
  }
  var late = lateCustomers();
  if(late.length){ var owed = late.reduce(function(s,c){ return s+c.balance; },0); items.push({ id:'late', level:'high', text:late.length+' '+(late.length===1?'customer has':'customers have')+' not paid for over '+CREDIT_LATE_DAYS+' days, '+fmtMoney(owed)+' in all. '+late[0].name+' owes the most.', go:'customers', label:'Open customers' }); }
  var tr2 = brainTrends();
  if(tr2.up.length) items.push({ id:'up', level:'info', text:tr2.up[0].name+' is selling faster than usual: '+tr2.up[0].week+' this week against '+(tr2.up[0].avg < 1 ? 'almost none' : 'about '+Math.round(tr2.up[0].avg))+' in a normal week. Check you have enough.' });
  if(tr2.down.length) items.push({ id:'down', level:'info', text:tr2.down[0].name+' has slowed down: '+tr2.down[0].week+' this week against about '+Math.round(tr2.down[0].avg)+' in a normal week.' });
  var dead = brainDeadStock(45);
  if(dead.length){ var tied = dead.reduce(function(s,d){ return s+d.tied; },0); items.push({ id:'dead', level:'info', text:dead.length+' '+(dead.length===1?'product has':'products have')+' not sold in 45 days'+(tied>0 ? ' and '+fmtMoney(tied)+' of your money sits in them' : '')+'. Consider a special price. The biggest is '+dead[0].product.name+'.', go:'insights', label:'Deeper insights' }); }
  var thin = brainThinMargin();
  if(thin.length) items.push({ id:'thin', level:'med', text:thin[0].product.name+' earns only '+thin[0].margin+'% after cost'+(thin.length>1 ? ', and '+(thin.length-1)+' more earn under 10%' : '')+'. Check the price.', go:'risk', label:'Risk warnings' });
  return items;
}
function brainAlerts(){
  var out = [];
  try{
    var now = new Date(), t = brainToday(now);
    if(t.pct != null && t.usual && now.getHours() >= 13 && t.pct <= -40 && t.expectedNow > 0)
      out.push({ id:'slowday', level:'info', notify:true, title:'Quiet day so far', body:'Sales are '+Math.abs(t.pct)+'% below what you usually have by now.' });
    var dead = brainDeadStock(60);
    if(dead.length >= 3) out.push({ id:'deadstock', level:'info', title:dead.length+' products have not sold in 60 days', body:'Open Pesa Brain to see them and the money tied up.', go:'brain', label:'Open Pesa Brain' });
    var thin = brainThinMargin();
    if(thin.length) out.push({ id:'thinmargin', level:'info', title:thin.length+' '+(thin.length===1?'product earns':'products earn')+' under 10% after cost', body:thin[0].product.name+' earns '+thin[0].margin+'%.', go:'brain', label:'Open Pesa Brain' });
  }catch(e){}
  return out;
}
/* ---- Ask Pesa: plain questions answered from the shop's records ---- */
function brainPeriod(q){
  var now = new Date(), s = new Date(now.getFullYear(), now.getMonth(), now.getDate()), e = new Date(s.getTime()+DAY_MS), label = 'today';
  if(/yesterday/.test(q)){ s = new Date(s.getTime()-DAY_MS); e = new Date(s.getTime()+DAY_MS); label = 'yesterday'; }
  else if(/last month/.test(q)){ s = new Date(now.getFullYear(), now.getMonth()-1, 1); e = new Date(now.getFullYear(), now.getMonth(), 1); label = 'last month'; }
  else if(/(this )?month/.test(q)){ s = new Date(now.getFullYear(), now.getMonth(), 1); e = new Date(now.getTime()+1); label = 'this month'; }
  else if(/week/.test(q)){ s = new Date(now.getTime()-6*DAY_MS); s = new Date(s.getFullYear(), s.getMonth(), s.getDate()); e = new Date(now.getTime()+1); label = 'the last 7 days'; }
  else if(/year/.test(q)){ s = new Date(now.getFullYear(), 0, 1); e = new Date(now.getTime()+1); label = 'this year'; }
  return { s:s.getTime(), e:e.getTime(), label:label };
}
function brainFindProducts(q){
  var stop = /\b(how|many|much|do|i|we|have|has|is|are|the|of|a|an|in|on|stock|left|price|cost|costs|what|whats|what's|for|my|me|show|tell|got|much|does|to|sell|sold|sells|selling|quantity|qty|there|any|of|and)\b/g;
  var rest = q.replace(stop, ' ').replace(/[?.,!]/g, ' ').replace(/\s+/g, ' ').trim();
  return rest ? searchProducts(State.products, rest).slice(0, 4) : [];
}
function brainAnswer(raw){
  var q = String(raw||'').toLowerCase().trim();
  if(!q) return { text:'Type or say a question, for example: how much did I sell today?' };
  var per = brainPeriod(q);
  var sales = State.sales.filter(function(s){ var t = new Date(s.createdAt).getTime(); return t >= per.s && t < per.e; });
  var total = sales.reduce(function(a,s){ return a + (Number(s.total)||0); }, 0), cost = sales.reduce(function(a,s){ return a + (Number(s.cost)||0); }, 0);
  if(/(owe|owes|debt|debtor|credit|unpaid|late)/.test(q) && !/(sell|sold|sale)/.test(q)){
    var d = State.customers.filter(function(c){ return c.balance > 0; }).sort(function(a,b){ return b.balance - a.balance; });
    if(!d.length) return { text:'Nobody owes you anything right now.' };
    return { text:d.length+' '+(d.length===1?'customer owes':'customers owe')+' you '+fmtMoney(d.reduce(function(s,c){ return s+c.balance; },0))+' in all.', lines:d.slice(0,5).map(function(c){ return c.name+': '+fmtMoney(c.balance)+(customerDaysLate(c) >= CREDIT_LATE_DAYS ? ' (late)' : ''); }) };
  }
  if(/(profit|earn|made|margin)/.test(q) && !/(low|thin)/.test(q))
    return { text:'Profit for '+per.label+' is about '+fmtMoney(total-cost)+' on sales of '+fmtMoney(total)+' ('+(total>0?Math.round((total-cost)/total*100):0)+'% margin).' };
  if(/(expense|spent|spend)/.test(q)){
    var ex = State.expenses.filter(function(e){ var t = new Date(e.createdAt).getTime(); return t >= per.s && t < per.e; }).reduce(function(a,e){ return a + (Number(e.amount)||0); }, 0);
    return { text:'You spent '+fmtMoney(ex)+' on expenses '+per.label+'.' };
  }
  if(/(best|top|most popular|bestseller|best seller|popular)/.test(q)){
    var v = smartVelocity(30), arr = Object.keys(v).map(function(k){ return v[k]; }).sort(function(a,b){ return b.qty - a.qty; }).slice(0,5);
    if(!arr.length) return { text:'There are no sales in the last 30 days yet.' };
    return { text:'Your best sellers over the last 30 days:', lines:arr.map(function(a,i){ return (i+1)+'. '+a.name+': '+a.qty+' sold, '+fmtMoney(a.revenue); }) };
  }
  if(/(restock|reorder|re-order|run out|running out|running low|low stock|need to order|should i order|order)/.test(q)){
    var re = reorderSuggestions().slice(0,6);
    if(!re.length) return { text:'Nothing needs reordering. Every product has enough stock for now.' };
    return { text:re.length+' '+(re.length===1?'product needs':'products need')+' attention:', lines:re.map(function(r){ return r.product.name+': '+r.stock+' left'+(r.daysLeft===Infinity?'':', about '+Math.max(0,Math.floor(r.daysLeft))+' days')+', order about '+r.qty; }), go:'reorder', label:'Open reorder list' };
  }
  if(/(not selling|slow|dead|idle|stuck|nobody buys|no one buys)/.test(q)){
    var dd = brainDeadStock(45).slice(0,6);
    if(!dd.length) return { text:'Everything in stock has sold within the last 45 days.' };
    return { text:'These have not sold in 45 days:', lines:dd.map(function(x){ return x.product.name+': '+x.product.stockQty+' in stock'+(x.tied>0?', '+fmtMoney(x.tied)+' tied up':''); }) };
  }
  if(/(busy|peak|rush|hour|time of day|quiet)/.test(q)){
    var hrs = new Array(24).fill(0); smartSalesSince(30).forEach(function(s){ hrs[new Date(s.createdAt).getHours()] += Number(s.total)||0; });
    var top = hrs.map(function(x,h){ return {h:h,v:x}; }).filter(function(x){ return x.v>0; }).sort(function(a,b){ return b.v-a.v; }).slice(0,3);
    if(!top.length) return { text:'There are no sales in the last 30 days yet.' };
    return { text:'Your busiest hours over the last 30 days:', lines:top.map(function(x){ return String(x.h).padStart(2,'0')+':00 to '+String((x.h+1)%24).padStart(2,'0')+':00: '+fmtMoney(x.v); }) };
  }
  if(/(sold|sell|sales|sale|revenue|takings|turnover|made|income|how much did)/.test(q) && !/(how many).*(stock|have)/.test(q) && !brainFindProducts(q).length)
    return { text:'Sales for '+per.label+': '+fmtMoney(total)+' from '+sales.length+' '+(sales.length===1?'sale':'sales')+'.' };
  var found = brainFindProducts(q);
  if(found.length){
    return { text: found.length === 1 ? found[0].name : 'I found '+found.length+' products:', lines:found.map(function(p){
      var qty = p.stockQty == null ? 'stock not tracked' : p.stockQty+' '+(p.unit||'')+' in stock';
      var sold = smartVelocity(30)[p.id]; return p.name+': '+fmtMoney(p.sellPrice)+', '+qty.trim()+(sold ? ', '+sold.qty+' sold in 30 days' : ''); }) };
  }
  if(/(sold|sell|sales|revenue|takings)/.test(q)) return { text:'Sales for '+per.label+': '+fmtMoney(total)+' from '+sales.length+' '+(sales.length===1?'sale':'sales')+'.' };
  return { text:'I did not understand that yet. Try one of the examples below, or type a product name.' };
}
function brainCardHtml(){
  try{
    if(!State.session || isRestricted() || !State.ready.sales || !State.sales.length) return '';
    var b = brainBriefing(); if(!b.length) return '';
    var head = b[0].id === 'today' ? b[0].text : b[0].text;
    var more = Math.max(0, b.length - 1);
    return '<button type="button" id="brainCard" class="banner" style="display:block;width:100%;text-align:left;margin:8px 0;cursor:pointer;">' +
      '<div style="font-weight:600;margin-bottom:2px;">'+tr('Pesa Brain')+'</div><div style="font-size:13px;">'+esc(head)+'</div>' +
      (more ? '<div style="font-size:12px;color:var(--text-muted);margin-top:4px;">'+more+' '+tr(more===1?'more thing to look at':'more things to look at')+'</div>' : '') + '</button>';
  }catch(e){ return ''; }
}
function openBrainSheet(){
  var items = brainBriefing(), col = { high:'var(--danger)', med:'var(--warn, #d98e2b)', info:'var(--text)' };
  var ex = ['How much did I sell today?','What is my profit this week?','Who owes me money?','What should I reorder?','What is not selling?','Best sellers','When am I busiest?'];
  var html = '<div class="sheet-head"><h2>'+tr('Pesa Brain')+'</h2></div>' +
    '<div class="banner" style="display:block;">'+tr('Pesa studies your own records on this device and tells you what needs attention. Nothing is sent to anyone.')+'</div>' +
    '<div class="field" style="margin-top:10px;"><label>'+tr('Ask Pesa')+'</label><div style="display:flex;gap:8px;align-items:center;"><div class="searchbar" style="flex:1;"><input id="brQ" placeholder="'+esc(tr('Ask about your shop…'))+'" autocomplete="off"></div>' +
      (voiceSupported() ? '<button class="icon-btn" id="brMic" type="button" title="'+esc(tr('Voice search'))+'" style="flex:0 0 auto;">'+MIC_ICON+'</button>' : '') +
      '<button class="btn btn-primary" id="brGo" type="button">'+tr('Ask')+'</button></div>' +
    '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:8px;">'+ex.map(function(e){ return '<button class="btn btn-ghost" type="button" data-br-ex="'+esc(e)+'" style="padding:5px 9px;font-size:12px;">'+esc(tr(e))+'</button>'; }).join('')+'</div></div>' +
    '<div id="brAns" aria-live="polite"></div>' +
    '<div class="sheet-head" style="margin-top:14px;"><h3 style="margin:0;font-size:15px;">'+tr('Right now')+'</h3></div>' +
    (items.length ? '<div class="rowlist">' + items.map(function(a,i){
      return '<div class="row"><div class="main"><div class="sub" style="color:'+col[a.level]+';white-space:normal;">'+esc(a.text)+'</div></div>' +
        (a.go ? '<div class="trail"><button class="btn btn-ghost" data-br-go="'+i+'" type="button">'+tr(a.label||'Open')+'</button></div>' : '') + '</div>';
    }).join('') + '</div>' : '<div class="empty"><div class="t">'+tr('All clear')+'</div><div class="s">'+tr('Make a few sales and Pesa Brain will start learning your shop.')+'</div></div>') +
    smartBackBtn();
  var ov = openSheet(html);
  wireSmartBack(ov);
  var inp = ov.querySelector('#brQ'), ans = ov.querySelector('#brAns');
  function ask(t){
    var r = brainAnswer(t); if(inp) inp.value = t;
    ans.innerHTML = '<div class="banner" style="display:block;margin-top:10px;"><div style="font-weight:600;">'+esc(r.text)+'</div>' +
      (r.lines ? '<div style="margin-top:6px;font-size:13px;line-height:1.5;">'+r.lines.map(function(l){ return '<div>'+esc(l)+'</div>'; }).join('')+'</div>' : '') +
      (r.go ? '<div style="margin-top:8px;"><button class="btn btn-ghost" id="brAnsGo" type="button">'+tr(r.label||'Open')+'</button></div>' : '') + '</div>';
    var g = ans.querySelector('#brAnsGo'); if(g) g.addEventListener('click', function(){ closeModal(); openSmartSection(r.go); });
  }
  ov.querySelector('#brGo').addEventListener('click', function(){ ask(inp.value); });
  inp.addEventListener('keydown', function(e){ if(e.key === 'Enter'){ e.preventDefault(); ask(inp.value); } });
  ov.querySelectorAll('[data-br-ex]').forEach(function(b){ b.addEventListener('click', function(){ ask(b.getAttribute('data-br-ex')); }); });
  var mic = ov.querySelector('#brMic'); if(mic) mic.addEventListener('click', function(){ startVoiceSearch(mic, ask); });
  ov.querySelectorAll('[data-br-go]').forEach(function(b){ b.addEventListener('click', function(){ var a = items[+b.getAttribute('data-br-go')]; closeModal(); openSmartSection(a.go); }); });
}
// Runs quietly: at most one device notification per alert per day.
function smartTick(){
  try{
    if(!State.session || isRestricted()) return;
    var al = smartAlerts();
    try{ if(navigator.setAppBadge){ if(al.length) navigator.setAppBadge(al.length).catch(function(){}); else if(navigator.clearAppBadge) navigator.clearAppBadge().catch(function(){}); } }catch(e){}
    if(!notifyActive() && !emailAlertsOn()) return;
    var key = 'pesa_smart_notified_' + WS.id, seen = {};
    try{ seen = JSON.parse(localStorage.getItem(key) || '{}') || {}; }catch(e){}
    var today = todayKey();
    al.filter(function(a){ return (a.level === 'high' || a.notify) && seen[a.id] !== today; }).forEach(function(a){
      showDeviceNotification(a.title, a.body, 'pesa-smart-'+a.id); seen[a.id] = today;
    });
    try{ localStorage.setItem(key, JSON.stringify(seen)); }catch(e){}
  }catch(e){}
}

function smartBackBtn(){ return '<div class="actions"><button class="btn btn-ghost btn-block" id="smBack" type="button">'+tr(State.session ? 'Back to Smart Tools' : 'Close')+'</button></div>'; }
function wireSmartBack(ov){ var b = ov.querySelector('#smBack'); if(b) b.addEventListener('click', function(){ closeModal(); if(State.session) openSmartToolsSheet(); }); }
function smartBar(pct, color){ return '<div style="height:8px;border-radius:4px;background:var(--surface-2);overflow:hidden;"><div style="height:100%;width:'+Math.max(2,Math.min(100,pct))+'%;background:'+(color||'var(--primary)')+';"></div></div>'; }

/* ---- hub ---- */
function openSmartToolsSheet(){
  var al = smartAlerts();
  var tiles = [
    ['brain','Pesa Brain','Ask Pesa, daily briefing, what to do next'],
    ['alerts','Alert centre', al.length ? al.length+' need attention' : 'All clear'],
    ['reorder','Reorder list', reorderSuggestions().length+' suggested'],
    ['insights','Deeper insights','Best sellers, busy hours, forecast'],
    ['risk','Risk warnings','Shortages, sales below cost, deletions'],
    ['agent','Pesa AI Assistant','Daily reorder draft, risk watch, month end filing'],
    ['customers','Customer profiles','Credit limits and reminders'],
    ['reconcile','End of day check','Cash, card and wallet totals'],
    ['backups','Automatic backups','Daily snapshots and restore'],
    ['health','Data health check','Storage, backup, connection'],
    ['nearby','Nearby Wi-Fi sync','Connect two devices with no internet'],
    ['whatsnew','What’s new','Latest changes in Pesa']
  ];
  var html = '<div class="sheet-head"><h2>'+tr('Pesa Smart Tools')+'</h2></div>' +
    '<div class="banner" style="display:block;">'+tr('These tools work from your own shop records on this device. Nothing is sent to anyone.')+'</div>' +
    '<div class="rowlist">' + tiles.map(function(t){
      return '<button class="row" type="button" data-smart="'+t[0]+'" style="width:100%;text-align:left;">' +
        '<div class="main"><div class="title">'+tr(t[1])+'</div><div class="sub">'+tr(t[2])+'</div></div></button>';
    }).join('') + '</div>';
  var ov = openSheet(html);
  ov.querySelectorAll('[data-smart]').forEach(function(b){
    b.addEventListener('click', function(){ var k = b.getAttribute('data-smart'); closeModal(); openSmartSection(k); });
  });
}
function openSmartSection(k){
  if(k==='brain') openBrainSheet();
  else if(k==='alerts') openAlertCentreSheet();
  else if(k==='reorder') openReorderSheet();
  else if(k==='insights') openDeepInsightsSheet();
  else if(k==='risk') openRiskSheet();
  else if(k==='agent') openAgentSheet();
  else if(k==='customers') openCustomerProfilesSheet();
  else if(k==='reconcile') openReconcileSheet();
  else if(k==='backups') openBackupsSheet();
  else if(k==='accountant') openAccountantSheet();
  else if(k==='health') openHealthSheet();
  else if(k==='nearby') openNearbySheet();
  else if(k==='whatsnew') openWhatsNewSheet();
  else if(k.indexOf('biz:') === 0) openBizSection(k.slice(4));
}

/* ---- alert centre ---- */
