/* ============================== AUTOMATIC BACKUPS ==============================
   A snapshot of the business is saved on this device once a day while Pesa is
   open (owner or manager login), keeping the latest 7. They live in the
   browser's own database on this device only. Clearing the browser's data
   removes them, so download a copy now and then. */
/* Safety net: an unexpected error must never leave the person guessing. Show one calm,
   throttled message (not for every error) and keep going. Records are not touched here. */
var _errN = 0, _errAt = 0;
function safetyNote(msg){
  var m = String((msg && msg.message) || msg || '');
  if(!m || /^script error|resizeobserver|loading chunk|network ?error|failed to fetch|load failed|abort|serviceworker|service worker/i.test(m)) return;
  var now = Date.now();
  if(_errN >= 3 || now - _errAt < 15000) return;
  _errN++; _errAt = now;
  var det=''; try{ var st=(msg&&msg.stack)||''; det=m.slice(0,90)+(st?' @ '+String(st).split('\n').slice(1,2).join('').replace(/https?:\/\/[^ )]*\//,'').trim().slice(0,70):''); localStorage.setItem('pesa_lasterr', new Date().toISOString()+' '+det); }catch(e){}
  try{ toast(tr('Pesa hit a snag. Your saved records are not affected. If something looks stuck, reload the page.')+(det?' ['+det+']':'')); }catch(e){}
}
window.addEventListener('error', function(e){ if(e && e.target && e.target !== window) return; safetyNote(e && (e.error || e.message)); });
window.addEventListener('unhandledrejection', function(e){ safetyNote(e && e.reason); });

var APP_VERSION = '2026.10.213';
/* ---- newer version check: a tiny version note is read straight from the network; if it is newer, an Update now bar appears ---- */
/* An update or reconnect reload must never feel like a sign out: the signed in person stays signed in, a fingerprint lock is not asked again
   for this reload, and a sale in progress (the cart) is kept. Only this tab's own storage is used, and it is used once. */
function pesaKeepForReload(){
  try{
    if(!State.session) return;
    _sessTouchAt = 0; sessionTouch();
    sessionStorage.setItem('pesa_after_update', String(Date.now()));
    if(State.cart && State.cart.length) sessionStorage.setItem('pesa_cart_keep', JSON.stringify(State.cart));
  }catch(e){}
}
function pesaAfterUpdateFresh(){
  try{ var t = parseInt(sessionStorage.getItem('pesa_after_update') || '0', 10); return !!t && Date.now() - t < 3*60000; }catch(e){ return false; }
}
function pesaRestoreKept(){
  try{
    var raw = sessionStorage.getItem('pesa_cart_keep'); if(!raw) return;
    if(!State.session || !(State.ready && State.ready.products)){ if((pesaRestoreKept._n = (pesaRestoreKept._n||0) + 1) < 12) setTimeout(pesaRestoreKept, 1000); return; }
    sessionStorage.removeItem('pesa_cart_keep');
    var cart = JSON.parse(raw);
    if(Array.isArray(cart) && cart.length && !(State.cart && State.cart.length)){
      State.cart = cart.filter(function(i){ return State.products.some(function(p){ return p.id === i.productId; }); });
      try{ renderCartBar(); }catch(e){}
      if(State.cart.length) toast(tr('Pesa updated. Your sale in progress was kept.'));
    }
  }catch(e){}
}
function pesaVerNewer(a, b){
  var x = String(a||'').split('.').map(Number), y = String(b||'').split('.').map(Number);
  for(var i=0; i<Math.max(x.length, y.length); i++){ var d = (x[i]||0) - (y[i]||0); if(d) return d > 0; }
  return false;
}
function pesaCheckVersion(manual){
  try{
    if(navigator.onLine === false){ if(manual) toast(tr('You are offline. Pesa keeps working and will update when you are connected.')); return; }
    fetch('version.json?t=' + Date.now(), { cache:'no-store' }).then(function(r){ return r.ok ? r.json() : Promise.reject(); }).then(function(j){
      if(j && pesaVerNewer(j.version, APP_VERSION)){ _pesaNewVer = String(j.version); pesaShowUpdateBar(j.version); pesaAutoTry(); }
      else if(manual) toast(tr('You already have the newest version.') + ' (' + APP_VERSION + ')');
    }).catch(function(){ if(manual) toast(tr('Could not check for updates right now. Try again when the connection is better.')); });
  }catch(e){}
}
/* A new version applies by itself only when nobody is signed in (nothing to lose, and it has not already been tried in this session, so a slow
   download can never cause a reload loop). Someone who is signed in is never reloaded: the Update now bar stays until they tap it. */
var _pesaNewVer = '', _pesaLastAct = Date.now();
(function(){
  try{
    ['pointerdown', 'keydown', 'input', 'touchstart', 'wheel'].forEach(function(ev){ document.addEventListener(ev, function(){ _pesaLastAct = Date.now(); }, true); });
    document.addEventListener('visibilitychange', function(){ if(document.hidden){ _pesaHiddenAt = Date.now(); } else { if(_pesaHiddenAt && Date.now() - _pesaHiddenAt > 20000) _pesaLastAct = 0; try{ pesaCheckVersion(false); }catch(e){} setTimeout(pesaAutoTry, 1500); } });
    setInterval(function(){ if(_pesaNewVer) pesaAutoTry(); }, 15000);
  }catch(e){}
})();
var _pesaHiddenAt = 0;
function pesaSafeToUpdate(){
  try{
    if(!State.session) return true;                                  // nobody signed in: nothing to lose
    if(pfBusy()) return false;                                       // a sheet, a form or the till is open
    var a = document.activeElement; if(a && /^(INPUT|TEXTAREA|SELECT)$/.test(a.tagName) && String(a.value || '').length) return false;
    return Date.now() - _pesaLastAct > 25000;                        // paused for a moment, or just came back to the app
  }catch(e){ return false; }
}
function pesaAutoTry(){
  try{
    if(!_pesaNewVer || !pesaVerNewer(_pesaNewVer, APP_VERSION)) return;
    if(navigator.onLine === false || State.session || !pesaSafeToUpdate()) return;   // never reload under someone who is signed in: they tap Update now when ready
    var key = 'pesa_auto_upd_' + _pesaNewVer;
    if(sessionStorage.getItem(key)) return;                          // already tried this version in this session
    sessionStorage.setItem(key, '1');
    toast(tr('Updating Pesa to the newest version...'));
    setTimeout(pesaForceRefresh, 700);
  }catch(e){}
}
function pesaShowUpdateBar(v){
  if(document.getElementById('pesaUpdBar')) return;
  var b = document.createElement('div'); b.id = 'pesaUpdBar';
  b.setAttribute('style', 'position:fixed;left:12px;right:12px;bottom:calc(76px + env(safe-area-inset-bottom,0px));z-index:9998;display:flex;align-items:center;gap:10px;padding:11px 12px;border-radius:16px;background:linear-gradient(135deg,#075E47,#0B7A5C 55%,#14A37A);color:#fff;box-shadow:0 14px 30px -12px rgba(0,60,40,.7);font:600 13.5px Inter,system-ui,sans-serif;max-width:520px;margin:0 auto;');
  b.innerHTML = '<span style="flex:1;min-width:0;">' + esc(tr('A newer version of Pesa is ready')) + ' (' + esc(v) + ')</span>' +
    '<button type="button" id="pesaUpdGo" style="border:0;border-radius:12px;padding:8px 14px;font:800 13px Inter,system-ui,sans-serif;background:#F2B53A;color:#3D2A02;cursor:pointer;">' + esc(tr('Update now')) + '</button>' +
    '<button type="button" id="pesaUpdX" aria-label="' + esc(tr('Close')) + '" style="border:0;background:transparent;color:#fff;font-size:20px;line-height:1;cursor:pointer;padding:0 4px;">×</button>';
  document.body.appendChild(b);
  b.querySelector('#pesaUpdX').addEventListener('click', function(){ b.remove(); });
  b.querySelector('#pesaUpdGo').addEventListener('click', pesaForceRefresh);
}
function pesaForceRefresh(){
  var go = function(){ pesaKeepForReload(); try{ location.reload(); }catch(e){} };
  // download the newest page first and save it into the app cache, then reload from that saved copy. Nothing is deleted,
  // so a weak mobile connection can never leave Pesa without a copy, and the reload itself needs no network.
  toast(tr('Downloading the update...'));
  fetch('index.html', { cache:'no-store' }).then(function(r){
    if(!r.ok) throw new Error('x');
    var copy = r.clone();
    return r.text().then(function(txt){
      if(!(window.caches && caches.keys)) return null;
      // the page loads its code from app.js (named with the version), so the matching code is saved too
      var mj = txt.match(/<script src="(app\.js\?v=[^"]+)">/);
      var jsReq = mj ? fetch(mj[1], { cache:'no-store' }).then(function(jr){ if(!jr.ok) throw new Error('x'); return jr; }) : Promise.resolve(null);
      return jsReq.then(function(jr){
        return caches.keys().then(function(ks){
          var cur = ks.filter(function(k){ return /^pesa-shell-/.test(k); }).sort().pop();
          if(!cur) return null;
          return caches.open(cur).then(function(c){
            return (jr ? c.put(new Request('./' + mj[1]), jr) : Promise.resolve()).then(function(){ return c.put(new Request('./index.html'), copy); });
          });
        });
      });
    });
  }).then(function(){
    var reg = (navigator.serviceWorker && navigator.serviceWorker.getRegistration) ? navigator.serviceWorker.getRegistration() : Promise.resolve();
    return reg.then(function(rg){ try{ return rg && rg.update().catch(function(){}); }catch(e){} }).catch(function(){});
  }).then(go, function(){ try{ toast(tr('Could not download the update. Try again when the connection is better.')); }catch(e){} });
}
function backupPayload(){
  return {
    exportedAt: new Date().toISOString(),
    appVersion: APP_VERSION,
    shop: State.settings,
    products: State.products.filter(function(p){ return !p.isMock; }), customers: State.customers, sales: State.sales, expenses: State.expenses,
    invoices: State.invoices, reports: State.reports, suppliers: State.suppliers, purchaseOrders: State.purchaseOrders,
    branches: State.branches, wastage: State.wastage, tillSessions: State.tillSessions,
    posDevices: State.posDevices, posBatches: State.posBatches, messages: State.messages, workReports: State.workReports,
    stockTakes: State.stockTakes, stockMoves: State.stockMoves, supplierInvoices: State.supplierInvoices, supplierPayments: State.supplierPayments, supplierStatements: State.supplierStatements, channelLogs: State.channelLogs, entTransfers: State.entTransfers,
    quotes: State.quotes, recurring: State.recurring, loyaltyLog: State.loyaltyLog, accountingPeriods: State.accountingPeriods, payRuns: State.payRuns, courseProgress: State.courseProgress, deletedRecords: State.deletedRecords, clockLogs: State.clockLogs, tips: State.tips, calEvents: State.calEvents
  };
}
// Customer ledgers live under each customer, so they are read separately.
function gatherLedgers(){
  var out = {};
  return Promise.all(State.customers.map(function(c){
    return new Promise(function(resolve){
      var done = false, un = null, t = setTimeout(function(){ if(!done){ done = true; try{ un && un(); }catch(e){} resolve(); } }, 1500);
      try{
        un = refs.customers.doc(c.id).collection('ledger').onSnapshot(function(docs){
          if(done) return; done = true; clearTimeout(t);
          out[c.id] = docs.map(function(d){ return Object.assign({id:d.id}, d.data); });
          try{ un && un(); }catch(e){} resolve();
        });
      }catch(e){ done = true; clearTimeout(t); resolve(); }
    });
  })).then(function(){ return out; });
}
async function restoreBackupData(data){
  var chk = backupCheck(data);
  if(!chk.ok) throw new Error('Backup refused: ' + chk.problems.join(' '));
  if((await backupSealOk(data)) === false) throw new Error('Backup refused: the file was changed or cut off after it was saved.');
  try{ await Backups.make('before restore'); }catch(e){}
  delete data.integrity; if(data.shop){ delete data.shop.syncServiceKey; }
  if(data.shop){ State.settings = Object.assign({}, State.settings, data.shop); refs.settings.set(State.settings); }
  var put = async function(colRef, rows){
    if(!Array.isArray(rows)) return;
    for(var i=0;i<rows.length;i++){ var row = Object.assign({}, rows[i]); var id = row.id; delete row.id; await colRef.doc(id).set(row); }
  };
  await put(refs.products, data.products); await put(refs.customers, data.customers); await put(refs.sales, data.sales);
  await put(refs.expenses, data.expenses); await put(refs.invoices, data.invoices); await put(refs.reports, data.reports);
  await put(refs.suppliers, data.suppliers); await put(refs.purchaseOrders, data.purchaseOrders);
  await put(refs.branches, data.branches); await put(refs.wastage, data.wastage); await put(refs.tills, data.tillSessions);
  await put(refs.posDevices, data.posDevices); await put(refs.posBatches, data.posBatches); await put(refs.messages, data.messages); await put(refs.workReports, data.workReports);
  await put(refs.stockTakes, data.stockTakes); await put(refs.stockMoves, data.stockMoves); await put(refs.supplierInvoices, data.supplierInvoices);
  await put(refs.supplierPayments, data.supplierPayments); await put(refs.supplierStatements, data.supplierStatements); await put(refs.channelLogs, data.channelLogs); await put(refs.entTransfers, data.entTransfers);
  await put(refs.quotes, data.quotes); await put(refs.recurring, data.recurring); await put(refs.loyaltyLog, data.loyaltyLog); await put(refs.accountingPeriods, data.accountingPeriods); await put(refs.payRuns, data.payRuns); await put(refs.courseProgress, data.courseProgress); await put(refs.deletedRecords, data.deletedRecords); await put(refs.clockLogs, data.clockLogs); await put(refs.tips, data.tips); await put(refs.calEvents, data.calEvents);
  if(data.ledgers){
    for(var cid in data.ledgers){ await put(refs.customers.doc(cid).collection('ledger'), data.ledgers[cid]); }
  }
}
var Backups = (function(){
  var DB = 'pesa_backups_v1', STORE = 'snaps', KEEP = 7, running = false;
  function lastKey(){ return 'pesa_backup_last_' + WS.id; }
  function open(){
    return new Promise(function(res, rej){
      if(!window.indexedDB) return rej(new Error('no indexedDB'));
      var r = indexedDB.open(DB, 1);
      r.onupgradeneeded = function(){ r.result.createObjectStore(STORE, { keyPath:'key' }); };
      r.onsuccess = function(){ res(r.result); }; r.onerror = function(){ rej(r.error); };
    });
  }
  function tx(mode, fn){
    return open().then(function(db){ return new Promise(function(res, rej){
      var t = db.transaction(STORE, mode), st = t.objectStore(STORE), out = fn(st);
      t.oncomplete = function(){ res(out && out.result !== undefined ? out.result : undefined); db.close(); }; t.onerror = function(){ rej(t.error); db.close(); };
    }); });
  }
  function list(){
    return tx('readonly', function(st){ return st.getAll(); }).then(function(rows){
      return (rows||[]).filter(function(r){ return r.ws === WS.id; }).sort(function(a,b){ return b.at - a.at; });
    });
  }
  async function make(reason){
    if(running) return null; running = true;
    try{
      var data = backupPayload(); data.ledgers = await gatherLedgers();
      var json = JSON.stringify(data), at = Date.now();
      var snap = { key: WS.id+'|'+at, ws: WS.id, at: at, reason: reason||'auto', json: json, size: json.length, sha: await sha256Hex(json), app: APP_VERSION,
        counts: { products:State.products.length, customers:State.customers.length, sales:State.sales.length } };
      await tx('readwrite', function(st){ return st.put(snap); });
      try{ BackupFolder.writeJson(json, at); }catch(e){}
      try{ snap.verified = await backupVerifyKey(snap.key); }catch(e){}
      var all = await list();
      for(var i=KEEP;i<all.length;i++){ await tx('readwrite', function(st){ return st.delete(all[i].key); }); }
      try{ localStorage.setItem(lastKey(), String(at)); }catch(e){}
      return snap;
    }catch(e){ return null; }
    finally{ running = false; }
  }
  function lastAt(){ try{ return parseInt(localStorage.getItem(lastKey()) || '0', 10) || 0; }catch(e){ return 0; } }
  function ready(){ return State.ready.products && State.ready.customers && State.ready.sales && State.ready.expenses && State.ready.settings; }
  function auto(){
    try{
      if(!State.session || isRestricted() || !ready()) return;
      if(!State.products.length && !State.sales.length && !State.customers.length) return;
      if(Date.now() - lastAt() < 20*3600000) return;
      make('auto');
    }catch(e){}
  }
  return { list:list, make:make, lastAt:lastAt, auto:auto, remove:function(k){ return tx('readwrite', function(st){ return st.delete(k); }); }, get:function(k){ return tx('readonly', function(st){ return st.get(k); }); } };
})();
function fmtBytes(n){ return n > 1048576 ? (n/1048576).toFixed(1)+' MB' : Math.max(1,Math.round(n/1024))+' KB'; }
function openBackupsSheet(){
  var html = '<div class="sheet-head"><h2>'+tr('Automatic backups')+'</h2></div>' +
    '<div class="banner" style="display:block;">'+tr('Pesa saves a backup on this device about once a day while it is open, and keeps the latest 7. They stay on this device only. If you clear your browser data or lose the device, they go too, so download a copy now and then.')+'</div>' +
    '<div id="bkFolder"></div>' +
    '<div class="actions"><button class="btn btn-primary btn-block" id="bkNow" type="button">'+tr('Back up now')+'</button><button class="btn btn-ghost btn-block" id="bkSend" type="button">'+tr('Send a copy by WhatsApp, email or Drive')+'</button></div><div id="bkList" style="margin-top:10px;"></div>' + smartBackBtn();
  var ov = openSheet(html); wireSmartBack(ov);
  btBackupFolderPaint(ov.querySelector('#bkFolder'));
  function paint(){
    Backups.list().then(function(rows){
      ov.querySelector('#bkList').innerHTML = rows.length ? '<div class="rowlist">' + rows.map(function(r){
        return '<div class="row"><div class="main"><div class="title">'+fmtDateTime(new Date(r.at).toISOString())+'</div><div class="sub">'+(r.counts?r.counts.products+' '+tr('products')+', '+r.counts.customers+' '+tr('customers')+', '+r.counts.sales+' '+tr('sales')+' · ':'')+fmtBytes(r.size)+' · '+(r.reason==='auto'?tr('automatic'):tr('manual'))+'</div></div>' +
          '<div class="trail" style="display:flex;gap:6px;"><button class="btn btn-ghost" data-bk-dl="'+r.key+'" type="button">'+tr('Download')+'</button><button class="btn btn-ghost" data-bk-rs="'+r.key+'" type="button">'+tr('Restore')+'</button></div></div>';
      }).join('') + '</div>' : '<div class="empty"><div class="t">'+tr('No backups yet')+'</div></div>';
      ov.querySelectorAll('[data-bk-dl]').forEach(function(b){ b.addEventListener('click', function(){
        Backups.get(b.getAttribute('data-bk-dl')).then(function(r){ if(r){ downloadTextFile('pesa-backup-'+todayKey(new Date(r.at))+'.json', r.json); bkMarkOutside(); } });
      }); });
      ov.querySelectorAll('[data-bk-rs]').forEach(function(b){ b.addEventListener('click', function(){
        Backups.get(b.getAttribute('data-bk-rs')).then(function(r){
          if(!r) return;
          confirmSheet(tr('Restore this backup?'), tr('This puts the records from this backup back into Pesa (products, customers and their ledgers, sales, expenses, invoices, reports, suppliers, purchase orders, branches, wastage and tills). Records made after the backup are kept.'), tr('Restore'), function(){
            restoreBackupData(JSON.parse(r.json)).then(function(){ toast(tr('Backup restored')); }, function(){ toast(tr('Restore failed')); });
          }, true, true);
        });
      }); });
    }, function(){ ov.querySelector('#bkList').innerHTML = '<div class="banner">'+tr('This browser does not allow backups to be stored here.')+'</div>'; });
  }
  ov.querySelector('#bkSend').addEventListener('click', btShareBackup);
  ov.querySelector('#bkNow').addEventListener('click', function(){
    var b = ov.querySelector('#bkNow'); b.disabled = true;
    try{ BackupFolder.renew(); }catch(e){}
    Backups.make('manual').then(function(s){ b.disabled = false; toast(s ? tr('Backup saved') : tr('Could not save a backup')); paint(); });
  });
  paint();
}
function downloadTextFile(filename, text){
  (async function(){
    try{
      if(window.claude && window.claude.use){ var dl = await window.claude.use('downloads'); if(dl){ await dl.save({ filename:filename, data:text }); toast(tr('Download ready')); return; } }
    }catch(e){}
    try{
      var blob = new Blob([text], { type:'application/json' }), url = URL.createObjectURL(blob), a = document.createElement('a');
      a.href = url; a.download = filename; document.body.appendChild(a); a.click(); document.body.removeChild(a);
      setTimeout(function(){ URL.revokeObjectURL(url); }, 4000);
    }catch(e){ toast(tr('Could not download')); }
  })();
}

/* ============================== DATA HEALTH CHECK ============================== */
async function healthChecks(){
  var out = [];
  function add(level, title, body, fix){ out.push({ level:level, title:title, body:body, fix:fix }); }
  var bk = Backups.lastAt();
  if(!bk) add('bad','No backup yet','Tap Automatic backups and back up now.');
  else { var d = Math.floor((Date.now()-bk)/DAY_MS); add(d <= 2 ? 'ok' : 'warn', d <= 2 ? 'Backup is up to date' : 'Backup is '+d+' days old', 'Last backup: '+fmtDateTime(new Date(bk).toISOString())+'.'); }
  try{
    if(navigator.storage && navigator.storage.estimate){
      var e = await navigator.storage.estimate(), pct = e.quota ? Math.round(e.usage/e.quota*100) : 0;
      add(pct < 60 ? 'ok' : (pct < 85 ? 'warn' : 'bad'), 'Storage used: '+fmtBytes(e.usage||0)+' ('+pct+'%)', pct < 60 ? 'Plenty of room left on this device.' : 'Free some space or download and clear old backups.');
    }
    if(navigator.storage && navigator.storage.persisted){
      var p = await navigator.storage.persisted();
      add(p ? 'ok' : 'warn', p ? 'Data is protected from automatic clean up' : 'Data is not protected from automatic clean up', p ? 'The browser will not delete Pesa data to free space.' : 'Some browsers may delete site data when the phone is very low on space.', p ? null : 'persist');
    }
  }catch(e){}
  add(navigator.onLine ? 'ok' : 'warn', navigator.onLine ? 'This device is online' : 'This device is offline', navigator.onLine ? 'Updates and cloud connection can work.' : 'Pesa works offline. Connect to the internet to get updates and to sync.');
  try{
    var ss = Sync.status();
    if(ss.state === 'off') add('warn','Cloud connection is off','Devices are not connected. Turn it on in Settings, Advanced Pesa Connection settings, if you use more than one device.');
    else if(ss.state === 'error') add('bad','Cloud connection has a problem', Sync.lastError() || 'It will retry automatically.');
    else if(ss.state === 'cloud') add('ok','Saving to Claude storage','This is the preview copy.');
    else add(ss.state === 'ok' ? 'ok':'warn', 'Cloud connection: '+ss.label, 'Changes waiting: '+(ss.state==='pending'?ss.label:'none')+'.');
  }catch(e){}
  var swOk = !!(navigator.serviceWorker && navigator.serviceWorker.controller);
  add(swOk ? 'ok' : 'warn', swOk ? 'Ready to run offline' : 'Not yet saved for offline use', swOk ? 'Pesa has saved itself on this device.' : 'Open Pesa once with internet and let it finish loading.');
  add(notifyActive() ? 'ok' : 'warn', notifyActive() ? 'Alerts are on' : 'Device alerts are off', notifyActive() ? 'You will get low stock and late payment alerts.' : 'Turn them on in Settings, Notifications.');
  return out;
}
function openHealthSheet(){
  var html = '<div class="sheet-head"><h2>'+tr('Data health check')+'</h2></div><div id="hcBody"><div class="banner">'+tr('Checking…')+'</div></div>' + '<div class="actions"><button class="btn btn-ghost btn-block" id="hcSpeed" type="button">'+tr('Speed check and test products')+'</button></div>' + smartBackBtn();
  var ov = openSheet(html); wireSmartBack(ov);
  healthChecks().then(function(list){
    var col = { ok:'var(--success)', warn:'var(--warn, #d98e2b)', bad:'var(--danger)' }, mark = { ok:'OK', warn:'CHECK', bad:'FIX' };
    var bad = list.filter(function(x){ return x.level==='bad'; }).length, warn = list.filter(function(x){ return x.level==='warn'; }).length;
    ov.querySelector('#hcBody').innerHTML = '<div class="banner" style="display:block;"><b>'+(bad ? tr('Needs attention') : (warn ? tr('Mostly good') : tr('All good')))+'</b></div><div class="rowlist">' + list.map(function(x){
      return '<div class="row"><div class="main"><div class="title">'+esc(tr(x.title))+'</div><div class="sub">'+esc(tr(x.body))+'</div></div><div class="trail" style="color:'+col[x.level]+';font-weight:700;">'+(x.fix ? '<button class="btn btn-ghost" data-hc-fix="'+x.fix+'" type="button">'+tr('Protect')+'</button>' : mark[x.level])+'</div></div>';
    }).join('') + '</div>';
    var sp = ov.querySelector('#hcSpeed'); if(sp) sp.addEventListener('click', function(){ closeModal(); openSpeedSheet(); });
    var f = ov.querySelector('[data-hc-fix="persist"]');
    if(f) f.addEventListener('click', function(){ navigator.storage.persist().then(function(ok){ toast(ok ? tr('Data protected') : tr('The browser did not allow it')); }); });
  });
}

