/* ---- connection ---- */
var NB = { pc:null, dc:null, role:'', onState:null, inbox:[], handler:null };
// Messages can arrive before the sync screen is ready, so keep them until it is.
function nbAttachInbox(dc){ NB.inbox = []; NB.handler = null; dc.onmessage = function(e){ if(NB.handler) NB.handler(e); else NB.inbox.push(e); }; }
function nbClose(){ try{ NB.dc && NB.dc.close(); }catch(e){} try{ NB.pc && NB.pc.close(); }catch(e){} NB.pc = NB.dc = null; }
function nbNewPeer(){
  nbClose();
  var pc = new RTCPeerConnection({ iceServers: [] });   // no internet servers: same Wi-Fi only
  NB.pc = pc;
  pc.onconnectionstatechange = function(){ if(NB.onState) NB.onState(pc.connectionState); };
  return pc;
}
function nbGather(pc){
  return new Promise(function(res){
    if(pc.iceGatheringState === 'complete') return res();
    var t = setTimeout(res, 5000);
    pc.addEventListener('icegatheringstatechange', function(){ if(pc.iceGatheringState === 'complete'){ clearTimeout(t); res(); } });
  });
}
async function nbHostCode(){
  var pc = nbNewPeer(); NB.role = 'host';
  NB.dc = pc.createDataChannel('pesa', { ordered:true }); nbAttachInbox(NB.dc);
  var offer = await pc.createOffer(); await pc.setLocalDescription(offer); await nbGather(pc);
  return nbEncode({ ws:WS.id === 'default' ? '' : WS.id, s:pc.localDescription.sdp, y:'o' });
}
async function nbAcceptAnswer(code){
  var o = await nbDecode(code); if(o.y !== 'a') throw new Error('That is not a reply code. Use the code shown on the other device after it joined.');
  await NB.pc.setRemoteDescription({ type:'answer', sdp:o.s });
}
async function nbJoinCode(code){
  var o = await nbDecode(code); if(o.y !== 'o') throw new Error('That is not a start code. Use the code shown on the first device.');
  var pc = nbNewPeer(); NB.role = 'join';
  pc.ondatachannel = function(e){ NB.dc = e.channel; nbAttachInbox(NB.dc); if(NB.onChannel) NB.onChannel(); };
  await pc.setRemoteDescription({ type:'offer', sdp:o.s });
  var ans = await pc.createAnswer(); await pc.setLocalDescription(ans); await nbGather(pc);
  return nbEncode({ s:pc.localDescription.sdp, y:'a' });
}
/* ---- message protocol (chunked so large data fits) ---- */
function nbMessenger(dc, onMsg){
  var bufs = {}, seq = 0;
  function handle(e){
    var m = JSON.parse(e.data), b = bufs[m.m] || (bufs[m.m] = { n:m.n, got:0, parts:[] });
    b.parts[m.i] = m.p; b.got++;
    if(b.got === b.n){ delete bufs[m.m]; onMsg(JSON.parse(b.parts.join(''))); }
  }
  NB.handler = handle;
  var queued = NB.inbox; NB.inbox = [];
  setTimeout(function(){ queued.forEach(handle); }, 0);   // after the caller has its send function
  return async function send(obj){
    var s = JSON.stringify(obj), size = 14000, n = Math.ceil(s.length/size) || 1, id = ++seq;
    for(var i=0;i<n;i++){
      while(dc.bufferedAmount > 1000000) await new Promise(function(r){ setTimeout(r, 40); });
      dc.send(JSON.stringify({ m:id, i:i, n:n, p:s.slice(i*size, (i+1)*size) }));
    }
  };
}
function nbRunSync(onProgress){
  return new Promise(function(resolve, reject){
    var dc = NB.dc, mine = nbLocalSet(), sentN = 0, gotN = 0, peerDone = false, mineDone = false;
    var send = nbMessenger(dc, function(msg){
      if(msg.k === 'hello'){
        var out = [];
        Object.keys(mine).forEach(function(k){
          var pt = msg.man[k] !== undefined ? msg.man[k] : -1;
          if(mine[k].t > pt) out.push({ c:mine[k].c, i:mine[k].i, t:mine[k].t, d:mine[k].d });
        });
        (async function(){
          for(var i=0;i<out.length;i+=100){ await send({ k:'docs', list:out.slice(i, i+100) }); sentN += Math.min(100, out.length-i); onProgress(sentN, gotN); }
          await send({ k:'done' }); mineDone = true; if(peerDone) finish();
        })().catch(reject);
      } else if(msg.k === 'docs'){ gotN += nbApply(msg.list); onProgress(sentN, gotN); }
      else if(msg.k === 'done'){ peerDone = true; if(mineDone) finish(); }
    });
    function finish(){ resolve({ sent:sentN, got:gotN }); }
    var man = {}; Object.keys(mine).forEach(function(k){ man[k] = mine[k].t; });
    var start = function(){ send({ k:'hello', man:man }).catch(reject); };
    if(dc.readyState === 'open') start(); else dc.onopen = start;
    dc.onclose = function(){ if(!(peerDone && mineDone)) reject(new Error('The connection closed before it finished.')); };
  });
}
/* ---- screen ---- */
function openNearbySheet(){
  if(Store.mode() !== 'local'){
    var ov0 = openSheet('<div class="sheet-head"><h2>'+tr('Nearby Wi-Fi sync')+'</h2></div><div class="banner">'+tr('This works in the installed app only, not in the Claude preview copy.')+'</div>'+smartBackBtn());
    wireSmartBack(ov0); return;
  }
  if(typeof RTCPeerConnection === 'undefined'){
    var ov1 = openSheet('<div class="sheet-head"><h2>'+tr('Nearby Wi-Fi sync')+'</h2></div><div class="banner">'+tr('This browser cannot connect devices directly.')+'</div>'+smartBackBtn());
    wireSmartBack(ov1); return;
  }
  var html = '<div class="sheet-head"><h2>'+tr('Nearby Wi-Fi sync')+'</h2></div>' +
    '<div class="banner" style="display:block;">'+tr('Connect two devices with no internet. Both must be on the same Wi-Fi (a router with no internet is fine, or one phone’s hotspot) and have Pesa open. You swap two short codes, then the devices exchange their newest changes directly, encrypted. The newest change to a record wins.')+'</div>' +
    '<div id="nbBody"></div>' + smartBackBtn();
  var ov = openSheet(html); wireSmartBack(ov);
  var body = ov.querySelector('#nbBody');
  function codeBox(code, label){
    return '<div class="field"><label>'+label+'</label><div style="background:#fff;padding:6px;border-radius:10px;max-width:280px;margin:0 auto 8px;">'+nbQrSvg(code)+'</div>' +
      '<textarea id="nbCodeOut" readonly rows="3" style="width:100%;font-family:monospace;font-size:11px;">'+esc(code)+'</textarea>' +
      '<div class="actions"><button class="btn btn-ghost btn-block" id="nbCopy" type="button">'+tr('Copy code')+'</button></div></div>';
  }
  function wireCopy(){ var c = body.querySelector('#nbCopy'); if(c) c.addEventListener('click', function(){ copyText(body.querySelector('#nbCodeOut').value, tr('Code copied')); }); }
  function err(m){ var e = body.querySelector('#nbErr'); if(e) e.innerHTML = m ? '<div class="banner">'+ICONS.warn+'<span>'+esc(m)+'</span></div>' : ''; }
  function pickStage(){
    body.innerHTML = '<div class="actions"><button class="btn btn-primary btn-block" id="nbHost" type="button">'+tr('1. Start on this device')+'</button></div>' +
      '<div class="actions" style="margin-top:8px;"><button class="btn btn-ghost btn-block" id="nbJoin" type="button">'+tr('2. Join a device that already started')+'</button></div>' +
      '<div class="banner" style="display:block;margin-top:10px;">'+tr('On the first device tap 1. On the second device tap 2.')+'</div>';
    body.querySelector('#nbHost').addEventListener('click', hostStage);
    body.querySelector('#nbJoin').addEventListener('click', joinStage);
  }
  function connectedStage(){
    body.innerHTML = '<div class="banner" style="display:block;"><b>'+tr('Connected. Syncing…')+'</b><div id="nbProg" style="margin-top:6px;">'+tr('Working…')+'</div></div><div id="nbErr"></div>';
    nbRunSync(function(s, g){ var p = body.querySelector('#nbProg'); if(p) p.textContent = tr('Sent')+' '+s+' · '+tr('Received')+' '+g; })
      .then(function(r){
        body.innerHTML = '<div class="banner" style="display:block;color:var(--success);"><b>'+tr('Done')+'</b><br>'+tr('Sent')+' '+r.sent+' '+tr('changes')+' · '+tr('Received')+' '+r.got+' '+tr('changes')+'</div>' +
          '<div class="actions"><button class="btn btn-ghost btn-block" id="nbAgain" type="button">'+tr('Sync again')+'</button></div>';
        body.querySelector('#nbAgain').addEventListener('click', function(){ nbClose(); pickStage(); });
        nbClose(); toast(tr('Nearby sync finished'));
      }, function(e){ var er = body.querySelector('#nbErr'); if(er) er.innerHTML = '<div class="banner">'+ICONS.warn+'<span>'+esc(e.message||String(e))+'</span></div>'; });
  }
  function hostStage(){
    body.innerHTML = '<div class="banner">'+tr('Preparing…')+'</div>';
    nbHostCode().then(function(code){
      body.innerHTML = '<div class="section-title">'+tr('Step 1')+'</div>' + codeBox(code, tr('Show this to the other device'))+
        '<div class="section-title">'+tr('Step 2')+'</div>' +
        '<div class="field"><label>'+tr('Reply code from the other device')+'</label><textarea id="nbIn" rows="3" placeholder="PN1.…" style="width:100%;font-family:monospace;font-size:11px;"></textarea>' +
        '<div class="actions"><button class="btn btn-ghost" id="nbScan" type="button">'+tr('Scan reply')+'</button><button class="btn btn-primary" id="nbGo" type="button">'+tr('Connect')+'</button></div></div><div id="nbErr"></div>';
      wireCopy();
      body.querySelector('#nbScan').addEventListener('click', function(){ openBarcodeScanSheet(function(c){ body.querySelector('#nbIn').value = c; body.querySelector('#nbGo').click(); }); });
      body.querySelector('#nbGo').addEventListener('click', function(){
        var c = body.querySelector('#nbIn').value; err('');
        NB.onState = function(s){ if(s === 'failed') err('Could not connect. Check that both devices are on the same Wi-Fi.'); };
        nbAcceptAnswer(c).then(function(){ waitOpen(connectedStage); }, function(e){ err(e.message||String(e)); });
      });
    }, function(e){ body.innerHTML = '<div class="banner">'+ICONS.warn+'<span>'+esc(e.message||String(e))+'</span></div>'; });
  }
  function waitOpen(next){
    body.insertAdjacentHTML('beforeend','<div class="banner" id="nbWait">'+tr('Connecting…')+'</div>');
    var t0 = Date.now(), iv = setInterval(function(){
      if(NB.dc && NB.dc.readyState === 'open'){ clearInterval(iv); next(); }
      else if(Date.now()-t0 > 25000){ clearInterval(iv); err('Could not connect. Check that both devices are on the same Wi-Fi and try again.'); var w = body.querySelector('#nbWait'); if(w) w.remove(); }
    }, 300);
  }
  function joinStage(){
    body.innerHTML = '<div class="field"><label>'+tr('Code from the first device')+'</label><textarea id="nbIn" rows="3" placeholder="PN1.…" style="width:100%;font-family:monospace;font-size:11px;"></textarea>' +
      '<div class="actions"><button class="btn btn-ghost" id="nbScan" type="button">'+tr('Scan code')+'</button><button class="btn btn-primary" id="nbGo" type="button">'+tr('Continue')+'</button></div></div><div id="nbErr"></div>';
    body.querySelector('#nbScan').addEventListener('click', function(){
      openBarcodeScanSheet(function(c){ body.querySelector('#nbIn').value = c; body.querySelector('#nbGo').click(); });
    });
    body.querySelector('#nbGo').addEventListener('click', function(){
      var c = body.querySelector('#nbIn').value; err('');
      nbJoinCode(c).then(function(ans){
        body.innerHTML = '<div class="section-title">'+tr('Step 3')+'</div>' + codeBox(ans, tr('Show this reply to the first device'))+'<div id="nbErr"></div>';
        wireCopy();
        NB.onChannel = function(){ waitOpen(connectedStage); };
        if(NB.dc) waitOpen(connectedStage);
        NB.onState = function(s){ if(s === 'failed') err('Could not connect. Check that both devices are on the same Wi-Fi.'); };
      }, function(e){ err(e.message||String(e)); });
    });
  }
  pickStage();
}

