// Formats the current date the way the stamp shows it: day, three letter
// month in capitals, four digit year, separated only by spaces, for
// example "28 SEP 2026". Built from the date's own numeric parts (never a
// locale string) so the format is exact and never contains a hyphen or
// dash character. Always called fresh against a live Date, never cached.
function fmtStampDate(d){
  var MONTHS = ['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'];
  var day = String(d.getDate());
  if(day.length<2) day = '0'+day;
  return day+' '+MONTHS[d.getMonth()]+' '+d.getFullYear();
}

// Generates a verification reference in the form "PESA-XXXXXXXX" (an eight
// character uppercase alphanumeric code). The single hyphen here is the
// literal ID format itself, not a stray dash, so it is exempt from the
// "no hyphen or dash" rule that applies to the rest of this page's text.
function genVerificationId(){
  var chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  var s = '';
  for(var i=0;i<8;i++) s += chars.charAt(Math.floor(Math.random()*chars.length));
  return 'PESA-'+s;
}

// Maps a point given as a fraction of the stamp image's own width and
// height (fx from its left edge, fy from its top edge, ordinary image
// pixel convention) to its final page position, once that image has been
// placed at (ix,iy) with size D x D and rotated by `tilt` degrees the way
// drawWetStamp() below places it with doc.addImage(). jsPDF rotates an
// image around the bottom left corner of its unrotated box, not around
// its center, so this reconstructs that same pivot and rotation to find
// where a point inside the image, such as the empty date box left behind
// by the stamp asset processing, actually lands on the page, so text can
// be drawn precisely inside it. `nudgeMm` shifts the point downward
// (inside the image, pre-rotation) to help centre a text baseline.
function stampImagePoint(ix, iy, D, tilt, fx, fy, nudgeMm){
  var rad = tilt*Math.PI/180, C = Math.cos(rad), S = Math.sin(rad);
  var px = ix, py = iy + D; // bottom left corner of the unrotated image = jsPDF's rotation pivot
  var Lx = fx*D, Ly = (1-fy)*D - (nudgeMm||0);
  var Rx = C*Lx - S*Ly, Ry = S*Lx + C*Ly;
  return { x: px + Rx, y: py - Ry };
}

// Draws the real Pesa wet stamp graphic (the user's own reference stamp
// photo, processed into black ink on a transparent background with the
// baked in sample date erased from inside its date box, embedded as
// STAMP_IMG_DATA_URL) onto the page with doc.addImage(), tilted a few
// degrees like a genuine hand pressed stamp, then draws the live current
// date as ordinary jsPDF vector text on top, positioned precisely inside
// that emptied date box and rotated to match. `now` is the single
// canonical Date computed once by the caller (generateAboutPdf) for this
// document generation, so the visible date can never be stale or drift
// from the verification record written to the audit log. Throws if the
// image cannot be embedded, rather than silently continuing, so the
// caller can treat that as a real failure instead of a false success.
function drawWetStamp(doc, pageW, pageH, now){
  var D = 46, tilt = -9; // stamp size (mm) and hand stamped tilt (degrees)
  var cx = pageW - 44, cy = pageH - 54; // clear white space, bottom right of the page, above the footer
  var half = D/2;
  var rad = tilt*Math.PI/180, C = Math.cos(rad), S = Math.sin(rad);
  // Solve for the addImage x,y (top left of the unrotated image) such that
  // the image's own centre lands exactly on the intended stamp centre
  // (cx,cy) once jsPDF rotates it around its bottom left corner.
  var px = cx - half*C + half*S;
  var py = cy + half*S + half*C;
  var ix = px, iy = py - D;

  // No try/catch here on purpose: if the stamp image cannot be embedded
  // (a corrupt data URL, an unsupported jsPDF build, and so on) this
  // throws, and generateAboutPdf()/openAboutSheet() must treat that as a
  // real failure rather than quietly producing a document with no stamp.
  doc.addImage(STAMP_IMG_DATA_URL, 'PNG', ix, iy, D, D, undefined, undefined, tilt);

  // today's date is sized to fill the date box (about four fifths of its width, never taller than about two thirds of its height) and centred in it
  var dateTxt = fmtStampDate(now), boxWmm = STAMP_DATE_BOX_W * D, boxHmm = STAMP_DATE_BOX_H * D;
  doc.setFont('helvetica','bold'); doc.setFontSize(20);
  var fitW = 20 * (boxWmm * 0.8) / Math.max(1, doc.getTextWidth(dateTxt)), fitH = (boxHmm * 0.66) / (0.72 * 0.3528);
  var dateFs = Math.max(6, Math.min(fitW, fitH, 30)), capH = 0.72 * dateFs * 0.3528;
  doc.setFontSize(dateFs);
  doc.setTextColor(15,15,15);
  var datePt = stampImagePoint(ix, iy, D, tilt, STAMP_DATE_BOX_FX, STAMP_DATE_BOX_FY, capH / 2);
  doc.text(dateTxt, datePt.x, datePt.y, {align:'center', angle: tilt});
}

// Builds the "About Pesa" PDF, sharing drawDocHeader() so it carries the
// same logo and layout conventions as every other Pesa document. The text
// content contains no hyphen or dash character, same as the in app page.
// Typography and spacing here are deliberately tightened (measured against
// the real content, not guessed) so the header, both paragraphs, the full
// feature list, the developer credit, the copyright notice and the stamp
// all reliably fit on this single first page, there is no page overflow
// fallback here, and this function never calls doc.addPage().
function generateAboutPdf(){
  var JsPDFCtor = getJsPDF();
  var doc = newPdfDoc(JsPDFCtor, { unit:'mm', format:'a4' });
  // One canonical Date for the whole document: the generated line, the
  // stamp and the verification record all read this same value.
  var now = new Date();
  var head = drawDocHeader(doc, {plain:true});
  var margin = head.margin, contentW = head.contentW, pageW = head.pageW, y = head.y;
  var pal = head.pal, primary = pal.mid, muted = pal.muted, dark = pal.text;
  var pageH = doc.internal.pageSize.getHeight();
  var bottomLimit = 265;
  function pad2(n){ return n<10 ? '0'+n : ''+n; }
  var stampTime = pad2(now.getHours())+':'+pad2(now.getMinutes());

  // Starts a continuation page with the same logo header when text would
  // run past the bottom margin.
  function need(h){
    if(y + h <= bottomLimit) return;
    doc.addPage();
    var hd = drawDocHeader(doc, {plain:true});
    y = hd.y;
  }

  var aty = y; y = pdTitle(doc, pal, margin, y, 'About Pesa');
  doc.setFont('helvetica','normal'); doc.setFontSize(8.5); doc.setTextColor(muted[0],muted[1],muted[2]);
  doc.text('Generated '+fmtDateNice(now)+' at '+stampTime, pageW-margin, aty+6, {align:'right'});
  y += 1;

  doc.setFont('helvetica','normal'); doc.setFontSize(9.5); doc.setTextColor(dark[0],dark[1],dark[2]);
  ABOUT_PARAGRAPHS.forEach(function(p){
    var lines = doc.splitTextToSize(p, contentW);
    need(lines.length*4.6 + 3);
    doc.setFont('helvetica','normal'); doc.setFontSize(9.5); doc.setTextColor(dark[0],dark[1],dark[2]);
    doc.text(lines, margin, y);
    y += lines.length*4.6 + 3;
  });

  function bulletList(items){
    items.forEach(function(f){
      doc.setFont('helvetica','normal'); doc.setFontSize(9);
      var lines = doc.splitTextToSize(f, contentW-5);
      need(lines.length*4.3 + 2);
      doc.setFont('helvetica','normal'); doc.setFontSize(9);
      doc.setTextColor(primary[0],primary[1],primary[2]);
      doc.text('•', margin, y);
      doc.setTextColor(dark[0],dark[1],dark[2]);
      doc.text(lines, margin+5, y);
      y += lines.length*4.3 + 1.8;
    });
  }
  function heading(txt){
    need(30);
    y += 6;
    pdSection(doc, pal, margin, y, contentW, txt); y += 7;
  }

  function groups(list){
    list.forEach(function(sec){
      need(16);
      y += 2;
      doc.setFont('helvetica','bold'); doc.setFontSize(10); doc.setTextColor(dark[0],dark[1],dark[2]);
      doc.text(sec.h, margin, y); y += 5.5;
      bulletList(sec.items);
      y += 2;
    });
  }

  heading(ABOUT_FEATURES_TITLE);
  bulletList(ABOUT_FEATURES);

  heading('Working with and without internet');
  groups(ABOUT_INTERNET);

  heading(ABOUT_CONNECTION_TITLE);
  groups(ABOUT_CONNECTION);

  heading(ABOUT_SMART_TITLE);
  groups(ABOUT_SMART);

  heading('Your privacy and confidentiality');
  doc.setFont('helvetica','normal'); doc.setFontSize(9); doc.setTextColor(dark[0],dark[1],dark[2]);
  var pi = doc.splitTextToSize(PRIVACY_INTRO, contentW); need(pi.length*4.3+3);
  doc.text(pi, margin, y); y += pi.length*4.3 + 3;
  groups(PRIVACY_SECTIONS);

  heading('Contact the Pesa Representative Team');
  doc.setFont('helvetica','normal'); doc.setFontSize(9.5); doc.setTextColor(dark[0],dark[1],dark[2]);
  if(hasDevMail()){ doc.text('Email: '+DEV_EMAIL, margin, y); y += 5; }
  if(hasDevWa()){ doc.text('WhatsApp: '+DEV_WHATSAPP, margin, y); y += 7; }
  if(!hasDevMail() && !hasDevWa()){ doc.text('Contact details will be shared by the Pesa Representative Team.', margin, y); y += 7; }

  // Credit, copyright, stamp and verification: kept together on the last
  // page. Room is made for the stamp so it never overlaps text.
  need(67);   // keeps the credit block clear of the stamp, which sits above the footer
  doc.setDrawColor(220,224,218); doc.line(margin,y,pageW-margin,y); y += 7;
  doc.setFont('helvetica','bold'); doc.setFontSize(9); doc.setTextColor(dark[0],dark[1],dark[2]);
  try{ doc.addImage(DEV_LOGO_DATA_URL, 'PNG', margin, y-4, 16, 16); }catch(e){}
  doc.text(DEV_CREDIT_LINE, margin+19, y+1); y += 6.5;
  doc.setFont('helvetica','normal'); doc.setFontSize(7.5); doc.setTextColor(muted[0],muted[1],muted[2]);
  var crLines = doc.splitTextToSize(copyrightLine(), contentW-19);
  doc.text(crLines, margin+19, y);
  y += Math.max(crLines.length*3.7, 8);

  // The stamp is anchored near the bottom right of the last page. If the
  // stamp image cannot be embedded, drawWetStamp() throws and the error
  // propagates, so a document without its stamp is never returned.
  drawWetStamp(doc, pageW, pageH, now);

  var verification = { id: genVerificationId(), status: 'VERIFIED', isoTimestamp: now.toISOString() };
  doc.setFont('helvetica','normal'); doc.setFontSize(7); doc.setTextColor(muted[0],muted[1],muted[2]);
  var vLine = 'Status: '+verification.status+'    Date: '+fmtStampDate(now)+'    Time: '+stampTime+'    Verification ID: '+verification.id;
  doc.text(vLine, margin, 271.6);

  return { doc: doc, verification: verification };
}

