    function row(t, v, lvl){ return '<div class="row"><div class="main"><div class="title">'+tr(t)+'</div></div><div class="trail" style="text-align:right;'+(lvl==='bad'?'color:#c0392b;':lvl==='warn'?'color:#b9770e;':'')+'">'+v+'</div></div>'; }
